import { useQuery } from '@tanstack/react-query';
import {
  Send,
  Loader2,
  CheckCircle,
  Volume2,
  VolumeX,
  Mic,
  Square,
  Play,
  Pause,
  Paperclip,
  X,
  ChevronDown,
  Copy,
  Flag,
  FileText,
  Image as ImageIcon,
  ExternalLink,
  ZoomIn,
  ZoomOut,
  RotateCcw,
} from 'lucide-react';
import { useState, useEffect, useLayoutEffect, useRef, useCallback, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { toast } from 'sonner';
import SafeMathMarkdown from './SafeMathMarkdown';
import type { AssignmentClipboardTrackingCallbacks } from '@/hooks/useAssignmentClipboardTracking';
import type { NuanceTrackingCallbacks } from '@/hooks/useNuanceTracking';
import type { DbAssignmentType } from '@/types/models';
import { StudentFacingTaskSection } from '@/components/features/assignment/StudentFacingTaskSection';
import { SubmissionStoragePreview } from '@/components/features/submission/SubmissionStoragePreview';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from '@/components/ui/collapsible';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Textarea } from '@/components/ui/textarea';
import { USER_ROLES } from '@/config/constants';
import { useLanguage } from '@/contexts/LanguageContext';
import { useAuth } from '@/contexts/useAuth';
import { useStudentProfile } from '@/hooks/queries';
import { useConversation } from '@/hooks/useConversation';
import { supabase } from '@/integrations/supabase/client';
import { validateChatAttachmentFile } from '@/lib/chatAttachment';
import {
  formatInlineListsForChatMarkdown,
  isPerleapAssistantIntro,
  normalizePerleapIntroParagraphBreaks,
  splitAssistantMessageIntoSentences,
  splitChatDisplayText,
  splitExplainTaskDisplayText,
  splitPerleapIntroDisplayText,
  stripConversationCompleteMarker,
  stripProgressMarker,
} from '@/lib/chatDisplay';
import { clipboardZoneProps } from '@/lib/clipboardSourceResolution';
import { getTaskUnderstandingChoice } from '@/lib/taskUnderstandingStorage';
import { detectUnderstandingCue } from '@/lib/understandingCueDetection';
import { cn } from '@/lib/utils';
import { synthesizeSpeech, transcribeAudio } from '@/services/speechService';
import { syncOpikChatSentenceFlag } from '@/services/submissionService';
import { isAppAdminRole } from '@/utils/role';
import {
  isSubmissionPdfAttachment,
  openSubmissionFileInNewTab,
} from '@/services/submissionFileService';

interface Message {
  role: 'user' | 'assistant';
  content: string;
  fileContext?: {
    name: string;
    content: string;
    url?: string;
    type?: string;
  };
}

export type AssignmentChatCompletePayload = {
  /** True when the green "conversation complete" state was true at submit. */
  conversationComplete: boolean;
};

interface AssignmentChatInterfaceProps {
  assignmentId: string;
  assignmentTitle: string;
  teacherName: string;
  assignmentInstructions: string;
  submissionId: string;
  /** Student `user_id` for this submission (required so admins opening the page still chat as the learner). */
  studentUserId: string;
  /** Optional; ordered prior submission ids (whole-unit chain); server validates and merges excerpts. */
  priorSubmissionIdsForContext?: string[];
  onComplete: (payload: AssignmentChatCompletePayload) => void | Promise<void>;
  nuanceTracking?: NuanceTrackingCallbacks;
  clipboardTracking?: AssignmentClipboardTrackingCallbacks;
  /** primary = chat completes the assignment; companion = Q&A alongside another task UI */
  variant?: 'primary' | 'companion';
  assignmentType: DbAssignmentType;
  studentFacingTask?: string | null;
  taskLoading?: boolean;
  /** When false, the first AI greeting is deferred until this becomes true. */
  chatInitAllowed?: boolean;
  initialGreetingMode?: 'default' | 'explain_task';
  postExplainTutoring?: boolean;
}

import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Checkbox } from '@/components/ui/checkbox';
import { Label } from '@/components/ui/label';

const CHAT_INPUT_MAX_HEIGHT_PX = 200;
const COMPANION_CHAT_OPEN_LS = 'perleap_assignment_companion_chat_open';

// Helper to clean markdown for TTS
const cleanTextForTTS = (text: string) => {
  return stripProgressMarker(stripConversationCompleteMarker(text))
    .replace(/(\*\*|__)(.*?)\1/g, '$2') // Remove bold
    .replace(/(\*|_)(.*?)\1/g, '$2') // Remove italic
    .replace(/\[(.*?)\]\(.*?\)/g, '$1') // Remove links
    .replace(/#{1,6}\s+(.*)/g, '$1') // Remove headers
    .replace(/`{1,3}([\s\S]*?)`{1,3}/g, '$1') // Remove code blocks
    .replace(/<[^>]*>/g, '') // Remove HTML tags
    .replace(/\\/g, '') // Remove backslashes
    .trim();
};

export const AssignmentChatInterface = ({
  assignmentId,
  assignmentTitle: _assignmentTitle,
  teacherName: _teacherName,
  assignmentInstructions,
  submissionId,
  studentUserId,
  priorSubmissionIdsForContext,
  onComplete,
  nuanceTracking,
  clipboardTracking,
  variant = 'primary',
  assignmentType,
  studentFacingTask,
  taskLoading = false,
  chatInitAllowed = true,
  initialGreetingMode = 'default',
  postExplainTutoring = false,
}: AssignmentChatInterfaceProps) => {
  const { user, loading: authLoading } = useAuth();
  const { t } = useTranslation();
  const { isRTL } = useLanguage();
  const isAdminRole = isAppAdminRole(user?.user_metadata?.role);
  const dbAdminQuery = useQuery({
    queryKey: ['is_app_admin_db', user?.id],
    enabled: !authLoading && !!user?.id && user?.user_metadata?.role === USER_ROLES.ADMIN,
    queryFn: async () => {
      const { data, error } = await supabase.rpc('is_app_admin', { _user_id: user!.id });
      if (error) throw error;
      return data === true;
    },
  });
  const chatDebugEnabled = isAdminRole && dbAdminQuery.isSuccess && dbAdminQuery.data === true;

  const { data: profile } = useStudentProfile(studentUserId);

  const [input, setInput] = useState('');
  const [conversationEnded, setConversationEnded] = useState(false);
  const [completing, setCompleting] = useState(false);
  const [showCompletionDialog, setShowCompletionDialog] = useState(false);
  const [dialogType, setDialogType] = useState<'turnLimit' | 'aiDetected'>('turnLimit');
  const [activeTab, setActiveTab] = useState('chat');
  const [previewResource, setPreviewResource] = useState<{
    name: string;
    content: string;
    url?: string;
    type?: string;
    messageIndex: number;
  } | null>(null);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [flagDialogMessageIndex, setFlagDialogMessageIndex] = useState<number | null>(null);
  const [flagSelectedSentenceIdx, setFlagSelectedSentenceIdx] = useState<Set<number>>(new Set());
  const [flagSubmitting, setFlagSubmitting] = useState(false);

  const [companionPanelOpen, setCompanionPanelOpen] = useState(() => {
    if (variant !== 'companion') return true;
    if (initialGreetingMode === 'explain_task') return true;
    try {
      return localStorage.getItem(COMPANION_CHAT_OPEN_LS) === 'true';
    } catch {
      return false;
    }
  });
  const companionLsHydrated = useRef(false);

  useEffect(() => {
    if (variant === 'companion' && initialGreetingMode === 'explain_task') {
      setCompanionPanelOpen(true);
    }
  }, [variant, initialGreetingMode]);

  // File attachment state
  const [attachedFile, setAttachedFile] = useState<{
    name: string;
    content: string;
    url?: string;
    type?: string;
  } | null>(null);
  const [uploadingFile, setUploadingFile] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatInputRef = useRef<HTMLTextAreaElement>(null);

  useLayoutEffect(() => {
    const el = chatInputRef.current;
    if (!el) return;
    el.style.height = 'auto';
    el.style.height = `${Math.min(el.scrollHeight, CHAT_INPUT_MAX_HEIGHT_PX)}px`;
  }, [input]);

  useEffect(() => {
    if (variant !== 'companion') return;
    if (!companionLsHydrated.current) {
      companionLsHydrated.current = true;
      return;
    }
    try {
      localStorage.setItem(COMPANION_CHAT_OPEN_LS, companionPanelOpen ? 'true' : 'false');
    } catch {
      /* ignore quota / private mode */
    }
  }, [variant, companionPanelOpen]);

  // Nuance tracking: detect first keystroke after AI message
  const hasTrackedTypingStart = useRef(false);
  const prevSendingRef = useRef(false);

  // Audio & Recording states
  const [playingMessageIndex, setPlayingMessageIndex] = useState<number | null>(null);
  const [loadingAudioIndex, setLoadingAudioIndex] = useState<number | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const currentAudioUrlRef = useRef<string | null>(null);
  const [isRecording, setIsRecording] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
        mediaRecorderRef.current.stop();
      }
      // If we have an active stream, stop all tracks
      if (mediaRecorderRef.current && mediaRecorderRef.current.stream) {
        mediaRecorderRef.current.stream.getTracks().forEach((track) => track.stop());
      }
      // Cleanup TTS audio
      if (audioRef.current) {
        audioRef.current.pause();
        audioRef.current.src = '';
      }
      if (currentAudioUrlRef.current) {
        URL.revokeObjectURL(currentAudioUrlRef.current);
        currentAudioUrlRef.current = null;
      }
    };
  }, []);

  // Use the conversation hook which handles language, greeting initialization, and API calls
  const {
    messages,
    loading,
    sending,
    conversationEnded: hookConversationEnded,
    language: conversationLanguage,
    lastAssistantDebug,
    sendMessage: sendConversationMessage,
  } = useConversation({
    submissionId,
    assignmentInstructions,
    studentFacingTask,
    assignmentId,
    priorSubmissionIds: priorSubmissionIdsForContext,
    companionMode: variant === 'companion',
    debugChat: chatDebugEnabled,
    autoInitialize: chatInitAllowed,
    initialGreetingMode,
    postExplainTutoring,
  });

  const canFlagAssistantText = !!user?.id && user.id === studentUserId;

  const flagDialogSentences = useMemo(() => {
    if (flagDialogMessageIndex === null) return [];
    const msg = messages[flagDialogMessageIndex];
    if (!msg?.content || msg.role !== 'assistant') return [];
    return splitAssistantMessageIntoSentences(String(msg.content));
  }, [flagDialogMessageIndex, messages]);

  // Update local state when hook reports conversation ended (primary assignments only)
  useEffect(() => {
    if (variant === 'primary' && hookConversationEnded && !conversationEnded) {
      setConversationEnded(true);
      setDialogType('aiDetected');
    }
  }, [variant, hookConversationEnded, conversationEnded]);

  // Nuance: record AI message arrival when streaming finishes
  useEffect(() => {
    if (prevSendingRef.current && !sending && nuanceTracking) {
      const lastMsg = messages[messages.length - 1];
      if (lastMsg?.role === 'assistant' && lastMsg.content) {
        nuanceTracking.recordAiMessageArrival();
        hasTrackedTypingStart.current = false;
      }
    }
    prevSendingRef.current = sending;
  }, [sending, messages, nuanceTracking]);

  const prevSendingForFocusRef = useRef(false);
  useEffect(() => {
    const wasSending = prevSendingForFocusRef.current;
    prevSendingForFocusRef.current = sending;
    if (!wasSending || sending || loading) return;
    if (activeTab !== 'chat') return;
    if (variant === 'companion' && !companionPanelOpen) return;
    if (previewResource) return;
    if (flagDialogMessageIndex !== null) return;
    if (showCompletionDialog) return;
    if (isRecording) return;

    requestAnimationFrame(() => {
      chatInputRef.current?.focus({ preventScroll: true });
    });
  }, [
    sending,
    loading,
    activeTab,
    variant,
    companionPanelOpen,
    previewResource,
    flagDialogMessageIndex,
    showCompletionDialog,
    isRecording,
  ]);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const shouldScrollRef = useRef(false);
  const firstAssistantMessageIndex = useMemo(
    () => messages.findIndex((m) => m.role === 'assistant'),
    [messages]
  );

  const taskUnderstandingChoice = useMemo(
    () => (studentUserId ? getTaskUnderstandingChoice(studentUserId, submissionId) : null),
    [studentUserId, submissionId]
  );

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    if (shouldScrollRef.current) {
      scrollToBottom();
      shouldScrollRef.current = false;
    }
  }, [messages, loading, sending]);

  const processAttachmentFile = useCallback(
    async (file: File) => {
      const validated = validateChatAttachmentFile(file);
      if (validated.ok === false) {
        toast.error(
          validated.reason === 'size'
            ? t('assignmentChat.errors.fileTooLarge')
            : t('assignmentChat.errors.fileTypeNotAllowed')
        );
        return;
      }

      setUploadingFile(true);
      try {
        const isText =
          file.type.startsWith('text/') || file.name.endsWith('.md') || file.name.endsWith('.txt');

        if (isText) {
          const text = await file.text();
          setAttachedFile({ name: file.name, content: text, type: 'text' });
        } else {
          const safeName = file.name?.trim() || `pasted-${Date.now()}.bin`;
          const filePath = `${submissionId}/${Date.now()}_${safeName}`;

          const { error } = await supabase.storage
            .from('submission-files')
            .upload(filePath, file, { upsert: true });

          if (error) {
            throw error;
          }

          const isImage = file.type.startsWith('image/');
          setAttachedFile({
            name: safeName,
            content: `[File: ${safeName}]\nStorage path: ${filePath}`,
            url: filePath,
            type: isImage ? 'image' : 'pdf',
          });
        }
        toast.success(t('assignmentChat.success.fileAttached'));
      } catch (err) {
        toast.error(t('assignmentChat.errors.fileUpload'));
      } finally {
        setUploadingFile(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    },
    [submissionId, t]
  );

  const handleFileSelect = useCallback(
    async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      await processAttachmentFile(file);
    },
    [processAttachmentFile]
  );

  const handlePaste = useCallback(
    async (e: React.ClipboardEvent<HTMLTextAreaElement>) => {
      const text = e.clipboardData?.getData('text/plain') ?? '';
      if (text.trim() && clipboardTracking) {
        clipboardTracking.trackPaste({
          pastedText: text,
          sourceKind: 'chat_input',
        });
      }

      const items = e.clipboardData?.items;
      if (items?.length) {
        for (let i = 0; i < items.length; i++) {
          const item = items[i];
          if (item.kind === 'file') {
            const file = item.getAsFile();
            if (file) {
              e.preventDefault();
              await processAttachmentFile(file);
              return;
            }
          }
        }
      }
      const files = e.clipboardData?.files;
      if (files && files.length > 0) {
        e.preventDefault();
        await processAttachmentFile(files[0]);
      }
    },
    [processAttachmentFile, clipboardTracking]
  );

  const handleSendMessage = async () => {
    if ((!input.trim() && !attachedFile) || loading || sending) return;

    const outgoingMessageIndex = messages.length;

    if (nuanceTracking) {
      const elapsed = nuanceTracking.getTimeSinceLastAiMessage();
      if (elapsed !== null) {
        nuanceTracking.trackResponseSubmitted(elapsed, messages.length);
      }
    }

    const userMessage = input.trim();
    if (userMessage) {
      if (nuanceTracking) {
        const cue = detectUnderstandingCue(userMessage);
        nuanceTracking.trackUnderstandingCue(cue, userMessage.length, messages.length);
      } else if (import.meta.env.DEV) {
        // eslint-disable-next-line no-console
        console.debug(
          '[Nuance] no tracking hook on chat — understanding cues are skipped (e.g. wrong route or tracking disabled)'
        );
      }
    }
    setInput('');
    const fileCtx = attachedFile ?? undefined;
    setAttachedFile(null);
    shouldScrollRef.current = true;

    await sendConversationMessage(userMessage, fileCtx);
    if (userMessage && clipboardTracking) {
      clipboardTracking.linkRecentChatPastes(outgoingMessageIndex);
    }
  };

  const handleComplete = async () => {
    if (!user) {
      if (!authLoading) {
        toast.error(t('assignmentChat.errors.sessionExpired'));
      }
      return;
    }
    if (messages.length === 0) {
      toast.error(t('assignmentChat.completeNotReady'));
      return;
    }

    setCompleting(true);
    try {
      await onComplete({ conversationComplete: conversationEnded });
    } catch (error) {
      toast.error(t('assignmentChat.errors.completing'));
    } finally {
      setCompleting(false);
    }
  };

  const handleDialogContinue = () => setShowCompletionDialog(false);
  const handleDialogComplete = () => {
    setShowCompletionDialog(false);
    handleComplete();
  };

  const handlePlayTTS = async (text: string, index: number) => {
    if (playingMessageIndex === index) {
      if (audioRef.current) {
        audioRef.current.pause();
        audioRef.current.currentTime = 0;
      }
      if (currentAudioUrlRef.current) {
        URL.revokeObjectURL(currentAudioUrlRef.current);
        currentAudioUrlRef.current = null;
      }
      setPlayingMessageIndex(null);
      return;
    }

    // Stop and cleanup any currently playing audio and its URL
    if (audioRef.current) {
      audioRef.current.pause();
      if (currentAudioUrlRef.current) {
        URL.revokeObjectURL(currentAudioUrlRef.current);
        currentAudioUrlRef.current = null;
      }
      try {
        // Resetting src helps stop the actual network request/buffering
        audioRef.current.src = '';
        audioRef.current.load();
      } catch (e) {
        // Ignore reset errors
      }
    }

    try {
      setLoadingAudioIndex(index);
      const voice = profile?.voice_preference || 'shimmer';

      const cleanedText = cleanTextForTTS(formatInlineListsForChatMarkdown(text));
      if (!cleanedText) {
        throw new Error('No text to play after cleaning');
      }

      const audioUrl = await synthesizeSpeech(cleanedText, voice);
      currentAudioUrlRef.current = audioUrl;

      if (!audioRef.current) {
        audioRef.current = new Audio();
      }

      const audio = audioRef.current;
      audio.src = audioUrl;

      audio.onplay = () => {
        setLoadingAudioIndex(null);
        setPlayingMessageIndex(index);
      };

      audio.onended = () => {
        setPlayingMessageIndex(null);
        if (currentAudioUrlRef.current === audioUrl) {
          URL.revokeObjectURL(audioUrl);
          currentAudioUrlRef.current = null;
        }
      };

      audio.onpause = () => {
        setPlayingMessageIndex(null);
        // We don't revoke here because it might be a temporary pause or we might want to resume
        // (though current UI doesn't support resume, just toggle)
      };

      audio.onerror = () => {
        // If we just reset the source manually, don't show an error
        if (audio.src === '' || audio.src === window.location.href) return;

        const error = audio.error;
        console.error('Audio element error details:', {
          code: error?.code,
          message: error?.message,
          src: audio.src,
        });
        setLoadingAudioIndex(null);
        setPlayingMessageIndex(null);
        if (currentAudioUrlRef.current === audioUrl) {
          URL.revokeObjectURL(audioUrl);
          currentAudioUrlRef.current = null;
        }
        toast.error(t('assignmentChat.errors.tts'));
      };

      // Ensure we catch the play promise error (e.g. if interrupted by another click)
      await audio.play().catch((err) => {
        if (err.name === 'AbortError') {
          // Ignore AbortError as it usually means we started a new audio before this one loaded
        } else {
          throw err;
        }
      });
    } catch (error) {
      console.error('TTS Playback catch block:', error);
      setLoadingAudioIndex(null);
      setPlayingMessageIndex(null);
      if (currentAudioUrlRef.current) {
        URL.revokeObjectURL(currentAudioUrlRef.current);
        currentAudioUrlRef.current = null;
      }
      // Only toast if it wasn't a manual abort
      if ((error as any).name !== 'AbortError') {
        toast.error(t('assignmentChat.errors.tts'));
      }
    }
  };

  const openFlagDialog = (messageIndex: number) => {
    setFlagDialogMessageIndex(messageIndex);
    setFlagSelectedSentenceIdx(new Set());
  };

  const toggleFlagSentenceSelection = (sentenceIdx: number) => {
    setFlagSelectedSentenceIdx((prev) => {
      const next = new Set(prev);
      if (next.has(sentenceIdx)) next.delete(sentenceIdx);
      else next.add(sentenceIdx);
      return next;
    });
  };

  const handleSubmitSentenceFlags = async () => {
    if (flagDialogMessageIndex === null || flagSelectedSentenceIdx.size === 0) {
      toast.warning(t('assignmentChat.flag.selectSentences'));
      return;
    }

    setFlagSubmitting(true);
    let anyNew = false;
    let anyDup = false;
    try {
      const sortedIdx = [...flagSelectedSentenceIdx].sort((a, b) => a - b);
      const { data: dbConv } = await supabase
        .from('assignment_conversations')
        .select('messages')
        .eq('submission_id', submissionId)
        .maybeSingle();
      const dbMessages = Array.isArray(dbConv?.messages) ? dbConv.messages : [];
      const dbMsg = dbMessages[flagDialogMessageIndex] as { content?: string } | undefined;
      const dbContent = typeof dbMsg?.content === 'string' ? dbMsg.content : '';
      const dbSentences = splitAssistantMessageIntoSentences(dbContent);

      for (const si of sortedIdx) {
        const uiSentence = flagDialogSentences[si];
        if (!uiSentence) continue;
        const sentenceText = dbSentences[si] ?? uiSentence;
        const { data, error } = await supabase.rpc('report_assignment_chat_sentence', {
          args: {
            p_submission_id: submissionId,
            p_message_index: flagDialogMessageIndex,
            p_sentence_index: si,
            p_sentence_text: sentenceText,
          },
        });
        if (error) throw error;
        const r = data as { ok?: boolean; duplicate?: boolean; error?: string };
        if (r?.duplicate) {
          anyDup = true;
        } else if (r?.ok) {
          anyNew = true;
          syncOpikChatSentenceFlag({
            submissionId,
            messageIndex: flagDialogMessageIndex,
            sentenceText,
          });
        } else {
          throw new Error(r?.error ?? 'flag_rejected');
        }
      }
      if (anyNew) toast.success(t('assignmentChat.flag.success'));
      if (anyDup && !anyNew) toast.info(t('assignmentChat.flag.duplicateOnly'));
      if (anyNew || anyDup) {
        setFlagDialogMessageIndex(null);
        setFlagSelectedSentenceIdx(new Set());
      }
    } catch (e) {
      console.error(e);
      toast.error(t('assignmentChat.errors.flag'));
    } finally {
      setFlagSubmitting(false);
    }
  };

  const startRecording = async () => {
    let stream: MediaStream | null = null;
    try {
      stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      // Choose supported MIME type
      const mimeType = MediaRecorder.isTypeSupported('audio/webm')
        ? 'audio/webm'
        : MediaRecorder.isTypeSupported('audio/ogg')
          ? 'audio/ogg'
          : 'audio/mp4';

      const mediaRecorder = new MediaRecorder(stream, { mimeType });
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          audioChunksRef.current.push(event.data);
        }
      };

      mediaRecorder.onstop = async () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: mimeType });
        try {
          const text = await transcribeAudio(audioBlob, conversationLanguage);
          if (text.trim()) {
            setInput((prev) => prev + (prev ? ' ' : '') + text.trim());
          }
        } catch (error) {
          toast.error(t('assignmentChat.errors.stt'));
        }

        // Stop all tracks to release microphone
        if (stream) {
          stream.getTracks().forEach((track) => track.stop());
        }
      };

      // Set a small timeslice to get data regularly (can help with large recordings)
      mediaRecorder.start(1000);
      setIsRecording(true);
    } catch (error) {
      console.error('Recording error:', error);
      if (stream) {
        stream.getTracks().forEach((track) => track.stop());
      }
      toast.error(t('assignmentChat.errors.micAccess'));
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const isDisabled = loading || sending || !chatInitAllowed;
  const canComplete = messages.length > 0;

  const handleViewInChat = (index: number) => {
    setPreviewResource(null);
    setActiveTab('chat');
    // Give tab time to render before scrolling
    setTimeout(() => {
      const messageElement = document.getElementById(`message-${index}`);
      if (messageElement) {
        messageElement.scrollIntoView({ behavior: 'smooth', block: 'center' });
        // Optional: Add a brief highlight effect
        messageElement.classList.add('bg-primary/10');
        setTimeout(() => messageElement.classList.remove('bg-primary/10'), 2000);
      }
    }, 100);
  };

  const handlePreviewAttachment = useCallback(
    async (
      fileContext: { name: string; content: string; url?: string; type?: string },
      messageIndex: number
    ) => {
      if (isSubmissionPdfAttachment(fileContext.name, fileContext.type) && fileContext.url) {
        const ok = await openSubmissionFileInNewTab(fileContext.url);
        if (!ok) toast.error(t('submissionDetail.projectView.downloadFailed'));
        return;
      }
      setPreviewResource({ ...fileContext, messageIndex });
    },
    [t]
  );

  const resources = messages
    .map((m, i) => ({ ...m, originalIndex: i }))
    .filter((m) => m.role === 'user' && m.fileContext);

  const chatScrollAreaClass =
    variant === 'companion' ? 'mb-4 h-[min(42vh,400px)] shrink-0 pr-4' : 'mb-4 min-h-0 flex-1 pr-4';
  const resourcesScrollAreaClass = variant === 'companion' ? 'h-[min(38vh,340px)]' : 'h-[400px]';

  const chatPanelBody = (
    <>
      {chatDebugEnabled ? (
        <Collapsible className="rounded-md border border-amber-500/30 bg-amber-500/5 px-3 py-2">
          <CollapsibleTrigger className="flex w-full items-center justify-between gap-2 text-left text-sm font-medium text-amber-900 dark:text-amber-100">
            <span>{t('assignmentChat.adminDebug.title')}</span>
            <ChevronDown className="size-4 shrink-0 opacity-70" />
          </CollapsibleTrigger>
          <CollapsibleContent className="pb-1 pt-2">
            <p className="text-xs text-muted-foreground mb-3">
              {t('assignmentChat.adminDebug.warning')}
            </p>
            {lastAssistantDebug ? (
              <div className="space-y-3">
                <div className="flex flex-wrap gap-x-3 gap-y-1 text-xs text-muted-foreground">
                  <span>
                    {t('assignmentChat.adminDebug.model')}: {lastAssistantDebug.model}
                  </span>
                  <span>
                    {t('assignmentChat.adminDebug.polish')}:{' '}
                    {lastAssistantDebug.polishEnabled ? t('common.yes') : t('common.no')}
                  </span>
                  <span>
                    {t('assignmentChat.adminDebug.temperature')}: {lastAssistantDebug.temperature}
                  </span>
                  <span>
                    {t('assignmentChat.adminDebug.maxTokens')}: {lastAssistantDebug.maxTokens}
                  </span>
                </div>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  className="gap-1.5"
                  onClick={() =>
                    navigator.clipboard.writeText(JSON.stringify(lastAssistantDebug, null, 2))
                  }
                >
                  <Copy className="size-3.5" />
                  {t('assignmentChat.adminDebug.copyJson')}
                </Button>
                <div className="space-y-1">
                  <p className="text-xs font-medium">{t('assignmentChat.adminDebug.rawModel')}</p>
                  <pre className="text-xs font-mono whitespace-pre-wrap break-words rounded-md bg-muted p-2 max-h-[180px] overflow-auto">
                    {lastAssistantDebug.rawModelText}
                  </pre>
                </div>
                <div className="space-y-1">
                  <p className="text-xs font-medium">
                    {t('assignmentChat.adminDebug.afterPostprocess')}
                  </p>
                  <pre className="text-xs font-mono whitespace-pre-wrap break-words rounded-md bg-muted p-2 max-h-[180px] overflow-auto">
                    {lastAssistantDebug.afterPostprocess}
                  </pre>
                </div>
                <div className="space-y-1">
                  <p className="text-xs font-medium">
                    {t('assignmentChat.adminDebug.finalClient')}
                  </p>
                  <pre className="text-xs font-mono whitespace-pre-wrap break-words rounded-md bg-muted p-2 max-h-[180px] overflow-auto">
                    {lastAssistantDebug.finalClientMessage}
                  </pre>
                </div>
              </div>
            ) : (
              <p className="text-xs text-muted-foreground">
                {t('assignmentChat.adminDebug.empty')}
              </p>
            )}
          </CollapsibleContent>
        </Collapsible>
      ) : null}

      <Tabs
        value={activeTab}
        onValueChange={setActiveTab}
        className={cn('flex min-h-0 flex-col flex-1', variant === 'companion' && 'overflow-hidden')}
      >
        <TabsList className="grid w-full grid-cols-3 mb-2">
          <TabsTrigger value="chat">{t('assignmentChat.tabs.chat')}</TabsTrigger>
          <TabsTrigger value="assignment">{t('assignmentChat.tabs.assignment')}</TabsTrigger>
          <TabsTrigger value="resources">
            {t('assignmentChat.tabs.resources')}
            {resources.length > 0 && (
              <span className="ml-2 bg-primary/20 text-primary text-xs rounded-full px-2 py-0.5">
                {resources.length}
              </span>
            )}
          </TabsTrigger>
        </TabsList>

        {/* Chat Tab - Using CSS hidden instead of conditional rendering to preserve state/scroll */}
        <div className={`flex-1 flex flex-col min-h-0 ${activeTab !== 'chat' ? 'hidden' : ''}`}>
          <ScrollArea className={chatScrollAreaClass}>
            <div className="space-y-4 pt-2 pb-4">
              {messages.map((message, index) => {
                const isUser = message.role === 'user';
                const rawContent = isUser
                  ? String(message.content || '')
                  : stripProgressMarker(
                      stripConversationCompleteMarker(String(message.content || ''))
                    );
                const isExplainTaskIntro =
                  !isUser &&
                  !!message.content &&
                  index === firstAssistantMessageIndex &&
                  taskUnderstandingChoice === 'no';
                const isIntro =
                  !isUser &&
                  !!message.content &&
                  index === firstAssistantMessageIndex &&
                  isPerleapAssistantIntro(rawContent);
                const formattedContent = formatInlineListsForChatMarkdown(
                  isIntro ? normalizePerleapIntroParagraphBreaks(rawContent) : rawContent
                );
                const displayParts =
                  isUser || !message.content
                    ? [rawContent]
                    : isExplainTaskIntro
                      ? splitExplainTaskDisplayText(formattedContent)
                      : isIntro
                        ? splitPerleapIntroDisplayText(formattedContent)
                        : splitChatDisplayText(formattedContent);
                // User messages always on the right side of the chat (end)
                // Assistant messages always on the left side of the chat (start)
                // This is standard chat convention regardless of language direction
                return (
                  <div
                    key={index}
                    id={`message-${index}`}
                    className={`flex ${isUser ? 'justify-end' : 'justify-start'} transition-colors duration-500 rounded-lg`}
                  >
                    <div
                      className={`flex flex-col gap-1.5 ${isUser ? 'items-end' : 'items-start'} max-w-[80%]`}
                    >
                      {displayParts.map((part, partIdx) => (
                        <div
                          key={`${index}-p-${partIdx}`}
                          className="rounded-lg p-3 bg-muted"
                          dir="auto"
                          {...clipboardZoneProps({
                            sourceKind: isUser ? 'user_message' : 'assistant_message',
                            messageIndex: index,
                            messageContent: isUser ? undefined : String(message.content ?? ''),
                          })}
                          style={{
                            unicodeBidi: 'plaintext',
                            animationDelay:
                              !isUser && partIdx > 0 ? `${partIdx * 45}ms` : undefined,
                          }}
                        >
                          <div className="text-sm markdown-content">
                            {part ? <SafeMathMarkdown content={part} /> : null}
                          </div>
                        </div>
                      ))}

                      {/* Render attachment underneath the message text */}
                      {message.fileContext && (
                        <div
                          className={`p-2 rounded-md border bg-background/50 flex items-center gap-2 cursor-pointer hover:bg-background transition-colors max-w-full ${!message.content ? 'mt-0' : ''}`}
                          onClick={() => void handlePreviewAttachment(message.fileContext!, index)}
                        >
                          {message.fileContext.type === 'image' ? (
                            <ImageIcon className="h-4 w-4 text-primary" />
                          ) : (
                            <FileText className="h-4 w-4 text-primary" />
                          )}
                          <span className="text-sm font-medium truncate max-w-[200px]">
                            {message.fileContext.name}
                          </span>
                        </div>
                      )}
                      {!isUser && message.content && (
                        <div className="flex flex-row items-center gap-1 mt-1">
                          <Button
                            variant="ghost"
                            size="sm"
                            className="h-8 w-8 p-0"
                            onClick={() => handlePlayTTS(message.content, index)}
                            disabled={loadingAudioIndex !== null && loadingAudioIndex !== index}
                          >
                            {loadingAudioIndex === index ? (
                              <Loader2 className="h-4 w-4 animate-spin" />
                            ) : playingMessageIndex === index ? (
                              <VolumeX className="h-4 w-4 text-primary" />
                            ) : (
                              <Volume2 className="h-4 w-4 text-muted-foreground" />
                            )}
                          </Button>
                          {canFlagAssistantText &&
                            splitAssistantMessageIntoSentences(String(message.content)).length >
                              0 && (
                              <Button
                                type="button"
                                variant="ghost"
                                size="sm"
                                className="h-8 w-8 p-0"
                                title={t('assignmentChat.flag.open')}
                                aria-label={t('assignmentChat.flag.open')}
                                onClick={() => openFlagDialog(index)}
                              >
                                <Flag className="h-4 w-4 text-muted-foreground" />
                              </Button>
                            )}
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}
              {(loading || sending) && (
                <div className="flex justify-start">
                  <div className="bg-muted rounded-lg p-3">
                    <Loader2 className="h-4 w-4 animate-spin" />
                  </div>
                </div>
              )}
              <div ref={messagesEndRef} />
            </div>
          </ScrollArea>

          {variant === 'primary' && conversationEnded && (
            <div
              className={`bg-success/10 border border-success/20 rounded-lg p-3 text-sm text-success mb-4 ${isRTL ? 'text-right' : 'text-left'}`}
              dir={isRTL ? 'rtl' : 'ltr'}
            >
              {isRTL ? '✓ ' : ''}
              {t(
                'assignmentChat.conversationComplete',
                'Conversation complete! You can now finish the activity.'
              )}
              {!isRTL ? ' ✓' : ''}
            </div>
          )}

          <input
            ref={fileInputRef}
            type="file"
            accept=".txt,.md,.pdf,.png,.jpg,.jpeg"
            className="hidden"
            onChange={handleFileSelect}
          />

          {attachedFile && (
            <div className="flex items-center gap-2 px-3 py-1.5 bg-muted rounded-lg text-sm mb-2">
              <Paperclip className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
              <span className="truncate text-foreground">{attachedFile.name}</span>
              <Button
                variant="ghost"
                size="icon"
                className="h-5 w-5 p-0 ml-auto shrink-0"
                onClick={() => setAttachedFile(null)}
              >
                <X className="h-3.5 w-3.5" />
              </Button>
            </div>
          )}

          <div className="flex gap-1.5 items-end mb-1">
            <div className="flex-1 relative">
              <Textarea
                ref={chatInputRef}
                {...clipboardZoneProps({ sourceKind: 'chat_input' })}
                placeholder={
                  conversationEnded
                    ? t(
                        'assignmentChat.conversationEndedPlaceholder',
                        'Conversation ended - please complete the activity'
                      )
                    : t('assignmentChat.placeholder')
                }
                value={input}
                onChange={(e) => {
                  setInput(e.target.value);
                  if (!hasTrackedTypingStart.current && e.target.value && nuanceTracking) {
                    nuanceTracking.trackResponseStarted(messages.length);
                    hasTrackedTypingStart.current = true;
                  }
                }}
                onPaste={(e) => void handlePaste(e)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    if (!isDisabled && (input.trim() || attachedFile)) {
                      handleSendMessage();
                    }
                  }
                }}
                disabled={isDisabled}
                className={`min-h-[44px] max-h-[200px] resize-none overflow-y-auto ${isRTL ? 'pl-11 text-right' : 'pr-11 text-left'}`}
                rows={1}
                dir={isRTL ? 'rtl' : 'ltr'}
                autoDirection
              />
              <Button
                variant="ghost"
                size="icon"
                className={`absolute bottom-1.5 ${isRTL ? 'left-3' : 'right-3'} h-8 w-8 rounded-full ${isRecording ? 'text-destructive animate-pulse' : 'text-muted-foreground'}`}
                onClick={isRecording ? stopRecording : startRecording}
                disabled={isDisabled}
              >
                {isRecording ? (
                  <Square className="h-4 w-4 fill-current" />
                ) : (
                  <Mic className="h-4 w-4" />
                )}
              </Button>
            </div>
            <Button
              variant="ghost"
              size="icon"
              className={`h-10 w-10 shrink-0 rounded-full ${uploadingFile ? 'text-primary animate-pulse' : attachedFile ? 'text-primary' : 'text-muted-foreground'}`}
              onClick={() => fileInputRef.current?.click()}
              disabled={isDisabled || uploadingFile}
              type="button"
            >
              {uploadingFile ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <Paperclip className="h-4 w-4" />
              )}
            </Button>
            <Button
              onClick={handleSendMessage}
              disabled={isDisabled || (!input.trim() && !attachedFile)}
              size="icon"
              className="h-10 w-10 shrink-0"
            >
              {loading || sending ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <Send className="h-4 w-4" />
              )}
            </Button>
          </div>

          {variant === 'primary' ? (
            <>
              {!canComplete && !loading && !sending ? (
                <p className="text-sm text-muted-foreground mb-2" dir={isRTL ? 'rtl' : 'ltr'}>
                  {t('assignmentChat.completeNotReady')}
                </p>
              ) : null}
              <Button
                onClick={handleComplete}
                disabled={completing || loading || sending}
                className="w-full mt-auto"
                variant={conversationEnded ? 'default' : 'secondary'}
              >
                {completing ? (
                  <>
                    <Loader2 className="me-2 h-4 w-4 animate-spin" />
                    {t('assignmentChat.completingActivity')}
                  </>
                ) : (
                  <>
                    <CheckCircle className="me-2 h-4 w-4" />
                    {t('assignmentChat.completeActivity')}
                  </>
                )}
              </Button>
            </>
          ) : null}
        </div>

        <TabsContent value="assignment" className="flex-1 mt-0 overflow-visible">
          <ScrollArea className={resourcesScrollAreaClass}>
            <StudentFacingTaskSection
              assignmentType={assignmentType}
              taskText={studentFacingTask}
              taskLoading={taskLoading}
              className={cn('px-3 py-4', isRTL && 'text-end')}
            />
          </ScrollArea>
        </TabsContent>

        <TabsContent value="resources" className="flex-1 mt-0 overflow-visible">
          <ScrollArea className={resourcesScrollAreaClass}>
            {resources.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-full text-muted-foreground space-y-2 py-10">
                <Paperclip className="h-8 w-8 opacity-50" />
                <p>{t('assignmentChat.resources.empty', 'No resources uploaded yet')}</p>
              </div>
            ) : (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-2 px-3 pb-3">
                {resources.map((msg, idx) => (
                  <Card
                    key={idx}
                    className="cursor-pointer hover:bg-muted/50 transition-colors"
                    onClick={() =>
                      void handlePreviewAttachment(msg.fileContext!, msg.originalIndex)
                    }
                  >
                    <CardContent className="p-3 flex items-start gap-3">
                      <div className="bg-primary/10 p-2 rounded-md shrink-0">
                        {msg.fileContext?.type === 'image' ? (
                          <ImageIcon className="h-5 w-5 text-primary" />
                        ) : (
                          <FileText className="h-5 w-5 text-primary" />
                        )}
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium truncate" title={msg.fileContext?.name}>
                          {msg.fileContext?.name}
                        </p>
                        <p className="text-xs text-muted-foreground mt-1">
                          {msg.fileContext?.type === 'image' ? 'Image' : 'Document'}
                        </p>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            )}
          </ScrollArea>
        </TabsContent>
      </Tabs>
    </>
  );

  return (
    <>
      <Card className={cn('flex flex-col', variant === 'primary' && 'h-full')}>
        {variant === 'companion' ? (
          <Collapsible open={companionPanelOpen} onOpenChange={setCompanionPanelOpen}>
            <CardHeader className="px-4 py-3">
              <CollapsibleTrigger
                type="button"
                className={cn(
                  'flex w-full items-center justify-between gap-2 rounded-md py-1 text-start outline-none ring-offset-background transition-colors hover:bg-muted/60 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
                  isRTL && 'flex-row-reverse text-end'
                )}
              >
                <div className="min-w-0 flex-1 space-y-0.5">
                  <CardTitle className="text-base font-medium">
                    {t('assignmentChat.contextHelpTitle')}
                  </CardTitle>
                  <p className="text-xs font-normal leading-snug text-muted-foreground">
                    {companionPanelOpen
                      ? t('assignmentChat.companion.expandedHint')
                      : t('assignmentChat.companion.collapsedHint')}
                  </p>
                </div>
                <ChevronDown
                  className={cn(
                    'size-5 shrink-0 opacity-70 transition-transform duration-200',
                    companionPanelOpen && 'rotate-180'
                  )}
                />
              </CollapsibleTrigger>
            </CardHeader>
            <CollapsibleContent>
              <CardContent className="flex max-h-[min(55vh,520px)] min-h-0 flex-col space-y-4 pt-4">
                {chatPanelBody}
              </CardContent>
            </CollapsibleContent>
          </Collapsible>
        ) : (
          <CardContent className="flex min-h-0 flex-1 flex-col space-y-4 pt-6">
            {chatPanelBody}
          </CardContent>
        )}
      </Card>

      <Dialog
        open={flagDialogMessageIndex !== null}
        onOpenChange={(open) => {
          if (!open) {
            setFlagDialogMessageIndex(null);
            setFlagSelectedSentenceIdx(new Set());
          }
        }}
      >
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle>{t('assignmentChat.flag.title')}</DialogTitle>
            <DialogDescription>{t('assignmentChat.flag.description')}</DialogDescription>
          </DialogHeader>
          <p className="text-xs text-muted-foreground -mt-1">
            {t('assignmentChat.flag.privacyNotice')}
          </p>
          <div className="max-h-[min(280px,50vh)] overflow-y-auto space-y-3 py-2 pe-1">
            {flagDialogSentences.map((sentence, si) => (
              <div key={si} className="flex gap-3 items-start">
                <Checkbox
                  id={`flag-sent-${flagDialogMessageIndex}-${si}`}
                  checked={flagSelectedSentenceIdx.has(si)}
                  onCheckedChange={() => toggleFlagSentenceSelection(si)}
                  className="mt-1"
                />
                <Label
                  htmlFor={`flag-sent-${flagDialogMessageIndex}-${si}`}
                  className="text-sm leading-snug cursor-pointer font-normal whitespace-pre-wrap"
                >
                  {sentence}
                </Label>
              </div>
            ))}
          </div>
          <DialogFooter className="gap-2 sm:gap-0">
            <Button
              type="button"
              variant="outline"
              onClick={() => {
                setFlagDialogMessageIndex(null);
                setFlagSelectedSentenceIdx(new Set());
              }}
              disabled={flagSubmitting}
            >
              {t('common.cancel')}
            </Button>
            <Button
              type="button"
              onClick={() => void handleSubmitSentenceFlags()}
              disabled={flagSubmitting || flagSelectedSentenceIdx.size === 0}
              className="inline-flex items-center gap-2"
            >
              {flagSubmitting ? <Loader2 className="h-4 w-4 animate-spin shrink-0" /> : null}
              {t('assignmentChat.flag.submit')}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog
        open={!!previewResource}
        onOpenChange={(open) => {
          if (!open) {
            setPreviewResource(null);
            setZoomLevel(1);
          }
        }}
      >
        <DialogContent
          showCloseButton={false}
          className="max-w-5xl w-[90vw] max-h-[92vh] flex flex-col"
        >
          <DialogHeader className="space-y-0 pb-2">
            <div className="flex items-start justify-between gap-3">
              <DialogTitle className="text-base font-semibold break-words line-clamp-2 min-w-0 pt-0.5">
                {previewResource?.name}
              </DialogTitle>
              <Button
                variant="ghost"
                size="icon-sm"
                className="shrink-0"
                onClick={() => {
                  setPreviewResource(null);
                  setZoomLevel(1);
                }}
              >
                <X className="h-4 w-4" />
                <span className="sr-only">Close</span>
              </Button>
            </div>
            <div className="flex items-center gap-2 pt-1">
              {previewResource?.type === 'image' && (
                <div className="flex items-center gap-1 border rounded-md px-1">
                  <Button
                    variant="ghost"
                    size="icon-sm"
                    onClick={() => setZoomLevel((z) => Math.max(0.25, z - 0.25))}
                    disabled={zoomLevel <= 0.25}
                  >
                    <ZoomOut className="h-4 w-4" />
                    <span className="sr-only">Zoom out</span>
                  </Button>
                  <span className="text-xs font-medium min-w-[3rem] text-center tabular-nums">
                    {Math.round(zoomLevel * 100)}%
                  </span>
                  <Button
                    variant="ghost"
                    size="icon-sm"
                    onClick={() => setZoomLevel((z) => Math.min(5, z + 0.25))}
                    disabled={zoomLevel >= 5}
                  >
                    <ZoomIn className="h-4 w-4" />
                    <span className="sr-only">Zoom in</span>
                  </Button>
                  {zoomLevel !== 1 && (
                    <Button variant="ghost" size="icon-sm" onClick={() => setZoomLevel(1)}>
                      <RotateCcw className="h-3.5 w-3.5" />
                      <span className="sr-only">Reset zoom</span>
                    </Button>
                  )}
                </div>
              )}
              <Button
                variant="outline"
                size="sm"
                onClick={() => previewResource && handleViewInChat(previewResource.messageIndex)}
              >
                <ExternalLink className="h-4 w-4 mr-2" />
                View in Chat
              </Button>
            </div>
          </DialogHeader>
          <div className="flex-1 overflow-auto min-h-[50vh] border rounded-md p-4 bg-muted/30">
            <SubmissionStoragePreview
              storedUrl={previewResource?.url}
              type={previewResource?.type}
              name={previewResource?.name ?? ''}
              content={previewResource?.content ?? ''}
              zoomLevel={zoomLevel}
            />
          </div>
        </DialogContent>
      </Dialog>

      <AlertDialog open={showCompletionDialog} onOpenChange={setShowCompletionDialog}>
        <AlertDialogContent dir={isRTL ? 'rtl' : 'ltr'}>
          <AlertDialogHeader className={isRTL ? 'text-right' : 'text-left'}>
            <AlertDialogTitle>
              {dialogType === 'turnLimit'
                ? t('assignmentChat.completionDialog.turnLimitTitle')
                : t('assignmentChat.completionDialog.aiDetectedTitle')}
            </AlertDialogTitle>
            <AlertDialogDescription>
              {dialogType === 'turnLimit'
                ? t('assignmentChat.completionDialog.turnLimitDescription')
                : t('assignmentChat.completionDialog.aiDetectedDescription')}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter
            className={
              isRTL ? 'flex-row-reverse justify-start gap-2' : 'flex-row justify-end gap-2'
            }
          >
            <AlertDialogCancel onClick={handleDialogContinue} className="mt-0">
              {t('assignmentChat.completionDialog.continueButton')}
            </AlertDialogCancel>
            <AlertDialogAction onClick={handleDialogComplete}>
              {t('assignmentChat.completionDialog.completeButton')}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
};

import { Layers } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import type { SyllabusWithSections } from '@/types/syllabus';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { cn } from '@/lib/utils';

export interface AssignmentCourseOutlineLinkCardProps {
  isRTL: boolean;
  syllabus: SyllabusWithSections | null | undefined;
  syllabusLoading?: boolean;
  /** When true, module is fixed to `syllabusSectionId` (read-only label, no section Select). */
  lockSyllabusSection?: boolean;
  syllabusSectionId: string;
  onSyllabusSectionIdChange: (id: string) => void;
  gradingCategoryId: string;
  onGradingCategoryIdChange: (id: string) => void;
  /** `card`: bordered block + course outline title. `inline`: fields only for nested layout. */
  variant?: 'card' | 'inline';
  /** Merged onto the outer wrapper when `variant` is `inline`. */
  className?: string;
}

export const AssignmentCourseOutlineLinkCard = ({
  isRTL,
  syllabus,
  syllabusLoading,
  lockSyllabusSection = false,
  syllabusSectionId,
  onSyllabusSectionIdChange,
  gradingCategoryId,
  onGradingCategoryIdChange,
  variant = 'card',
  className,
}: AssignmentCourseOutlineLinkCardProps) => {
  const { t } = useTranslation();
  const hasSyllabus = !!syllabus;
  const hasSections = (syllabus?.sections?.length ?? 0) > 0;
  const hasCategories = (syllabus?.grading_categories?.length ?? 0) > 0;
  const hasLinkTargets = hasSections || hasCategories;

  const sectionDisplayLabel = !syllabusSectionId
    ? t('common.none', 'None')
    : (syllabus?.sections.find((s) => s.id === syllabusSectionId)?.title ?? syllabusSectionId);

  const categoryDisplayLabel = !gradingCategoryId
    ? t('common.none', 'None')
    : (() => {
        const c = syllabus?.grading_categories.find((x) => x.id === gradingCategoryId);
        return c ? `${c.name} (${c.weight}%)` : gradingCategoryId;
      })();

  const sectionLabel =
    variant === 'inline'
      ? t('createAssignment.metadata.linkedModule')
      : t('createAssignment.syllabusModelLabel');

  const triggerClass = cn(
    'w-full min-w-0',
    variant === 'inline' ? 'h-9 rounded-lg text-sm' : 'h-11 rounded-xl',
    isRTL ? 'text-right' : 'text-left'
  );

  const body = (
    <>
      {syllabusLoading ? (
        <p className={cn('text-sm text-muted-foreground', isRTL ? 'text-right' : 'text-left')}>
          {t('createAssignment.courseOutlineLoading')}
        </p>
      ) : !hasSyllabus ? (
        <p className={cn('text-sm text-muted-foreground', isRTL ? 'text-right' : 'text-left')}>
          {t('createAssignment.courseOutlineNoSyllabus')}
        </p>
      ) : !hasLinkTargets ? (
        <p className={cn('text-sm text-muted-foreground', isRTL ? 'text-right' : 'text-left')}>
          {t('createAssignment.courseOutlineNoSections')}
        </p>
      ) : (
        <div
          className={cn(
            'grid grid-cols-1',
            variant === 'inline'
              ? 'w-fit max-w-full gap-x-2 gap-y-2 md:grid-cols-2 md:gap-x-2 md:[grid-template-columns:minmax(0,12rem)_minmax(0,12rem)]'
              : 'w-full gap-x-6 gap-y-4 md:grid-cols-2'
          )}
        >
          {hasSections && (
            <div
              className={cn(
                'space-y-1.5',
                hasCategories ? '' : 'md:col-span-2',
                variant === 'inline' && !hasCategories && 'max-w-[12rem]'
              )}
            >
              <Label
                className={cn('text-body font-medium block', isRTL ? 'text-right' : 'text-left')}
              >
                {sectionLabel}
              </Label>
              {lockSyllabusSection && syllabusSectionId ? (
                <p
                  className={cn(
                    'rounded-lg border border-border bg-muted/40 px-3 py-2 text-sm text-foreground',
                    triggerClass
                  )}
                >
                  {sectionDisplayLabel}
                </p>
              ) : (
                <Select
                  value={syllabusSectionId || '_none'}
                  onValueChange={(v) => onSyllabusSectionIdChange(v === '_none' ? '' : v)}
                >
                  <SelectTrigger className={triggerClass} dir={isRTL ? 'rtl' : 'ltr'}>
                    <SelectValue placeholder={t('createAssignment.linkToSyllabusModel')}>
                      {sectionDisplayLabel}
                    </SelectValue>
                  </SelectTrigger>
                  <SelectContent className="rounded-xl" dir={isRTL ? 'rtl' : 'ltr'}>
                    <SelectItem value="_none">{t('common.none', 'None')}</SelectItem>
                    {syllabus!.sections.map((s) => (
                      <SelectItem
                        key={s.id}
                        value={s.id}
                        className={isRTL ? 'text-right' : 'text-left'}
                      >
                        {s.title}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}
            </div>
          )}
          {hasCategories && (
            <div
              className={cn(
                'space-y-1.5',
                hasSections ? '' : 'md:col-span-2',
                variant === 'inline' && !hasSections && 'max-w-[12rem]'
              )}
            >
              <Label
                className={cn('text-body font-medium block', isRTL ? 'text-right' : 'text-left')}
              >
                {t('syllabus.gradingCategory')}
              </Label>
              <Select
                value={gradingCategoryId || '_none'}
                onValueChange={(v) => onGradingCategoryIdChange(v === '_none' ? '' : v)}
              >
                <SelectTrigger className={triggerClass} dir={isRTL ? 'rtl' : 'ltr'}>
                  <SelectValue placeholder={t('syllabus.selectCategory')}>
                    {categoryDisplayLabel}
                  </SelectValue>
                </SelectTrigger>
                <SelectContent className="rounded-xl" dir={isRTL ? 'rtl' : 'ltr'}>
                  <SelectItem value="_none">{t('common.none', 'None')}</SelectItem>
                  {syllabus!.grading_categories.map((c) => (
                    <SelectItem
                      key={c.id}
                      value={c.id}
                      className={isRTL ? 'text-right' : 'text-left'}
                    >
                      {c.name} ({c.weight}%)
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}
        </div>
      )}
    </>
  );

  if (variant === 'inline') {
    return <div className={cn('w-fit max-w-full space-y-2', className)}>{body}</div>;
  }

  return (
    <div className="space-y-4 rounded-xl border border-border p-6 shadow-sm">
      <div className={cn('flex items-center gap-2 text-primary', isRTL && 'flex-row-reverse')}>
        <Layers className="h-5 w-5 shrink-0" />
        <h3 className={cn('font-bold text-heading', isRTL ? 'text-right' : 'text-left')}>
          {t('createAssignment.courseOutlineLinkTitle')}
        </h3>
      </div>
      {body}
    </div>
  );
};

