                      t={t}
                    />
                  </TableHeader>
                  <TableBody>
                    <CraDataRowsList
                      rows={all}
                      showStudentCol={showStudentCol}
                      showModuleCol
                      showAssignmentCol
                      groupByDomain={groupByDomain}
                      {...tableShared}
                    />
                  </TableBody>
                </Table>
              </div>
            );
          })()
        ) : null}
      </CardContent>
      <Dialog
        open={!!mobileDetailAssessment}
        onOpenChange={(o) => {
          if (!o) setExpandedRowIds(new Set());
        }}
      >
        <DialogContent
          className="max-h-[min(32rem,88vh)] overflow-y-auto sm:max-w-lg"
          id={CRA_MOBILE_DIALOG_CONTENT_ID}
        >
          {mobileDetailAssessment ? (
            <>
              <DialogHeader>
                <DialogTitle>
                  {t('cra.table.detailsDialogTitle', {
                    domain: mobileDetailAssessment.domain,
                    skill: mobileDetailAssessment.skill_component,
                  })}
                </DialogTitle>
              </DialogHeader>
              <CraDetailBody assessment={mobileDetailAssessment} t={t} />
            </>
          ) : null}
        </DialogContent>
      </Dialog>
    </Card>
  );
};

function mergeAllAssignmentsFromModules(
  modules: [string, { byAssignment: Map<string, { title: string; rows: EnrichedAssessment[] }> }][]
) {
  const out = new Map<string, { title: string; rows: EnrichedAssessment[] }>();
  for (const [, mod] of modules) {
    for (const [aid, val] of mod.byAssignment) {
      if (!out.has(aid)) {
        out.set(aid, { title: val.title, rows: [...val.rows] });
      } else {
        out.get(aid)!.rows.push(...val.rows);
      }
    }
  }
  return out;
}

function groupRowsByDomain(rows: EnrichedAssessment[]) {
  const m = new Map<string, EnrichedAssessment[]>();
  for (const r of rows) {
    const d = r.domain;
    if (!m.has(d)) m.set(d, []);
    m.get(d)!.push(r);
  }
  return [...m.entries()]
    .sort((a, b) => a[0].localeCompare(b[0]))
    .map(([domain, items]) => ({ domain, items }));
}

import { forwardRef } from 'react';
import { NavLink as RouterNavLink } from 'react-router-dom';
import type { NavLinkProps } from 'react-router-dom';
import { cn } from '@/lib/utils';

interface NavLinkCompatProps extends Omit<NavLinkProps, 'className'> {
  className?: string;
  activeClassName?: string;
  pendingClassName?: string;
}

const NavLink = forwardRef<HTMLAnchorElement, NavLinkCompatProps>(
  ({ className, activeClassName, pendingClassName, to, ...props }, ref) => {
    return (
      <RouterNavLink
        ref={ref}
        to={to}
        className={({ isActive, isPending }) =>
          cn(className, isActive && activeClassName, isPending && pendingClassName)
        }
        {...props}
      />
    );
  }
);

NavLink.displayName = 'NavLink';

export { NavLink };

import { Loader2 } from 'lucide-react';
import { useEffect, useRef, type ReactNode } from 'react';
import { useNavigate, useLocation, Navigate } from 'react-router-dom';
import type { Session } from '@supabase/supabase-js';
import { USER_ROLES } from '@/config/constants';
import { useAuth } from '@/contexts/useAuth';

interface ProtectedRouteProps {
  children: ReactNode;
  requiredRole?: 'teacher' | 'student';
  /** When true, only users with admin metadata may access; others redirect to teacher dashboard. */
  requireAppAdmin?: boolean;
  redirectTo?: string;
}

const ProtectedRoute = ({
  children,
  requiredRole,
  requireAppAdmin = false,
  redirectTo = '/auth',
}: ProtectedRouteProps) => {
  const { user, session, loading, hasProfile, isProfileLoading } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const hasNavigated = useRef(false);

  // Validate session freshness
  const isSessionValid = (session: Session | null) => {
    if (!session) return false;

    // Check if session has expiration time
    if (session.expires_at) {
      const expiresAt = session.expires_at * 1000; // Convert to milliseconds
      const now = Date.now();
      const isValid = expiresAt > now;

      if (!isValid) {
        console.warn('⚠️ Session has expired', {
          expiresAt: new Date(expiresAt).toISOString(),
          now: new Date(now).toISOString(),
        });
      }

      return isValid;
    }

    return true; // If no expiration time, assume valid
  };

  useEffect(() => {
    // Reset navigation flag when location changes
    hasNavigated.current = false;
  }, [location.pathname]);

  useEffect(() => {
    const checkAccessAndNavigate = async () => {
      // Don't navigate while core auth is loading
      if (loading) return;

      // If we have a user but are still checking for their profile, wait
      // unless we already have a profile in cache (handled by AuthContext)
      if (user && hasProfile === null && isProfileLoading) return;

      if (hasNavigated.current) return; // Prevent multiple navigations

      const currentPath = location.pathname;

      // Redirect to auth if not authenticated or session is invalid
      if (!user || !session || !isSessionValid(session)) {
        // Prevent navigation loop - don't redirect if already at redirectTo
        if (currentPath === redirectTo) {
          return;
        }

        console.log('🔒 Protected route: No valid session, redirecting to auth');

        // Save current path for post-login redirect (except auth pages)
        if (!currentPath.startsWith('/auth') && currentPath !== '/') {
          sessionStorage.setItem('redirectAfterLogin', currentPath);
        }

        hasNavigated.current = true;
        navigate(redirectTo, { replace: true });
        return;
      }

      if (requireAppAdmin) {
        const userRole = user.user_metadata?.role;
        if (userRole !== USER_ROLES.ADMIN) {
          if (currentPath.startsWith('/admin')) {
            hasNavigated.current = true;
            const dest = userRole === 'student' ? '/student/dashboard' : '/teacher/dashboard';
            navigate(dest, { replace: true });
          }
          return;
        }
      }

      // Check role-based access
      if (requiredRole) {
        const userRole = user.user_metadata?.role;
        const isAdmin = userRole === USER_ROLES.ADMIN;
        const adminOnStudentAssignment =
          isAdmin && requiredRole === 'student' && currentPath.startsWith('/student/assignment/');

        if (isAdmin && requiredRole === 'student' && !adminOnStudentAssignment) {
          if (currentPath !== '/teacher/dashboard') {
            hasNavigated.current = true;
            navigate('/teacher/dashboard', { replace: true });
          }
          return;
        }

        const roleOk =
          userRole === requiredRole ||
          (requiredRole === 'teacher' && isAdmin) ||
          adminOnStudentAssignment;

        if (!roleOk) {
          console.log('🔒 Protected route: Role mismatch', {
            required: requiredRole,
            actual: userRole,
          });

          const dashboardRoute =
            userRole === 'teacher' || isAdmin
              ? '/teacher/dashboard'
              : userRole === 'student'
                ? '/student/dashboard'
                : '/role-selection';

          // Prevent navigation loop
          if (currentPath !== dashboardRoute) {
            hasNavigated.current = true;
            navigate(dashboardRoute, { replace: true });
          }
          return;
        }

        // Check if user has completed their profile (unless they're on onboarding page)
        if (!currentPath.startsWith('/onboarding/') && !isAdmin) {
          // Use cached profile check from AuthContext
          // Only redirect if we ARE NOT currently loading the profile and we know it's missing
          if (hasProfile === false && !isProfileLoading) {
            console.log(
              `🔒 Protected route: User has ${userRole} role but no profile, redirecting to onboarding`
            );
            const onboardingPath = `/onboarding/${userRole}`;

            if (currentPath !== onboardingPath) {
              hasNavigated.current = true;
              navigate(onboardingPath, { replace: true });
            }
            return;
          }
        }
      }
    };

    checkAccessAndNavigate();
  }, [
    user,
    session,
    loading,
    requiredRole,
    requireAppAdmin,
    navigate,
    redirectTo,
    location.pathname,
    hasProfile,
    isProfileLoading,
  ]);

  // STABILIZED LOADING CHECK:
  // Only show the full-page loader if:
  // 1. Initial auth is loading
  // 2. We have a user but haven't determined if they have a profile yet AND it's currently being fetched
  const shouldShowLoader = loading || (user && isProfileLoading && !hasProfile);

  if (shouldShowLoader) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="flex flex-col items-center gap-4">
          <Loader2 className="h-8 w-8 animate-spin text-primary" />
          <p className="text-muted-foreground">Loading...</p>
        </div>
      </div>
    );
  }

  if (!user || !session) {
    return null;
  }

  if (requireAppAdmin) {
    const r = user.user_metadata?.role;
    if (r !== USER_ROLES.ADMIN) {
      return (
        <Navigate to={r === 'student' ? '/student/dashboard' : '/teacher/dashboard'} replace />
      );
    }
  }

  if (requiredRole) {
    const actualRole = user.user_metadata?.role;
    const isAdmin = actualRole === USER_ROLES.ADMIN;
    const adminOnStudentAssignment =
      isAdmin && requiredRole === 'student' && location.pathname.startsWith('/student/assignment/');

    if (isAdmin && requiredRole === 'student' && !adminOnStudentAssignment) {
      return <Navigate to="/teacher/dashboard" replace />;
    }

    const roleOk =
      actualRole === requiredRole ||
      (requiredRole === 'teacher' && isAdmin) ||
      adminOnStudentAssignment;
    if (!roleOk) {
      if (actualRole !== 'teacher' && actualRole !== 'student' && !isAdmin) {
        return <Navigate to="/role-selection" replace />;
      }
      return null;
    }
  }

  return <>{children}</>;
};

export default ProtectedRoute;

import { useEffect, useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import {
  Radar,
  RadarChart as RechartsRadarChart,
  PolarGrid,
  PolarAngleAxis,
  PolarRadiusAxis,
  ResponsiveContainer,
  Tooltip,
} from 'recharts';
import type { FiveDDimensionKey, FiveDScores, FiveDQedMeasures } from '@/types/models';
import { Checkbox } from '@/components/ui/checkbox';
import { Label } from '@/components/ui/label';
import { DIMENSION_CONFIG, QED_LAYER_CONFIG } from '@/config/constants';
import { FIVE_D_DIMENSION_KEYS } from '@/lib/fiveDScores';
import { getLayerChartValue, hasDualLayerQedData, type QedLayerKey } from '@/lib/qedMeasures';

interface RadarChartProps {
  scores: FiveDScores;
  qedMeasures?: FiveDQedMeasures | null;
  explanations?: Partial<Record<keyof FiveDScores, string>> | null;
  showLabels?: boolean;
  height?: number;
  /** Side-by-side legend (default) or stacked centered chart for compact/PDF views. */
  layerControlsLayout?: 'side' | 'stacked';
}

type ChartPoint = {
  dimension: FiveDDimensionKey;
  label: string;
  developmentValue: number;
  motivationValue: number;
  developmentRaw: number | null;
  motivationRaw: number | null;
  phase: 'up' | 'down' | null;
  next: string | null;
  explanation: string;
  scoreRaw: number | null;
};

interface CustomTooltipProps {
  active?: boolean;
  payload?: Array<{
    value: number;
    name: string;
    color: string;
    payload: ChartPoint;
  }>;
  visibleLayers: Set<QedLayerKey>;
  showMotivationLayer: boolean;
}

const CustomTooltip = ({
  active,
  payload,
  visibleLayers,
  showMotivationLayer,
}: CustomTooltipProps) => {
  const { t } = useTranslation();
  if (!active || !payload?.length) return null;

  const point = payload[0].payload;
  const blurb = point.next || point.explanation || t(`dimensions.${point.dimension}.description`);

  return (
    <div className="bg-background border border-border rounded-lg shadow-lg p-3 max-w-xs z-50">
      <p className="font-semibold text-sm mb-2">{t(`dimensions.${point.dimension}.label`)}</p>
      {visibleLayers.has('development') ? (
        <p className="text-xs mb-1" style={{ color: QED_LAYER_CONFIG.development.color }}>
          {t('qedLayers.development')}:{' '}
          {point.developmentRaw != null ? (
            <span className="font-bold">{point.developmentRaw}/100</span>
          ) : point.developmentValue > 0 ? (
            <span className="font-bold">{Math.round(point.developmentValue)}/100</span>
          ) : (
            <span>{t('dimensions.notAssessable', { defaultValue: 'N/A' })}</span>
          )}
        </p>
      ) : null}
      {showMotivationLayer && visibleLayers.has('motivation') ? (
        <p className="text-xs mb-1" style={{ color: QED_LAYER_CONFIG.motivation.color }}>
          {t('qedLayers.motivation')}:{' '}
          {point.motivationRaw != null ? (
            <span className="font-bold">{point.motivationRaw}/100</span>
          ) : point.motivationValue > 0 ? (
            <span className="font-bold">{Math.round(point.motivationValue)}/100</span>
          ) : (
            <span>{t('dimensions.notAssessable', { defaultValue: 'N/A' })}</span>
          )}
        </p>
      ) : null}
      {point.phase ? (
        <p className="text-xs text-muted-foreground mb-2">
          {t('qedLayers.phase')}:{' '}
          {point.phase === 'up' ? t('qedLayers.phaseUp') : t('qedLayers.phaseDown')}
        </p>
      ) : null}
      {point.next ? (
        <p className="text-xs text-muted-foreground border-t pt-2 mt-2 leading-relaxed">
          <span className="font-medium">{t('qedLayers.nextStep')}: </span>
          {point.next}
        </p>
      ) : (
        <p className="text-xs text-muted-foreground border-t pt-2 mt-2 leading-relaxed">{blurb}</p>
      )}
    </div>
  );
};

function layerOpacity(
  layer: QedLayerKey,
  hoveredLayer: QedLayerKey | null,
  visible: boolean
): number {
  if (!visible) return 0;
  if (hoveredLayer === null) return 1;
  return hoveredLayer === layer ? 1 : 0.25;
}

export const RadarChart = ({
  scores,
  qedMeasures,
  explanations,
  showLabels = true,
  height = 400,
  layerControlsLayout = 'side',
}: RadarChartProps) => {
  const { t } = useTranslation();
  const [hoveredDimension, setHoveredDimension] = useState<FiveDDimensionKey | null>(null);
  const [hoveredLayer, setHoveredLayer] = useState<QedLayerKey | null>(null);
  const dualLayer = hasDualLayerQedData(qedMeasures);
  const [showDevelopment, setShowDevelopment] = useState(true);
  const [showMotivation, setShowMotivation] = useState(true);

  useEffect(() => {
    setShowMotivation(dualLayer);
    setShowDevelopment(true);
  }, [dualLayer]);

  const stacked = layerControlsLayout === 'stacked';

  const data: ChartPoint[] = useMemo(
    () =>
      FIVE_D_DIMENSION_KEYS.map((dimension) => {
        const devChart = getLayerChartValue(
          qedMeasures,
          dimension,
          'development',
          scores[dimension]
        );
        const motChart = getLayerChartValue(qedMeasures, dimension, 'motivation', null);
        const dimQed = qedMeasures?.[dimension];
        return {
          dimension,
          label: t(`dimensions.${dimension}.label`),
          developmentValue: devChart ?? 0,
          motivationValue: motChart ?? 0,
          developmentRaw: dimQed?.development ?? null,
          motivationRaw: dimQed?.motivation ?? null,
          phase: dimQed?.phase ?? null,
          next: dimQed?.next ?? null,
          explanation: explanations?.[dimension] || '',
          scoreRaw: scores[dimension],
        };
      }),
    [scores, qedMeasures, explanations, t]
  );

  const visibleLayers = useMemo(() => {
    const set = new Set<QedLayerKey>();
    if (showDevelopment) set.add('development');
    if (dualLayer && showMotivation) set.add('motivation');
    return set;
  }, [showDevelopment, showMotivation, dualLayer]);

  const devConfig = QED_LAYER_CONFIG.development;
  const motConfig = QED_LAYER_CONFIG.motivation;
  const devOpacity = layerOpacity('development', hoveredLayer, showDevelopment);
  const motOpacity = layerOpacity('motivation', hoveredLayer, dualLayer && showMotivation);

  return (
    <div className="w-full">
      <div
        className={
          stacked
            ? 'flex flex-col items-center gap-3'
            : 'flex flex-col sm:flex-row gap-4 items-stretch'
        }
      >
        <div className={stacked ? 'w-full' : 'flex-1 min-w-0'}>
          <ResponsiveContainer width="100%" height={height}>
            <RechartsRadarChart
              data={data}
              margin={
                stacked
                  ? { top: 12, right: 28, bottom: 12, left: 28 }
                  : { top: 8, right: 36, bottom: 8, left: 36 }
              }
            >
              <PolarGrid stroke="hsl(var(--border))" />
              <PolarAngleAxis
                dataKey="label"
                tick={({ payload, x, y, textAnchor }) => {
                  const dimension = data[payload.index].dimension;
                  const isHovered = hoveredDimension === dimension;
                  const color = DIMENSION_CONFIG[dimension].color;
                  const isTopAxis = dimension === 'vision';
                  const tickY = typeof y === 'number' ? y : Number(y);

                  return (
                    <text
                      x={x}
                      y={isTopAxis ? tickY - 10 : tickY}
                      textAnchor={textAnchor}
                      fill={isHovered ? color : 'hsl(var(--foreground))'}
                      fontSize={isHovered ? 14 : 12}
                      fontWeight={isHovered ? 'bold' : 'normal'}
                      className="cursor-pointer transition-all duration-200"
                      onMouseEnter={() => setHoveredDimension(dimension)}
                      onMouseLeave={() => setHoveredDimension(null)}
                    >
                      {payload.value}
                    </text>
                  );
                }}
              />
              <PolarRadiusAxis
                angle={90}
                domain={[0, 100]}
                tick={{ fill: 'hsl(var(--muted-foreground))', fontSize: 10 }}
              />
              {showDevelopment ? (
                <Radar
                  name={t('qedLayers.development')}
                  dataKey="developmentValue"
                  stroke={devConfig.color}
                  fill={devConfig.color}
                  fillOpacity={devConfig.fillOpacity * devOpacity}
                  strokeWidth={devConfig.strokeWidth}
                  strokeOpacity={devOpacity}
                  isAnimationActive={false}
                />
              ) : null}
              {dualLayer && showMotivation ? (
                <Radar
                  name={t('qedLayers.motivation')}
                  dataKey="motivationValue"
                  stroke={motConfig.color}
                  fill={motConfig.color}
                  fillOpacity={motConfig.fillOpacity * motOpacity}
                  strokeWidth={motConfig.strokeWidth}
                  strokeOpacity={motOpacity}
                  strokeDasharray={motConfig.dash}
                  isAnimationActive={false}
                />
              ) : null}
              <Tooltip
                content={({ active, payload }) => (
                  <CustomTooltip
                    active={active}
                    payload={payload as CustomTooltipProps['payload']}
                    visibleLayers={visibleLayers}
                    showMotivationLayer={dualLayer}
                  />
                )}
              />
            </RechartsRadarChart>
          </ResponsiveContainer>
        </div>

        <div
          className={
            stacked
              ? 'flex flex-row flex-wrap justify-center gap-4 w-full'
              : 'flex sm:flex-col justify-center gap-4 sm:min-w-[10rem] sm:border-s sm:ps-4 border-border shrink-0'
          }
          onMouseLeave={() => setHoveredLayer(null)}
        >
          <div
            className="flex items-start gap-2 rounded-lg p-2 transition-opacity cursor-default"
            style={{ opacity: hoveredLayer === 'motivation' ? 0.5 : 1 }}
            onMouseEnter={() => setHoveredLayer('development')}
          >
            <Checkbox
              id="qed-layer-development"
              checked={showDevelopment}
              onCheckedChange={(v) => setShowDevelopment(v === true)}
            />
            <Label htmlFor="qed-layer-development" className="cursor-pointer leading-tight">
              <span
                className="inline-block w-3 h-3 rounded-full me-1.5 align-middle"
                style={{ backgroundColor: devConfig.color }}
              />
              {t('qedLayers.development')}
            </Label>
          </div>
          {dualLayer ? (
            <div
              className="flex items-start gap-2 rounded-lg p-2 transition-opacity cursor-default"
              style={{ opacity: hoveredLayer === 'development' ? 0.5 : 1 }}
              onMouseEnter={() => setHoveredLayer('motivation')}
            >
              <Checkbox
                id="qed-layer-motivation"
                checked={showMotivation}
                onCheckedChange={(v) => setShowMotivation(v === true)}
              />
              <Label htmlFor="qed-layer-motivation" className="cursor-pointer leading-tight">
                <span
                  className="inline-block w-3 h-3 rounded-full me-1.5 align-middle border border-dashed"
                  style={{
                    backgroundColor: motConfig.color,
                    borderColor: motConfig.color,
                  }}
                />
                {t('qedLayers.motivation')}
              </Label>
            </div>
          ) : null}
        </div>
      </div>

      {showLabels ? (
        <div className="mt-4 grid grid-cols-1 md:grid-cols-2 gap-4">
          {FIVE_D_DIMENSION_KEYS.map((dimension) => {
            const config = DIMENSION_CONFIG[dimension];
            const point = data.find((d) => d.dimension === dimension)!;
            const explanation = explanations?.[dimension];
            const isHovered = hoveredDimension === dimension;

            return (
              <div
                key={dimension}
                className={`flex items-start gap-3 p-3 rounded-lg transition-all duration-200 cursor-pointer ${isHovered ? 'bg-card shadow-md scale-105 ring-1' : 'bg-muted/30'}`}
                style={
                  {
                    '--tw-ring-color': isHovered ? config.color : 'transparent',
                  } as React.CSSProperties
                }
                onMouseEnter={() => setHoveredDimension(dimension)}
                onMouseLeave={() => setHoveredDimension(null)}
              >
                <div
                  className="w-3 h-3 rounded-full mt-1 flex-shrink-0"
                  style={{ backgroundColor: config.color }}
                />
                <div className="flex-1 min-w-0">
                  <div className="flex justify-between items-baseline mb-1 gap-2">
                    <span className={`text-sm font-semibold ${isHovered ? 'text-foreground' : ''}`}>
                      {t(`dimensions.${dimension}.label`)}
                    </span>
                    <div className="text-end shrink-0">
                      {showDevelopment ? (
                        <span
                          className="text-xs font-bold block"
                          style={{ color: devConfig.color }}
                        >
                          D:{' '}
                          {point.developmentRaw != null
                            ? `${point.developmentRaw}/100`
                            : point.scoreRaw != null
                              ? `${Math.round(point.scoreRaw * 10)}/100`
                              : t('dimensions.notAssessable', { defaultValue: 'N/A' })}
                        </span>
                      ) : null}
                      {dualLayer && showMotivation && point.motivationRaw != null ? (
                        <span
                          className="text-xs font-bold block"
                          style={{ color: motConfig.color }}
                        >
                          M: {point.motivationRaw}/100
                        </span>
                      ) : null}
                    </div>
                  </div>
                  <p className="text-xs text-muted-foreground leading-relaxed">
                    {point.next || explanation || t(`dimensions.${dimension}.description`)}
                  </p>
                </div>
              </div>
            );
          })}
        </div>
      ) : null}
    </div>
  );
};

import { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { toast } from 'sonner';
import { LoadingSpinner } from './common/LoadingSpinner';
import { FiveDChart } from './FiveDChart';
import type { FiveDScores, FiveDSnapshot, FiveDQedMeasures } from '@/types/models';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { supabase } from '@/integrations/supabase/client';
import { selectBestSubmissionIdForAggregate } from '@/lib/bestSubmission';
import { averageFiveDScoresAcrossSnapshots } from '@/lib/fiveDScores';
import { averageQedMeasuresAcrossSnapshots, parseQedMeasures } from '@/lib/qedMeasures';

interface StudentAnalyticsProps {
  studentId: string;
  classroomId: string;
  currentSubmissionId?: string;
}

interface SubmissionInfo {
  id: string;
  title: string;
  submitted_at: string;
}

export const StudentAnalytics = ({
  studentId,
  classroomId,
  currentSubmissionId,
}: StudentAnalyticsProps) => {
  const { t } = useTranslation();
  const [loading, setLoading] = useState(true);
  const [viewMode, setViewMode] = useState<'average' | 'perSubmission'>('perSubmission');
  const [selectedSubmissionId, setSelectedSubmissionId] = useState(currentSubmissionId || '');
  const [submissions, setSubmissions] = useState<SubmissionInfo[]>([]);
  const [averageScores, setAverageScores] = useState<{
    scores: FiveDScores;
    score_explanations: FiveDSnapshot['score_explanations'];
    qed_measures: FiveDQedMeasures | null;
  } | null>(null);
  const [perSubmissionScores, setPerSubmissionScores] = useState<{
    scores: FiveDScores;
    score_explanations: FiveDSnapshot['score_explanations'];
    qed_measures: FiveDQedMeasures | null;
  } | null>(null);

  useEffect(() => {
    fetchData();
  }, [studentId, classroomId]);

  useEffect(() => {
    if (viewMode === 'perSubmission' && selectedSubmissionId) {
      fetchPerSubmissionData();
    }
  }, [selectedSubmissionId, viewMode]);

  const fetchData = async () => {
    try {
      setLoading(true);

      const { data: assignmentsData } = await supabase
        .from('assignments')
        .select('id')
        .eq('classroom_id', classroomId);

      if (!assignmentsData?.length) {
        setLoading(false);
        return;
      }

      const submissionsData = await supabase
        .from('submissions')
        .select('id, submitted_at, assignment_id, status, attempt_number, assignments(title)')
        .eq('student_id', studentId)
        .in(
          'assignment_id',
          assignmentsData.map((a) => a.id)
        )
        .order('submitted_at', { ascending: false });

      if (submissionsData.data) {
        const rows = submissionsData.data;
        const submissionsList = rows.map((sub) => ({
          id: sub.id,
          title: (sub.assignments as any)?.title || 'Unknown Assignment',
          submitted_at: sub.submitted_at || new Date().toISOString(),
        }));
        setSubmissions(submissionsList);

        if (submissionsList.length && !selectedSubmissionId) {
          setSelectedSubmissionId(currentSubmissionId || submissionsList[0].id);
        }

        const submissionIds = rows.map((s) => s.id);
        const { data: snapshotsData } = await supabase
          .from('five_d_snapshots')
          .select('submission_id, scores, score_explanations, qed_measures')
          .eq('user_id', studentId)
          .in('submission_id', submissionIds);

        const snapBySub = new Map((snapshotsData ?? []).map((s) => [s.submission_id, s]));

        const byAssignment = new Map<string, typeof rows>();
        for (const s of rows) {
          const list = byAssignment.get(s.assignment_id) || [];
          list.push(s);
          byAssignment.set(s.assignment_id, list);
        }

        const bestForAverage: NonNullable<typeof snapshotsData> = [];
        for (const [, attempts] of byAssignment) {
          const map = new Map<string, { scores: unknown }>();
          for (const a of attempts) {
            const sn = snapBySub.get(a.id);
            if (sn) map.set(a.id, { scores: sn.scores });
          }
          const bestId = selectBestSubmissionIdForAggregate(
            attempts.map((a) => ({
              id: a.id,
              attempt_number: a.attempt_number ?? 1,
              status: a.status as 'in_progress' | 'completed',
              submitted_at: a.submitted_at || null,
            })),
            map
          );
          if (bestId && snapBySub.has(bestId)) {
            bestForAverage.push(snapBySub.get(bestId)!);
          }
        }

        if (bestForAverage.length) {
          const avgScores = averageFiveDScoresAcrossSnapshots(
            bestForAverage.map((snapshot) => ({
              scores: snapshot.scores as unknown as FiveDScores,
            }))
          );

          if (avgScores) {
            const avgQed = averageQedMeasuresAcrossSnapshots(bestForAverage);
            setAverageScores({
              scores: avgScores,
              score_explanations: null,
              qed_measures: avgQed,
            });
          }
        }
      }
    } catch (error) {
      toast.error(t('analytics.loadError'));
    } finally {
      setLoading(false);
    }
  };

  const fetchPerSubmissionData = async () => {
    if (!selectedSubmissionId) return;

    try {
      const { data } = await supabase
        .from('five_d_snapshots')
        .select('scores, score_explanations, qed_measures')
        .eq('user_id', studentId)
        .eq('submission_id', selectedSubmissionId)
        .order('created_at', { ascending: false })
        .limit(1)
        .maybeSingle();

      setPerSubmissionScores(
        data
          ? {
              scores: data.scores as unknown as FiveDScores,
              score_explanations: data.score_explanations as unknown,
              qed_measures: parseQedMeasures(data.qed_measures),
            }
          : null
      );
    } catch {
      toast.error(t('analytics.scoresError'));
    }
  };

  if (loading) {
    return (
      <Card className="bg-card border-border">
        <CardContent className="py-12">
          <LoadingSpinner />
        </CardContent>
      </Card>
    );
  }

  if (submissions.length === 0) {
    return (
      <Card className="bg-card border-border">
        <CardHeader>
          <CardTitle className="text-foreground">{t('studentAnalytics.title')}</CardTitle>
          <CardDescription className="text-muted-foreground">
            {t('studentAnalytics.noSubmissions')}
          </CardDescription>
        </CardHeader>
      </Card>
    );
  }

  return (
    <Card className="bg-card border-border">
      <CardHeader>
        <CardTitle className="text-foreground">{t('studentAnalytics.title')}</CardTitle>
        <CardDescription className="text-muted-foreground">
          {submissions.length === 1
            ? t('studentAnalytics.developmentAcross', { count: submissions.length })
            : t('studentAnalytics.developmentAcrossPlural', { count: submissions.length })}
        </CardDescription>
      </CardHeader>
      <CardContent>
        <Tabs value={viewMode} onValueChange={(v) => setViewMode(v as 'average' | 'perSubmission')}>
          <TabsList className="grid w-full grid-cols-2 bg-muted/30">
            <TabsTrigger
              value="perSubmission"
              className="text-foreground data-[state=active]:bg-card"
            >
              {t('studentAnalytics.perSubmission')}
            </TabsTrigger>
            <TabsTrigger value="average" className="text-foreground data-[state=active]:bg-card">
              {t('studentAnalytics.allSubmissionsAverage')}
            </TabsTrigger>
          </TabsList>

          <TabsContent value="perSubmission" className="mt-6">
            {perSubmissionScores ? (
              <div className="space-y-4">
                <div className="text-sm text-muted-foreground">
                  {t('studentAnalytics.scoresFromSubmission')}
                </div>
                <FiveDChart
                  scores={perSubmissionScores.scores}
                  qedMeasures={perSubmissionScores.qed_measures}
                  explanations={perSubmissionScores.score_explanations}
                />
              </div>
            ) : (
              <div className="text-center py-8 text-muted-foreground">
                No score data available for this submission
              </div>
            )}
          </TabsContent>

          <TabsContent value="average" className="mt-6">
            {averageScores ? (
              <div className="space-y-4">
                <div className="text-sm text-muted-foreground">
                  Average across all {submissions.length} submission
                  {submissions.length !== 1 ? 's' : ''} in this classroom
                </div>
                <FiveDChart
                  scores={averageScores.scores}
                  qedMeasures={averageScores.qed_measures}
                  explanations={null}
                />
              </div>
            ) : (
              <div className="text-center py-8 text-muted-foreground">No score data available</div>
            )}
          </TabsContent>
        </Tabs>
      </CardContent>
    </Card>
  );
};

