  variant = 'stack',
  onOpen,
}: SubmissionCardProps) => {
  const { t } = useTranslation();
  const { isRTL } = useLanguage();
  const navigate = useNavigate();

  const showDetails = variant !== 'list';
  /** Detailed layout + timeline use richer metadata and larger type */
  const isRich = variant === 'detailed';
  const msgCount = submission.conversation_context?.length ?? 0;
  const feedbackMaxLen = isRich ? 280 : 160;
  const chatPreviewMax = isRich ? 140 : 0;

  const feedbackPreview = useMemo(() => {
    if (!submission.teacher_feedback?.trim()) return '';
    return stripFeedbackPreview(submission.teacher_feedback, feedbackMaxLen);
  }, [submission.teacher_feedback, feedbackMaxLen]);

  const chatPreview = useMemo(
    () =>
      isRich && chatPreviewMax > 0
        ? lastChatSnippet(submission.conversation_context, chatPreviewMax)
        : '',
    [isRich, submission.conversation_context, chatPreviewMax]
  );

  const initials = submission.student_name
    .split(' ')
    .map((n) => n[0])
    .join('')
    .toUpperCase()
    .slice(0, 2);

  const pending = submission.id.startsWith('pending-');
  const isSubmitted = !pending && submission.status === 'completed';

  const displayAssignmentTitle = formatSubmissionAssignmentTitle(
    submission.assignment_title,
    submission.attempt_number,
    submissionAttemptCount
  );

  const avatarClass =
    variant === 'list' || variant === 'compact'
      ? 'h-9 w-9'
      : variant === 'detailed'
        ? 'h-11 w-11'
        : 'h-10 w-10';

  const titleClass = cn(
    'font-bold text-foreground leading-snug line-clamp-2 min-w-0 flex-1',
    variant === 'detailed' && 'text-xl sm:text-2xl',
    variant === 'compact' && 'text-base',
    variant === 'stack' && 'text-lg'
  );

  const detailRowClass = cn(
    'flex items-start gap-2 text-muted-foreground',
    isRich ? 'text-base' : 'text-sm'
  );
  const detailIconClass = cn('shrink-0', isRich ? 'h-4 w-4 mt-1' : 'h-4 w-4 mt-0.5');

  const studentBlock = (
    <div className="flex items-center gap-2 min-w-0 justify-start">
      <Avatar
        className={cn(
          avatarClass,
          'shrink-0 rounded-full border-2 border-border shadow-sm overflow-hidden'
        )}
      >
        <SecureAvatarImage
          src={submission.student_avatar_url}
          bucket={STUDENT_AVATARS_BUCKET}
          alt=""
          className="h-full w-full object-cover"
        />
        <AvatarFallback
          className={cn(
            'bg-primary/10 text-primary font-bold',
            variant === 'compact' || variant === 'list' ? 'text-xs' : 'text-sm'
          )}
        >
          {initials}
        </AvatarFallback>
      </Avatar>
      <span
        className={cn(
          'font-medium text-foreground truncate',
          variant === 'list' && 'text-sm sm:text-base',
          variant !== 'list' && (isRich ? 'text-base sm:text-lg' : 'text-base')
        )}
      >
        {submission.student_name}
      </span>
    </div>
  );

  const dateBlock = (
    <time
      className={cn(
        'text-muted-foreground tabular-nums shrink-0',
        variant === 'list' && 'text-sm sm:text-base font-medium',
        variant !== 'list' && (isRich ? 'text-sm sm:text-base' : 'text-sm')
      )}
      dateTime={submission.submitted_at}
    >
      {new Date(submission.submitted_at).toLocaleDateString()}
    </time>
  );

  const statusBadge = (
    <Badge
      variant={isSubmitted ? 'default' : 'secondary'}
      className={cn(
        'shrink-0 rounded-full px-2.5 py-0.5 font-medium text-xs',
        isSubmitted
          ? 'bg-success/20 text-success dark:bg-success/30 dark:text-success-foreground'
          : 'bg-yellow-500/20 text-yellow-700 dark:bg-yellow-500/30 dark:text-yellow-400'
      )}
    >
      {pending
        ? t('submissionCard.notStarted')
        : isSubmitted
          ? t('submissionCard.completed')
          : t('submissionCard.inProgress')}
    </Badge>
  );

  const showTeacherPreview = !pending && Boolean(submission.is_teacher_attempt);
  const teacherPreviewBadge = showTeacherPreview ? (
    <Badge
      variant="outline"
      className="shrink-0 rounded-full border-border bg-muted/50 px-2.5 py-0.5 text-xs font-medium text-foreground"
    >
      {t('submissionDetail.teacherTryBadge')}
    </Badge>
  ) : null;

  const showChatFlowBadge =
    !pending &&
    isChatLikeAssignmentType(submission.assignment_type) &&
    (submission.conversation_complete_at_submit === true ||
      submission.conversation_complete_at_submit === false);

  const chatFlowBadge = showChatFlowBadge ? (
    <Badge
      variant="outline"
      className={cn(
        'shrink-0 rounded-full px-2.5 py-0.5 font-medium text-xs',
        submission.conversation_complete_at_submit
          ? 'border-success/40 bg-success/10 text-success'
          : 'border-amber-500/50 bg-amber-500/10 text-amber-800 dark:text-amber-200'
      )}
    >
      {submission.conversation_complete_at_submit
        ? t('submissionCard.conversationFlowComplete')
        : t('submissionCard.conversationFlowEarly')}
    </Badge>
  ) : null;

  const flaggedSentencesBadge = (
    <SubmissionFlaggedSentencesBadge
      count={submission.chat_sentence_flag_count ?? 0}
      assignmentType={submission.assignment_type}
    />
  );

  const clipboardActivityBadge = (
    <SubmissionClipboardActivityBadge
      hasCopy={submission.clipboard_has_copy ?? false}
      hasPaste={submission.clipboard_has_paste ?? false}
    />
  );

  const topRow = (
    <div className="flex items-start justify-between gap-3">
      <h3 className={titleClass}>{displayAssignmentTitle}</h3>
      <div className="flex shrink-0 flex-col items-end gap-1.5 sm:flex-row sm:flex-wrap sm:items-center sm:justify-end">
        {flaggedSentencesBadge}
        {clipboardActivityBadge}
        {chatFlowBadge}
        {teacherPreviewBadge}
        {statusBadge}
      </div>
    </div>
  );

  const detailsBlock = showDetails && (
    <div className={cn('w-full text-start space-y-2', isRich && 'space-y-3')}>
      <p className={detailRowClass}>
        <Clock className={detailIconClass} aria-hidden />
        <span className="leading-snug">
          {new Date(submission.submitted_at).toLocaleString(undefined, {
            dateStyle: 'medium',
            timeStyle: 'short',
          })}
        </span>
      </p>
      {!pending && (
        <p className={detailRowClass}>
          <MessageSquare className={detailIconClass} aria-hidden />
          <span>{t('submissionCard.chatMessages', { count: msgCount })}</span>
        </p>
      )}
      {isRich && !pending && chatPreview && (
        <p className={detailRowClass}>
          <MessageSquare className={detailIconClass} aria-hidden />
          <span>
            <span className="font-medium text-foreground/90">
              {t('submissionCard.latestInChat')}{' '}
            </span>
            <span className="line-clamp-4 text-foreground/80">{chatPreview}</span>
          </span>
        </p>
      )}
      <p className={cn('leading-snug text-muted-foreground', isRich ? 'text-base' : 'text-sm')}>
        <span className={cn('font-medium text-foreground', isRich && 'text-foreground')}>
          {t('submissionCard.feedbackLabel')}{' '}
        </span>
        {pending ? (
          <span>{t('submissionCard.notStarted')}</span>
        ) : submission.has_feedback ? (
          feedbackPreview ? (
            <span className={cn('text-foreground/90', isRich ? 'line-clamp-6' : 'line-clamp-3')}>
              {feedbackPreview}
            </span>
          ) : (
            <span>{t('submissionCard.feedbackRecorded')}</span>
          )
        ) : (
          <span>{t('submissionCard.awaitingFeedback')}</span>
        )}
      </p>
    </div>
  );

  const bottomRow = (
    <div className="flex w-full justify-between items-center gap-3">
      {studentBlock}
      {dateBlock}
    </div>
  );

  const isList = variant === 'list';

  const listAvatar = (
    <Avatar
      className={cn(
        'h-10 w-10 shrink-0 rounded-full border-2 border-border bg-muted/40 shadow-sm overflow-hidden'
      )}
    >
      <SecureAvatarImage
        src={submission.student_avatar_url}
        bucket={STUDENT_AVATARS_BUCKET}
        alt=""
        className="h-full w-full object-cover"
      />
      <AvatarFallback className="bg-primary/10 text-primary text-xs font-bold">
        {initials}
      </AvatarFallback>
    </Avatar>
  );

  const listRow = (
    <div className="flex w-full items-center gap-3">
      <div className="shrink-0">{listAvatar}</div>
      <div className="min-w-0 flex-1 flex flex-col gap-2">
        <div className="flex items-start justify-between gap-2 sm:gap-3">
          <h3 className="min-w-0 flex-1 text-start font-semibold leading-snug text-foreground line-clamp-2 text-base sm:text-[1.0625rem]">
            {displayAssignmentTitle}
          </h3>
          <div className="flex shrink-0 flex-col items-end gap-1 sm:flex-row sm:flex-wrap sm:items-center sm:justify-end sm:pt-0.5">
            {flaggedSentencesBadge}
            {clipboardActivityBadge}
            {chatFlowBadge}
            {teacherPreviewBadge}
            {statusBadge}
          </div>
        </div>
        <div className="flex items-center justify-between gap-3 min-w-0">
          <p className="text-start text-sm text-muted-foreground truncate min-w-0 flex-1 pe-2">
            {submission.student_name}
          </p>
          <time
            className="shrink-0 tabular-nums text-sm font-medium text-muted-foreground whitespace-nowrap"
            dateTime={submission.submitted_at}
          >
            {new Date(submission.submitted_at).toLocaleDateString()}
          </time>
        </div>
      </div>
    </div>
  );

  return (
    <button
      type="button"
      dir={isRTL ? 'rtl' : 'ltr'}
      disabled={pending}
      onClick={() => {
        if (onOpen) onOpen(submission.id);
        else navigate(`/teacher/submission/${submission.id}`);
      }}
      className={cn(
        'w-full text-start flex flex-col transition-all',
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background',
        'disabled:opacity-60 disabled:pointer-events-none cursor-pointer disabled:cursor-not-allowed',
        isList &&
          'flex-none h-auto rounded-xl border border-border/80 bg-card p-4 shadow-sm hover:border-border hover:bg-muted/20 hover:shadow-md sm:p-4',
        !isList &&
          'rounded-xl border-none shadow-sm hover:shadow-md transition-all bg-card ring-1 ring-border',
        isList && 'min-h-0',
        !isList && variant === 'compact' && 'gap-3 p-4 min-h-[280px]',
        !isList && variant === 'detailed' && 'gap-6 p-6 sm:p-8 min-h-[480px]',
        !isList && variant === 'stack' && 'gap-4 p-5 sm:p-6 min-h-[400px]'
      )}
    >
      {isList ? (
        listRow
      ) : (
        <>
          {topRow}
          {detailsBlock}
          <div
            className={cn('flex-1 w-full', isRich ? 'min-h-[2rem]' : 'min-h-[3rem]')}
            aria-hidden
          />
          <div className="mt-auto w-full pt-1">{bottomRow}</div>
        </>
      )}
    </button>
  );
};

import {
  FileText,
  Download,
  Loader2,
  Search,
  ChevronDown,
  ChevronUp,
  X,
  LayoutGrid,
  LayoutTemplate,
  List,
  Rows3,
  Table2,
  Calendar,
} from 'lucide-react';
import { useState, useMemo, useEffect, useCallback, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { useLocation, useNavigate, useSearchParams } from 'react-router-dom';
import { toast } from 'sonner';
import {
  SubmissionCard,
  formatSubmissionAssignmentTitle,
  SubmissionClipboardActivityBadge,
  SubmissionFlaggedSentencesBadge,
  type SubmissionCardVariant,
} from './SubmissionCard';
import type { SubmissionDetailLocationState } from '@/types/navigation';
import type { LucideIcon } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from '@/components/ui/collapsible';
import { DatePicker } from '@/components/ui/date-picker';
import { Input } from '@/components/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { useLanguage } from '@/contexts/LanguageContext';
import { useEnrichedClassroomSubmissions, useSyllabus } from '@/hooks/queries';
import { isChatLikeAssignmentType } from '@/lib/assignmentChatLike';
import { exportClassroomStudentWorkJson } from '@/lib/submissionExport';
import {
  applySubmissionFiltersToSearchParams,
  clearSubmissionFilterSearchParams,
  defaultSubmissionFilters,
  readSubmissionFiltersFromSearchParams,
  type SubmissionFiltersSnapshot,
} from '@/lib/submissionFilterUrl';
import { cn } from '@/lib/utils';

interface SubmissionsTabProps {
  classroomId: string;
  /** Pre-select this assignment in filters (e.g. deep link from curriculum). */
  initialAssignmentFilterId?: string;
}

export type SubmissionViewMode = 'grid' | 'compact' | 'list' | 'detailed' | 'table' | 'timeline';

const VIEW_MODE_ICONS: Record<SubmissionViewMode, LucideIcon> = {
  list: List,
  grid: LayoutGrid,
  compact: LayoutTemplate,
  detailed: Rows3,
  table: Table2,
  timeline: Calendar,
};

/** Ensures Latin labels show a capital first letter when i18n or the control leaks raw values. */
function capitalizeLatinFirstLetter(s: string) {
  if (!s) return s;
  const c = s.charAt(0);
  if (c >= 'a' && c <= 'z') return c.toUpperCase() + s.slice(1);
  return s;
}

export const SubmissionsTab = ({ classroomId, initialAssignmentFilterId }: SubmissionsTabProps) => {
  const { t } = useTranslation();
  const { isRTL } = useLanguage();
  const navigate = useNavigate();
  const location = useLocation();
  const [searchParams, setSearchParams] = useSearchParams();
  const readUrlRef = useRef(false);
  const initialAssignmentAppliedRef = useRef(false);
  const prevClassroomIdRef = useRef(classroomId);

  const defaults = defaultSubmissionFilters();

  // Filter states
  const [selectedStudent, setSelectedStudent] = useState<string>(defaults.student);
  const [selectedAssignment, setSelectedAssignment] = useState<string>(defaults.assignment);
  const [selectedModule, setSelectedModule] = useState<string>(defaults.module);
  const [selectedStatus, setSelectedStatus] = useState<string>(defaults.status);
  const [searchQuery, setSearchQuery] = useState<string>(defaults.q);
  const [startDate, setStartDate] = useState<string>(defaults.from);
  const [endDate, setEndDate] = useState<string>(defaults.to);
  const [isFiltersOpen, setIsFiltersOpen] = useState(false);
  const [viewMode, setViewMode] = useState<SubmissionViewMode>(defaults.view);
  const [exporting, setExporting] = useState(false);

  const { data: submissions = [], isLoading: loading } =
    useEnrichedClassroomSubmissions(classroomId);
  const { data: syllabus } = useSyllabus(classroomId);

  const submissionReturnTo = `${location.pathname}${location.search}`;

  const openSubmission = useCallback(
    (submissionId: string) => {
      navigate(`/teacher/submission/${submissionId}`, {
        state: { returnTo: submissionReturnTo } satisfies SubmissionDetailLocationState,
      });
    },
    [navigate, submissionReturnTo]
  );

  const applyFilters = useCallback(
    (patch: Partial<SubmissionFiltersSnapshot>) => {
      const next: SubmissionFiltersSnapshot = {
        module: patch.module ?? selectedModule,
        assignment: patch.assignment ?? selectedAssignment,
        student: patch.student ?? selectedStudent,
        status: patch.status ?? selectedStatus,
        from: patch.from ?? startDate,
        to: patch.to ?? endDate,
        q: patch.q ?? searchQuery,
        view: patch.view ?? viewMode,
      };
      setSelectedModule(next.module);
      setSelectedAssignment(next.assignment);
      setSelectedStudent(next.student);
      setSelectedStatus(next.status);
      setStartDate(next.from);
      setEndDate(next.to);
      setSearchQuery(next.q);
      setViewMode(next.view);
      setSearchParams((prev) => applySubmissionFiltersToSearchParams(prev, next), {
        replace: true,
      });
    },
    [
      endDate,
      searchQuery,
      selectedAssignment,
      selectedModule,
      selectedStatus,
      selectedStudent,
      setSearchParams,
      startDate,
      viewMode,
    ]
  );

  useEffect(() => {
    if (prevClassroomIdRef.current === classroomId) return;
    prevClassroomIdRef.current = classroomId;
    readUrlRef.current = false;
    initialAssignmentAppliedRef.current = false;
    const d = defaultSubmissionFilters();
    setSelectedModule(d.module);
    setSelectedStudent(d.student);
    setSelectedAssignment(d.assignment);
    setSelectedStatus(d.status);
    setSearchQuery(d.q);
    setStartDate(d.from);
    setEndDate(d.to);
    setViewMode(d.view);
    setSearchParams((prev) => clearSubmissionFilterSearchParams(prev), { replace: true });
  }, [classroomId, setSearchParams]);

  useEffect(() => {
    if (!initialAssignmentFilterId || initialAssignmentAppliedRef.current) return;
    initialAssignmentAppliedRef.current = true;
    applyFilters({ assignment: initialAssignmentFilterId });
  }, [initialAssignmentFilterId, applyFilters]);

  const modules = useMemo(() => {
    const list = syllabus?.sections ?? [];
    return [...list]
      .sort((a, b) => a.order_index - b.order_index)
      .map((s) => ({ id: s.id, title: s.title }));
  }, [syllabus?.sections]);

  const moduleIds = useMemo(() => new Set(modules.map((m) => m.id)), [modules]);
  const allAssignmentIds = useMemo(
    () => new Set(submissions.map((s) => s.assignment_id)),
    [submissions]
  );
  const allStudentIds = useMemo(() => new Set(submissions.map((s) => s.student_id)), [submissions]);

  useEffect(() => {
    if (loading || readUrlRef.current) return;
    readUrlRef.current = true;
    const fromUrl = readSubmissionFiltersFromSearchParams(searchParams, {
      moduleIds,
      assignmentIds: allAssignmentIds,
      studentIds: allStudentIds,
    });
    setSelectedModule(fromUrl.module);
    setSelectedAssignment(fromUrl.assignment);
    setSelectedStudent(fromUrl.student);
    setSelectedStatus(fromUrl.status);
    setStartDate(fromUrl.from);
    setEndDate(fromUrl.to);
    setSearchQuery(fromUrl.q);
    setViewMode(fromUrl.view);
  }, [loading, searchParams, moduleIds, allAssignmentIds, allStudentIds]);

  /** Submissions matching module scope (cascade upstream). */
  const submissionsAfterModule = useMemo(() => {
    if (selectedModule === 'all') return submissions;
    return submissions.filter((s) => s.syllabus_section_id === selectedModule);
  }, [submissions, selectedModule]);

  /** Assignment choices narrowed by selected module. */
  const assignmentsForSelect = useMemo(() => {
    return Array.from(
      new Map(
        submissionsAfterModule.map((s) => [
          s.assignment_id,
          { id: s.assignment_id, title: s.assignment_title },
        ])
      ).values()
    );
  }, [submissionsAfterModule]);

  const assignmentIdsForSelect = useMemo(
    () => new Set(assignmentsForSelect.map((a) => a.id)),
    [assignmentsForSelect]
  );

  /** Submissions matching module + assignment scope. */
  const submissionsAfterModuleAndAssignment = useMemo(() => {
    if (selectedAssignment === 'all') return submissionsAfterModule;
    return submissionsAfterModule.filter((s) => s.assignment_id === selectedAssignment);
  }, [submissionsAfterModule, selectedAssignment]);

  /** Student choices narrowed by module and assignment. */
  const studentsForSelect = useMemo(() => {
    return Array.from(
      new Map(
        submissionsAfterModuleAndAssignment.map((s) => [
          s.student_id,
          { id: s.student_id, name: s.student_name },
        ])
      ).values()
    );
  }, [submissionsAfterModuleAndAssignment]);

  const studentIdsForSelect = useMemo(
    () => new Set(studentsForSelect.map((s) => s.id)),
    [studentsForSelect]
  );

  useEffect(() => {
    if (loading) return;
    if (selectedAssignment !== 'all' && !assignmentIdsForSelect.has(selectedAssignment)) {
      applyFilters({ assignment: 'all' });
    }
  }, [loading, selectedModule, assignmentIdsForSelect, selectedAssignment, applyFilters]);

  useEffect(() => {
    if (loading) return;
    if (selectedStudent !== 'all' && !studentIdsForSelect.has(selectedStudent)) {
      applyFilters({ student: 'all' });
    }
  }, [
    loading,
    selectedAssignment,
    selectedModule,
    studentIdsForSelect,
    selectedStudent,
    applyFilters,
  ]);

  /** Rows per (student, assignment) — used to hide #1 when only one attempt exists. */
  const attemptCountByStudentAssignment = useMemo(() => {
    const m = new Map<string, number>();
    for (const s of submissions) {
      const key = `${s.student_id}:${s.assignment_id}`;
      m.set(key, (m.get(key) ?? 0) + 1);
    }
    return m;
  }, [submissions]);

  // Memoize filtered submissions to avoid recalculating on every render
  const filteredSubmissions = useMemo(() => {
    // Use selectedStatus for filtering
    const effectiveStatus = selectedStatus;

    let filtered = [...submissions];

    if (selectedStudent !== 'all') {
      filtered = filtered.filter((s) => s.student_id === selectedStudent);
    }

    if (selectedAssignment !== 'all') {
      filtered = filtered.filter((s) => s.assignment_id === selectedAssignment);
    }

    if (selectedModule !== 'all') {
      filtered = filtered.filter((s) => s.syllabus_section_id === selectedModule);
    }

    if (effectiveStatus === 'completed') {
      filtered = filtered.filter((s) => s.status === 'completed');
    } else if (effectiveStatus === 'in_progress') {
      filtered = filtered.filter((s) => s.status === 'in_progress');
    }

    if (startDate) {
      filtered = filtered.filter((s) => new Date(s.submitted_at) >= new Date(startDate));
    }

    if (endDate) {
      // Add one day to include the end date fully
      const end = new Date(endDate);
      end.setDate(end.getDate() + 1);
      filtered = filtered.filter((s) => new Date(s.submitted_at) < end);
    }

    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase();
      filtered = filtered.filter((s) => {
        // Search in teacher feedback and metadata (conversation text loads on submission detail only)
        const feedbackText = s.teacher_feedback?.toLowerCase() || '';
        const metaText = `${s.student_name} ${s.assignment_title}`.toLowerCase();

        return feedbackText.includes(query) || metaText.includes(query);
      });
    }

    return filtered;
  }, [
    submissions,
    selectedStudent,
    selectedAssignment,
    selectedModule,
    selectedStatus,
    searchQuery,
    startDate,
    endDate,
  ]);

  const timelineSubmissions = useMemo(
    () =>
      [...filteredSubmissions].sort(
        (a, b) => new Date(b.submitted_at).getTime() - new Date(a.submitted_at).getTime()
      ),
    [filteredSubmissions]
  );

  const cardVariantForView = useMemo((): SubmissionCardVariant => {
    switch (viewMode) {
      case 'compact':
        return 'compact';
      case 'detailed':
        return 'detailed';
      case 'list':
        return 'list';
      case 'grid':
      default:
        return 'stack';
    }
  }, [viewMode]);

  const activeFiltersCount = [
    selectedStudent !== 'all',
    selectedAssignment !== 'all',
    selectedModule !== 'all',
    selectedStatus !== 'all',
    startDate !== '',
    endDate !== '',
  ].filter(Boolean).length;

  /** Status + date only — drives "More filters" trigger badge/highlight (scope filters stay visible above). */
  const secondaryFiltersCount = [selectedStatus !== 'all', startDate !== '', endDate !== ''].filter(
    Boolean
  ).length;

  const clearFilters = () => {
    applyFilters(defaultSubmissionFilters());
  };

  const handleModuleChange = (module: string) => {
    applyFilters({ module, assignment: 'all', student: 'all' });
  };

  const handleAssignmentChange = (assignment: string) => {
    applyFilters({ assignment });
  };

  const handleBulkExport = async () => {
    if (exporting) return;

    setExporting(true);
    try {
      await exportClassroomStudentWorkJson(classroomId);
