import { AlertTriangle, CheckCircle, Clock } from 'lucide-react';
import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { toast } from 'sonner';
import SafeMathMarkdown from './SafeMathMarkdown';
import {
  ALERT_LEVEL_COLORS,
  ALERT_TYPE_LABELS,
  type AlertLevel,
  type StudentAlert,
} from '@/types/alerts';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { supabase } from '@/integrations/supabase/client';

interface WellbeingAlertCardProps {
  alerts: StudentAlert[];
  studentName: string;
  onAcknowledge?: () => void;
}

export const WellbeingAlertCard = ({
  alerts,
  studentName,
  onAcknowledge,
}: WellbeingAlertCardProps) => {
  const { t } = useTranslation();
  const [acknowledging, setAcknowledging] = useState<string | null>(null);

  if (!alerts || alerts.length === 0) {
    return null;
  }

  // Consolidate alerts - get unique alert types and most severe level
  const uniqueAlertTypes = Array.from(new Set(alerts.map((a) => a.alert_type)));
  const hasAnyAcknowledged = alerts.some((a) => a.is_acknowledged);
  const hasAnyUnacknowledged = alerts.some((a) => !a.is_acknowledged);

  const mostSevereLevel: AlertLevel = alerts.some((a) => a.alert_level === 'critical')
    ? 'critical'
    : 'concerning';
  const colors = ALERT_LEVEL_COLORS[mostSevereLevel];

  // Get all unique triggered messages (avoid duplicates)
  const allTriggeredMessages = Array.from(
    new Map(
      alerts.flatMap((a) => a.triggered_messages).map((tm) => [tm.message_index, tm])
    ).values()
  );

  // Get the most comprehensive AI analysis (use the longest one)
  const bestAnalysis = alerts.reduce((best, current) =>
    current.ai_analysis.length > best.ai_analysis.length ? current : best
  ).ai_analysis;

  const handleAcknowledge = async (alertId: string) => {
    setAcknowledging(alertId);
    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      const { error } = await supabase
        .from('student_alerts')
        .update({
          is_acknowledged: true,
          acknowledged_at: new Date().toISOString(),
          acknowledged_by: user?.id,
        })
        .eq('id', alertId);

      if (error) throw error;

      toast.success(t('wellbeing.success'));
      onAcknowledge?.();
    } catch (_error) {
      toast.error(t('wellbeing.error'));
    } finally {
      setAcknowledging(null);
    }
  };

  const handleAcknowledgeAll = async () => {
    setAcknowledging('all');
    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      const unacknowledgedIds = alerts.filter((a) => !a.is_acknowledged).map((a) => a.id);

      const { error } = await supabase
        .from('student_alerts')
        .update({
          is_acknowledged: true,
          acknowledged_at: new Date().toISOString(),
          acknowledged_by: user?.id,
        })
        .in('id', unacknowledgedIds);

      if (error) throw error;

      toast.success(t('wellbeing.successAll'));
      onAcknowledge?.();
    } catch (_error) {
      toast.error(t('wellbeing.errorAll'));
    } finally {
      setAcknowledging(null);
    }
  };

  return (
    <Card className={`border-2 ${colors.border} ${colors.bg}`}>
      <CardHeader>
        <div className="flex items-start justify-between gap-4">
          <div className="flex items-start gap-3">
            <AlertTriangle className={`h-6 w-6 ${colors.text} mt-1`} />
            <div>
              <CardTitle className={`text-xl ${colors.text}`}>
                {mostSevereLevel === 'critical'
                  ? `🚨 ${t('wellbeing.level.critical')} ${t('wellbeing.alert')}`
                  : `⚠️ ${t('wellbeing.level.concerning')}`}
              </CardTitle>
              <CardDescription className="mt-1">
                Concerning signs detected in {studentName}'s conversation
              </CardDescription>
            </div>
          </div>
          {hasAnyUnacknowledged && (
            <Button
              variant={mostSevereLevel === 'critical' ? 'destructive' : 'default'}
              size="sm"
              onClick={handleAcknowledgeAll}
              disabled={acknowledging !== null}
            >
              {acknowledging === 'all' ? (
                <>
                  <Clock className="h-4 w-4 me-2 animate-spin" />
                  Acknowledging...
                </>
              ) : (
                <>
                  <CheckCircle className="h-4 w-4 me-2" />
                  {t('wellbeing.acknowledgeAll')}
                </>
              )}
            </Button>
          )}
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Consolidated alert display */}
        <div className="p-4 rounded-lg border bg-card/50 border-border">
          <div className="flex items-start justify-between gap-4 mb-3">
            <div className="flex flex-wrap items-center gap-2">
              <Badge variant={mostSevereLevel === 'critical' ? 'destructive' : 'default'}>
                {mostSevereLevel.toUpperCase()}
              </Badge>
              {uniqueAlertTypes.map((type) => (
                <Badge key={type} variant="outline">
                  {ALERT_TYPE_LABELS[type]}
                </Badge>
              ))}
              {hasAnyAcknowledged && (
                <Badge variant="secondary" className="gap-1">
                  <CheckCircle className="h-3 w-3" />
                  Acknowledged
                </Badge>
              )}
            </div>
          </div>

          <div className="mb-3">
            <h4 className="font-semibold text-sm mb-2 text-foreground">AI Analysis:</h4>
            <SafeMathMarkdown content={bestAnalysis} className="text-sm text-foreground/80" />
          </div>

          {allTriggeredMessages.length > 0 && (
            <div>
              <h4 className="font-semibold text-sm mb-2 text-foreground">Concerning Messages:</h4>
              <div className="space-y-2">
                {allTriggeredMessages.map((msg, idx) => (
                  <div
                    key={idx}
                    className="bg-destructive/10 border-l-4 border-destructive p-3 text-sm"
                  >
                    <SafeMathMarkdown
                      content={`"${msg.content}"`}
                      className="text-foreground font-medium mb-1"
                    />
                    <p className="text-destructive text-xs italic">{msg.reason}</p>
                  </div>
                ))}
              </div>
            </div>
          )}

          {hasAnyAcknowledged && alerts[0].acknowledged_at && (
            <div className="mt-3 pt-3 border-t border-border text-xs text-muted-foreground">
              Acknowledged on {new Date(alerts[0].acknowledged_at).toLocaleString()}
            </div>
          )}
        </div>

        {mostSevereLevel === 'critical' && (
          <div className="mt-4 p-4 bg-red-100 border border-red-300 rounded-lg">
            <p className="text-sm font-semibold text-red-900 mb-2">
              ⚠️ Immediate Action Recommended
            </p>
            <p className="text-sm text-red-800">
              This is a critical alert. Please reach out to {studentName} immediately to ensure
              their safety and wellbeing. Consider involving school counseling services or mental
              health professionals if appropriate.
            </p>
            <p className="text-xs text-red-700 mt-2">
              If you believe the student is in immediate danger, contact emergency services or your
              institution's crisis response team.
            </p>
          </div>
        )}

        {mostSevereLevel === 'concerning' && (
          <div className="mt-4 p-4 bg-yellow-50 border border-yellow-300 rounded-lg">
            <p className="text-sm font-semibold text-yellow-900 mb-2">💡 Recommended Action</p>
            <p className="text-sm text-yellow-800">
              Please check in with {studentName} to provide support and guidance. Early intervention
              can make a significant difference in student wellbeing and academic success.
            </p>
          </div>
        )}
      </CardContent>
    </Card>
  );
};

import { Loader2 } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import type { Compare5dNarrativeContext } from '@/lib/analyticsCompare5d/types';
import type { FiveDScores, FiveDQedMeasures } from '@/types/models';
import type { ReactNode } from 'react';
import { FiveDChart } from '@/components/FiveDChart';
import {
  useAnalytics5dNarrative,
  type Analytics5dNarrativeContext,
} from '@/hooks/queries/useAnalytics5dNarrative';

type Lang = 'en' | 'he';

const NarrativeFraming = ({
  isLoading,
  isError,
  scopeSummary,
  isRTL,
  evidenceSourceCount,
  children,
}: {
  isLoading: boolean;
  isError: boolean;
  scopeSummary: string | null | undefined;
  isRTL: boolean;
  /**
   * Count of text excerpts used in the evidence bundle for this call (0 = scores-and-filters only).
   * Omitted: do not show an evidence status line.
   */
  evidenceSourceCount?: number;
  children: ReactNode;
}) => {
  const { t } = useTranslation();
  const showEvidenceStatus = !isLoading && !isError && evidenceSourceCount != null;
  return (
    <div className="space-y-3">
      {isLoading && (
        <div className="flex items-center gap-2 text-sm text-muted-foreground">
          <Loader2 className="h-4 w-4 animate-spin shrink-0" />
          {t('analytics.narrative.loading')}
        </div>
      )}
      {isError && <p className="text-xs text-destructive">{t('analytics.narrative.error')}</p>}
      {scopeSummary && !isLoading && (
        <p
          className={`text-sm text-muted-foreground leading-relaxed ${
            isRTL ? 'text-right' : 'text-left'
          }`}
        >
          {scopeSummary}
        </p>
      )}
      {showEvidenceStatus && evidenceSourceCount! > 0 ? (
        <p className={`text-xs text-muted-foreground/80 ${isRTL ? 'text-right' : 'text-left'}`}>
          {t('analytics.narrative.basedOnSources', { count: evidenceSourceCount! })}
        </p>
      ) : null}
      {showEvidenceStatus && evidenceSourceCount === 0 ? (
        <p className={`text-xs text-muted-foreground/80 ${isRTL ? 'text-right' : 'text-left'}`}>
          {t('analytics.narrative.scoresOnlyHint')}
        </p>
      ) : null}
      <div className={isLoading ? 'opacity-60 pointer-events-none' : ''}>{children}</div>
    </div>
  );
};

export const MainAnalytics5dNarrativeBlock = ({
  classroomId,
  classAverage,
  classAverageQed,
  filterSummary,
  language,
  selectedStudent,
  studentName,
  isRTL,
  enabled,
  narrativeId,
  evidenceText,
  evidenceSourceCount,
}: {
  classroomId: string;
  classAverage: FiveDScores;
  classAverageQed?: FiveDQedMeasures | null;
  filterSummary: string;
  language: Lang;
  selectedStudent: string;
  studentName?: string;
  isRTL: boolean;
  enabled: boolean;
  narrativeId: string;
  evidenceText?: string;
  evidenceSourceCount?: number;
}) => {
  const context: Analytics5dNarrativeContext =
    selectedStudent === 'all' ? 'class_avg' : 'student_avg';
  const { data, isLoading, isError } = useAnalytics5dNarrative(
    {
      classroomId,
      context,
      language,
      scores: classAverage,
      filterSummary,
      studentName: selectedStudent === 'all' ? undefined : studentName,
      evidenceText,
      evidenceSourceCount,
    },
    { enabled: enabled && !!classroomId, narrativeId }
  );
  return (
    <NarrativeFraming
      isLoading={isLoading}
      isError={isError}
      scopeSummary={data?.scopeSummary}
      isRTL={isRTL}
      evidenceSourceCount={evidenceSourceCount ?? 0}
    >
      <FiveDChart
        scores={classAverage}
        qedMeasures={classAverageQed}
        explanations={data?.explanations ?? null}
      />
    </NarrativeFraming>
  );
};

export const CompareSide5dNarrativeBlock = ({
  classroomId,
  sideScores,
  sideQedMeasures,
  filterSummary,
  language,
  compareLabelA,
  compareLabelB,
  peerScores,
  isRTL,
  enabled,
  narrativeId,
  evidenceText,
  evidenceSourceCount,
  context = 'module_compare',
}: {
  classroomId: string;
  sideScores: FiveDScores;
  sideQedMeasures?: FiveDQedMeasures | null;
  filterSummary: string;
  language: Lang;
  compareLabelA: string;
  compareLabelB: string;
  peerScores: FiveDScores;
  isRTL: boolean;
  enabled: boolean;
  narrativeId: string;
  evidenceText?: string;
  evidenceSourceCount?: number;
  context?: Compare5dNarrativeContext;
}) => {
  const { data, isLoading, isError } = useAnalytics5dNarrative(
    {
      classroomId,
      context,
      language,
      scores: sideScores,
      filterSummary,
      compareLabelA,
      compareLabelB,
      peerScores,
      evidenceText,
      evidenceSourceCount,
    },
    { enabled: enabled && !!classroomId, narrativeId }
  );
  return (
    <NarrativeFraming
      isLoading={isLoading}
      isError={isError}
      scopeSummary={data?.scopeSummary}
      isRTL={isRTL}
      evidenceSourceCount={evidenceSourceCount ?? 0}
    >
      <FiveDChart
        scores={sideScores}
        qedMeasures={sideQedMeasures}
        explanations={data?.explanations ?? null}
        showLabels={false}
        layerControlsLayout="stacked"
        height={300}
      />
    </NarrativeFraming>
  );
};

export const StudentList5dNarrativeBlock = ({
  classroomId,
  studentId,
  studentName,
  scores,
  qedMeasures,
  filterSummary,
  language,
  isOpen,
  isRTL,
  enabled,
  evidenceText,
  evidenceSourceCount,
}: {
  classroomId: string;
  studentId: string;
  studentName: string;
  scores: FiveDScores;
  qedMeasures?: FiveDQedMeasures | null;
  filterSummary: string;
  language: Lang;
  isOpen: boolean;
  isRTL: boolean;
  enabled: boolean;
  evidenceText?: string;
  evidenceSourceCount?: number;
}) => {
  const { data, isLoading, isError } = useAnalytics5dNarrative(
    {
      classroomId,
      context: 'student_avg',
      language,
      scores,
      filterSummary,
      studentName,
      evidenceText,
      evidenceSourceCount,
    },
    { enabled: enabled && isOpen, narrativeId: `student-5d-${studentId}` }
  );
  return (
    <NarrativeFraming
      isLoading={isLoading}
      isError={isError}
      scopeSummary={data?.scopeSummary}
      isRTL={isRTL}
      evidenceSourceCount={evidenceSourceCount ?? 0}
    >
      <FiveDChart
        scores={scores}
        qedMeasures={qedMeasures}
        explanations={data?.explanations ?? null}
      />
    </NarrativeFraming>
  );
};

import { GitCompare } from 'lucide-react';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import type { Compare5dMode, Compare5dStudentRow } from '@/lib/analyticsCompare5d/types';
import type {
  AnalyticsModuleFilter,
  AnalyticsAssignmentRef,
  AnalyticsModuleRef,
} from '@/lib/analyticsScope';
import { Compare5dResults } from '@/components/analytics/Compare5dResults';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  assignmentsInCompareScope,
  buildCompare5dScopeSummary,
  compare5dModeAvailability,
  defaultCompare5dMode,
  resolveCompare5dSide,
  sideOptionsForCompare5dMode,
} from '@/lib/analyticsCompare5d/resolveCompare5dSide';

type Lang = 'en' | 'he';

export type AnalyticsCompare5dCardProps = {
  classroomId: string;
  modules: AnalyticsModuleRef[];
  assignments: AnalyticsAssignmentRef[];
  students: Compare5dStudentRow[];
  showUnplaced: boolean;
  structKey: string;
  analyticsLanguage: Lang;
  isRTL: boolean;
  rawSubmissions: { id: string; assignment_id: string }[];
  rawSnapshots: Compare5dStudentRow['snapshots'];
  sectionTitleResolver: (syllabusSectionId: string | null) => string;
};

export const AnalyticsCompare5dCard = ({
  classroomId,
  modules,
  assignments,
  students,
  showUnplaced,
  structKey,
  analyticsLanguage,
  isRTL,
  rawSubmissions,
  rawSnapshots,
  sectionTitleResolver,
}: AnalyticsCompare5dCardProps) => {
  const { t } = useTranslation();

  const availability = useMemo(
    () => compare5dModeAvailability(modules, showUnplaced, students, assignments),
    [modules, showUnplaced, students, assignments]
  );

  const initialMode = defaultCompare5dMode(availability);

  const [compareMode, setCompareMode] = useState<Compare5dMode>(initialMode ?? 'sections');
  const [compareSideA, setCompareSideA] = useState('');
  const [compareSideB, setCompareSideB] = useState('');
  const [compareScopeModule, setCompareScopeModule] = useState<AnalyticsModuleFilter>('all');
  const [compareScopeAssignment, setCompareScopeAssignment] = useState<'all' | string>('all');

  useEffect(() => {
    if (!availability[compareMode]) {
      const next = defaultCompare5dMode(availability);
      if (next) setCompareMode(next);
    }
  }, [availability, compareMode]);

  const allModulesLabel = t('analytics.allSyllabusSections', {
    sectionType: t(`syllabus.${structKey}`),
  });

  const labelForSection = useCallback(
    (id: string) => {
      if (id === 'unplaced') return t('analytics.unplacedAssignments');
      return modules.find((m) => m.id === id)?.title ?? id;
    },
    [modules, t]
  );

  const labelForStudent = useCallback(
    (id: string) => students.find((s) => s.id === id)?.fullName ?? id,
    [students]
  );

  const labelForAssignment = useCallback(
    (id: string) => assignments.find((a) => a.id === id)?.title ?? id,
    [assignments]
  );

  const labelForScopeModule = useMemo(() => {
    if (compareScopeModule === 'all') return allModulesLabel;
    if (compareScopeModule === 'unplaced') return t('analytics.unplacedAssignments');
    return modules.find((m) => m.id === compareScopeModule)?.title ?? compareScopeModule;
  }, [compareScopeModule, allModulesLabel, modules, t]);

  const labelForScopeAssignment = useMemo(() => {
    if (compareScopeAssignment === 'all') {
      return compareScopeModule === 'all'
        ? t('analytics.allAssignments')
        : t('analytics.allAssignmentsInScope');
    }
    return (
      assignments.find((a) => a.id === compareScopeAssignment)?.title ?? compareScopeAssignment
    );
  }, [compareScopeAssignment, compareScopeModule, assignments, t]);

  const sideOptions = useMemo(() => {
    const raw = sideOptionsForCompare5dMode(
      compareMode,
      students,
      assignments,
      modules,
      showUnplaced,
      compareScopeModule
    );
    return raw.map((o) => ({
      id: o.id,
      label: o.label === '__unplaced__' ? t('analytics.unplacedAssignments') : o.label,
    }));
  }, [compareMode, students, assignments, modules, showUnplaced, compareScopeModule, t]);

  const labelForSide = useCallback(
    (id: string) => {
      const fromOptions = sideOptions.find((o) => o.id === id)?.label;
      if (fromOptions) return fromOptions;
      if (compareMode === 'sections') return labelForSection(id);
      if (compareMode === 'students') return labelForStudent(id);
      return labelForAssignment(id);
    },
    [sideOptions, compareMode, labelForSection, labelForStudent, labelForAssignment]
  );

  const scopedAssignments = useMemo(
    () => assignmentsInCompareScope(assignments, compareScopeModule),
    [assignments, compareScopeModule]
  );

  const onModeChange = (mode: Compare5dMode) => {
    setCompareMode(mode);
    setCompareSideA('');
    setCompareSideB('');
  };

  const onScopeModuleChange = (mod: AnalyticsModuleFilter) => {
    setCompareScopeModule(mod);
    setCompareScopeAssignment('all');
    setCompareSideA('');
    setCompareSideB('');
  };

  const onScopeAssignmentChange = (asg: 'all' | string) => {
    setCompareScopeAssignment(asg);
    setCompareSideA('');
    setCompareSideB('');
  };

  const resolveInput = useMemo(
    () => ({
      students,
      assignments,
      modules,
      rawSubmissions,
      rawSnapshots,
      sectionTitleResolver,
      labelForSection,
      labelForStudent,
      labelForAssignment,
      scopeModule: compareScopeModule,
      scopeAssignment: compareScopeAssignment,
    }),
    [
      students,
      assignments,
      modules,
      rawSubmissions,
      rawSnapshots,
      sectionTitleResolver,
      labelForSection,
      labelForStudent,
      labelForAssignment,
      compareScopeModule,
      compareScopeAssignment,
    ]
  );

  const sideA = useMemo(
    () =>
      resolveCompare5dSide({
        ...resolveInput,
        mode: compareMode,
        sideId: compareSideA,
      }),
    [resolveInput, compareMode, compareSideA]
  );

  const sideB = useMemo(
    () =>
      resolveCompare5dSide({
        ...resolveInput,
        mode: compareMode,
        sideId: compareSideB,
      }),
    [resolveInput, compareMode, compareSideB]
  );

  const scopeSummary = useMemo(
    () =>
      buildCompare5dScopeSummary(
        compareMode,
        compareScopeModule,
        compareScopeAssignment,
        assignments,
        allModulesLabel,
        t('analytics.unplacedAssignments'),
        t('analytics.allAssignments'),
        t('analytics.allAssignmentsInScope'),
        modules
      ),
    [
      compareMode,
      compareScopeModule,
      compareScopeAssignment,
      assignments,
      allModulesLabel,
      modules,
      t,
    ]
  );

  const filterSummary = useMemo(() => {
    if (!compareSideA || !compareSideB) {
      return scopeSummary || t('analytics.compare5dTitle');
    }
    const base = t('analytics.compareNarrativeScope', {
      a: sideA.label,
      b: sideB.label,
      filters: scopeSummary || t('analytics.allAssignments'),
    });
    return base;
  }, [compareSideA, compareSideB, sideA.label, sideB.label, scopeSummary, t]);

  const modeHint = useMemo(() => {
    if (compareMode === 'sections') return t('analytics.compareHint');
    if (compareMode === 'students') return t('analytics.compareStudentsHint');
    return t('analytics.compareAssignmentsHint');
  }, [compareMode, t]);

  const narrativeIdPrefix = `5d-compare-${compareMode}-${compareSideA}-${compareSideB}-${compareScopeModule}-${compareScopeAssignment}`;

  const showCard = availability.sections || availability.students || availability.assignments;
  if (!showCard) return null;

  const canShowResults =
    compareSideA && compareSideB && compareSideA !== compareSideB && sideA.scores && sideB.scores;

  return (
    <Card
      className="rounded-[32px] border-none shadow-lg bg-card/80 backdrop-blur-sm overflow-hidden"
      dir={isRTL ? 'rtl' : 'ltr'}
    >
      <CardHeader className="border-b border-border pb-4">
        <CardTitle
          className={`flex items-center gap-3 text-lg font-bold text-foreground ${isRTL ? 'text-right' : 'text-left'}`}
        >
          <div className="p-2 bg-primary/10 rounded-lg shrink-0">
            <GitCompare className="h-5 w-5 text-primary" />
          </div>
          {t('analytics.compare5dTitle')}
        </CardTitle>
        <CardDescription className={isRTL ? 'text-right' : 'text-left'}>
          {t('analytics.compare5dHint')}
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-6 pt-4">
        <div className="space-y-2">
          <span
            className={`text-sm font-semibold text-muted-foreground block ${isRTL ? 'text-right' : 'text-left'}`}
          >
            {t('analytics.compareBy')}
          </span>
          <Tabs value={compareMode} onValueChange={(v) => onModeChange(v as Compare5dMode)}>
            <TabsList className="flex flex-wrap h-auto gap-1">
              {availability.sections ? (
                <TabsTrigger value="sections">{t('analytics.compareModeSections')}</TabsTrigger>
              ) : null}
              {availability.students ? (
                <TabsTrigger value="students">{t('analytics.compareModeStudents')}</TabsTrigger>
              ) : null}
              {availability.assignments ? (
                <TabsTrigger value="assignments">
                  {t('analytics.compareModeAssignments')}
                </TabsTrigger>
              ) : null}
            </TabsList>
          </Tabs>
          <p className={`text-sm text-muted-foreground ${isRTL ? 'text-right' : 'text-left'}`}>
            {modeHint}
          </p>
        </div>

        {compareMode !== 'sections' ? (
          <div className="flex flex-col gap-4 sm:flex-row sm:flex-wrap sm:items-end sm:gap-6">
            <div className="space-y-2 sm:min-w-[200px]">
              <span
                className={`text-sm font-semibold text-muted-foreground block ${isRTL ? 'text-right' : 'text-left'}`}
              >
                {t('analytics.compareScopeSection', {
                  sectionType: t(`syllabus.${structKey}`),
                })}
              </span>
              <Select
                value={compareScopeModule}
                onValueChange={(v) => onScopeModuleChange(v as AnalyticsModuleFilter)}
              >
                <SelectTrigger className="h-11 rounded-lg" dir={isRTL ? 'rtl' : 'ltr'}>
                  <SelectValue>{labelForScopeModule}</SelectValue>
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">{allModulesLabel}</SelectItem>
                  {modules.map((m) => (
                    <SelectItem key={m.id} value={m.id}>
                      {m.title}
                    </SelectItem>
                  ))}
                  {showUnplaced ? (
                    <SelectItem value="unplaced">{t('analytics.unplacedAssignments')}</SelectItem>
                  ) : null}
                </SelectContent>
              </Select>
            </div>
            {compareMode === 'students' ? (
              <div className="space-y-2 sm:min-w-[200px]">
                <span
                  className={`text-sm font-semibold text-muted-foreground block ${isRTL ? 'text-right' : 'text-left'}`}
                >
                  {t('analytics.compareScopeAssignment')}
                </span>
                <Select
                  value={compareScopeAssignment}
                  onValueChange={(v) => onScopeAssignmentChange(v)}
                >
                  <SelectTrigger className="h-11 rounded-lg" dir={isRTL ? 'rtl' : 'ltr'}>
                    <SelectValue>{labelForScopeAssignment}</SelectValue>
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">
                      {compareScopeModule === 'all'
                        ? t('analytics.allAssignments')
                        : t('analytics.allAssignmentsInScope')}
                    </SelectItem>
                    {scopedAssignments.map((a) => (
                      <SelectItem key={a.id} value={a.id}>
                        {a.title}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            ) : null}
          </div>
        ) : null}

        <div className="flex flex-col gap-4 sm:flex-row sm:flex-wrap sm:items-end sm:gap-6">
          <div className="space-y-2 sm:min-w-[200px]">
            <span
              className={`text-sm font-semibold text-muted-foreground block ${isRTL ? 'text-right' : 'text-left'}`}
            >
              {t('analytics.compareSideA')}
            </span>
            <Select
              value={compareSideA || '_none_'}
              onValueChange={(v) => setCompareSideA(v === '_none_' ? '' : v)}
            >
              <SelectTrigger className="h-11 rounded-lg" dir={isRTL ? 'rtl' : 'ltr'}>
                <SelectValue placeholder={t('analytics.compareSelectItem')}>
                  {compareSideA ? labelForSide(compareSideA) : t('analytics.compareSelectItem')}
                </SelectValue>
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="_none_">{t('analytics.compareSelectItem')}</SelectItem>
                {sideOptions.map((o) => (
                  <SelectItem key={o.id} value={o.id}>
                    {o.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-2 sm:min-w-[200px]">
            <span
              className={`text-sm font-semibold text-muted-foreground block ${isRTL ? 'text-right' : 'text-left'}`}
            >
              {t('analytics.compareSideB')}
            </span>
            <Select
              value={compareSideB || '_none_'}
              onValueChange={(v) => setCompareSideB(v === '_none_' ? '' : v)}
            >
              <SelectTrigger className="h-11 rounded-lg" dir={isRTL ? 'rtl' : 'ltr'}>
                <SelectValue placeholder={t('analytics.compareSelectItem')}>
                  {compareSideB ? labelForSide(compareSideB) : t('analytics.compareSelectItem')}
                </SelectValue>
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="_none_">{t('analytics.compareSelectItem')}</SelectItem>
                {sideOptions.map((o) => (
                  <SelectItem key={`b-${o.id}`} value={o.id}>
                    {o.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>

        {compareSideA && compareSideB && compareSideA === compareSideB ? (
          <p className="text-sm text-amber-700 dark:text-amber-500">
            {t('analytics.compareSameItem')}
          </p>
        ) : null}

        {compareSideA &&
        compareSideB &&
        compareSideA !== compareSideB &&
        (!sideA.scores || !sideB.scores) ? (
          <p className="text-sm text-muted-foreground">
            {t('classroomAnalytics.noStudentDataInScope')}
          </p>
        ) : null}

        {canShowResults ? (
          <Compare5dResults
            classroomId={classroomId}
            labelA={sideA.label}
            labelB={sideB.label}
            scoresA={sideA.scores!}
            scoresB={sideB.scores!}
            qedA={sideA.qed}
            qedB={sideB.qed}
            evidenceA={sideA.evidence}
            evidenceB={sideB.evidence}
            narrativeContext={sideA.narrativeContext}
            filterSummary={filterSummary}
            narrativeIdPrefix={narrativeIdPrefix}
            language={analyticsLanguage}
            isRTL={isRTL}
          />
        ) : null}
      </CardContent>
    </Card>
  );
};

import { Flag, Loader2 } from 'lucide-react';
import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import {
  reportTeacherAiContentFlag,
  type TeacherAiContentType,
} from '@/services/submissionService';

type AiContentFlagButtonProps = {
  contentType: TeacherAiContentType;
  contentExcerpt: string;
  opikTraceId?: string;
  assignmentId?: string;
  submissionId?: string;
  className?: string;
};

export const AiContentFlagButton = ({
  contentType,
  contentExcerpt,
  opikTraceId,
  assignmentId,
  submissionId,
  className,
}: AiContentFlagButtonProps) => {
  const { t } = useTranslation();
  const [submitting, setSubmitting] = useState(false);

  if (!opikTraceId?.trim() && !assignmentId && !submissionId) {
    return null;
  }

  const handleClick = async () => {
    const excerpt = contentExcerpt.trim();
    if (!excerpt) {
      toast.warning(t('aiContentFlag.emptyContent'));
      return;
    }
    setSubmitting(true);
    try {
      const result = await reportTeacherAiContentFlag({
        assignmentId,
        submissionId,
        contentType,
        contentExcerpt: excerpt,
        opikTraceId,
      });
      if (result.ok) {
        toast.success(t('aiContentFlag.success'));
      } else if (result.duplicate) {
        toast.info(t('aiContentFlag.duplicate'));
      } else {
        toast.error(t('aiContentFlag.error'));
      }
    } catch {
      toast.error(t('aiContentFlag.error'));
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Button
      type="button"
      variant="ghost"
      size="sm"
      className={className ?? 'h-8 w-8 p-0 shrink-0'}
      title={t('aiContentFlag.title')}
      aria-label={t('aiContentFlag.title')}
      disabled={submitting}
      onClick={() => void handleClick()}
    >
      {submitting ? (
        <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
      ) : (
        <Flag className="h-4 w-4 text-muted-foreground" />
      )}
    </Button>
  );
};

export function readOpikTraceId(raw: unknown, key: string): string | undefined {
  if (!raw || typeof raw !== 'object') return undefined;
  const value = (raw as Record<string, unknown>)[key];
  return typeof value === 'string' && value.trim() ? value.trim() : undefined;
}

/**
 * Error Boundary Component
 * React error boundary for graceful error handling
 */

import { AlertCircle } from 'lucide-react';
import { Component } from 'react';
import type { ReactNode } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';

interface ErrorBoundaryProps {
  children: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
}

/**
 * Error boundary to catch and display React errors
 */
export class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: unknown) {
    console.error('Error boundary caught error:', error, errorInfo);
  }

  handleReset = () => {
    this.setState({ hasError: false, error: null });
  };

  render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen flex items-center justify-center p-4">
          <Card className="max-w-md">
            <CardHeader>
              <div className="flex items-center gap-2">
                <AlertCircle className="h-6 w-6 text-destructive" />
                <CardTitle>Something went wrong</CardTitle>
              </div>
              <CardDescription>An error occurred while rendering this component</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              {this.state.error && (
                <div className="rounded-md bg-muted p-3">
                  <p className="text-sm font-mono text-muted-foreground">
                    {this.state.error.message}
                  </p>
                </div>
              )}
              <Button onClick={this.handleReset} className="w-full">
                Try Again
              </Button>
            </CardContent>
          </Card>
        </div>
      );
    }

    return this.props.children;
  }
}

/**
 * Loading Spinner Component
 * GSAP-powered loading state component
 */

import gsap from 'gsap';
import { Loader2 } from 'lucide-react';
import { useEffect, useRef } from 'react';

interface LoadingSpinnerProps {
  text?: string;
  className?: string;
  size?: 'sm' | 'md' | 'lg';
}

/**
 * Display a GSAP-animated loading spinner with optional text
 */
export const LoadingSpinner = ({
  text = 'Loading...',
  className = '',
  size = 'md',
}: LoadingSpinnerProps) => {
  const spinnerRef = useRef<SVGSVGElement>(null);
  const textRef = useRef<HTMLParagraphElement>(null);

  const sizeClasses = {
    sm: 'h-5 w-5',
    md: 'h-8 w-8',
    lg: 'h-12 w-12',
  };

  useEffect(() => {
    if (spinnerRef.current) {
      // GSAP spin animation
      gsap.to(spinnerRef.current, {
        rotation: 360,
        duration: 1,
        repeat: -1,
        ease: 'linear',
        transformOrigin: 'center center',
      });
    }

    if (textRef.current) {
      // Subtle pulse on text
      gsap.to(textRef.current, {
        opacity: 0.6,
        duration: 0.8,
        repeat: -1,
        yoyo: true,
        ease: 'power1.inOut',
      });
    }

    return () => {
      if (spinnerRef.current) {
        gsap.killTweensOf(spinnerRef.current);
      }
      if (textRef.current) {
        gsap.killTweensOf(textRef.current);
      }
    };
  }, []);

  return (
    <div className={`flex flex-col items-center justify-center py-12 ${className}`}>
      <Loader2 ref={spinnerRef} className={`${sizeClasses[size]} text-primary mb-2`} />
      {text && (
        <p ref={textRef} className="text-muted-foreground">
          {text}
        </p>
      )}
    </div>
  );
};

/**
 * Full page loading spinner for page transitions
 */
export const PageLoadingSpinner = ({ text }: { text?: string }) => {
  return (
    <div className="min-h-screen flex items-center justify-center bg-background">
      <LoadingSpinner text={text} size="lg" />
    </div>
  );
};

