type RouterAssignment = {
  id: string;
  type: string;
  title: string;
  instructions: string;
  student_facing_task?: string | null;
  enable_ai_feedback?: boolean | null;
  auto_publish_ai_feedback?: boolean | null;
  syllabus_section_id?: string | null;
  classrooms: {
    teacher_profiles?: { full_name?: string | null } | null;
  };
};

type RouterSubmission = {
  id: string;
  status: string;
  student_id: string;
  text_body?: string | null;
  awaiting_teacher_feedback_release?: boolean | null;
  evaluation_status?: string | null;
};

export type AssignmentFlowContinue = {
  nextIn: FlowStepTarget | null;
  firstNext: FlowStepTarget | null;
  nextModId: string | null | undefined;
} | null;

export type AssignmentDetailSubmissionRouterProps = {
  assignment: RouterAssignment;
  submission: RouterSubmission;
  hasFeedback: boolean;
  isTeacherTry: boolean;
  isRTL: boolean;
  resolvedStudentFacingTask: string;
  isStudentTaskLoading: boolean;
  chatInitAllowed: boolean;
  initialGreetingMode: 'default' | 'explain_task';
  storedTaskUnderstandingChoice: 'yes' | 'no' | null;
  chatPriorSubmissionIds: string[];
  nuanceTracking?: NuanceTrackingCallbacks;
  clipboardTracking?: AssignmentClipboardTrackingCallbacks;
  companionChatAnchorRef: RefObject<HTMLDivElement | null>;
  assignmentFlowContinue: AssignmentFlowContinue;
  onNavigateToFlowTarget: (target: FlowStepTarget, opts?: { priorSubmissionId?: string }) => void;
  onGoCurriculum: () => void;
  onAssignmentCompleted: (tone?: AssignmentCompletionTone) => void | Promise<void>;
  onActivityComplete: (args?: { conversationComplete?: boolean }) => void | Promise<void>;
};

export const AssignmentDetailSubmissionRouter = ({
  assignment,
  submission,
  hasFeedback,
  isTeacherTry,
  isRTL,
  resolvedStudentFacingTask,
  isStudentTaskLoading,
  chatInitAllowed,
  initialGreetingMode,
  storedTaskUnderstandingChoice,
  chatPriorSubmissionIds,
  nuanceTracking,
  clipboardTracking,
  companionChatAnchorRef,
  assignmentFlowContinue,
  onNavigateToFlowTarget,
  onGoCurriculum,
  onAssignmentCompleted,
  onActivityComplete,
}: AssignmentDetailSubmissionRouterProps) => {
  const { t } = useTranslation();
  const isCompleted = submission.status === 'completed';

  const flowContinueRow =
    assignmentFlowContinue &&
    assignment.syllabus_section_id &&
    submission.status === 'completed' ? (
      <div className="flex flex-wrap justify-center gap-2 pt-4" dir={isRTL ? 'rtl' : 'ltr'}>
        {assignmentFlowContinue.nextIn ? (
          <Button
            type="button"
            variant="outline"
            className="gap-1 bg-background"
            onClick={() =>
              onNavigateToFlowTarget(assignmentFlowContinue.nextIn!, {
                priorSubmissionId:
                  assignmentFlowContinue.nextIn!.kind === 'assignment' ? submission.id : undefined,
              })
            }
          >
            {assignmentFlowContinue.nextIn.kind === 'assignment'
              ? t('assignmentDetail.continue')
              : t('activityPage.continueNext')}
            <ChevronRight className="h-4 w-4" />
          </Button>
        ) : null}
        {!assignmentFlowContinue.nextIn && assignmentFlowContinue.firstNext ? (
          <Button
            type="button"
            variant="outline"
            className="gap-1 bg-background"
            onClick={() =>
              onNavigateToFlowTarget(assignmentFlowContinue.firstNext!, {
                priorSubmissionId:
                  assignmentFlowContinue.firstNext!.kind === 'assignment'
                    ? submission.id
                    : undefined,
              })
            }
          >
            {t('assignmentDetail.continueNextModule')}
            <ChevronRight className="h-4 w-4" />
          </Button>
        ) : null}
        {!assignmentFlowContinue.nextIn && !assignmentFlowContinue.firstNext ? (
          <Button
            type="button"
            variant="outline"
            className="gap-1 bg-background"
            onClick={onGoCurriculum}
          >
            {t('assignmentDetail.openCurriculum')}
            <ChevronRight className="h-4 w-4" />
          </Button>
        ) : null}
      </div>
    ) : null;

  if (isCompleted && submission.awaiting_teacher_feedback_release) {
    return (
      <Card className="border-primary/20 bg-primary/5">
        <CardContent className="flex flex-col items-center justify-center py-12 text-center">
          <Clock className="h-10 w-10 text-primary mb-4" />
          <p className="text-sm font-medium text-primary">
            {t('assignmentDetail.awaitingTeacherFeedback')}
          </p>
          {flowContinueRow}
        </CardContent>
      </Card>
    );
  }

  const evalStatus = submission.evaluation_status;

  if (isCompleted && evalStatus === EVALUATION_STATUS.FAILED && !hasFeedback) {
    return (
      <Card className="border-primary/20 bg-primary/5">
        <CardContent className="flex flex-col items-center justify-center py-12 text-center">
          <Clock className="h-10 w-10 text-primary mb-4" />
          <p className="text-sm font-medium text-primary">
            {t('assignmentDetail.aiFeedbackFailed')}
          </p>
          {flowContinueRow}
        </CardContent>
      </Card>
    );
  }

  if (isCompleted && assignment.enable_ai_feedback === false && !hasFeedback) {
    const awaitingKey = `assignmentDetail.${assignment.type}.awaitingReview`;
    const awaitingFallback = t('assignmentDetail.submittedAwaitingReview', {
      defaultValue: 'Your activity has been submitted and is awaiting teacher review.',
    });
    return (
      <Card className="border-primary/20 bg-primary/5">
        <CardContent className="flex flex-col items-center justify-center py-12 text-center">
          <Clock className="h-10 w-10 text-primary mb-4" />
          <p className="text-sm font-medium text-primary">
            {t(awaitingKey, { defaultValue: awaitingFallback })}
          </p>
          {flowContinueRow}
        </CardContent>
      </Card>
    );
  }

  if (
    isCompleted &&
    !hasFeedback &&
    assignment.enable_ai_feedback !== false &&
    !submission.awaiting_teacher_feedback_release
  ) {
    return (
      <Card className="border-primary/20 bg-primary/5">
        <CardContent className="flex flex-col items-center justify-center py-12 text-center space-y-2">
          <CheckCircle className="h-10 w-10 text-primary mb-2" />
          <p className="text-sm font-medium text-primary">
            {t('assignmentDetail.success.completed')}
          </p>
          <p className="text-sm text-muted-foreground max-w-md">
            {t('assignmentDetail.assessmentInProgress')}
          </p>
          {flowContinueRow}
        </CardContent>
      </Card>
    );
  }

  const wrapAssignmentWorkspace = (content: ReactNode) => (
    <div className="space-y-6">{content}</div>
  );

  const chatPanelProps = {
    assignment,
    submission,
    isTeacherTry,
    isRTL,
    resolvedStudentFacingTask,
    isStudentTaskLoading,
    chatInitAllowed,
    initialGreetingMode,
    storedTaskUnderstandingChoice,
    chatPriorSubmissionIds,
    nuanceTracking,
    clipboardTracking,
  };

  const companionBlock = (
    <AssignmentDetailChatPanel
      {...chatPanelProps}
      variant="companion"
      companionChatAnchorRef={companionChatAnchorRef}
      onComplete={() => {}}
    />
  );

  switch (assignment.type) {
    case 'test':
      return wrapAssignmentWorkspace(
        <>
          <TestTakingPage
            assignmentId={assignment.id}
            assignmentInstructions={assignment.instructions}
            submissionId={submission.id}
            enableAiFeedback={assignment.enable_ai_feedback !== false}
            showAiFeedbackToStudents={assignment.auto_publish_ai_feedback !== false}
            isTeacherTry={isTeacherTry}
            nuanceTracking={nuanceTracking}
            clipboardTracking={clipboardTracking}
            onComplete={onAssignmentCompleted}
          />
          {companionBlock}
        </>
      );
    case 'text_essay':
      return wrapAssignmentWorkspace(
        <>
          <EssaySubmissionPage
            assignmentId={assignment.id}
            submissionId={submission.id}
            assignmentInstructions={assignment.instructions}
            enableAiFeedback={assignment.enable_ai_feedback !== false}
            showAiFeedbackToStudents={assignment.auto_publish_ai_feedback !== false}
            isTeacherTry={isTeacherTry}
            initialText={submission.text_body}
            clipboardTracking={clipboardTracking}
            onComplete={onAssignmentCompleted}
          />
          {companionBlock}
        </>
      );
    case 'project':
      return wrapAssignmentWorkspace(
        <>
          <ProjectSubmissionPage
            assignmentId={assignment.id}
            submissionId={submission.id}
            assignmentInstructions={assignment.instructions}
            enableAiFeedback={assignment.enable_ai_feedback !== false}
            showAiFeedbackToStudents={assignment.auto_publish_ai_feedback !== false}
            isTeacherTry={isTeacherTry}
            onComplete={onAssignmentCompleted}
          />
          {companionBlock}
        </>
      );
    case 'presentation':
      return wrapAssignmentWorkspace(
        <>
          <PresentationSubmissionPage
            assignmentId={assignment.id}
            submissionId={submission.id}
            assignmentInstructions={assignment.instructions}
            enableAiFeedback={assignment.enable_ai_feedback !== false}
            showAiFeedbackToStudents={assignment.auto_publish_ai_feedback !== false}
            isTeacherTry={isTeacherTry}
            onComplete={onAssignmentCompleted}
          />
          {companionBlock}
        </>
      );
    case 'langchain':
      return wrapAssignmentWorkspace(
        <>
          <LangchainBuilderPage
            assignmentId={assignment.id}
            submissionId={submission.id}
            assignmentInstructions={assignment.instructions}
            enableAiFeedback={assignment.enable_ai_feedback !== false}
            showAiFeedbackToStudents={assignment.auto_publish_ai_feedback !== false}
            isTeacherTry={isTeacherTry}
            initialPipelineText={submission.text_body}
            nuanceTracking={nuanceTracking}
            clipboardTracking={clipboardTracking}
            onComplete={onAssignmentCompleted}
          />
          {companionBlock}
        </>
      );
    default:
      return wrapAssignmentWorkspace(
        <AssignmentDetailChatPanel
          {...chatPanelProps}
          variant="primary"
          onComplete={onActivityComplete}
        />
      );
  }
};

import { useEffect, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';

export type CropPreset = 'free' | '16_9' | '4_3' | '1_1';

export interface CropPercent {
  x: number;
  y: number;
  width: number;
  height: number;
}

export const DEFAULT_CROP: CropPercent = { x: 0, y: 0, width: 100, height: 100 };

function clampCrop(c: CropPercent): CropPercent {
  let { x, y, width, height } = c;
  width = Math.max(8, Math.min(100, width));
  height = Math.max(8, Math.min(100, height));
  x = Math.max(0, Math.min(100 - width, x));
  y = Math.max(0, Math.min(100 - height, y));
  return { x, y, width, height };
}

interface CropOverlayProps {
  crop: CropPercent;
  onCropChange: (next: CropPercent) => void;
  preset: CropPreset;
  onPresetChange: (p: CropPreset) => void;
  /** When true, fills parent (use parent as positioned aspect-video wrapper) */
  overlayMode?: boolean;
  showPresetButtons?: boolean;
  className?: string;
}

export const CropOverlay = ({
  crop,
  onCropChange,
  preset,
  onPresetChange,
  overlayMode,
  showPresetButtons = true,
  className,
}: CropOverlayProps) => {
  const { t } = useTranslation();
  const containerRef = useRef<HTMLDivElement>(null);
  const captureTargetRef = useRef<HTMLElement | null>(null);
  const [dragging, setDragging] = useState<'move' | 'nw' | 'ne' | 'sw' | 'se' | null>(null);
  const startRef = useRef({ clientX: 0, clientY: 0, crop: crop });

  useEffect(() => {
    const onMove = (e: PointerEvent) => {
      if (!dragging || !containerRef.current) return;
      const el = containerRef.current;
      const rect = el.getBoundingClientRect();
      const dx = ((e.clientX - startRef.current.clientX) / rect.width) * 100;
      const dy = ((e.clientY - startRef.current.clientY) / rect.height) * 100;
      const sc = startRef.current.crop;

      if (dragging === 'move') {
        onCropChange(clampCrop({ ...sc, x: sc.x + dx, y: sc.y + dy }));
        return;
      }

      let next = { ...sc };
      if (dragging === 'nw') {
        next.x = sc.x + dx;
        next.y = sc.y + dy;
        next.width = sc.width - dx;
        next.height = sc.height - dy;
      } else if (dragging === 'ne') {
        next.y = sc.y + dy;
        next.width = sc.width + dx;
        next.height = sc.height - dy;
      } else if (dragging === 'sw') {
        next.x = sc.x + dx;
        next.width = sc.width - dx;
        next.height = sc.height + dy;
      } else if (dragging === 'se') {
        next.width = sc.width + dx;
        next.height = sc.height + dy;
      }

      if (preset !== 'free') {
        const ratio = preset === '16_9' ? 16 / 9 : preset === '4_3' ? 4 / 3 : 1;
        const elW = el.clientWidth;
        const elH = el.clientHeight;
        const wPx = (next.width / 100) * elW;
        const hPx = wPx / ratio;
        next.height = (hPx / elH) * 100;
        next = clampCrop(next);
      } else {
        next = clampCrop(next);
      }
      onCropChange(next);
    };

    const onUp = (ev: PointerEvent) => {
      const cap = captureTargetRef.current;
      if (cap) {
        try {
          if (cap.hasPointerCapture(ev.pointerId)) {
            cap.releasePointerCapture(ev.pointerId);
          }
        } catch {
          /* ignore */
        }
        captureTargetRef.current = null;
      }
      setDragging(null);
    };

    if (dragging) {
      document.addEventListener('pointermove', onMove, { passive: false });
      document.addEventListener('pointerup', onUp);
      document.addEventListener('pointercancel', onUp);
    }
    return () => {
      document.removeEventListener('pointermove', onMove);
      document.removeEventListener('pointerup', onUp);
      document.removeEventListener('pointercancel', onUp);
    };
  }, [dragging, onCropChange, preset]);

  const startDrag = (kind: 'move' | 'nw' | 'ne' | 'sw' | 'se') => (e: React.PointerEvent) => {
    if (preset !== 'free' && kind !== 'move') return;
    e.preventDefault();
    e.stopPropagation();
    startRef.current = { clientX: e.clientX, clientY: e.clientY, crop };
    const el = e.currentTarget as HTMLElement;
    captureTargetRef.current = el;
    try {
      el.setPointerCapture(e.pointerId);
    } catch {
      /* still use document listeners */
    }
    setDragging(kind);
  };

  const applyPreset = (p: CropPreset) => {
    onPresetChange(p);
    if (p === 'free') {
      onCropChange(DEFAULT_CROP);
      return;
    }
    const ratio = p === '16_9' ? 16 / 9 : p === '4_3' ? 4 / 3 : 1;
    let width = 88;
    let height = width / ratio;
    if (height > 88) {
      height = 88;
      width = height * ratio;
    }
    const x = (100 - width) / 2;
    const y = (100 - height) / 2;
    onCropChange(clampCrop({ x, y, width, height }));
  };

  return (
    <div className={cn('space-y-3', className)}>
      {showPresetButtons && (
        <div className="flex flex-wrap gap-1.5">
          {(['free', '16_9', '4_3', '1_1'] as const).map((p) => (
            <Button
              key={p}
              type="button"
              size="sm"
              variant={preset === p ? 'default' : 'outline'}
              onClick={() => applyPreset(p)}
            >
              {t(`assignmentDetail.presentation.editor.cropPresets.${p}`)}
            </Button>
          ))}
        </div>
      )}

      <div
        ref={containerRef}
        className={cn(
          'relative overflow-hidden rounded-md bg-black/50 select-none',
          overlayMode
            ? 'absolute inset-0 h-full w-full touch-none'
            : 'aspect-video touch-manipulation'
        )}
      >
        <div className="absolute inset-0 bg-black/30 pointer-events-none z-[1]" />
        <div
          className="absolute border-2 border-primary bg-primary/15 z-[2]"
          style={{
            left: `${crop.x}%`,
            top: `${crop.y}%`,
            width: `${crop.width}%`,
            height: `${crop.height}%`,
            cursor: 'move',
          }}
          onPointerDown={startDrag('move')}
        />
        {preset === 'free' && (
          <>
            {(
              [
                ['nw', crop.x, crop.y],
                ['ne', crop.x + crop.width, crop.y],
                ['sw', crop.x, crop.y + crop.height],
                ['se', crop.x + crop.width, crop.y + crop.height],
              ] as const
            ).map(([key, leftPct, topPct]) => (
              <div
                key={key}
                className="absolute z-[3] h-3 w-3 rounded-full bg-primary border-2 border-background"
                style={{
                  left: `${leftPct}%`,
                  top: `${topPct}%`,
                  transform: 'translate(-50%, -50%)',
                  cursor: `${key}-resize`,
                }}
                onPointerDown={startDrag(key)}
              />
            ))}
          </>
        )}
      </div>
    </div>
  );
};

import { RefreshCw } from 'lucide-react';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';

export const NO_AUDIO = '__no_audio__';

export interface DeviceSelection {
  videoDeviceId: string;
  audioDeviceId: string | typeof NO_AUDIO;
}

/** Request transient capture so browsers populate MediaDeviceInfo.label (privacy rule). */
async function primeDeviceLabels(): Promise<void> {
  if (!navigator.mediaDevices?.getUserMedia) return;
  try {
    const stream = await navigator.mediaDevices.getUserMedia({
      video: true,
      audio: true,
    });
    stream.getTracks().forEach((t) => t.stop());
  } catch {
    try {
      const v = await navigator.mediaDevices.getUserMedia({ video: true });
      v.getTracks().forEach((t) => t.stop());
    } catch {
      try {
        const a = await navigator.mediaDevices.getUserMedia({ audio: true });
        a.getTracks().forEach((t) => t.stop());
      } catch {
        /* user may deny; labels can stay empty until permission */
      }
    }
  }
}

interface DeviceSelectorProps {
  value: DeviceSelection;
  onChange: (next: DeviceSelection) => void;
  className?: string;
}

export const DeviceSelector = ({ value, onChange, className }: DeviceSelectorProps) => {
  const { t } = useTranslation();
  const [videoDevices, setVideoDevices] = useState<MediaDeviceInfo[]>([]);
  const [audioDevices, setAudioDevices] = useState<MediaDeviceInfo[]>([]);

  const applyDeviceList = useCallback((list: MediaDeviceInfo[]) => {
    const vids = list.filter((d) => d.kind === 'videoinput');
    const auds = list.filter((d) => d.kind === 'audioinput');
    setVideoDevices(vids);
    setAudioDevices(auds);
  }, []);

  /** No getUserMedia — avoids camera/mic prompts on mount (labels may be generic until permission). */
  const enumerateSilent = useCallback(async () => {
    try {
      const list = await navigator.mediaDevices.enumerateDevices();
      applyDeviceList(list);
    } catch {
      setVideoDevices([]);
      setAudioDevices([]);
    }
  }, [applyDeviceList]);

  /** User-triggered refresh: prime labels (may prompt) then enumerate. */
  const enumerateWithLabels = useCallback(async () => {
    try {
      await primeDeviceLabels();
      const list = await navigator.mediaDevices.enumerateDevices();
      applyDeviceList(list);
    } catch {
      setVideoDevices([]);
      setAudioDevices([]);
    }
  }, [applyDeviceList]);

  const initRef = useRef(false);

  useEffect(() => {
    enumerateSilent();
  }, [enumerateSilent]);

  useEffect(() => {
    if (initRef.current || videoDevices.length === 0) return;
    initRef.current = true;
    onChange({
      videoDeviceId: videoDevices[0].deviceId,
      audioDeviceId: audioDevices[0]?.deviceId ?? NO_AUDIO,
    });
  }, [videoDevices, audioDevices, onChange]);

  const labelFor = (d: MediaDeviceInfo, index: number, kind: 'video' | 'audio') => {
    if (d.label?.trim()) return d.label.trim();
    return kind === 'video'
      ? `${t('assignmentDetail.presentation.selectCamera')} ${index + 1}`
      : `${t('assignmentDetail.presentation.selectMicrophone')} ${index + 1}`;
  };

  const videoDisplayLabel = useMemo(() => {
    const d = videoDevices.find((x) => x.deviceId === value.videoDeviceId);
    if (!d) return '';
    return labelFor(d, videoDevices.indexOf(d), 'video');
  }, [videoDevices, value.videoDeviceId, t]);

  const micDisplayLabel = useMemo(() => {
    if (value.audioDeviceId === NO_AUDIO) return t('assignmentDetail.presentation.noAudio');
    const d = audioDevices.find((x) => x.deviceId === value.audioDeviceId);
    if (!d) return '';
    return labelFor(d, audioDevices.indexOf(d), 'audio');
  }, [audioDevices, value.audioDeviceId, t]);

  return (
    <div className={className}>
      <div className="flex flex-col sm:flex-row sm:flex-wrap gap-3 sm:items-end">
        <div className="space-y-1.5 flex-1 min-w-0 sm:min-w-[200px]">
          <Label className="text-xs">{t('assignmentDetail.presentation.selectCamera')}</Label>
          <Select
            value={value.videoDeviceId || videoDevices[0]?.deviceId || ''}
            onValueChange={(videoDeviceId) => onChange({ ...value, videoDeviceId })}
          >
            <SelectTrigger className="w-full min-w-0 max-w-full">
              <SelectValue
                placeholder={t('assignmentDetail.presentation.selectCamera')}
                className="truncate min-w-0 block text-left"
              >
                {videoDisplayLabel || t('assignmentDetail.presentation.selectCamera')}
              </SelectValue>
            </SelectTrigger>
            <SelectContent>
              {videoDevices.map((d, i) => (
                <SelectItem key={d.deviceId} value={d.deviceId}>
                  <span className="truncate block max-w-[min(100vw-4rem,320px)]">
                    {labelFor(d, i, 'video')}
                  </span>
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <div className="space-y-1.5 flex-1 min-w-0 sm:min-w-[200px]">
          <Label className="text-xs">{t('assignmentDetail.presentation.selectMicrophone')}</Label>
          <Select
            value={value.audioDeviceId}
            onValueChange={(audioDeviceId) =>
              onChange({
                ...value,
                audioDeviceId: audioDeviceId as DeviceSelection['audioDeviceId'],
              })
            }
          >
            <SelectTrigger className="w-full min-w-0 max-w-full">
              <SelectValue
                placeholder={t('assignmentDetail.presentation.selectMicrophone')}
                className="truncate min-w-0 block text-left"
              >
                {micDisplayLabel || t('assignmentDetail.presentation.selectMicrophone')}
              </SelectValue>
            </SelectTrigger>
            <SelectContent>
              <SelectItem value={NO_AUDIO}>{t('assignmentDetail.presentation.noAudio')}</SelectItem>
              {audioDevices.map((d, i) => (
                <SelectItem key={d.deviceId} value={d.deviceId}>
                  <span className="truncate block max-w-[min(100vw-4rem,320px)]">
                    {labelFor(d, i, 'audio')}
                  </span>
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={() => void enumerateWithLabels()}
          className="gap-1.5 shrink-0"
        >
          <RefreshCw className="h-3.5 w-3.5" />
          {t('assignmentDetail.presentation.refreshDevices')}
        </Button>
      </div>
    </div>
  );
};

import { Loader2, Upload, FileIcon, X, Send, Plus } from 'lucide-react';
import { useState, useRef, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { toast } from 'sonner';
import type { AssignmentCompletionTone } from '@/types/submission';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Progress } from '@/components/ui/progress';
import { useLanguage } from '@/contexts/LanguageContext';
import { useAuth } from '@/contexts/useAuth';
import { supabase } from '@/integrations/supabase/client';
import { cn } from '@/lib/utils';
import { completeSubmission, submitWithBackgroundAiFeedback } from '@/services/submissionService';
import { getAssignmentLanguage } from '@/utils/languageDetection';
interface ProjectSubmissionPageProps {
  assignmentId: string;
  submissionId: string;
  assignmentInstructions: string;
  enableAiFeedback?: boolean;
  showAiFeedbackToStudents?: boolean;
  isTeacherTry?: boolean;
  onComplete: (tone?: AssignmentCompletionTone) => void | Promise<void>;
}

type SelectedFile = {
  id: string;
  file: File;
  uploadedPath?: string;
};

function makeFileId() {
  return `${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

export const ProjectSubmissionPage = ({
  assignmentId,
  submissionId,
  assignmentInstructions,
  enableAiFeedback = true,
  showAiFeedbackToStudents = true,
  isTeacherTry = false,
  onComplete,
}: ProjectSubmissionPageProps) => {
  const { t } = useTranslation();
  const { language: uiLanguage = 'en' } = useLanguage();
  const { user } = useAuth();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [selectedFiles, setSelectedFiles] = useState<SelectedFile[]>([]);
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [submitting, setSubmitting] = useState(false);
  const [dragOver, setDragOver] = useState(false);

  const allUploaded =
    selectedFiles.length > 0 && selectedFiles.every((entry) => Boolean(entry.uploadedPath));

  const addFiles = (files: FileList | File[]) => {
    const next = Array.from(files).map((file) => ({
      id: makeFileId(),
      file,
    }));
    if (next.length === 0) return;
    setSelectedFiles((prev) => [...prev, ...next]);
  };

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    if (e.dataTransfer.files.length > 0) {
      addFiles(e.dataTransfer.files);
    }
  }, []);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(true);
  }, []);

  const handleDragLeave = useCallback(() => {
    setDragOver(false);
  }, []);

  const removeFile = (id: string) => {
    setSelectedFiles((prev) => prev.filter((entry) => entry.id !== id));
  };

  const uploadFiles = async () => {
    const pending = selectedFiles.filter((entry) => !entry.uploadedPath);
    if (pending.length === 0) return;

    setUploading(true);
    setUploadProgress(0);

    try {
      const uploadedEntries: SelectedFile[] = [...selectedFiles];
      let completed = selectedFiles.length - pending.length;

      for (const entry of pending) {
        const ext = entry.file.name.split('.').pop();
        const safeName = entry.file.name.replace(/[^\w.-]+/g, '_');
        const filePath = `${assignmentId}/${submissionId}/${entry.id}_${safeName || `project.${ext}`}`;

        const { error: uploadError } = await supabase.storage
          .from('submission-files')
          .upload(filePath, entry.file, { upsert: true });

        if (uploadError) throw uploadError;

        const index = uploadedEntries.findIndex((item) => item.id === entry.id);
        if (index >= 0) {
          uploadedEntries[index] = { ...uploadedEntries[index]!, uploadedPath: filePath };
        }

        completed += 1;
        setUploadProgress(Math.round((completed / selectedFiles.length) * 100));
      }

      const fileUrls = uploadedEntries
        .map((entry) => entry.uploadedPath)
        .filter((path): path is string => Boolean(path));

      const { error: updateError } = await supabase
        .from('submissions')
        .update({
          file_urls: fileUrls,
          file_url: fileUrls[0] ?? null,
        })
        .eq('id', submissionId);

      if (updateError) throw updateError;

      setSelectedFiles(uploadedEntries);
      setUploadProgress(100);
    } catch (error) {
      console.error('Upload error:', error);
      toast.error(t('assignmentDetail.project.uploadError'));
    } finally {
      setUploading(false);
    }
  };

  const handleSubmit = async () => {
    const fileUrls = selectedFiles
      .map((entry) => entry.uploadedPath)
      .filter((path): path is string => Boolean(path));

    if (fileUrls.length === 0) return;

    setSubmitting(true);
    try {
      const { error: updateError } = await supabase
        .from('submissions')
        .update({
          file_urls: fileUrls,
          file_url: fileUrls[0] ?? null,
        })
        .eq('id', submissionId);

      if (updateError) throw updateError;

      if (isTeacherTry) {
        const { error } = await completeSubmission(submissionId);
        if (error) throw error;
        await onComplete('activityCompleted');
        return;
      }

      if (!enableAiFeedback) {
        const { error } = await completeSubmission(submissionId);
        if (error) throw error;
        await onComplete('awaitingReview');
        return;
      }

      if (!user?.id) {
        toast.error(t('common.error'));
        return;
      }

      const language = getAssignmentLanguage(assignmentInstructions, uiLanguage);
      const { error: submitError, evaluationInvokeFailed } = await submitWithBackgroundAiFeedback({
        submissionId,
        studentId: user.id,
        assignmentId,
        language,
      });
      if (submitError) throw submitError;
      if (evaluationInvokeFailed) {
        toast.warning(t('assignmentDetail.errors.generatingFeedbackButCompleted'));
      }

      await onComplete(showAiFeedbackToStudents ? 'activityCompleted' : 'awaitingTeacher');
    } catch (error) {
      console.error('Submit error:', error);
      toast.error(t('common.error'));
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Card className="rounded-xl border-border shadow-sm">
      <CardHeader className="pb-3">
        <CardTitle className="text-lg font-semibold">
          {t('assignmentDetail.project.uploadFile')}
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div
          className={cn(
            'cursor-pointer rounded-xl border-2 border-dashed p-10 text-center transition-all sm:p-12',
            dragOver
              ? 'scale-[1.01] border-primary bg-primary/5'
              : 'border-border bg-muted/10 hover:border-primary/40'
          )}
          onClick={() => fileInputRef.current?.click()}
          onDrop={handleDrop}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          role="presentation"
        >
          <Upload className="mx-auto mb-4 h-10 w-10 text-muted-foreground" />
          <p className="text-sm font-medium text-foreground">
            {t('assignmentDetail.project.dragDrop')}
          </p>
          <p className="mt-1 text-xs text-muted-foreground">
            {t('assignmentDetail.project.fileTypes')}
          </p>
          <input
            ref={fileInputRef}
            type="file"
            multiple
            className="hidden"
            onChange={(e) => {
              if (e.target.files && e.target.files.length > 0) {
                addFiles(e.target.files);
              }
              e.target.value = '';
            }}
          />
        </div>

        {selectedFiles.length > 0 && (
          <div className="space-y-3">
            {selectedFiles.map((entry) => (
              <div
                key={entry.id}
                className="flex items-center gap-3 rounded-xl border border-border bg-card p-4 shadow-sm"
              >
                <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-primary/10">
                  <FileIcon className="h-5 w-5 text-primary" />
                </div>
                <div className="min-w-0 flex-1">
                  <p className="truncate text-sm font-medium">{entry.file.name}</p>
                  <p className="text-xs text-muted-foreground">
                    {(entry.file.size / (1024 * 1024)).toFixed(2)} MB
                    {entry.uploadedPath ? ` · ${t('assignmentDetail.project.fileSelected')} ✓` : ''}
                  </p>
                </div>
                {!uploading && (
                  <Button
                    variant="ghost"
                    size="icon"
                    className="h-8 w-8 shrink-0 text-muted-foreground hover:text-destructive"
                    onClick={() => removeFile(entry.id)}
                  >
                    <X className="h-4 w-4" />
                  </Button>
                )}
              </div>
            ))}

            {uploading && <Progress value={uploadProgress} className="h-2" />}

            {!uploading && (
              <Button
                variant="outline"
                size="sm"
                className="gap-2 rounded-xl"
                onClick={() => fileInputRef.current?.click()}
              >
                <Plus className="h-4 w-4" />
                {t('assignmentDetail.project.addMoreFiles')}
              </Button>
            )}
          </div>
        )}

        <div className="flex flex-wrap justify-end gap-2 pt-2">
          {selectedFiles.length > 0 && !allUploaded && (
            <Button onClick={uploadFiles} disabled={uploading} className="gap-2 rounded-xl">
              {uploading ? (
                <>
                  <Loader2 className="h-4 w-4 animate-spin" />
                  {t('assignmentDetail.project.submitting')}
                </>
              ) : (
                <>
                  <Upload className="h-4 w-4" />
                  {t('assignmentDetail.project.uploadFile')}
                </>
              )}
            </Button>
          )}
          {allUploaded && (
            <Button
              onClick={handleSubmit}
              disabled={submitting}
              size="lg"
              className="gap-2 rounded-xl shadow-sm"
            >
              {submitting ? (
                <>
                  <Loader2 className="h-4 w-4 animate-spin" />
                  {t('assignmentDetail.project.submitting')}
                </>
              ) : (
                <>
                  <Send className="h-4 w-4" />
                  {t('assignmentDetail.project.submit')}
                </>
              )}
            </Button>
          )}
        </div>
      </CardContent>
    </Card>
  );
};

import { Plus, Trash2, GripVertical, CircleDot, AlignLeft } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Checkbox } from '@/components/ui/checkbox';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Textarea } from '@/components/ui/textarea';
import { useLanguage } from '@/contexts/LanguageContext';
import { deriveAllowMultipleSelections, parseOptionIds, toggleOptionId } from '@/lib/testMcq';
import { cn } from '@/lib/utils';

export interface TestQuestionDraft {
  id: string;
  question_text: string;
  question_type: 'multiple_choice' | 'open_ended';
  options: { id: string; text: string }[];
  correct_option_ids: string[];
  allow_multiple_selections: boolean;
  order_index: number;
}

/** Normalize legacy drafts that still use correct_option_id. */
export function normalizeTestQuestionDraft(
  draft: TestQuestionDraft & { correct_option_id?: string }
): TestQuestionDraft {
  const correct_option_ids = draft.correct_option_ids?.length
    ? draft.correct_option_ids
    : parseOptionIds(null, draft.correct_option_id ?? null);
  return {
    ...draft,
    correct_option_ids,
    allow_multiple_selections:
      draft.allow_multiple_selections ?? deriveAllowMultipleSelections(correct_option_ids),
  };
}

export function isTestQuestionDraftValid(question: TestQuestionDraft): boolean {
  if (!question.question_text.trim()) return false;
  if (question.question_type === 'open_ended') return true;
  const filledOptions = question.options.filter((o) => o.text.trim());
  if (filledOptions.length < 2) return false;
  const correctIds = question.correct_option_ids.filter((id) =>
    filledOptions.some((o) => o.id === id)
  );
  return correctIds.length >= 1;
}

export function validateTestQuestionsForPublish(questions: TestQuestionDraft[]): boolean {
  return questions.length >= 1 && questions.every(isTestQuestionDraftValid);
}

interface TestQuestionBuilderProps {
  questions: TestQuestionDraft[];
  onQuestionsChange: (questions: TestQuestionDraft[]) => void;
}

let nextId = 1;
function generateTempId() {
  return `temp_${Date.now()}_${nextId++}`;
}

export const TestQuestionBuilder = ({ questions, onQuestionsChange }: TestQuestionBuilderProps) => {
  const { t } = useTranslation();
  const { isRTL } = useLanguage();

  const addQuestion = () => {
    const newQuestion: TestQuestionDraft = {
      id: generateTempId(),
      question_text: '',
      question_type: 'multiple_choice',
      options: [
        { id: 'a', text: '' },
        { id: 'b', text: '' },
        { id: 'c', text: '' },
        { id: 'd', text: '' },
      ],
      correct_option_ids: [],
      allow_multiple_selections: false,
      order_index: questions.length,
    };
    onQuestionsChange([...questions, newQuestion]);
  };

  const removeQuestion = (index: number) => {
    const updated = questions
      .filter((_, i) => i !== index)
      .map((q, i) => ({ ...q, order_index: i }));
    onQuestionsChange(updated);
  };

  const updateQuestion = (index: number, changes: Partial<TestQuestionDraft>) => {
    const updated = questions.map((q, i) => (i === index ? { ...q, ...changes } : q));
    onQuestionsChange(updated);
  };

  const addOption = (questionIndex: number) => {
    const question = questions[questionIndex];
    const nextLetter = String.fromCharCode(97 + question.options.length);
    const newOptions = [...question.options, { id: nextLetter, text: '' }];
    updateQuestion(questionIndex, { options: newOptions });
  };

  const removeOption = (questionIndex: number, optionIndex: number) => {
    const question = questions[questionIndex];
    if (question.options.length <= 2) return;
    const removedId = question.options[optionIndex].id;
    const newOptions = question.options.filter((_, i) => i !== optionIndex);
    const correct_option_ids = question.correct_option_ids.filter((id) => id !== removedId);
    updateQuestion(questionIndex, {
      options: newOptions,
      correct_option_ids,
      allow_multiple_selections: deriveAllowMultipleSelections(correct_option_ids),
    });
  };

  const updateOptionText = (questionIndex: number, optionIndex: number, text: string) => {
    const question = questions[questionIndex];
    const newOptions = question.options.map((o, i) => (i === optionIndex ? { ...o, text } : o));
    updateQuestion(questionIndex, { options: newOptions });
  };

  const toggleCorrectOption = (questionIndex: number, optionId: string, checked: boolean) => {
    const question = questions[questionIndex];
    const correct_option_ids = toggleOptionId(question.correct_option_ids, optionId, checked);
    updateQuestion(questionIndex, {
      correct_option_ids,
      allow_multiple_selections: deriveAllowMultipleSelections(correct_option_ids),
    });
  };

  const toggleQuestionType = (questionIndex: number, type: 'multiple_choice' | 'open_ended') => {
    const updates: Partial<TestQuestionDraft> = { question_type: type };
    if (type === 'open_ended') {
      updates.options = [];
      updates.correct_option_ids = [];
      updates.allow_multiple_selections = false;
    } else if (type === 'multiple_choice') {
      updates.options = [
        { id: 'a', text: '' },
        { id: 'b', text: '' },
        { id: 'c', text: '' },
        { id: 'd', text: '' },
      ];
      updates.correct_option_ids = [];
      updates.allow_multiple_selections = false;
    }
    updateQuestion(questionIndex, updates);
  };

  return (
    <Card className="rounded-xl border-dashed border-2 border-primary/30 bg-primary/5">
      <CardHeader className="pb-3">
        <CardTitle className="text-lg flex items-center gap-2">
          {t('createAssignment.testBuilder.title')}
        </CardTitle>
        <CardDescription>{t('createAssignment.testBuilder.description')}</CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {questions.length === 0 && (
          <p className="text-sm text-muted-foreground text-center py-6">
            {t('createAssignment.testBuilder.noQuestions')}
          </p>
        )}

        {questions.map((question, qIndex) => {
          const correctLabels = question.correct_option_ids
            .map((id) => question.options.find((o) => o.id === id)?.text || id)
            .filter(Boolean);

          return (
            <Card key={question.id} className="rounded-lg">
              <CardContent className="pt-4 space-y-3">
                <div className="flex items-start gap-2">
                  <GripVertical className="h-5 w-5 mt-2 text-muted-foreground/40 shrink-0" />
                  <div className="flex-1 space-y-3">
                    <div className="flex items-center justify-between gap-2">
                      <span className="text-sm font-medium text-muted-foreground">
                        {t('submissionDetail.testResults.question')} {qIndex + 1}
                      </span>
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        onClick={() => removeQuestion(qIndex)}
                        className="text-destructive hover:text-destructive h-8 w-8 p-0"
                        title={t('createAssignment.testBuilder.removeQuestion')}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>

                    <Textarea
                      value={question.question_text}
                      onChange={(e) => updateQuestion(qIndex, { question_text: e.target.value })}
                      placeholder={t('createAssignment.testBuilder.questionPlaceholder')}
                      className="min-h-[60px] resize-none rounded-lg"
                      dir={isRTL ? 'rtl' : 'ltr'}
                    />

                    <div className="flex flex-wrap items-center gap-3">
                      <Label className="text-xs text-muted-foreground">
                        {t('createAssignment.testBuilder.questionType')}:
                      </Label>
                      <div className="inline-flex rounded-lg bg-muted/50 p-1">
                        <Tabs
                          value={question.question_type}
                          onValueChange={(v) => {
                            if (v === 'multiple_choice' || v === 'open_ended') {
                              toggleQuestionType(qIndex, v);
                            }
                          }}
                        >
                          <TabsList className="h-8 gap-1 border-none bg-transparent p-0">
                            <TabsTrigger
                              value="multiple_choice"
                              aria-label={t('createAssignment.testBuilder.multipleChoice')}
                              className="h-7 gap-1.5 rounded-md border-none px-3 text-xs text-muted-foreground transition-all hover:text-foreground data-[active]:bg-background data-[active]:text-foreground data-[active]:shadow-sm"
                            >
                              <CircleDot className="size-3.5 shrink-0" />
                              {t('createAssignment.testBuilder.multipleChoice')}
                            </TabsTrigger>
                            <TabsTrigger
                              value="open_ended"
                              aria-label={t('createAssignment.testBuilder.openEnded')}
                              className="h-7 gap-1.5 rounded-md border-none px-3 text-xs text-muted-foreground transition-all hover:text-foreground data-[active]:bg-background data-[active]:text-foreground data-[active]:shadow-sm"
                            >
                              <AlignLeft className="size-3.5 shrink-0" />
                              {t('createAssignment.testBuilder.openEnded')}
                            </TabsTrigger>
                          </TabsList>
                        </Tabs>
                      </div>
                    </div>

                    {question.question_type === 'multiple_choice' && (
                      <div className="space-y-2 ps-2">
                        <p className="text-xs text-muted-foreground">
                          {t('createAssignment.testBuilder.markCorrectOptions')}
                        </p>
                        {question.options.map((option, oIndex) => (
                          <div key={option.id} className="flex items-center gap-2">
                            <Checkbox
                              id={`${question.id}-${option.id}-correct`}
                              checked={question.correct_option_ids.includes(option.id)}
                              onCheckedChange={(checked) =>
                                toggleCorrectOption(qIndex, option.id, checked === true)
                              }
                            />
                            <Input
                              value={option.text}
                              onChange={(e) => updateOptionText(qIndex, oIndex, e.target.value)}
                              placeholder={t('createAssignment.testBuilder.optionPlaceholder', {
                                index: oIndex + 1,
                              })}
                              className={cn('h-8 text-sm rounded-lg flex-1', isRTL && 'text-right')}
                              dir={isRTL ? 'rtl' : 'ltr'}
                            />
                            {question.options.length > 2 && (
                              <Button
                                type="button"
                                variant="ghost"
                                size="sm"
                                onClick={() => removeOption(qIndex, oIndex)}
                                className="h-8 w-8 p-0 text-muted-foreground hover:text-destructive"
                                title={t('createAssignment.testBuilder.removeOption')}
                              >
                                <Trash2 className="h-3 w-3" />
                              </Button>
                            )}
                          </div>
                        ))}
                        <Button
                          type="button"
                          variant="ghost"
                          size="sm"
                          onClick={() => addOption(qIndex)}
                          className="h-7 text-xs gap-1 text-primary"
                        >
                          <Plus className="h-3 w-3" />
                          {t('createAssignment.testBuilder.addOption')}
                        </Button>
                        {correctLabels.length > 0 && (
                          <p className="text-xs text-green-600 dark:text-green-400">
                            {correctLabels.length > 1
                              ? t('createAssignment.testBuilder.correctAnswers')
                              : t('createAssignment.testBuilder.correctAnswer')}
                            : {correctLabels.join(', ')}
                          </p>
                        )}
                      </div>
                    )}

                    {question.question_type === 'open_ended' && (
                      <div className="ps-2">
                        <p className="text-xs text-muted-foreground italic">
                          {t('createAssignment.testBuilder.openEnded')} —{' '}
                          {t('assignmentDetail.testTaking.typeAnswer')}
                        </p>
                      </div>
                    )}
                  </div>
                </div>
              </CardContent>
            </Card>
          );
        })}

        <Button
          type="button"
          variant="outline"
          onClick={addQuestion}
          className="w-full rounded-lg border-dashed gap-2"
        >
          <Plus className="h-4 w-4" />
          {t('createAssignment.testBuilder.addQuestion')}
        </Button>
      </CardContent>
    </Card>
  );
};

