  id: string;
  question_text: string;
  question_type: string;
  options: unknown;
  correct_option_id: string | null;
  correct_option_ids?: unknown;
  allow_multiple_selections?: boolean | null;
  order_index: number;
}): TestQuestionDraft {
  const opts = row.options as { id: string; text: string }[] | null;
  const correct_option_ids = parseOptionIds(row.correct_option_ids, row.correct_option_id);
  return {
    id: row.id,
    question_text: row.question_text,
    question_type: row.question_type as 'multiple_choice' | 'open_ended',
    options: Array.isArray(opts) ? opts : [],
    correct_option_ids,
    allow_multiple_selections:
      row.allow_multiple_selections ?? deriveAllowMultipleSelections(correct_option_ids),
    order_index: row.order_index,
  };
}

function testQuestionToInsertRow(q: TestQuestionDraft, assignmentId: string) {
  const correct_option_ids = q.question_type === 'multiple_choice' ? q.correct_option_ids : [];
  return {
    assignment_id: assignmentId,
    question_text: q.question_text,
    question_type: q.question_type,
    options: q.question_type === 'multiple_choice' ? q.options : null,
    correct_option_ids,
    allow_multiple_selections:
      q.question_type === 'multiple_choice' ? q.allow_multiple_selections : false,
    correct_option_id:
      q.question_type === 'multiple_choice' ? legacySingleOptionId(correct_option_ids) : null,
    order_index: q.order_index,
  };
}

export const AssignmentWizardDialog = (props: AssignmentWizardDialogProps) => {
  const { t } = useTranslation();
  const { isRTL, language: uiLanguage } = useLanguage();
  const { user } = useAuth();
  const queryClient = useQueryClient();

  const isCreate = props.mode === 'create';
  const classroomId = isCreate ? props.classroomId : props.assignment.classroom_id;
  const initialData = isCreate ? props.initialData : undefined;
  const lockSyllabusSection = isCreate ? (props.lockSyllabusSection ?? false) : false;
  const assignedStudentId = isCreate ? props.assignedStudentId : undefined;
  const onCreatedAssignment = isCreate ? props.onCreatedAssignment : undefined;

  const assignment = !isCreate ? props.assignment : null;

  const { open, onOpenChange, onSuccess } = props;

  const { data: syllabus, isLoading: isSyllabusLoading } = useSyllabus(classroomId);

  const [currentStepId, setCurrentStepId] = useState<AssignmentWizardStepId>(
    ASSIGNMENT_WIZARD_FIRST_STEP
  );
  const [formData, setFormData] = useState<AssignmentWizardFormData>(() =>
    getDefaultAssignmentWizardFormData()
  );
  const [loading, setLoading] = useState(false);
  const [generatingStudentTask, setGeneratingStudentTask] = useState(false);
  const [uploadingMaterial, setUploadingMaterial] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [linkInput, setLinkInput] = useState('');
  const [classroomDomains, setClassroomDomains] = useState<
    Array<{ name: string; components: string[] }>
  >([]);
  const [classroomMaterials, setClassroomMaterials] = useState<
    Array<{ type: 'pdf' | 'link'; url: string; name: string }>
  >([]);
  const [selectedMaterialIds, setSelectedMaterialIds] = useState<Set<number>>(new Set());
  const [selectedDomain, setSelectedDomain] = useState<string>('');
  const [availableComponents, setAvailableComponents] = useState<string[]>([]);
  const [rephrasingInstructions, setRephrasingInstructions] = useState(false);
  const [testQuestions, setTestQuestions] = useState<TestQuestionDraft[]>([]);
  const [syllabusSectionId, setSyllabusSectionId] = useState<string>('');
  const [gradingCategoryId, setGradingCategoryId] = useState<string>('');
  const [linkedModuleActivityIds, setLinkedModuleActivityIds] = useState<string[]>([]);
  const moduleLinkInitKeyRef = useRef<string>('');
  const assignmentDraftSaveTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const assignmentDraftHydratedSessionRef = useRef(false);
  const syllabusSectionPrevRef = useRef<string | null>(null);

  const [aiMetadata, setAiMetadata] = useState<AssignmentCreateDraftV1['aiMetadata']>({});

  const [hasSubmissions, setHasSubmissions] = useState(false);
  const [hasTestResponses, setHasTestResponses] = useState(false);

  const [hardSkillsSuggestionStatus, setHardSkillsSuggestionStatus] =
    useState<HardSkillsSuggestionStatus>('idle');
  const [hardSkillsSuggestionSource, setHardSkillsSuggestionSource] = useState<
    'catalog' | 'custom' | null
  >(null);
  const suggestHardSkillsTokenRef = useRef(0);
  const studentTaskBgRequestIdRef = useRef(0);

  const hasDueDateInDb = Boolean(assignment?.due_at?.trim());
  const policyFrozen = !isCreate && hasSubmissions && hasDueDateInDb;

  const stepOrder = useMemo(() => assignmentWizardStepOrder(formData.type), [formData.type]);

  const moduleOutlineResources = useMemo(() => {
    if (!syllabusSectionId || !syllabus?.section_resources) return [];
    return filterOutlineMaterialResources(syllabus.section_resources[syllabusSectionId] ?? [], {
      excludeDrafts: false,
    });
  }, [syllabusSectionId, syllabus?.section_resources]);

  const indicatorSteps: WizardStep[] = useMemo(
    () =>
      stepOrder.map((id) => ({
        id,
        title: t(`createAssignment.wizard.steps.${id}`),
      })),
    [stepOrder, t]
  );

  const currentStepIndex = Math.max(0, stepOrder.indexOf(currentStepId));
  const isLastStep = currentStepId === 'review';

  const resetCreateDefaults = useCallback(() => {
    setFormData(getDefaultAssignmentWizardFormData());
    setTestQuestions([]);
    setLinkInput('');
    setSelectedMaterialIds(new Set());
    setSelectedDomain('');
    setAvailableComponents([]);
    setRephrasingInstructions(false);
    setAiMetadata({});
    setUploadingMaterial(false);
    setUploadProgress(0);
    setLinkedModuleActivityIds([]);
    moduleLinkInitKeyRef.current = '';
    setHardSkillsSuggestionStatus('idle');
    setHardSkillsSuggestionSource(null);
    studentTaskBgRequestIdRef.current = 0;
  }, []);

  /** After basics → run edge fn in background so Review/submit can save `student_facing_task` without waiting. */
  const queueBackgroundStudentTaskPrefill = useCallback(
    (snapshot: { title: string; instructions: string }) => {
      if (!classroomId || !snapshot.instructions.trim()) return;
      const myId = ++studentTaskBgRequestIdRef.current;
      const lang = uiLanguage === 'he' ? 'he' : 'en';
      void (async () => {
        const { data, error } = await supabase.functions.invoke('generate-student-facing-task', {
          body: {
            classroomId,
            title: snapshot.title,
            instructions: snapshot.instructions,
            language: lang,
          },
        });
        if (myId !== studentTaskBgRequestIdRef.current) return;
        if (error) return;
        const payload = data as { studentFacingTask?: string; opikTraceId?: string };
        const task = payload.studentFacingTask?.trim();
        if (!task) return;
        setFormData((prev) => {
          if (prev.instructions !== snapshot.instructions) return prev;
          if (prev.student_facing_task?.trim()) return prev;
          const nextIds = { ...(prev.opik_trace_ids ?? {}) };
          if (payload.opikTraceId?.trim()) {
            nextIds.student_facing_task = payload.opikTraceId.trim();
          }
          return {
            ...prev,
            student_facing_task: task,
            opik_trace_ids: nextIds,
          };
        });
      })();
    },
    [classroomId, uiLanguage]
  );

  useEffect(() => {
    if (!open) return;
    setCurrentStepId(ASSIGNMENT_WIZARD_FIRST_STEP);
  }, [open, isCreate ? classroomId : assignment?.id]);

  useEffect(() => {
    if (currentStepId === 'test' && formData.type !== 'test') {
      setCurrentStepId('review');
      return;
    }
    if (!stepOrder.includes(currentStepId)) {
      setCurrentStepId('review');
    }
  }, [formData.type, currentStepId, stepOrder]);

  useEffect(() => {
    if (!open) assignmentDraftHydratedSessionRef.current = false;
  }, [open]);

  useEffect(() => {
    if (!open || !isCreate) return;
    if (initialData) return;
    resetCreateDefaults();
  }, [open, initialData, resetCreateDefaults, isCreate]);

  useLayoutEffect(() => {
    if (!isCreate) return;
    if (!open || !classroomId || assignmentDraftHydratedSessionRef.current) return;
    if (initialData == null) return;
    const sectionKey = syllabusSectionId || initialData?.syllabus_section_id || 'none';
    const hasRichInitial =
      Boolean(initialData?.title?.trim()) ||
      Boolean(initialData?.instructions?.trim()) ||
      (Boolean(initialData?.type) && initialData.type !== 'chatbot');
    assignmentDraftHydratedSessionRef.current = true;
    if (hasRichInitial) return;
    try {
      const raw = sessionStorage.getItem(assignmentCreateDraftKey(classroomId, sectionKey));
      if (!raw) return;
      const draft = JSON.parse(raw) as AssignmentCreateDraftV1;
      if (draft.formData && typeof draft.formData === 'object') {
        setFormData(() => {
          const merged = { ...getDefaultAssignmentWizardFormData(), ...draft.formData };
          const hs = merged.hard_skills as unknown;
          if (Array.isArray(hs) && hs.length > 0 && typeof (hs as unknown[])[0] === 'string') {
            merged.hard_skills = parseHardSkillsFromDb(hs as string[], merged.hard_skill_domain);
          }
          return merged;
        });
      }
      if (Array.isArray(draft.testQuestions)) {
        setTestQuestions(draft.testQuestions.map((q) => normalizeTestQuestionDraft(q)));
      }
      if (typeof draft.gradingCategoryId === 'string')
        setGradingCategoryId(draft.gradingCategoryId);
      if (Array.isArray(draft.linkedModuleActivityIds))
        setLinkedModuleActivityIds(draft.linkedModuleActivityIds);
      if (draft.aiMetadata && typeof draft.aiMetadata === 'object') setAiMetadata(draft.aiMetadata);
      if (
        typeof draft.syllabusSectionId === 'string' &&
        draft.syllabusSectionId &&
        !lockSyllabusSection
      ) {
        setSyllabusSectionId(draft.syllabusSectionId);
      }
    } catch {
      /* ignore */
    }
  }, [open, classroomId, syllabusSectionId, initialData, lockSyllabusSection, isCreate]);

  useEffect(() => {
    if (!isCreate || !open || !classroomId || assignmentDraftHydratedSessionRef.current) return;
    if (initialData != null) return;
    const sectionKey = syllabusSectionId || 'none';
    assignmentDraftHydratedSessionRef.current = true;
    try {
      const raw = sessionStorage.getItem(assignmentCreateDraftKey(classroomId, sectionKey));
      if (!raw) return;
      const draft = JSON.parse(raw) as AssignmentCreateDraftV1;
      if (draft.formData && typeof draft.formData === 'object') {
        setFormData(() => {
          const merged = { ...getDefaultAssignmentWizardFormData(), ...draft.formData };
          const hs = merged.hard_skills as unknown;
          if (Array.isArray(hs) && hs.length > 0 && typeof (hs as unknown[])[0] === 'string') {
            merged.hard_skills = parseHardSkillsFromDb(hs as string[], merged.hard_skill_domain);
          }
          return merged;
        });
      }
      if (Array.isArray(draft.testQuestions)) {
        setTestQuestions(draft.testQuestions.map((q) => normalizeTestQuestionDraft(q)));
      }
      if (typeof draft.gradingCategoryId === 'string')
        setGradingCategoryId(draft.gradingCategoryId);
      if (Array.isArray(draft.linkedModuleActivityIds))
        setLinkedModuleActivityIds(draft.linkedModuleActivityIds);
      if (draft.aiMetadata && typeof draft.aiMetadata === 'object') setAiMetadata(draft.aiMetadata);
      if (
        typeof draft.syllabusSectionId === 'string' &&
        draft.syllabusSectionId &&
        !lockSyllabusSection
      ) {
        setSyllabusSectionId(draft.syllabusSectionId);
      }
    } catch {
      /* ignore */
    }
  }, [open, classroomId, initialData, syllabusSectionId, lockSyllabusSection, isCreate]);

  useEffect(() => {
    if (!isCreate || !open || !classroomId) return;
    if (assignmentDraftSaveTimerRef.current) clearTimeout(assignmentDraftSaveTimerRef.current);
    assignmentDraftSaveTimerRef.current = setTimeout(() => {
      assignmentDraftSaveTimerRef.current = null;
      const sectionKey = syllabusSectionId || initialData?.syllabus_section_id || 'none';
      try {
        const draft: AssignmentCreateDraftV1 = {
          formData,
          testQuestions,
          syllabusSectionId,
          gradingCategoryId,
          linkedModuleActivityIds,
          aiMetadata,
        };
        const raw = JSON.stringify(draft);
        if (raw.length > 4 * 1024 * 1024) return;
        sessionStorage.setItem(assignmentCreateDraftKey(classroomId, sectionKey), raw);
      } catch {
        /* quota */
      }
    }, 400);
    return () => {
      if (assignmentDraftSaveTimerRef.current) clearTimeout(assignmentDraftSaveTimerRef.current);
    };
  }, [
    isCreate,
    open,
    classroomId,
    formData,
    testQuestions,
    syllabusSectionId,
    gradingCategoryId,
    linkedModuleActivityIds,
    aiMetadata,
    initialData?.syllabus_section_id,
  ]);

  useEffect(() => {
    if (!open || !classroomId) return;
    let cancelled = false;
    (async () => {
      try {
        const { data: classroomData, error: classroomError } = await supabase
          .from('classrooms')
          .select('domains, materials')
          .eq('id', classroomId)
          .single();
        if (classroomError) throw classroomError;
        if (cancelled) return;
        const classroomDataWithExtras = classroomData as {
          domains?: Array<{ name: string; components: string[] }>;
          materials?: Array<{ type: 'pdf' | 'link'; url: string; name: string }>;
        };
        let domains: Array<{ name: string; components: string[] }> = [];
        if (classroomDataWithExtras?.domains) {
          domains = classroomDataWithExtras.domains;
          setClassroomDomains(domains);
        }
        if (classroomDataWithExtras?.materials) {
          setClassroomMaterials(classroomDataWithExtras.materials);
        }

        if (isCreate) {
          const { data: lastAssignment, error: assignmentError } = await supabase
            .from('assignments')
            .select('hard_skill_domain, hard_skills')
            .eq('classroom_id', classroomId)
            .order('created_at', { ascending: false })
            .limit(1)
            .maybeSingle();
          if (!assignmentError && lastAssignment && !cancelled) {
            const rawSkills = lastAssignment.hard_skills;
            let parsedList: unknown = rawSkills;
            if (typeof rawSkills === 'string') {
              try {
                parsedList = JSON.parse(rawSkills);
              } catch {
                parsedList = rawSkills
                  .split(',')
                  .map((s) => s.trim())
                  .filter(Boolean);
              }
            }
            const pairs = parseHardSkillsFromDb(parsedList, lastAssignment.hard_skill_domain);
            if (pairs.length > 0) {
              const doms = distinctDomains(pairs);
              const singleDomain = doms.length === 1 ? doms[0]! : '';
              setFormData((prev) => ({
                ...prev,
                hard_skill_domain: singleDomain,
                hard_skills: pairs,
              }));
              if (singleDomain) {
                setSelectedDomain(singleDomain);
                const domain = domains.find((d) => d.name === singleDomain);
                if (domain) setAvailableComponents(domain.components);
              }
            } else if (lastAssignment.hard_skill_domain) {
              setSelectedDomain(lastAssignment.hard_skill_domain);
              const domain = domains.find((d) => d.name === lastAssignment.hard_skill_domain);
              if (domain) setAvailableComponents(domain.components);
            }
          }
        }
      } catch (e) {
        console.error('Error fetching classroom data:', e);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [classroomId, open, isCreate]);

  useEffect(() => {
    if (!open) return;
    if (isCreate) {
      setSyllabusSectionId(initialData?.syllabus_section_id ?? '');
      setGradingCategoryId(initialData?.grading_category_id ?? '');
    }
  }, [
    open,
    classroomId,
    initialData?.syllabus_section_id,
    initialData?.grading_category_id,
    isCreate,
  ]);

  useEffect(() => {
    if (!open || isCreate) return;
    if (!assignment?.id) return;
    let cancelled = false;
    (async () => {
      const { data: submissionRows } = await supabase
        .from('submissions')
        .select('id')
        .eq('assignment_id', assignment.id);
      if (cancelled) return;
      const submissionIds = (submissionRows ?? []).map((row) => row.id);
      if (submissionIds.length === 0) {
        setHasTestResponses(false);
        return;
      }
      const { count } = await supabase
        .from('test_responses')
        .select('id', { count: 'exact', head: true })
        .in('submission_id', submissionIds);
      if (!cancelled) setHasTestResponses((count ?? 0) > 0);
    })();
    return () => {
      cancelled = true;
    };
  }, [open, assignment?.id, isCreate]);

  useEffect(() => {
    if (!open || !isCreate) return;
    const key = `${syllabusSectionId}|${syllabus?.id ?? ''}`;
    if (!syllabusSectionId || !syllabus?.section_resources) {
      if (!syllabusSectionId) {
        moduleLinkInitKeyRef.current = '';
        setLinkedModuleActivityIds([]);
      }
      return;
    }
    const list = syllabus.section_resources[syllabusSectionId] ?? [];
    if (key !== moduleLinkInitKeyRef.current) {
      moduleLinkInitKeyRef.current = key;
      setLinkedModuleActivityIds(list.map((r) => r.id));
    }
  }, [open, isCreate, syllabusSectionId, syllabus]);

  useEffect(() => {
    if (open && initialData && isCreate) {
      setFormData((prev) => ({
        ...prev,
        title: initialData.title || prev.title || '',
        instructions: initialData.instructions || prev.instructions || '',
        type: initialData.type || prev.type || 'chatbot',
        due_at: initialData.due_at || prev.due_at || '',
        target_dimensions: initialData.target_dimensions ||
          prev.target_dimensions || {
            vision: false,
            values: false,
            thinking: false,
            connection: false,
            action: false,
          },
        opik_trace_ids: initialData.opik_trace_ids ?? prev.opik_trace_ids ?? {},
      }));
      setAiMetadata({
        difficulty_level: initialData.difficulty_level,
        success_criteria: initialData.success_criteria,
        scaffolding_tips: initialData.scaffolding_tips,
      });
    }
    if (!open && isCreate) {
      setTestQuestions([]);
    }
  }, [open, isCreate, initialData == null ? '' : JSON.stringify(initialData)]);

  useEffect(() => {
    if (!open || !assignment || isCreate) return;

    setFormData({
      ...getDefaultAssignmentWizardFormData(),
      title: assignment.title,
      instructions: assignment.instructions,
      student_facing_task: assignment.student_facing_task?.trim() || '',
      type: assignment.type,
      status: assignment.status,
      due_at: formatDueForForm(assignment.due_at),
      attempt_mode: assignment.attempt_mode ?? 'single',
    });

    const loadAssignmentData = async () => {
      const { data } = await supabase
        .from('assignments')
        .select(
          'hard_skills, hard_skill_domain, materials, enable_ai_feedback, auto_publish_ai_feedback, use_course_memory, show_task_understanding_prompt, syllabus_section_id, grading_category_id, student_facing_task'
        )
        .eq('id', assignment.id)
        .single();

      setFormData((prev) => ({
        ...prev,
        enable_ai_feedback:
          (data as { enable_ai_feedback?: boolean })?.enable_ai_feedback !== false,
        auto_publish_ai_feedback: data?.auto_publish_ai_feedback !== false,
        use_course_memory: (data as { use_course_memory?: boolean }).use_course_memory !== false,
        show_task_understanding_prompt:
          (data as { show_task_understanding_prompt?: boolean }).show_task_understanding_prompt !==
          false,
        student_facing_task:
          (data as { student_facing_task?: string | null })?.student_facing_task?.trim() ||
          prev.student_facing_task,
      }));
      setSyllabusSectionId(
        (data as { syllabus_section_id?: string | null })?.syllabus_section_id || ''
      );
      setGradingCategoryId(
        (data as { grading_category_id?: string | null })?.grading_category_id || ''
      );

      let pairs: HardSkillPair[] = [];
      if (data?.hard_skills) {
        const raw = data.hard_skills as unknown;
        let parsedList: unknown = raw;
        if (typeof raw === 'string') {
          try {
            parsedList = JSON.parse(raw);
          } catch {
            parsedList = raw
              .split(',')
              .map((s) => s.trim())
              .filter(Boolean);
          }
        }
        pairs = parseHardSkillsFromDb(parsedList, data.hard_skill_domain);
      }
      let mats: Array<{ type: 'pdf' | 'link'; url: string; name: string }> = [];
      if (data?.materials) {
        try {
          const parsed =
            typeof data.materials === 'string' ? JSON.parse(data.materials) : data.materials;
          mats = Array.isArray(parsed) ? parsed : [];
        } catch {
          mats = [];
        }
      }
      const hd = data?.hard_skill_domain || '';
      const displayDomain =
        pairs.length === 0
          ? hd
          : distinctDomains(pairs).length === 1
            ? distinctDomains(pairs)[0]!
            : '';
      setFormData((prev) => ({
        ...prev,
        hard_skills: pairs,
        hard_skill_domain: displayDomain,
        materials: mats,
      }));

      const sid = (data as { syllabus_section_id?: string | null })?.syllabus_section_id;
      const { data: existingLinks } = await getLinkedActivitiesForAssignment(assignment.id);
      if (existingLinks && existingLinks.length > 0) {
        setLinkedModuleActivityIds(existingLinks.map((l) => l.activity_list_id));
      } else if (sid) {
        const { data: rids } = await getSectionResourceIdsForSectionInOrder(sid);
        setLinkedModuleActivityIds(rids ?? []);
      } else {
        setLinkedModuleActivityIds([]);
      }
    };

    void loadAssignmentData();
  }, [open, assignment?.id, isCreate]);

  useEffect(() => {
    if (!open || isCreate || !formData.hard_skill_domain) return;
    const domain = formData.hard_skill_domain;
    const matched = classroomDomains.find((d) => d.name === domain);
    if (matched) {
      setSelectedDomain(domain);
      setAvailableComponents(matched.components);
    }
  }, [open, isCreate, formData.hard_skill_domain, classroomDomains]);

  useEffect(() => {
    if (!open || !assignment || isCreate || assignment.type !== 'test') return;
    let cancelled = false;
    (async () => {
      const { data, error } = await supabase
        .from('test_questions')
        .select('*')
        .eq('assignment_id', assignment.id)
        .order('order_index', { ascending: true });
      if (cancelled || error) return;
      setTestQuestions((data ?? []).map(dbRowToTestDraft));
    })();
    return () => {
      cancelled = true;
    };
  }, [open, assignment?.id, assignment?.type, isCreate]);

  useEffect(() => {
    if (!open || isCreate) return;
    if (!assignment?.id) return;
    let cancelled = false;
    (async () => {
      const { count } = await supabase
        .from('submissions')
        .select('id', { count: 'exact', head: true })
        .eq('assignment_id', assignment.id);
      if (!cancelled) setHasSubmissions((count ?? 0) > 0);
    })();
    return () => {
      cancelled = true;
    };
  }, [open, assignment?.id, isCreate]);

  useEffect(() => {
    if (!open || isCreate) return;
    if (!assignment?.id) return;
    let cancelled = false;
    (async () => {
      const { data: submissionRows } = await supabase
        .from('submissions')
        .select('id')
        .eq('assignment_id', assignment.id);
      if (cancelled) return;
      const submissionIds = (submissionRows ?? []).map((row) => row.id);
      if (submissionIds.length === 0) {
        setHasTestResponses(false);
        return;
      }
      const { count } = await supabase
        .from('test_responses')
        .select('id', { count: 'exact', head: true })
        .in('submission_id', submissionIds);
      if (!cancelled) setHasTestResponses((count ?? 0) > 0);
    })();
    return () => {
      cancelled = true;
    };
  }, [open, assignment?.id, isCreate]);

  useEffect(() => {
    if (!open || isCreate) {
      syllabusSectionPrevRef.current = null;
      return;
    }
    const prev = syllabusSectionPrevRef.current;
    if (prev === null) {
      syllabusSectionPrevRef.current = syllabusSectionId;
      return;
    }
    if (prev === syllabusSectionId) return;
    if (prev === '' && syllabusSectionId) {
      syllabusSectionPrevRef.current = syllabusSectionId;
      return;
    }
    syllabusSectionPrevRef.current = syllabusSectionId;
    if (!syllabusSectionId || !syllabus?.section_resources) {
      setLinkedModuleActivityIds([]);
      return;
    }
    const list = syllabus.section_resources[syllabusSectionId] ?? [];
    setLinkedModuleActivityIds(list.map((r) => r.id));
  }, [open, isCreate, syllabusSectionId, syllabus]);

  const handleRephraseInstructions = async () => {
    if (!formData.instructions.trim()) {
      toast.error(t('createAssignment.rephraseError'));
      return;
    }
    setRephrasingInstructions(true);
    try {
      const sectionResources = syllabus?.section_resources?.[syllabusSectionId] ?? [];
      const referenceContext =
        syllabusSectionId && linkedModuleActivityIds.length > 0 && sectionResources.length > 0
          ? buildModuleContextTextFromSyllabusResources(linkedModuleActivityIds, sectionResources)
          : '';
      const { data, error } = await supabase.functions.invoke('rephrase-text', {
        body: {
          text: formData.instructions,
          language: isRTL ? 'he' : 'en',
          ...(referenceContext ? { referenceContext } : {}),
        },
      });
      if (error) throw error;
      if (data?.rephrasedText) {
        setFormData((prev) => ({ ...prev, instructions: data.rephrasedText }));
        toast.success(t('createAssignment.rephraseSuccess'));
      }
    } catch {
      toast.error(t('createAssignment.rephraseError'));
    } finally {
      setRephrasingInstructions(false);
    }
  };

  const handlePdfUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !user) return;
    if (!isPdfUploadFile(file)) {
      toast.error(
        t(isCreate ? 'createAssignment.errors.creating' : 'editAssignment.errors.saving')
      );
      return;
    }
    setUploadingMaterial(true);
    setUploadProgress(0);
    try {
      const fileName = `${user.id}/${Date.now()}.pdf`;
      const { error: uploadError } = await supabase.storage
        .from('assignment-materials')
        .upload(fileName, file, { cacheControl: '3600', upsert: true });
      if (uploadError) throw uploadError;
      setFormData((prev) => ({
        ...prev,
        materials: [...prev.materials, { type: 'pdf', file_path: fileName, name: file.name }],
      }));
      toast.success(t('createClassroom.success.pdfUploaded'));
      e.target.value = '';
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : 'Unknown error';
      toast.error(
        `${t(isCreate ? 'createAssignment.errors.creating' : 'editAssignment.errors.saving')}: ${msg}`
      );
    } finally {
      setUploadingMaterial(false);
    }
  };

  const handleAddLink = () => {
    if (!linkInput.trim()) {
      toast.error(t('createClassroom.errors.enterUrl'));
      return;
    }
    try {
      const url = new URL(linkInput.trim());
      const linkName =
        url.hostname.replace('www.', '') +
        (url.pathname !== '/' ? url.pathname.substring(0, 30) : '');
      setFormData((prev) => ({
        ...prev,
        materials: [
          ...prev.materials,
          { type: 'link', url: linkInput.trim(), name: linkName || linkInput.trim() },
        ],
      }));
      setLinkInput('');
      toast.success(t('createClassroom.success.linkAdded'));
    } catch {
      toast.error(t('createClassroom.errors.validUrl'));
    }
  };

  const handleRemoveMaterial = (index: number) => {
    setFormData((prev) => ({
      ...prev,
      materials: prev.materials.filter((_, i) => i !== index),
    }));
  };

  const toggleClassroomMaterial = (index: number) => {
    const material = classroomMaterials[index];
    setSelectedMaterialIds((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(index)) {
        newSet.delete(index);
        setFormData((fd) => ({
          ...fd,
          materials: fd.materials.filter((m) => !materialsMatch(m, material)),
        }));
      } else {
        newSet.add(index);
        setFormData((fd) => {
          if (!fd.materials.some((m) => materialsMatch(m, material))) {
            return { ...fd, materials: [...fd.materials, material] };
          }
          return fd;
        });
      }
      return newSet;
    });
  };

  const canProceedForStep = (stepId: AssignmentWizardStepId): boolean => {
    if (stepId === 'basics') {
      return Boolean(formData.title.trim() && formData.instructions.trim());
    }
    if (stepId === 'format') {
      if (formData.attempt_mode === 'multiple_until_due') {
        return Boolean(formData.due_at?.trim());
      }
      return true;
    }
    if (stepId === 'test') {
      return formData.type !== 'test' || validateTestQuestionsForPublish(testQuestions);
    }
    return true;
  };

  const runSuggestHardSkills = useCallback(
    async (snapshot: { instructions: string; type: string; title: string }) => {
      if (!classroomId) return;

      // State can still be [] if the user hits Next before the classroom `useEffect` fetch finishes — load domains now.
      let domains = classroomDomains;
      if (domains.length === 0) {
        const { data: roomRow, error: roomErr } = await supabase
          .from('classrooms')
          .select('domains')
          .eq('id', classroomId)
          .single();
        if (!roomErr) {
          const list = (
            roomRow as { domains?: Array<{ name: string; components: string[] }> } | null
          )?.domains;
          domains = Array.isArray(list) ? list : [];
          if (domains.length > 0) {
            setClassroomDomains(domains);
          }
        }
      }

      const token = ++suggestHardSkillsTokenRef.current;
      setHardSkillsSuggestionStatus('loading');
      setHardSkillsSuggestionSource(null);
      try {
        const { data, error } = await supabase.functions.invoke<{
          suggestions?: HardSkillPair[];
          source?: 'catalog' | 'custom';
          error?: string;
        }>('suggest-assignment-hard-skills', {
          body: {
            classroomId,
            instructions: snapshot.instructions,
            assignmentType: snapshot.type,
            title: snapshot.title,
            domains,
            language: isRTL ? 'he' : 'en',
          },
        });
        if (token !== suggestHardSkillsTokenRef.current) {
          return;
        }
        if (error) throw error;
        const suggestions = Array.isArray(data?.suggestions) ? data!.suggestions! : [];
        if (suggestions.length === 0) {
          setHardSkillsSuggestionStatus('idle');
          setHardSkillsSuggestionSource(null);
          return;
        }
        const doms = distinctDomains(suggestions);
        const singleDomain = doms.length === 1 ? doms[0]! : '';
        setFormData((prev) => ({
          ...prev,
          hard_skills: suggestions,
          hard_skill_domain: singleDomain,
        }));
        if (singleDomain) {
          const d = domains.find((x) => x.name === singleDomain);
          setSelectedDomain(singleDomain);
          if (d) setAvailableComponents(d.components);
        } else {
          setSelectedDomain('');
          setAvailableComponents([]);
        }
        setHardSkillsSuggestionStatus('success');
        setHardSkillsSuggestionSource(data?.source === 'catalog' ? 'catalog' : 'custom');
      } catch (e) {
        if (token !== suggestHardSkillsTokenRef.current) {
          return;
        }
        console.error(e);
        setHardSkillsSuggestionStatus('error');
        setHardSkillsSuggestionSource(null);
      }
    },
    [classroomId, classroomDomains, isRTL]
  );

  const handleNext = () => {
    if (!canProceedForStep(currentStepId)) return;
    const i = stepOrder.indexOf(currentStepId);
    if (i < 0 || i >= stepOrder.length - 1) return;
    if (currentStepId === 'basics') {
      queueBackgroundStudentTaskPrefill({
        title: formData.title,
        instructions: formData.instructions,
      });
    }
    if (currentStepId === 'format') {
      void runSuggestHardSkills({
        instructions: formData.instructions,
        type: formData.type,
        title: formData.title,
      });
    }
    setCurrentStepId(stepOrder[i + 1]!);
  };

  const handleBack = () => {
    const i = stepOrder.indexOf(currentStepId);
    if (i <= 0) return;
    setCurrentStepId(stepOrder[i - 1]!);
  };

  const handleGenerateStudentFacingTask = useCallback(async () => {
    if (!classroomId || !formData.instructions.trim()) return;
    setGeneratingStudentTask(true);
    try {
      const { data, error } = await supabase.functions.invoke('generate-student-facing-task', {
        body: {
          classroomId,
          title: formData.title,
          instructions: formData.instructions,
          language: uiLanguage,
        },
      });
      if (error) {
        const serverMsg = await parseEdgeFunctionErrorMessage(error);
        toast.error(serverMsg || t('createAssignment.wizard.studentFacingGenerateFailed'));
        return;
      }
      const payload = data as { studentFacingTask?: string; opikTraceId?: string; error?: string };
      const task = payload.studentFacingTask;
      const errMsg = payload.error;
      if (errMsg) {
        toast.error(errMsg);
        return;
      }
      if (task?.trim()) {
        setFormData((prev) => {
          const nextIds = { ...(prev.opik_trace_ids ?? {}) };
          if (payload.opikTraceId?.trim()) {
            nextIds.student_facing_task = payload.opikTraceId.trim();
          }
          return {
            ...prev,
            student_facing_task: task.trim(),
            opik_trace_ids: nextIds,
          };
        });
        toast.success(t('createAssignment.wizard.studentFacingGenerated'));
      } else {
        toast.error(t('createAssignment.wizard.studentFacingGenerateFailed'));
      }
    } catch (e) {
      console.error(e);
      toast.error(t('common.error'));
    } finally {
      setGeneratingStudentTask(false);
    }
  }, [classroomId, formData.instructions, formData.title, t, uiLanguage]);

  const resetWizardUi = () => {
    setCurrentStepId(ASSIGNMENT_WIZARD_FIRST_STEP);
    setHardSkillsSuggestionStatus('idle');
    setHardSkillsSuggestionSource(null);
    if (isCreate) resetCreateDefaults();
  };

  const handleDialogOpenChange = (val: boolean) => {
    onOpenChange(val);
    if (!val) resetWizardUi();
  };

  const handleSubmit = async () => {
    if (loading) return;
    if (!canProceedForStep('basics') || !canProceedForStep('format')) {
      toast.error(t('createAssignment.wizard.fixValidation'));
      return;
    }
    if (formData.type === 'test' && !validateTestQuestionsForPublish(testQuestions)) {
      toast.error(t('createAssignment.wizard.testQuestionsInvalid'));
      return;
    }

    setLoading(true);
    try {
      if (formData.attempt_mode === 'multiple_until_due' && !formData.due_at?.trim()) {
        toast.error(t('createAssignment.attemptMode.dueRequiredForRetries'));
        setLoading(false);
        return;
      }

      if (isCreate && classroomId) {
        let studentFacingTaskForInsert = formData.student_facing_task.trim();
        let opikTraceIdsForInsert = { ...(formData.opik_trace_ids ?? {}) };
        if (!studentFacingTaskForInsert && formData.instructions.trim()) {
          const generated = await generateStudentFacingTaskDraft({
            classroomId,
            title: formData.title,
            instructions: formData.instructions,
            uiLanguage: uiLanguage === 'he' ? 'he' : 'en',
          });
          if (generated) {
            studentFacingTaskForInsert = generated.task;
            if (generated.opikTraceId) {
              opikTraceIdsForInsert = {
                ...opikTraceIdsForInsert,
                student_facing_task: generated.opikTraceId,
              };
            }
          }
        }

        const insertRow: Database['public']['Tables']['assignments']['Insert'] = {
          classroom_id: classroomId,
          title: formData.title,
          instructions: formData.instructions,
          student_facing_task: studentFacingTaskForInsert || null,
          opik_trace_ids:
            Object.keys(opikTraceIdsForInsert).length > 0
              ? (opikTraceIdsForInsert as unknown as Json)
              : {},
          type: formData.type as Database['public']['Enums']['assignment_type'],
          due_at: dueAtLocalInputToIso(formData.due_at),
          attempt_mode: formData.attempt_mode,
          status: formData.status as Database['public']['Enums']['assignment_status'],
          hard_skills: JSON.stringify(formData.hard_skills),
          hard_skill_domain: resolveHardSkillDomainForDb(
            formData.hard_skills,
            formData.hard_skill_domain
          ),
          materials: (formData.materials ?? null) as unknown as Json | null,
          target_dimensions: formData.target_dimensions as unknown as Json,
          personalization_flag: formData.personalization_flag,
          enable_ai_feedback: formData.enable_ai_feedback,
          auto_publish_ai_feedback: formData.auto_publish_ai_feedback,
          use_course_memory: formData.use_course_memory,
          show_task_understanding_prompt: formData.show_task_understanding_prompt,
          assigned_student_id: assignedStudentId || null,
          syllabus_section_id: syllabusSectionId || null,
          grading_category_id: gradingCategoryId || null,
        };
        const { data: assignmentRow, error } = await supabase
          .from('assignments')
          .insert([insertRow])
          .select()
          .single();

        if (error) throw error;

        if (assignmentRow) {
          const items = linkedModuleActivityIds.map((id, i) => ({
            activity_list_id: id,
            order_index: i,
            include_in_ai_context: true,
          }));
          const { error: linkErr } = await setAssignmentLinkedActivities(
            assignmentRow.id,
            syllabusSectionId || null,
            items
          );
          if (linkErr) {
            console.error('assignment module activities:', linkErr);
            toast.warning(
              t(
                'syllabus.moduleActivities.linkSaveWarning',
                'Assignment was created, but module activity links could not be saved. You can edit the assignment to fix them.'
              )
            );
          }
        }

        if (formData.type === 'test' && assignmentRow) {
          const questionsToInsert = testQuestions.map((q) =>
            testQuestionToInsertRow(q, assignmentRow.id)
          );
          const { error: questionsError } = await supabase
            .from('test_questions')
            .insert(questionsToInsert);
          if (questionsError) {
            toast.error(t('createAssignment.wizard.testQuestionsSaveFailed'));
            throw questionsError;
          }
        }

        if (assignmentRow?.id && !studentFacingTaskForInsert && formData.instructions?.trim()) {
          await prefillStudentFacingTaskForAssignment(assignmentRow.id, {
            instructions: formData.instructions,
            uiLanguage: uiLanguage === 'he' ? 'he' : 'en',
          });
        }

        if (assignmentRow && formData.status === 'published') {
          try {
            if (assignedStudentId) {
              await createBulkNotifications([
                {
                  userId: assignedStudentId,
                  type: 'assignment_created' as const,
                  title: 'New Personalized Assignment',
                  message: `A follow-up assignment "${formData.title}" has been created for you`,
                  link: `/student/assignment/${assignmentRow.id}`,
                  actorId: user!.id,
                  metadata: {
                    assignment_id: assignmentRow.id,
                    classroom_id: classroomId,
                    assignment_title: formData.title,
                  },
                },
              ]);
            } else {
              const { data: enrollments } = await supabase
                .from('enrollments')
                .select('student_id')
                .eq('classroom_id', classroomId);
              if (enrollments && enrollments.length > 0) {
                const notifications = enrollments.map((e) => ({
                  userId: e.student_id,
                  type: 'assignment_created' as const,
                  title: 'New Assignment',
                  message: `New assignment "${formData.title}" has been posted`,
                  link: `/student/assignment/${assignmentRow.id}`,
                  actorId: user!.id,
                  metadata: {
                    assignment_id: assignmentRow.id,
                    classroom_id: classroomId,
                    assignment_title: formData.title,
                  },
                }));
                await createBulkNotifications(notifications);
              }
            }
          } catch (e) {
            console.error('Error sending notifications:', e);
          }
        }

        try {
          await supabase.from('activity_events').insert([
            {
              teacher_id: user!.id,
              type: 'create',
              entity_type: 'assignment',
              entity_id: assignmentRow.id,
              title: `Created assignment: ${formData.title}`,
              route: `/teacher/classroom/${classroomId}`,
            },
          ]);
        } catch {
          /* non-critical */
        }

        toast.success(t('createAssignment.success.created'));
        if (assignmentRow?.id) onCreatedAssignment?.(assignmentRow.id);
        if (syllabusSectionId) {
          await syncModuleFlowToResolvedDisplayForSection(
            queryClient,
            classroomId,
            syllabusSectionId,
            {
              ensureAssignmentIds: assignmentRow?.id ? [assignmentRow.id] : undefined,
            }
          );
        } else {
          await queryClient.invalidateQueries({ queryKey: syllabusKeys.byClassroom(classroomId) });
          await queryClient.invalidateQueries({
            queryKey: assignmentKeys.classroomAssignmentLists(classroomId),
            exact: false,
          });
          await queryClient.invalidateQueries({ queryKey: moduleFlowKeys.all });
        }
        try {
          sessionStorage.removeItem(
            assignmentCreateDraftKey(
              classroomId,
              syllabusSectionId || initialData?.syllabus_section_id || 'none'
            )
          );
        } catch {
          /* ignore */
        }
        handleDialogOpenChange(false);
        onSuccess();
        return;
      }

      if (!isCreate && assignment) {
        const wasPublished = assignment.status === 'draft' && formData.status === 'published';

        const baseUpdate: Database['public']['Tables']['assignments']['Update'] = {
          title: formData.title,
          instructions: formData.instructions,
          student_facing_task: formData.student_facing_task.trim() || null,
          type: formData.type as Database['public']['Enums']['assignment_type'],
          status: formData.status as Database['public']['Enums']['assignment_status'],
          hard_skills: JSON.stringify(formData.hard_skills),
          hard_skill_domain: resolveHardSkillDomainForDb(
            formData.hard_skills,
            formData.hard_skill_domain
          ),
          materials: (formData.materials ?? null) as unknown as Json | null,
          enable_ai_feedback: formData.enable_ai_feedback,
          auto_publish_ai_feedback: formData.auto_publish_ai_feedback,
          use_course_memory: formData.use_course_memory,
          show_task_understanding_prompt: formData.show_task_understanding_prompt,
          syllabus_section_id: syllabusSectionId || null,
          grading_category_id: gradingCategoryId || null,
        };

        const dueAtIso = dueAtLocalInputToIso(formData.due_at);
        baseUpdate.due_at = dueAtIso;
        if (!policyFrozen) {
          baseUpdate.attempt_mode = formData.attempt_mode;
        }

        const { error } = await supabase
          .from('assignments')
          .update(baseUpdate)
          .eq('id', assignment.id);
        if (error) throw error;

        if (!formData.student_facing_task?.trim() && formData.instructions?.trim()) {
          await prefillStudentFacingTaskForAssignment(assignment.id, {
            instructions: formData.instructions,
            uiLanguage: uiLanguage === 'he' ? 'he' : 'en',
          });
        }

        const linkItems = linkedModuleActivityIds.map((id, i) => ({
          activity_list_id: id,
          order_index: i,
          include_in_ai_context: true,
        }));
        const { error: linkErr } = await setAssignmentLinkedActivities(
          assignment.id,
          syllabusSectionId || null,
          linkItems
        );
        if (linkErr) {
          toast.warning(
            t(
              'syllabus.moduleActivities.linkSaveWarning',
              'Assignment was saved, but module activity links could not be updated.'
            )
          );
        }

        if (formData.type === 'test' && !hasTestResponses) {
          const { error: delErr } = await supabase
            .from('test_questions')
            .delete()
            .eq('assignment_id', assignment.id);
          if (delErr) {
            toast.error(t('createAssignment.wizard.testQuestionsSaveFailed'));
            throw delErr;
          }
          if (testQuestions.length > 0) {
            const questionsToInsert = testQuestions.map((q) =>
              testQuestionToInsertRow(q, assignment.id)
            );
            const { error: insErr } = await supabase
              .from('test_questions')
              .insert(questionsToInsert);
            if (insErr) {
              toast.error(t('createAssignment.wizard.testQuestionsSaveFailed'));
              throw insErr;
            }
          }
          await queryClient.invalidateQueries({
            queryKey: [...testKeys.all, 'questions', assignment.id],
          });
        }

        if (wasPublished) {
          try {
            let classroomIdForNotify = assignment.classroom_id;
            if (!classroomIdForNotify) {
              const { data: assignmentData } = await supabase
                .from('assignments')
                .select('classroom_id')
                .eq('id', assignment.id)
                .single();
              classroomIdForNotify = assignmentData?.classroom_id;
            }
            if (classroomIdForNotify) {
              const { data: enrollments, error: enrollError } = await supabase
                .from('enrollments')
                .select('student_id')
                .eq('classroom_id', classroomIdForNotify);
              if (!enrollError && enrollments && enrollments.length > 0) {
                const notifications = enrollments.map((enrollment) => ({
                  userId: enrollment.student_id,
                  type: 'assignment_created' as const,
                  title: 'New Assignment Posted',
                  message: `${formData.title} has been assigned`,
                  link: `/student/assignment/${assignment.id}`,
                  actorId: user!.id,
                  metadata: {
                    assignment_id: assignment.id,
                    classroom_id: classroomIdForNotify,
                    assignment_title: formData.title,
                    due_at: formData.due_at || null,
                  },
                }));
                await createBulkNotifications(notifications);
              }
            }
          } catch {
            /* non-critical */
          }
        }

        toast.success(t('editAssignment.success.saved'));
        const cid = assignment.classroom_id;
        if (cid) {
          if (syllabusSectionId) {
            await syncModuleFlowToResolvedDisplayForSection(queryClient, cid, syllabusSectionId);
          } else {
            await queryClient.invalidateQueries({ queryKey: syllabusKeys.byClassroom(cid) });
            await queryClient.invalidateQueries({ queryKey: moduleFlowKeys.all });
          }
          await queryClient.invalidateQueries({
            queryKey: assignmentKeys.classroomAssignmentLists(cid),
            exact: false,
          });
        }
        handleDialogOpenChange(false);
        onSuccess();
      }
    } catch (e) {
      console.error(e);
      toast.error(
        t(isCreate ? 'createAssignment.errors.creating' : 'editAssignment.errors.saving')
      );
    } finally {
      setLoading(false);
    }
  };

  const basicsKey = isCreate
    ? open
      ? `${classroomId}-${initialData?.title ?? 'new'}`
      : 'closed'
    : (assignment?.id ?? 'closed');

  const headerTitle = isCreate ? t('createAssignment.title') : t('editAssignment.title');

  const headerDescription = isCreate
    ? t('createAssignment.description')
    : t('editAssignment.description');

  const finalButtonLabel = isCreate
    ? t('createAssignment.createButton')
    : t('editAssignment.saveButton');

  return (
    <Dialog open={open} onOpenChange={handleDialogOpenChange}>
      <DialogContent
        dir={isRTL ? 'rtl' : 'ltr'}
        className="sm:max-w-6xl w-[95vw] max-h-[92vh] h-[92vh] p-0 overflow-hidden rounded-xl border-none shadow-2xl bg-background flex flex-col"
        showCloseButton
      >
        <div className="px-6 pt-6 pb-4 border-b border-border bg-gradient-to-br from-muted/20 to-transparent flex-shrink-0">
          <h2
            className={`text-2xl font-bold tracking-tight text-heading mb-1 ${isRTL ? 'text-right' : 'text-left'}`}
          >
            {headerTitle}
          </h2>
          <p className={`text-subtle text-body mb-4 ${isRTL ? 'text-right' : 'text-left'}`}>
            {headerDescription}
          </p>
          <WizardStepIndicator
            steps={indicatorSteps}
            currentStep={currentStepIndex}
            isRTL={isRTL}
          />
        </div>

        <ScrollArea className="flex-1 min-h-0">
          <div className="px-6 py-6">
            {currentStepId === 'basics' && (
              <AssignmentBasicsStep
                formData={formData}
                onFormChange={(partial) => setFormData((prev) => ({ ...prev, ...partial }))}
                isRTL={isRTL}
                rephrasingInstructions={rephrasingInstructions}
                onRephrase={() => void handleRephraseInstructions()}
                basicsTextareaKey={basicsKey}
              />
            )}
            {currentStepId === 'format' && (
              <AssignmentFormatStep
                formData={formData}
                onFormChange={(updater) => setFormData(updater)}
                isRTL={isRTL}
                attemptPolicyFrozen={policyFrozen}
              />
            )}
            {currentStepId === 'courseRelease' && (
              <AssignmentCourseReleaseStep
                syllabus={syllabus ?? undefined}
                syllabusLoading={isSyllabusLoading}
                syllabusSectionId={syllabusSectionId}
                onSyllabusSectionIdChange={setSyllabusSectionId}
                gradingCategoryId={gradingCategoryId}
                onGradingCategoryIdChange={setGradingCategoryId}
                linkedModuleActivityIds={linkedModuleActivityIds}
                onLinkedModuleActivityIdsChange={setLinkedModuleActivityIds}
                isRTL={isRTL}
                lockSyllabusSection={lockSyllabusSection}
                loading={loading}
                formData={formData}
                onFormChange={(updater) => setFormData(updater)}
              />
            )}
            {currentStepId === 'skills' && (
              <AssignmentSkillsMaterialsStep
                formData={formData}
                onFormChange={(updater) => setFormData(updater)}
                isRTL={isRTL}
                isEditMode={!isCreate}
                classroomDomains={classroomDomains}
                classroomMaterials={classroomMaterials}
                selectedDomain={selectedDomain}
                onSelectedDomainChange={setSelectedDomain}
                availableComponents={availableComponents}
                onAvailableComponentsChange={setAvailableComponents}
                selectedMaterialIds={selectedMaterialIds}
                onToggleClassroomMaterial={toggleClassroomMaterial}
                linkInput={linkInput}
                onLinkInputChange={setLinkInput}
                onAddLink={handleAddLink}
                onPdfUpload={(e) => void handlePdfUpload(e)}
                onRemoveMaterial={handleRemoveMaterial}
                uploadingMaterial={uploadingMaterial}
                uploadProgress={uploadProgress}
                moduleOutlineResources={moduleOutlineResources}
                hardSkillsSuggestionStatus={hardSkillsSuggestionStatus}
                hardSkillsSuggestionSource={hardSkillsSuggestionSource}
                onRetrySuggestHardSkills={() =>
                  void runSuggestHardSkills({
                    instructions: formData.instructions,
                    type: formData.type,
                    title: formData.title,
                  })
                }
              />
            )}
            {currentStepId === 'test' && (
              <AssignmentTestStep
                questions={testQuestions}
                onQuestionsChange={setTestQuestions}
                isRTL={isRTL}
                readOnly={!isCreate && hasTestResponses}
              />
            )}
            {currentStepId === 'review' && (
              <AssignmentReviewStep
                formData={formData}
                syllabus={syllabus ?? undefined}
                syllabusSectionId={syllabusSectionId}
                testQuestions={testQuestions}
                onJumpToStep={setCurrentStepId}
                isRTL={isRTL}
                onStudentFacingTaskChange={(value) =>
                  setFormData((prev) => ({ ...prev, student_facing_task: value }))
                }
                onGenerateForStudents={() => void handleGenerateStudentFacingTask()}
                generatingStudentTask={generatingStudentTask}
              />
            )}
          </div>
        </ScrollArea>

        <div className="px-6 py-4 border-t border-border flex-shrink-0">
          <div className={`flex items-center justify-between ${isRTL ? 'flex-row-reverse' : ''}`}>
            <div>
              {currentStepIndex > 0 && (
                <Button
                  type="button"
                  variant="ghost"
                  onClick={handleBack}
                  disabled={loading}
                  className="rounded-full gap-2"
                >
                  {isRTL ? <ArrowRight className="h-4 w-4" /> : <ArrowLeft className="h-4 w-4" />}
                  {t('syllabus.wizard.back')}
                </Button>
              )}
            </div>
            <div className={`flex items-center gap-3 ${isRTL ? 'flex-row-reverse' : ''}`}>
              <Button
                type="button"
                variant="ghost"
                onClick={() => handleDialogOpenChange(false)}
                disabled={loading}
              >
                {t('createAssignment.cancel')}
              </Button>
              {!isLastStep ? (
                <Button
                  type="button"
                  onClick={handleNext}
                  disabled={!canProceedForStep(currentStepId) || loading}
                  className="rounded-full px-8 font-bold shadow-lg shadow-primary/20 gap-2"
                >
                  {t('syllabus.wizard.next')}
                  {isRTL ? <ArrowLeft className="h-4 w-4" /> : <ArrowRight className="h-4 w-4" />}
                </Button>
              ) : (
                <Button
                  type="button"
                  onClick={() => void handleSubmit()}
                  disabled={
                    loading ||
                    !canProceedForStep('basics') ||
                    (formData.type === 'test' && !canProceedForStep('test'))
                  }
                  className="rounded-full px-10 font-bold shadow-lg shadow-primary/20"
                >
                  {loading ? (
                    <>
                      <Loader2 className="h-4 w-4 animate-spin me-2" />
                      {!isCreate ? t('editAssignment.saving') : t('createAssignment.createButton')}
                    </>
                  ) : (
                    finalButtonLabel
                  )}
                </Button>
              )}
            </div>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
};

import { Pencil, Sparkles, Loader2 } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import type { AssignmentWizardFormData, AssignmentWizardStepId } from '../assignmentWizardTypes';
import type { TestQuestionDraft } from '@/components/features/assignment/TestQuestionBuilder';
import type { SyllabusWithSections } from '@/types/syllabus';
import { AiContentFlagButton, readOpikTraceId } from '@/components/common/AiContentFlagButton';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { distinctDomains } from '@/lib/hardSkillsFormat';
import { cn } from '@/lib/utils';

interface AssignmentReviewStepProps {
  formData: AssignmentWizardFormData;
  syllabus: SyllabusWithSections | null | undefined;
  syllabusSectionId: string;
  testQuestions: TestQuestionDraft[];
  onJumpToStep: (id: AssignmentWizardStepId) => void;
  isRTL: boolean;
  onStudentFacingTaskChange: (value: string) => void;
  onGenerateForStudents: () => void;
  generatingStudentTask: boolean;
}

const ReviewField = ({ label, value, isRTL }: { label: string; value: string; isRTL: boolean }) => {
  return (
    <div
      className={cn(
        'grid gap-1 border-b border-border/60 pb-3 last:border-b-0 last:pb-0 sm:grid-cols-[minmax(7.5rem,32%)_1fr] sm:items-start sm:gap-x-6',
        isRTL && 'sm:[direction:ltr]'
      )}
    >
      <dt
        className={cn(
          'text-[11px] font-semibold uppercase tracking-wide text-muted-foreground',
          isRTL ? 'sm:text-end' : 'sm:text-start'
        )}
      >
        {label}
      </dt>
      <dd
        className={cn(
          'text-sm leading-relaxed text-foreground break-words',
          isRTL ? 'text-right sm:text-end' : 'text-left sm:text-start'
        )}
        dir="auto"
      >
        {value || '—'}
      </dd>
    </div>
  );
};

export const AssignmentReviewStep = ({
  formData,
  syllabus,
  syllabusSectionId,
  testQuestions,
  onJumpToStep,
  isRTL,
  onStudentFacingTaskChange,
  onGenerateForStudents,
  generatingStudentTask,
}: AssignmentReviewStepProps) => {
  const { t } = useTranslation();

  const sectionTitle =
    syllabus?.sections?.find((s) => s.id === syllabusSectionId)?.title ||
    (syllabusSectionId ? syllabusSectionId : '—');

  const instructionPreview = (() => {
    const s = formData.instructions?.trim();
    if (!s) return '—';
    if (s.length <= 200) return s;
    return `${s.slice(0, 200)}…`;
  })();

  const studentFacingTraceId = readOpikTraceId(formData.opik_trace_ids, 'student_facing_task');
  const instructionsTraceId = readOpikTraceId(formData.opik_trace_ids, 'instructions');

  const attemptLabel =
    formData.attempt_mode === 'multiple_until_due'
      ? t('createAssignment.attemptMode.multipleUntilDue')
      : formData.attempt_mode === 'multiple_unlimited'
        ? t('createAssignment.attemptMode.unlimited')
        : t('createAssignment.attemptMode.single');

  type SectionDef = {
    step: AssignmentWizardStepId;
    title: string;
    rows: { label: string; value: string }[];
  };

  const sections: SectionDef[] = [
    {
      step: 'basics',
      title: t('createAssignment.wizard.steps.basics'),
      rows: [
        { label: t('createAssignment.titleLabel'), value: formData.title || '' },
        { label: t('createAssignment.instructionsLabel'), value: instructionPreview },
      ],
    },
    {
      step: 'format',
      title: t('createAssignment.wizard.steps.format'),
      rows: [
        {
          label: t('createAssignment.metadata.assignmentType'),
          value: formData.type ? t(`createAssignment.typeOptions.${formData.type}`) : '',
        },
        {
          label: t('createAssignment.dueDate'),
          value: formData.due_at?.trim() || t('createAssignment.wizard.reviewNone'),
        },
        { label: t('createAssignment.attemptMode.label'), value: attemptLabel },
      ],
    },
    {
      step: 'courseRelease',
      title: t('createAssignment.wizard.steps.courseRelease'),
      rows: [
        { label: t('createAssignment.metadata.assignmentDetailsTitle'), value: sectionTitle },
        {
          label: t('createAssignment.metadata.publicationStatus'),
          value:
            formData.status === 'draft'
              ? t('assignments.status.draft')
              : t('assignments.status.published'),
        },
        {
          label: t('createAssignment.metadata.aiFeedback'),
          value: formData.enable_ai_feedback ? t('common.yes') : t('common.no'),
        },
        {
          label: t('createAssignment.metadata.showFeedback'),
          value: formData.auto_publish_ai_feedback ? t('common.yes') : t('common.no'),
        },
        {
          label: t('createAssignment.taskUnderstandingPrompt.label'),
          value: formData.show_task_understanding_prompt ? t('common.yes') : t('common.no'),
        },
      ],
    },
    {
      step: 'skills',
      title: t('createAssignment.wizard.steps.skills'),
      rows: [
        {
          label: t('createAssignment.subjectAreaLabel'),
          value: (() => {
            const doms = distinctDomains(formData.hard_skills);
            if (doms.length > 1) return doms.join(', ');
            if (doms.length === 1) return doms[0]!;
            return formData.hard_skill_domain?.trim() || '';
          })(),
        },
        {
          label: t('createAssignment.skillsToAssess'),
          value:
            formData.hard_skills.filter((p) => p.skill.trim()).length > 0
              ? formData.hard_skills
                  .filter((p) => p.skill.trim())
                  .map((p) => (p.domain.trim() ? `${p.domain} — ${p.skill}` : p.skill))
                  .join('; ')
              : '',
        },
        {
          label: t('createAssignment.assignmentMaterials'),
          value: t('createAssignment.wizard.materialCount', { count: formData.materials.length }),
        },
      ],
    },
  ];

  if (formData.type === 'test') {
    sections.push({
      step: 'test',
      title: t('createAssignment.wizard.steps.test'),
      rows: [
        {
          label: t('createAssignment.typeOptions.test'),
          value: t('createAssignment.wizard.questionCount', { count: testQuestions.length }),
        },
      ],
    });
  }

  return (
    <div className="mx-auto max-w-2xl space-y-4 pb-2" dir={isRTL ? 'rtl' : 'ltr'}>
      <div className={cn('space-y-1', isRTL ? 'text-right' : 'text-left')}>
        <h3 className="text-lg font-semibold tracking-tight text-foreground">
          {t('createAssignment.wizard.reviewTitle')}
        </h3>
        <p className="text-sm text-muted-foreground">
          {t('createAssignment.wizard.reviewSubtitle')}
        </p>
      </div>

      <section
        className="overflow-hidden rounded-xl border border-border bg-card shadow-sm"
        id="review-student-facing-task"
      >
        <div
          className={cn(
            'flex flex-col gap-3 border-b border-border bg-muted/25 px-4 py-3 sm:flex-row sm:items-center sm:justify-between',
            isRTL && 'sm:flex-row-reverse'
          )}
        >
          <div className="space-y-0.5">
            <h4 className="text-sm font-semibold text-foreground">
              {t('createAssignment.wizard.studentFacingTitle')}
            </h4>
            <p className="text-xs text-muted-foreground">
              {t('createAssignment.wizard.studentFacingHint')}
            </p>
          </div>
          <div className="flex shrink-0 items-center gap-1">
            {studentFacingTraceId ? (
              <AiContentFlagButton
                contentType="student_facing_task"
                contentExcerpt={formData.student_facing_task}
                opikTraceId={studentFacingTraceId}
              />
            ) : null}
            <Button
              type="button"
              variant="secondary"
              size="sm"
              className="gap-1.5"
              onClick={onGenerateForStudents}
              disabled={!formData.instructions.trim() || generatingStudentTask}
            >
              {generatingStudentTask ? (
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
              ) : (
                <Sparkles className="h-3.5 w-3.5" />
              )}
              {t('createAssignment.wizard.generateForStudents')}
            </Button>
          </div>
        </div>
        <div className="space-y-2 px-4 py-4">
          <Label htmlFor="student-facing-task" className="sr-only">
            {t('createAssignment.wizard.studentFacingTitle')}
          </Label>
          <Textarea
            id="student-facing-task"
            dir="auto"
            rows={4}
            className="min-h-[100px] resize-y text-sm"
            placeholder={t('createAssignment.wizard.studentFacingPlaceholder')}
            value={formData.student_facing_task}
            onChange={(e) => onStudentFacingTaskChange(e.target.value)}
          />
        </div>
      </section>

      {instructionsTraceId && formData.instructions.trim() ? (
        <section className="overflow-hidden rounded-xl border border-border bg-card shadow-sm">
          <div
            className={cn(
              'flex items-center justify-between gap-3 border-b border-border bg-muted/25 px-4 py-3',
              isRTL && 'flex-row-reverse'
            )}
          >
            <h4 className="text-sm font-semibold text-foreground">
              {t('createAssignment.instructionsLabel')}
            </h4>
            <AiContentFlagButton
              contentType="instructions"
              contentExcerpt={formData.instructions}
              opikTraceId={instructionsTraceId}
            />
          </div>
          <p className="px-4 py-3 text-sm text-muted-foreground whitespace-pre-wrap" dir="auto">
            {instructionPreview}
          </p>
        </section>
      ) : null}

      <div className="space-y-4">
        {sections.map((section) => (
          <section
            key={section.step}
            className="overflow-hidden rounded-xl border border-border bg-card shadow-sm"
          >
            <div
              className={cn(
                'flex items-center gap-3 border-b border-border bg-muted/25 px-4 py-3',
                isRTL ? 'flex-row-reverse justify-between' : 'justify-between'
              )}
            >
              <h4 className="text-sm font-semibold text-foreground">{section.title}</h4>
              <Button
                type="button"
                variant="ghost"
                size="sm"
                className={cn(
                  'h-8 gap-1.5 text-primary hover:text-primary',
                  isRTL && 'flex-row-reverse'
                )}
                onClick={() => onJumpToStep(section.step)}
              >
                <Pencil className="h-3.5 w-3.5 opacity-80" />
                {t('createAssignment.wizard.editSection')}
              </Button>
            </div>
            <div className="space-y-3 px-4 py-4">
              {section.rows.map((row) => (
                <ReviewField
                  key={`${section.step}-${row.label}`}
                  label={row.label}
                  value={row.value}
                  isRTL={isRTL}
                />
              ))}
            </div>
          </section>
        ))}
      </div>
    </div>
  );
};

import {
  Target,
  FileText,
  X,
  Upload,
  Link as LinkIcon,
  Plus,
  Eye,
  Loader2,
  RefreshCw,
  BookOpen,
} from 'lucide-react';
import { useTranslation } from 'react-i18next';
import type { AssignmentWizardFormData } from '../assignmentWizardTypes';
import type { CourseMaterial } from '@/types/models';
import type { SectionResource } from '@/types/syllabus';
import { ResourceViewer } from '@/components/features/syllabus/ResourceViewer';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { pairKey } from '@/lib/hardSkillsFormat';
import { cn } from '@/lib/utils';
import { openOrDownloadMaterial, resolveMaterialBucket } from '@/services/materialService';
import { ASSIGNMENT_MATERIALS_BUCKET } from '@/utils/storageUrls';

const MAX_HARD_SKILLS = 5;

export type HardSkillsSuggestionStatus = 'idle' | 'loading' | 'success' | 'error';

interface AssignmentSkillsMaterialsStepProps {
  formData: AssignmentWizardFormData;
  onFormChange: (updater: (prev: AssignmentWizardFormData) => AssignmentWizardFormData) => void;
  isRTL: boolean;
  isEditMode: boolean;
  classroomDomains: Array<{ name: string; components: string[] }>;
  classroomMaterials: Array<{ type: 'pdf' | 'link'; url: string; name: string }>;
  selectedDomain: string;
  onSelectedDomainChange: (v: string) => void;
  availableComponents: string[];
  onAvailableComponentsChange: (v: string[]) => void;
  selectedMaterialIds: Set<number>;
  onToggleClassroomMaterial: (index: number) => void;
  linkInput: string;
  onLinkInputChange: (v: string) => void;
  onAddLink: () => void;
  onPdfUpload: (e: React.ChangeEvent<HTMLInputElement>) => void;
  onRemoveMaterial: (index: number) => void;
  uploadingMaterial: boolean;
  uploadProgress: number;
  moduleOutlineResources?: SectionResource[];
  hardSkillsSuggestionStatus?: HardSkillsSuggestionStatus;
  hardSkillsSuggestionSource?: 'catalog' | 'custom' | null;
  onRetrySuggestHardSkills?: () => void;
}

export const AssignmentSkillsMaterialsStep = ({
  formData,
  onFormChange,
  isRTL,
  isEditMode,
  classroomDomains,
  classroomMaterials,
  selectedDomain,
  onSelectedDomainChange,
  availableComponents,
  onAvailableComponentsChange,
  selectedMaterialIds,
  onToggleClassroomMaterial,
  linkInput,
  onLinkInputChange,
  onAddLink,
  onPdfUpload,
  onRemoveMaterial,
  uploadingMaterial,
  uploadProgress,
  moduleOutlineResources = [],
  hardSkillsSuggestionStatus = 'idle',
  hardSkillsSuggestionSource = null,
  onRetrySuggestHardSkills,
}: AssignmentSkillsMaterialsStepProps) => {
  const { t } = useTranslation();
  const atCap = formData.hard_skills.length >= MAX_HARD_SKILLS;

  return (
    <div className="space-y-8">
      <div className="space-y-6 p-6 rounded-xl border border-border shadow-sm">
        <div
          className={`flex items-center gap-2 text-primary mb-2 ${isRTL ? 'flex-row-reverse' : ''}`}
        >
          <Target className="h-5 w-5" />
          <h3 className={`font-bold text-heading ${isRTL ? 'text-right' : 'text-left'}`}>
            {t('createAssignment.subjectAreaAndSkills')}
          </h3>
        </div>

        <p className={`text-sm text-subtle mb-4 ${isRTL ? 'text-right' : 'text-left'}`}>
          {isEditMode
            ? t('editAssignment.subjectAreasHelper')
            : t('createAssignment.subjectAreasHelper')}
        </p>

        {hardSkillsSuggestionStatus === 'loading' && (
          <div
            className={cn(
              'flex items-center gap-2 rounded-lg border border-border bg-muted/30 px-3 py-2 text-sm text-muted-foreground',
              isRTL ? 'flex-row-reverse' : ''
            )}
          >
            <Loader2 className="h-4 w-4 shrink-0 animate-spin" />
            <span>{t('createAssignment.hardSkillsSuggestion.loading')}</span>
          </div>
        )}
        {hardSkillsSuggestionStatus === 'error' && (
          <div
            className={cn(
              'flex flex-wrap items-center justify-between gap-2 rounded-lg border border-destructive/30 bg-destructive/5 px-3 py-2 text-sm',
              isRTL ? 'flex-row-reverse' : ''
            )}
          >
            <span className="text-destructive">
              {t('createAssignment.hardSkillsSuggestion.error')}
            </span>
            {onRetrySuggestHardSkills ? (
              <Button
                type="button"
                variant="outline"
                size="sm"
                className="h-8 gap-1"
                onClick={() => onRetrySuggestHardSkills()}
              >
                <RefreshCw className="h-3.5 w-3.5" />
                {t('createAssignment.hardSkillsSuggestion.retry')}
              </Button>
            ) : null}
          </div>
        )}
        {hardSkillsSuggestionStatus === 'success' && (
          <p className={`text-xs text-muted-foreground ${isRTL ? 'text-right' : 'text-left'}`}>
            {hardSkillsSuggestionSource === 'catalog'
              ? t('createAssignment.hardSkillsSuggestion.successHintCatalog')
              : t('createAssignment.hardSkillsSuggestion.successHintCustom')}
          </p>
        )}

        <div className="space-y-2">
          <Label
            htmlFor="wiz-hard_skill_domain"
            className={`text-body font-medium block ${isRTL ? 'text-right' : 'text-left'}`}
          >
            {t('createAssignment.subjectAreaLabel')}
          </Label>
          {classroomDomains.length > 0 ? (
            <div className="space-y-2">
              <Select
                value={selectedDomain}
                onValueChange={(value) => {
                  onSelectedDomainChange(value);
                  onFormChange((prev) => ({ ...prev, hard_skill_domain: value }));
                  const domain = classroomDomains.find((d) => d.name === value);
                  if (domain) {
                    onAvailableComponentsChange(domain.components);
                  }
                }}
              >
                <SelectTrigger
                  className={`rounded-xl bg-background h-11 ${isRTL ? 'text-right' : 'text-left'}`}
                  dir={isRTL ? 'rtl' : 'ltr'}
                >
                  <SelectValue>
                    {selectedDomain || t('createAssignment.selectFromDomains')}
                  </SelectValue>
                </SelectTrigger>
                <SelectContent className="rounded-xl" dir={isRTL ? 'rtl' : 'ltr'}>
                  {classroomDomains.map((domain, index) => (
                    <SelectItem
                      key={index}
                      value={domain.name}
                      className={isRTL ? 'text-right' : 'text-left'}
                    >
                      {domain.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <p className={`text-xs text-muted-foreground ${isRTL ? 'text-right' : 'text-left'}`}>
                {t('createAssignment.orEnterManually')}
              </p>
            </div>
          ) : null}
          <Input
            id="wiz-hard_skill_domain"
            placeholder={t('createAssignment.subjectAreaPlaceholder')}
            value={formData.hard_skill_domain}
            onChange={(e) => {
              onFormChange((prev) => ({ ...prev, hard_skill_domain: e.target.value }));
              onSelectedDomainChange('');
            }}
            className="rounded-xl bg-background h-11"
            dir={isRTL ? 'rtl' : 'ltr'}
            autoDirection
          />
        </div>

        <div className="space-y-3">
          <Label className={`text-body font-medium block ${isRTL ? 'text-right' : 'text-left'}`}>
            {t('createAssignment.skillsToAssess')}
          </Label>

          {selectedDomain && availableComponents.length > 0 && !atCap && (
            <div className="space-y-2">
              <Select
                onValueChange={(value: string) => {
                  const next = { domain: selectedDomain, skill: value };
                  onFormChange((prev) => {
                    const keys = new Set(prev.hard_skills.map(pairKey));
                    if (keys.has(pairKey(next)) || prev.hard_skills.length >= MAX_HARD_SKILLS)
                      return prev;
                    return { ...prev, hard_skills: [...prev.hard_skills, next] };
                  });
                }}
              >
                <SelectTrigger
                  className={`rounded-xl bg-background h-11 ${isRTL ? 'text-right' : 'text-left'}`}
                  dir={isRTL ? 'rtl' : 'ltr'}
                >
                  <SelectValue>
                    {t('createAssignment.selectFromSkills', { domain: selectedDomain })}
                  </SelectValue>
                </SelectTrigger>
                <SelectContent className="rounded-xl" dir={isRTL ? 'rtl' : 'ltr'}>
                  {availableComponents.map((component, index) => (
                    <SelectItem
                      key={index}
                      value={component}
                      className={isRTL ? 'text-right' : 'text-left'}
                    >
                      {component}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          <div className="space-y-2">
            {formData.hard_skills.map((pair, index) => (
              <div
                key={index}
                className={cn('flex items-center gap-2', isRTL ? 'flex-row-reverse' : '')}
              >
                {pair.domain.trim() ? (
                  <Badge
                    variant="secondary"
