import { Loader2 } from 'lucide-react';
import { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ThemeToggle } from '@/components/ThemeToggle';
import { USER_ROLES } from '@/config/constants';
import { supabase } from '@/integrations/supabase/client';
import {
  attemptRoleRecovery,
  getPendingRole,
  updateUserRole,
  clearPendingRole,
} from '@/utils/roleRecovery';
import { isSignupInProgress } from '@/utils/sessionState';

export const AuthCallbackContent = () => {
  const navigate = useNavigate();

  useEffect(() => {
    // Safety timeout: if callback takes more than 20 seconds, force redirect to login
    const timeout = setTimeout(() => {
      console.warn('⚠️ AuthCallback: Operation timed out, redirecting to /auth');
      navigate('/auth', { replace: true });
    }, 20000);

    const handleCallback = async () => {
      try {
        console.log('🔄 AuthCallback: Starting authentication callback');

        // Do NOT call exchangeCodeForSession here: createClient already has detectSessionInUrl + PKCE,
        // so the code verifier is consumed on first URL handling. A second exchange causes:
        // "both auth code and code verifier should be non-empty".
        const {
          data: { session },
        } = await supabase.auth.getSession();

        if (!session?.user) {
          console.log('❌ AuthCallback: No session, redirecting to /auth');
          clearTimeout(timeout);
          navigate('/auth', { replace: true });
          return;
        }

        const user = session.user;

        console.log('👤 AuthCallback: User data:', {
          userId: user.id,
          email: user.email,
          role: user.user_metadata?.role,
        });

        // ALWAYS check for existing profiles first to prevent duplicate registrations
        console.log('🔍 AuthCallback: Checking for existing profiles...');

        // Check by user_id - THIS IS THE SOURCE OF TRUTH
        const { data: teacherProfile, error: tError } = await supabase
          .from('teacher_profiles')
          .select('id, user_id, email')
          .eq('user_id', user.id)
          .maybeSingle();

        const { data: studentProfile, error: sError } = await supabase
          .from('student_profiles')
          .select('id, user_id, email')
          .eq('user_id', user.id)
          .maybeSingle();

        if (tError) console.error('Error fetching teacher profile:', tError);
        if (sError) console.error('Error fetching student profile:', sError);

        const userEmail = user.email?.toLowerCase().trim();
        const hasTeacherProfile = !!teacherProfile;
        const hasStudentProfile = !!studentProfile;

        const { data: appAdminRow } = await supabase
          .from('app_admins')
          .select('user_id')
          .eq('user_id', user.id)
          .maybeSingle();

        if (appAdminRow) {
          if (user.user_metadata?.role !== USER_ROLES.ADMIN) {
            await updateUserRole(USER_ROLES.ADMIN);
          }
          clearTimeout(timeout);
          navigate('/teacher/dashboard', { replace: true });
          return;
        }

        if (user.user_metadata?.role === USER_ROLES.ADMIN) {
          clearTimeout(timeout);
          navigate('/teacher/dashboard', { replace: true });
          return;
        }

        console.log('👨‍🏫 AuthCallback: Profile check results:', {
          hasTeacherProfile,
          hasStudentProfile,
          teacherProfileUserId: teacherProfile?.user_id,
          studentProfileUserId: studentProfile?.user_id,
          currentUserId: user.id,
          userEmail,
        });

        // Clean up orphaned profiles for this email (authenticated RPC; no anon PII leak)
        try {
          if (userEmail) {
            await supabase.rpc('cleanup_orphaned_profiles_by_email', { p_email: userEmail });
          }
        } catch (cleanupError) {
          console.error(
            '⚠️ AuthCallback: Non-blocking error during orphaned data cleanup:',
            cleanupError
          );
        }

        let userRole = user.user_metadata?.role;

        // If user already has a profile (matching current user_id), use that role
        if (hasTeacherProfile || hasStudentProfile) {
          const existingRole = hasTeacherProfile ? 'teacher' : 'student';
          console.log(`✅ AuthCallback: User has existing ${existingRole} profile`);

          // Update user metadata if it doesn't match
          if (userRole !== existingRole) {
            console.log(
              `🔄 AuthCallback: Updating user metadata to match existing profile: ${existingRole}`
            );
            await supabase.auth.updateUser({
              data: { role: existingRole },
            });
            userRole = existingRole;
          }

          // Clear any pending role since we're using the existing profile
          localStorage.removeItem('pending_role');

          // Redirect to the existing role's dashboard
          console.log(`🚀 AuthCallback: Redirecting to existing ${existingRole} dashboard`);
          clearTimeout(timeout);
          navigate(`/${existingRole}/dashboard`, { replace: true });
          return;
        }

        // No existing profiles found - process new registration
        console.log('🆕 AuthCallback: No existing profiles, processing new registration');

        // Check if this is an active signup or a recovery situation
        const activelySigningUp = isSignupInProgress();

        if (
          !userRole ||
          (userRole !== 'teacher' && userRole !== 'student' && userRole !== USER_ROLES.ADMIN)
        ) {
          // CRITICAL: Different behavior for active signup vs recovery
          if (activelySigningUp) {
            console.log('🔄 AuthCallback: Active signup - attempting quick recovery');

            // Try to recover from localStorage (backup from Auth.tsx)
            const pendingRole = getPendingRole();

            if (pendingRole && (pendingRole === 'teacher' || pendingRole === 'student')) {
              console.log(`🔄 AuthCallback: Found pending role: ${pendingRole}`);
              const updated = await updateUserRole(pendingRole as 'teacher' | 'student');

              if (updated) {
                console.log('✅ AuthCallback: Role set from pending');
                clearPendingRole();
                userRole = pendingRole;
              }
            }
          } else {
            // NOT actively signing up - this is a recovery situation
            console.warn('⚠️ AuthCallback: User has no valid role (not during active signup)');

            const { recovered, role, source } = await attemptRoleRecovery();

            if (recovered && role) {
              console.log(`✅ AuthCallback: Role recovered from ${source}: ${role}`);
              userRole = role;
            }
          }
        }

        console.log('🎭 AuthCallback: Final role for new user:', userRole);

        // If still no role, redirect to role selection page
        if (
          !userRole ||
          (userRole !== 'teacher' && userRole !== 'student' && userRole !== USER_ROLES.ADMIN)
        ) {
          console.warn('⚠️ AuthCallback: Cannot determine role, redirecting to role selection');
          clearTimeout(timeout);
          navigate('/role-selection', { replace: true });
          return;
        }

        // Check if there's a saved redirect path
        const redirectPath = sessionStorage.getItem('redirectAfterLogin');
        if (redirectPath) {
          sessionStorage.removeItem('redirectAfterLogin');
          clearTimeout(timeout);
          navigate(redirectPath);
          return;
        }

        // Redirect based on role and profile completion
        if (userRole === USER_ROLES.ADMIN) {
          clearTimeout(timeout);
          navigate('/teacher/dashboard', { replace: true });
          return;
        }

        if (userRole === 'teacher' || userRole === 'student') {
          console.log(`✅ AuthCallback: Role determined as ${userRole}, checking profile...`);

          // Check for profile existence using explicit table names for TypeScript
          let profile = null;
          let profileError = null;

          if (userRole === 'teacher') {
            const result = await supabase
              .from('teacher_profiles')
              .select('id')
              .eq('user_id', user.id)
              .maybeSingle();
            profile = result.data;
            profileError = result.error;
          } else {
            const result = await supabase
              .from('student_profiles')
              .select('id')
              .eq('user_id', user.id)
              .maybeSingle();
            profile = result.data;
            profileError = result.error;
          }

          if (profileError) {
            console.error('❌ AuthCallback: Error checking profile:', profileError);
          }

          const destination = profile ? `/${userRole}/dashboard` : `/onboarding/${userRole}`;

          console.log(
            `🚀 AuthCallback: ${profile ? 'Profile exists' : 'No profile found'}, redirecting to ${destination}`
          );
          clearTimeout(timeout);
          navigate(destination, { replace: true });
        } else {
          // New user with no role - redirect to auth to select role
          console.log('⚠️ AuthCallback: No role determined, redirecting to /auth to select role');
          // Store a flag to indicate the user needs to complete registration
          sessionStorage.setItem('needsRoleSelection', 'true');
          clearTimeout(timeout);
          navigate('/auth', { replace: true });
        }
      } catch (error) {
        console.error('❌ AuthCallback: Error during callback:', error);
        clearTimeout(timeout);
        navigate('/auth', { replace: true });
      }
    };

    handleCallback();

    return () => clearTimeout(timeout);
  }, [navigate]);

  return (
    <div className="min-h-screen flex items-center justify-center bg-background">
      <div className="fixed top-4 right-4 z-50">
        <ThemeToggle />
      </div>
      <div className="text-center">
        <Loader2 className="h-8 w-8 animate-spin mx-auto mb-4" />
        <p className="text-muted-foreground">Completing sign in...</p>
      </div>
    </div>
  );
};

import { Loader2, ArrowLeft } from 'lucide-react';
import { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useNavigate, useLocation, useSearchParams } from 'react-router-dom';
import { toast } from 'sonner';
import { z } from 'zod';
import { LanguageSwitcher } from '@/components/LanguageSwitcher';
import { PerleapLogo } from '@/components/PerleapLogo';
import { ThemeToggle } from '@/components/ThemeToggle';
import { BreathingBackground } from '@/components/ui/BreathingBackground';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { useLanguage } from '@/contexts/LanguageContext';
import { useAuth } from '@/contexts/useAuth';
import { useNavigateBack } from '@/hooks/useNavigateBack';
import { supabase } from '@/integrations/supabase/client';
import { getAuthErrorMessage } from '@/utils/authErrors';
import { savePendingRole } from '@/utils/roleRecovery';
import { markSignupInProgress, clearAllSignupState } from '@/utils/sessionState';

export const AuthContent = () => {
  const { t } = useTranslation();
  const { isRTL, setLanguage, language = 'en' } = useLanguage();
  const location = useLocation();
  const { user, loading: authLoading, hasProfile, isProfileLoading } = useAuth();

  // Dynamic validation schemas using translation
  const emailSchema = z.string().email(t('auth.errors.invalidEmail'));
  const passwordSchema = z.string().min(6, t('auth.errors.passwordTooShort'));
  const [loading, setLoading] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState<'teacher' | 'student' | null>(null);
  const [selectedLanguage, setSelectedLanguage] = useState<'en' | 'he'>(language);
  const [activeTab, setActiveTab] = useState<string>('signin');
  const navigate = useNavigate();
  const navigateBackHome = useNavigateBack('/');
  const [searchParams] = useSearchParams();

  // Check if we're in the middle of an OAuth callback or email confirmation
  const isOAuthCallback =
    searchParams.has('code') ||
    searchParams.has('access_token') ||
    searchParams.has('error') ||
    searchParams.has('type');

  // If we detect OAuth or email callback parameters on the auth page,
  // redirect to the dedicated callback handler
  useEffect(() => {
    if (isOAuthCallback) {
      console.log('🔄 Auth: OAuth callback detected, redirecting to /auth/callback');
      navigate(`/auth/callback${window.location.search}`, { replace: true });
    }
  }, [isOAuthCallback, navigate]);

  // Handle language selection - apply immediately
  const handleLanguageSelect = (lang: 'en' | 'he') => {
    setSelectedLanguage(lang);
    setLanguage(lang);
  };

  // Check if user is already authenticated and redirect
  useEffect(() => {
    const checkAuthAndRedirect = async () => {
      // Don't redirect if we're already handling a callback
      if (isOAuthCallback) return;

      // Wait for auth loading and profile loading
      if (authLoading || isProfileLoading) return;
      // If user is logged in but profile check is not done, wait
      if (user && hasProfile === null) return;

      if (user) {
        console.log('🔍 Auth: Checking authenticated user profile status...');

        const userRole = user.user_metadata?.role;

        // Check if user has completed their profile
        if (userRole === 'teacher' || userRole === 'student') {
          // Use cached profile check from AuthContext
          if (hasProfile === false) {
            console.log(
              `⚠️ Auth: User has ${userRole} role but no profile, redirecting to onboarding`
            );
            navigate(`/onboarding/${userRole}`, { replace: true });
            return;
          }
        }

        // Check if there's a saved redirect path
        const redirectPath = sessionStorage.getItem('redirectAfterLogin');

        if (redirectPath) {
          sessionStorage.removeItem('redirectAfterLogin');
          navigate(redirectPath);
          return;
        }

        // Otherwise, redirect to appropriate dashboard based on role
        if (userRole === 'teacher' || userRole === 'admin') {
          navigate('/teacher/dashboard');
        } else if (userRole === 'student') {
          navigate('/student/dashboard');
        } else {
          // User is authenticated but has no role metadata
          console.log('⚠️ Auth: User has no role, redirecting to role selection');
          navigate('/role-selection', { replace: true });
        }
      }
    };

    checkAuthAndRedirect();
  }, [user?.id, authLoading, navigate, hasProfile, isProfileLoading, isOAuthCallback]); // Use user?.id to avoid refetch on user object reference change

  // Set the active tab based on the route
  useEffect(() => {
    if (location.pathname === '/register') {
      setActiveTab('signup');
    } else if (location.pathname === '/login') {
      setActiveTab('signin');
    }
  }, [location.pathname]);

  // Clear fields when switching tabs to prevent autofill
  useEffect(() => {
    setEmail('');
    setPassword('');
  }, [activeTab]);

  const handleSignUp = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!role) {
      toast.error(t('auth.errors.selectRole'));
      return;
    }

    try {
      emailSchema.parse(email);
      passwordSchema.parse(password);
    } catch (err) {
      if (err instanceof z.ZodError) {
        toast.error(err.errors[0].message);
        return;
      }
    }

    setLoading(true);
    try {
      // Note: We skip pre-checking profiles by email because:
      // 1. Supabase will handle duplicate emails in auth.users
      // 2. Profiles have CASCADE DELETE, so orphaned profiles shouldn't exist
      // 3. If orphaned data exists, we'll handle it in AuthCallback
      // This prevents issues with orphaned data blocking legitimate registrations

      // Also check if current user is already authenticated with a profile
      const {
        data: { user: currentUser },
      } = await supabase.auth.getUser();

      if (currentUser) {
        // Check if user already has a profile
        const { data: teacherProfile } = await supabase
          .from('teacher_profiles')
          .select('id')
          .eq('user_id', currentUser.id)
          .maybeSingle();

        const { data: studentProfile } = await supabase
          .from('student_profiles')
          .select('id')
          .eq('user_id', currentUser.id)
          .maybeSingle();

        if (teacherProfile || studentProfile) {
          const existingRole = teacherProfile ? 'teacher' : 'student';
          toast.error(t('auth.errors.alreadyRegistered', { role: t(`common.${existingRole}`) }));
          setLoading(false);
          // Redirect to appropriate dashboard
          navigate(`/${existingRole}/dashboard`);
          return;
        }
      }

      // Mark signup as in progress (prevents role recovery interference)
      markSignupInProgress();

      // Save role to localStorage as backup
      savePendingRole(role);

      const { data, error } = await supabase.auth.signUp({
        email,
        password,
        options: {
          emailRedirectTo: `${window.location.origin}/auth/callback`,
          data: { role },
        },
      });

      if (error) throw error;

      // With email confirmation enabled, Supabase may return no error and a user whose
      // identities array is empty when the email is already registered (anti-enumeration).
      const identities = data.user?.identities ?? [];
      if (data.user && identities.length === 0) {
        clearAllSignupState();
        toast.error(t('auth.errors.emailAlreadyExists'));
        return;
      }

      // Handle signup response
      if (data.user) {
        console.log('✅ Signup successful, role metadata should be set:', role);

        // If we have a session, user is confirmed - proceed to onboarding
        if (data.session) {
          toast.success(t('auth.success.accountCreatedSuccess'));
          navigate(`/onboarding/${role}`);
        } else {
          // No session: Supabase is waiting on email confirmation (or rare edge cases).
          // Do not call signInWithPassword here — it returns 400 "Email not confirmed" and
          // pollutes the console; with confirmations off, signUp normally returns a session.
          clearAllSignupState();
          toast.success(t('auth.success.accountCreated'), {
            duration: 8000,
          });
        }
      }
    } catch (error: unknown) {
      console.error('Signup error:', error);
      clearAllSignupState();

      // Check for duplicate email error (explicit message/code only — not bare HTTP status)
      const err = error as { message?: string; code?: string; status?: number };
      const errorMsg = (err.message ?? '').toLowerCase();
      const errorCode = (err.code ?? '').toLowerCase();

      const isDuplicateEmail =
        errorMsg.includes('already registered') ||
        errorMsg.includes('already exists') ||
        errorMsg.includes('user already registered') ||
        errorCode.includes('email_exists') ||
        errorCode.includes('user_already_exists');

      if (isDuplicateEmail) {
        toast.error(t('auth.errors.emailAlreadyExists'));
      } else {
        toast.error(getAuthErrorMessage(error, t, 'auth.errors2.creatingAccount'));
      }
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleSignIn = async (selectedRole?: 'teacher' | 'student') => {
    setLoading(true);
    try {
      if (selectedRole) {
        // Mark signup as in progress for recovery logic in AuthCallback
        markSignupInProgress();
        savePendingRole(selectedRole);
      }

      // Check if user is already authenticated with an existing profile
      const {
        data: { user: currentUser },
      } = await supabase.auth.getUser();

      if (currentUser) {
        // Check if user already has a profile
        const { data: teacherProfile } = await supabase
          .from('teacher_profiles')
          .select('id')
          .eq('user_id', currentUser.id)
          .maybeSingle();

        const { data: studentProfile } = await supabase
          .from('student_profiles')
          .select('id')
          .eq('user_id', currentUser.id)
          .maybeSingle();

        if (teacherProfile || studentProfile) {
          const existingRole = teacherProfile ? 'teacher' : 'student';
          toast.error(t('auth.errors.alreadyRegistered', { role: t(`common.${existingRole}`) }));
          setLoading(false);
          // Redirect to appropriate dashboard
          navigate(`/${existingRole}/dashboard`);
          return;
        }
      }

      const { error } = await supabase.auth.signInWithOAuth({
        provider: 'google',
        options: {
          redirectTo: `${window.location.origin}/auth/callback`,
          queryParams: {
            access_type: 'offline',
            prompt: 'consent',
          },
        },
      });

      if (error) throw error;
    } catch (error: unknown) {
      console.error('Google Sign In Error:', error);
      toast.error(getAuthErrorMessage(error, t, 'auth.errors2.signingInGoogle'));
      setLoading(false);
    }
  };

  const handleSignIn = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      emailSchema.parse(email);
      passwordSchema.parse(password);
    } catch (err) {
      if (err instanceof z.ZodError) {
        toast.error(err.errors[0].message);
        return;
      }
    }

    setLoading(true);
    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        email,
        password,
      });

      if (error) throw error;

      toast.success(t('auth.success.signedIn'));

      // Check for saved redirect path
      const redirectPath = sessionStorage.getItem('redirectAfterLogin');
      if (redirectPath) {
        sessionStorage.removeItem('redirectAfterLogin');
        navigate(redirectPath);
        return;
      }

      // Redirect based on role and profile status
      const userRole = data.user.user_metadata?.role;

      if (userRole === 'teacher' || userRole === 'student') {
        const profileTable = userRole === 'teacher' ? 'teacher_profiles' : 'student_profiles';
        const dashboardPath = `/${userRole}/dashboard`;
        const onboardingPath = `/onboarding/${userRole}`;

        const { data: profile } = await supabase
          .from(profileTable)
          .select('id')
          .eq('user_id', data.user.id)
          .maybeSingle();

        navigate(profile ? dashboardPath : onboardingPath);
      } else {
        // No role in metadata - redirect to role selection
        console.warn('⚠️ Sign in successful but no role metadata found');
        navigate('/role-selection');
      }
    } catch (error: unknown) {
      console.error('Sign In Error:', error);
      toast.error(getAuthErrorMessage(error, t, 'auth.errors2.signingIn'));
    } finally {
      setLoading(false);
    }
  };

  // If OAuth callback is in progress or user is already authenticated, show loading state
  // This prevents the Auth page from rendering and causing a flicker
  // CRITICAL: Added safety check for missing role to prevent infinite spinner
  const hasUserButNoRole = user && !user.user_metadata?.role;

  if (
    isOAuthCallback ||
    (!authLoading && user && !hasUserButNoRole) ||
    isProfileLoading ||
    (user && hasProfile === null && !hasUserButNoRole)
  ) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="flex flex-col items-center gap-4">
          <Loader2 className="h-8 w-8 animate-spin text-primary" />
          <p className="text-muted-foreground">{t('common.redirecting')}</p>
        </div>
      </div>
    );
  }

  // If user is logged in but has no role, redirect to role selection instead of showing spinner
  if (user && hasUserButNoRole && !authLoading && !isOAuthCallback) {
    navigate('/role-selection', { replace: true });
    return null;
  }

  return (
    <BreathingBackground className="flex flex-col items-center min-h-screen p-4 pt-6 md:pt-8">
      {/* Equal-width side columns so the logo is geometrically centered on the screen */}
      <header className="relative z-20 grid w-full max-w-5xl grid-cols-[1fr_auto_1fr] items-center gap-3 pb-8 md:pb-10">
        <div className="flex min-w-0 justify-start">
          <Button
