                      autoComplete="username"
                      readOnly
                      autoDirection
                      className="h-11"
                    />
                  </div>
                  <div className={`space-y-2 ${isRTL ? 'text-right' : 'text-left'}`}>
                    <Label htmlFor="signin-password" className="text-sm font-semibold">
                      {t('auth.password')}
                    </Label>
                    <Input
                      id="signin-password"
                      type="password"
                      placeholder=""
