                      required
                      autoComplete="username"
                      readOnly
                      autoDirection
                      className="h-12 rounded-lg bg-muted/50 border-input focus:bg-background focus:border-primary/30 focus:ring-4 focus:ring-primary/10 transition-all px-6 text-lg shadow-sm"
