];

const SyllabusSettings = ({
  syllabus,
  editingMeta,
  onStartEdit,
  onSave,
  onCancel,
  saving,
  courseStartDate,
  courseEndDate,
  metaTitle,
  metaStructureType,
  metaPolicies,
  metaReleaseMode,
  metaStartDate,
  metaEndDate,
  onChangeTitle,
  onChangeStructureType,
  onChangePolicies,
  onChangeReleaseMode,
  onChangeCourseStartDate,
  onChangeCourseEndDate,
  isRTL,
}: {
  syllabus: SyllabusWithSections;
  editingMeta: boolean;
  onStartEdit: () => void;
  onSave: () => void;
  onCancel: () => void;
  saving: boolean;
  courseStartDate: string | null;
  courseEndDate: string | null;
  metaTitle: string;
  metaStructureType: SyllabusStructureType;
  metaPolicies: SyllabusPolicy[];
  metaReleaseMode: ReleaseModeType;
  metaStartDate: string;
  metaEndDate: string;
  onChangeTitle: (v: string) => void;
  onChangeStructureType: (v: SyllabusStructureType) => void;
  onChangePolicies: (v: SyllabusPolicy[]) => void;
  onChangeReleaseMode: (v: ReleaseModeType) => void;
  onChangeCourseStartDate: (v: string) => void;
  onChangeCourseEndDate: (v: string) => void;
  isRTL: boolean;
}) => {
  const { t } = useTranslation();
  const [popoverOpen, setPopoverOpen] = useState(false);

  const policies = editingMeta ? metaPolicies : (syllabus.policies ?? []);

  if (!editingMeta) {
    return (
      <div className="space-y-6">
        <div className={`flex items-center justify-between ${isRTL ? 'flex-row-reverse' : ''}`}>
          <h3 className="font-bold text-foreground text-lg">{t('syllabus.settings.title')}</h3>
          <Button
            variant="outline"
            size="sm"
            onClick={onStartEdit}
            className="rounded-full gap-1.5"
          >
            <Edit className="h-3.5 w-3.5" /> {t('syllabus.settings.edit')}
          </Button>
        </div>

        <div className="grid md:grid-cols-2 gap-6">
          <Card className="rounded-xl border-border shadow-sm">
            <CardContent className="p-5 space-y-4">
              <SettingsField label={t('syllabus.title')} value={syllabus.title} isRTL={isRTL} />
              <SettingsField
                label={t('syllabus.settings.structure')}
                value={syllabus.structure_type}
                isRTL={isRTL}
              />
              <div className={cn('grid gap-4 sm:grid-cols-2', isRTL ? 'text-right' : 'text-left')}>
                <SettingsField
                  label={t('createClassroom.startDate')}
                  value={formatCourseDateLabel(courseStartDate)}
                  isRTL={isRTL}
                />
                <SettingsField
                  label={t('createClassroom.endDate')}
                  value={formatCourseDateLabel(courseEndDate)}
                  isRTL={isRTL}
                />
              </div>
              <SettingsField
                label={t('syllabus.releaseMode.label', 'Release Mode')}
                value={t(
                  `syllabus.releaseMode.${syllabus.release_mode || 'all_at_once'}`,
                  syllabus.release_mode || 'all_at_once'
                )}
                isRTL={isRTL}
              />
              <SettingsField
                label={t('syllabus.settings.status')}
                value={syllabus.status}
                isRTL={isRTL}
              />
            </CardContent>
          </Card>

          <Card className="rounded-xl border-border shadow-sm">
            <CardContent className="p-5 space-y-4">
              {policies.length === 0 ? (
                <p className="text-sm text-muted-foreground">
                  {t('syllabus.policies.noPolicies', 'No policies defined.')}
                </p>
              ) : (
                policies.map((p) => (
                  <SettingsField
                    key={p.id}
                    label={p.label}
                    value={p.content || '—'}
                    isRTL={isRTL}
                  />
                ))
              )}
            </CardContent>
          </Card>
        </div>

        <ChangelogViewer syllabusId={syllabus.id} isRTL={isRTL} />
      </div>
    );
  }

  const addedTypes = new Set(metaPolicies.map((p) => p.type));

  const addPolicy = (type: SyllabusPolicyType, label: string) => {
    onChangePolicies([
      ...metaPolicies,
      { id: crypto.randomUUID(), type, label, content: '', order_index: metaPolicies.length },
    ]);
    setPopoverOpen(false);
  };

  const updatePolicy = (id: string, partial: Partial<SyllabusPolicy>) => {
    onChangePolicies(metaPolicies.map((p) => (p.id === id ? { ...p, ...partial } : p)));
  };

  const removePolicy = (id: string) => {
    onChangePolicies(
      metaPolicies.filter((p) => p.id !== id).map((p, i) => ({ ...p, order_index: i }))
    );
  };

  return (
    <div className="space-y-6">
      <div className={`flex items-center justify-between ${isRTL ? 'flex-row-reverse' : ''}`}>
        <h3 className="font-bold text-foreground text-lg">{t('syllabus.settings.editTitle')}</h3>
        <div className="flex gap-2">
          <Button variant="ghost" size="sm" onClick={onCancel} className="rounded-full">
            {t('syllabus.settings.cancel')}
          </Button>
          <Button
            variant="default"
            size="sm"
            onClick={onSave}
            disabled={saving}
            className="rounded-full gap-1.5"
          >
            {saving ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
            ) : (
              <Save className="h-3.5 w-3.5" />
            )}
            {t('syllabus.settings.save')}
          </Button>
        </div>
      </div>

      <div className="grid md:grid-cols-2 gap-6">
        <Card className="rounded-xl border-border shadow-sm">
          <CardContent className="p-5 space-y-4">
            <div className="space-y-1.5">
              <Label className="text-sm font-medium">{t('syllabus.title')}</Label>
              <Input
                value={metaTitle}
                onChange={(e) => onChangeTitle(e.target.value)}
                className="rounded-lg"
                autoDirection
              />
            </div>
            <div className="space-y-1.5">
              <Label className="text-sm font-medium">{t('syllabus.structureType')}</Label>
              <div className="grid grid-cols-3 gap-2">
                {(['weeks', 'units', 'modules'] as const).map((sType) => (
                  <button
                    key={sType}
                    type="button"
                    onClick={() => onChangeStructureType(sType)}
                    className={cn(
                      'p-2 rounded-lg border-2 text-center text-sm transition-all',
                      metaStructureType === sType
                        ? 'border-primary bg-primary/5 font-bold'
                        : 'border-border hover:border-primary/40'
                    )}
                  >
                    {t(`syllabus.${sType}`)}
                  </button>
                ))}
              </div>
            </div>
            <div className={cn('grid gap-3 sm:grid-cols-2', isRTL ? 'text-right' : 'text-left')}>
              <div className="space-y-1.5">
                <Label className="text-sm font-medium">{t('createClassroom.startDate')}</Label>
                <DatePicker
                  value={metaStartDate}
                  onChange={onChangeCourseStartDate}
                  placeholder={t('createClassroom.startDate')}
                  className="rounded-lg h-10 text-sm"
                />
              </div>
              <div className="space-y-1.5">
                <Label className="text-sm font-medium">{t('createClassroom.endDate')}</Label>
                <DatePicker
                  value={metaEndDate}
                  onChange={onChangeCourseEndDate}
                  placeholder={t('createClassroom.endDate')}
                  className="rounded-lg h-10 text-sm"
                />
              </div>
            </div>
            <ReleaseModeSelect
              label={t('syllabus.releaseMode.label', 'Release Mode')}
              value={metaReleaseMode}
              onChange={(v) => onChangeReleaseMode(v as ReleaseModeType)}
              triggerClassName="rounded-lg"
            />
          </CardContent>
        </Card>

        <Card className="rounded-xl border-border shadow-sm">
          <CardContent className="p-5 space-y-4">
            <div className={`flex items-center justify-between ${isRTL ? 'flex-row-reverse' : ''}`}>
              <Label className="text-sm font-medium">{t('syllabus.wizard.policies')}</Label>
              <Popover open={popoverOpen} onOpenChange={setPopoverOpen}>
                <PopoverTrigger className="inline-flex items-center justify-center gap-1 rounded-full h-7 px-2.5 text-xs font-medium hover:bg-accent hover:text-accent-foreground cursor-pointer">
                  <Plus className="h-3 w-3" /> {t('syllabus.policies.addPolicy', 'Add')}
                </PopoverTrigger>
                <PopoverContent align="end" className="w-64 p-2 rounded-xl" sideOffset={8}>
                  <div className="space-y-0.5">
                    {SETTINGS_PRESETS.map((preset) => {
                      const PIco = preset.icon;
                      const alreadyAdded = addedTypes.has(preset.type);
                      return (
                        <button
                          key={preset.type}
                          type="button"
                          disabled={alreadyAdded}
                          onClick={() =>
                            addPolicy(preset.type, t(preset.labelKey, preset.fallbackLabel))
                          }
                          className={cn(
                            'w-full flex items-center gap-3 px-3 py-2 rounded-lg text-sm transition-all',
                            alreadyAdded
                              ? 'opacity-50 cursor-not-allowed'
                              : 'hover:bg-muted/60 cursor-pointer',
                            isRTL && 'flex-row-reverse text-right'
                          )}
                        >
                          <div className={cn('p-1 rounded-md', preset.colorClass)}>
                            <PIco className="h-3 w-3" />
                          </div>
                          <span className="flex-1 font-medium text-foreground text-xs">
                            {t(preset.labelKey, preset.fallbackLabel)}
                          </span>
                          {alreadyAdded && <Check className="h-3.5 w-3.5 text-muted-foreground" />}
                        </button>
                      );
                    })}
                    <div className="border-t border-border my-1" />
                    <button
                      type="button"
                      onClick={() =>
                        addPolicy('custom', t('syllabus.policies.customPolicy', 'Custom Policy'))
                      }
                      className={cn(
                        'w-full flex items-center gap-3 px-3 py-2 rounded-lg text-sm hover:bg-muted/60',
                        isRTL && 'flex-row-reverse text-right'
                      )}
                    >
                      <div className="p-1 rounded-md text-gray-500 bg-gray-100 dark:bg-gray-900/30">
                        <PenLine className="h-3 w-3" />
                      </div>
                      <span className="flex-1 font-medium text-foreground text-xs">
                        {t('syllabus.policies.customPolicy', 'Custom Policy')}
                      </span>
                    </button>
                  </div>
                </PopoverContent>
              </Popover>
            </div>

            {metaPolicies.length === 0 ? (
              <div className="p-6 border-2 border-dashed border-border rounded-lg bg-muted/10 text-center">
                <Scale className="h-6 w-6 text-muted-foreground mx-auto mb-1" />
                <p className="text-xs text-muted-foreground">
                  {t('syllabus.policies.noPolicies', 'No policies added yet.')}
                </p>
              </div>
            ) : (
              <div className="space-y-3">
                {metaPolicies.map((policy) => {
                  const PIco = getPolicyIcon(policy.type);
                  const clr = getPolicyColor(policy.type);
                  return (
                    <div
                      key={policy.id}
                      className="space-y-1.5 p-3 rounded-lg border border-border bg-card"
                    >
                      <div className={`flex items-center gap-2 ${isRTL ? 'flex-row-reverse' : ''}`}>
                        <div className={cn('p-1 rounded-md', clr)}>
                          <PIco className="h-3 w-3" />
                        </div>
                        {policy.type === 'custom' ? (
                          <Input
                            value={policy.label}
                            onChange={(e) => updatePolicy(policy.id, { label: e.target.value })}
                            className="flex-1 h-7 text-xs rounded-md"
                            autoDirection
                          />
                        ) : (
                          <span className="flex-1 text-xs font-medium text-foreground">
                            {policy.label}
                          </span>
                        )}
                        <Button
                          type="button"
                          variant="ghost"
                          size="icon"
                          onClick={() => removePolicy(policy.id)}
                          className="h-6 w-6 text-muted-foreground hover:text-destructive rounded-full"
                        >
                          <Trash2 className="h-3 w-3" />
                        </Button>
                      </div>
                      <Textarea
                        value={policy.content}
                        onChange={(e) => updatePolicy(policy.id, { content: e.target.value })}
                        rows={2}
                        className="rounded-md resize-none text-sm"
                        autoDirection
                      />
                    </div>
                  );
                })}
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
};

