    user?.user_metadata?.role === USER_ROLES.TEACHER ? user.id : undefined;

  const invalidateAfterCourseMutation = async () => {
    await queryClient.invalidateQueries({ queryKey: classroomKeys.detail(classroomId) });
    await queryClient.invalidateQueries({ queryKey: classroomKeys.lists() });
    await queryClient.invalidateQueries({ queryKey: syllabusKeys.byClassroom(classroomId) });
    await queryClient.invalidateQueries({ queryKey: syllabusKeys.outlineByClassroom(classroomId) });
    await queryClient.invalidateQueries({
      queryKey: assignmentKeys.classroomAssignmentLists(classroomId),
      exact: false,
    });
    await queryClient.invalidateQueries({ queryKey: moduleFlowKeys.all, exact: false });
    /** Merge updates `activity_list` rows; syllabus hooks use staleTime 5m for section resources unless invalidated. */
    await queryClient.invalidateQueries({ queryKey: resourceKeys.all, exact: false });
  };

  const handleExportMergeSafe = async () => {
    if (exportInFlightRef.current) return;
    exportInFlightRef.current = true;
    try {
      const { data, error } = await buildExportPackageForClassroom(classroomId, {
        restrictToTeacherId,
        variant: 'v2_merge',
      });
      if (error) {
        toast.error(t('coursePackage.exportFailed'), { description: error.message });
        return;
      }
      if (!data) {
        toast.error(t('coursePackage.exportFailed'));
        return;
      }
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      const stamp = new Date().toISOString().slice(0, 10);
      a.href = url;
      a.download = `${safeFileSlug(classroomName)}-merge-${stamp}.perleap-course.json`;
      a.click();
      URL.revokeObjectURL(url);
      toast.success(t('coursePackage.exportSuccess'));
    } catch (e) {
      console.error(e);
      toast.error(t('coursePackage.exportFailed'));
    } finally {
      exportInFlightRef.current = false;
    }
  };

  const openFilePickerForImport = () => {
    queueMicrotask(() => fileInputRef.current?.click());
  };

  const closeImportModeDialog = () => {
    setImportModeDialogOpen(false);
    setPendingImportPkg(null);
  };

  const runMergeIntoCurrentClassroom = async (pkg: PerleapCoursePackageV2) => {
    const { data: mergeData, error: mergeErr } = await mergeCoursePackageIntoClassroom({
      classroomId,
      pkg,
      updateClassroomFromPackage: true,
      restrictToTeacherId,
    });
    if (mergeErr || !mergeData) {
      const ctx = getMergeFailureFromApiError(mergeErr ?? undefined);
      const phaseKey =
        ctx && ctx.phase
          ? `coursePackage.mergeError.phase.${ctx.phase}`
          : 'coursePackage.importFailed';
      const title =
        ctx && ctx.phase && i18n.exists(phaseKey)
          ? String(t(phaseKey))
          : String(t('coursePackage.importFailed'));
      const parts: string[] = [];
      if (mergeErr?.message) parts.push(mergeErr.message);
      if (ctx?.humanLabel) {
        const step =
          ctx.indexInPkg != null
            ? ` (${t('coursePackage.mergeError.step')} ${ctx.indexInPkg + 1})`
            : '';
        parts.push(`${t('coursePackage.mergeError.location')}: «${ctx.humanLabel}»${step}`);
      }
      if (ctx?.entityId)
        parts.push(`${t('coursePackage.mergeError.entityIdLabel')}: ${ctx.entityId}`);
      parts.push(
        ctx?.atomic === true
          ? t('coursePackage.mergeRollbackHint')
          : t('coursePackage.mergePartialApplyWarning')
      );
      toast.error(title, { description: parts.join('\n'), duration: 14000 });
      return;
    }
    toast.success(t('coursePackage.importMergeSuccess'));
    await invalidateAfterCourseMutation();
  };

  const runCreateNewClassroomFromPkg = async (pkg: PerleapCoursePackageAny) => {
    if (!user?.id) {
      toast.error(t('coursePackage.importFailed'), {
        description: t('coursePackage.importRequiresSignIn'),
      });
      return;
    }
    let pkgV1: PerleapCoursePackageV1;
    try {
      pkgV1 = packageForNewClassroomFromAny(pkg);
    } catch (normalizeErr) {
      toast.error(t('coursePackage.importFailed'), {
        description: normalizeErr instanceof Error ? normalizeErr.message : String(normalizeErr),
      });
      return;
    }
    const { data, error } = await importCoursePackageV1(pkgV1, user.id);
    if (error || !data?.classroomId?.trim()) {
      toast.error(t('coursePackage.importFailed'), { description: error?.message });
      return;
    }
    const newClassroomId = data.classroomId.trim();
    toast.success(t('coursePackage.importNewClassSuccess'));
    await queryClient.invalidateQueries({ queryKey: classroomKeys.lists() });
    await queryClient.invalidateQueries({ queryKey: classroomKeys.detail(newClassroomId) });
    /** Defer so AlertDialog teardown does not swallow the SPA navigation; replace avoids stacking the old classroom in history. */
    queueMicrotask(() => {
      navigate(buildRoute.teacherClassroom(newClassroomId), { replace: true });
    });
  };

  const handleIncomingPackageFileSelected = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    e.target.value = '';
    if (!file || !user?.id) return;

    setImporting(true);
    try {
      const text = await file.text();
      let json: unknown;
      try {
        json = JSON.parse(text);
      } catch {
        toast.error(t('coursePackage.importFailed'), {
          description: t('coursePackage.invalidFile'),
        });
        return;
      }
      const parsed = parseCoursePackageJson(json);
      if (parsed.ok === false) {
        toast.error(t('coursePackage.importFailed'), { description: parsed.error });
        return;
      }

      setPendingImportPkg(parsed.data);
      setImportModeDialogOpen(true);
    } catch (err) {
      console.error(err);
      toast.error(t('coursePackage.importFailed'));
    } finally {
      setImporting(false);
    }
  };

  const handleImportModeCreateNew = async () => {
    const pkg = pendingImportPkg;
    if (!pkg || !user?.id) {
      closeImportModeDialog();
      return;
    }
    closeImportModeDialog();
    setImporting(true);
    try {
      await runCreateNewClassroomFromPkg(pkg);
    } finally {
      setImporting(false);
      setPendingImportPkg(null);
    }
  };

  const handleImportModeMergeHere = async () => {
    const pkg = pendingImportPkg;
    if (!pkg) {
      closeImportModeDialog();
      return;
    }
    if (pkg.version !== COURSE_PACKAGE_VERSION_V2) {
      toast.error(t('coursePackage.importFailed'), {
        description: t('coursePackage.importMergeNeedsV2'),
      });
      closeImportModeDialog();
      return;
    }
    closeImportModeDialog();
    setImporting(true);
    try {
      await runMergeIntoCurrentClassroom(pkg);
    } finally {
      setImporting(false);
      setPendingImportPkg(null);
    }
  };

  return (
    <>
      <Card
        className="w-full rounded-xl border-none shadow-sm bg-card ring-1 ring-border overflow-hidden"
        dir={isRTL ? 'rtl' : 'ltr'}
      >
        <CardHeader className="pb-2">
          <CardTitle className={cn('text-foreground text-lg', isRTL ? 'text-right' : 'text-left')}>
            {t('coursePackage.title')}
          </CardTitle>
          <CardDescription className={cn(isRTL ? 'text-right' : 'text-left')}>
            {t('coursePackage.description')}
          </CardDescription>
        </CardHeader>
        <CardContent className="flex flex-wrap gap-2">
          <input
            ref={fileInputRef}
            type="file"
            accept="application/json,.json"
            className="hidden"
            tabIndex={-1}
            onChange={handleIncomingPackageFileSelected}
          />
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="rounded-full gap-2"
            disabled={importing}
            onClick={() => void handleExportMergeSafe()}
          >
            <Download className="h-4 w-4" />
            {t('coursePackage.export')}
          </Button>
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="rounded-full gap-2"
            disabled={importing || importModeDialogOpen}
            onClick={openFilePickerForImport}
          >
            {importing ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <Upload className="h-4 w-4" />
            )}
            {importing ? t('coursePackage.importing') : t('coursePackage.import')}
          </Button>
        </CardContent>
      </Card>

      <AlertDialog
        open={importModeDialogOpen}
        onOpenChange={(open) => {
          if (!open) closeImportModeDialog();
          else setImportModeDialogOpen(true);
        }}
      >
        <AlertDialogContent className="rounded-xl max-w-lg" dir={isRTL ? 'rtl' : 'ltr'}>
          <AlertDialogHeader className={cn(isRTL ? 'sm:text-right' : '')}>
            <AlertDialogTitle>{t('coursePackage.importModeTitle')}</AlertDialogTitle>
            <AlertDialogDescription
              className={cn(
                'text-muted-foreground text-sm text-balance md:text-pretty space-y-2',
                isRTL ? 'text-right' : 'text-left'
              )}
            >
              <span className="block">{t('coursePackage.importModeDescription')}</span>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <div
            className={cn(
              'flex flex-col gap-3 py-1 sm:items-stretch',
              isRTL ? 'sm:flex-row-reverse sm:justify-between' : 'sm:flex-row sm:justify-between'
            )}
          >
            <div className="flex min-w-0 flex-1 flex-col gap-1 rounded-lg border border-border/60 bg-muted/20 p-3">
              <p className={cn('text-sm font-medium', isRTL ? 'text-right' : 'text-left')}>
                {t('coursePackage.importModeCreateLabel')}
              </p>
              <p
                className={cn(
                  'flex-1 text-muted-foreground text-xs leading-snug',
                  isRTL ? 'text-right' : 'text-left'
                )}
              >
                {t('coursePackage.importModeCreateHint')}
              </p>
              <Button
                type="button"
                variant="outline"
                className="mt-3 w-full rounded-full bg-background text-foreground sm:w-auto"
                onClick={() => void handleImportModeCreateNew()}
              >
                {t('coursePackage.importModeCreateConfirm')}
              </Button>
            </div>
            <div className="flex min-w-0 flex-1 flex-col gap-1 rounded-lg border border-border/60 bg-muted/10 p-3">
              <p className={cn('text-sm font-medium', isRTL ? 'text-right' : 'text-left')}>
                {t('coursePackage.importModeMergeLabel')}
              </p>
              <p
                className={cn(
                  'flex-1 text-muted-foreground text-xs leading-snug',
                  isRTL ? 'text-right' : 'text-left'
                )}
              >
                {t('coursePackage.importModeMergeHint')}
              </p>
              <Button
                type="button"
                variant="outline"
                className="mt-3 w-full rounded-full bg-background text-foreground sm:w-auto"
                onClick={() => void handleImportModeMergeHere()}
              >
                {t('coursePackage.importModeMergeConfirm')}
              </Button>
            </div>
          </div>
          <AlertDialogFooter className={cn(isRTL ? 'sm:flex-row-reverse' : '')}>
            <AlertDialogCancel>{t('syllabus.cancel')}</AlertDialogCancel>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
};

import { useQueryClient } from '@tanstack/react-query';
import { ArrowLeft, ArrowRight, Loader2, Upload } from 'lucide-react';
import { useState, useCallback, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { toast } from 'sonner';
import { CourseBasicsStep } from './steps/CourseBasicsStep';
import { OutlineBuilderStep } from './steps/OutlineBuilderStep';
import { ReviewStep } from './steps/ReviewStep';
import { SyllabusSetupStep } from './steps/SyllabusSetupStep';
import { WizardStepIndicator, type WizardStep } from './WizardStepIndicator';
import type { Json } from '@/integrations/supabase/types';
import type { Domain, CourseMaterial } from '@/types/models';
import type {
  SyllabusStructureType,
  SyllabusPolicy,
  ReleaseMode,
  CompletionStatus,
  ProvisionBundleResourceItem,
  SyllabusStatus,
} from '@/types/syllabus';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent } from '@/components/ui/dialog';
import { ScrollArea } from '@/components/ui/scroll-area';
import { useLanguage } from '@/contexts/LanguageContext';
import { useAuth } from '@/contexts/useAuth';
import { useProvisionSyllabusBundle } from '@/hooks/queries';
import { classroomKeys } from '@/hooks/queries/useClassroomQueries';
import { supabase } from '@/integrations/supabase/client';
import { parseCoursePackageJson } from '@/lib/coursePackage/validateCoursePackage';
import { runSyllabusPublishedSideEffects } from '@/lib/syllabusPublishSideEffects';
import { packageForNewClassroomFromAny } from '@/services/coursePackageNewImportUtils';
import { importCoursePackageV1 } from '@/services/coursePackageService';

// ---------------------------------------------------------------------------
// Wizard Data Shape
// ---------------------------------------------------------------------------

export interface WizardResourceItem {
  id: string;
  type: 'link' | 'file';
  title: string;
  url: string; // URL for links, object-URL preview for local files
  file?: File; // present only for local file uploads
}

export interface WizardSectionData {
  tempId: string;
  title: string;
  description: string;
  /** Rich HTML; same field as SyllabusEditor */
  content: string;
  objectives: string[];
  startDate: string;
  endDate: string;
  completion_status: CompletionStatus;
  is_locked: boolean;
}

export interface WizardGradingCategory {
  tempId: string;
  name: string;
  weight: number;
}

export interface WizardData {
  // Step 1 – Course Basics
  courseTitle: string;
  startDate: string;
  endDate: string;
  /** Free-form course overview; persisted to classrooms.resources */
  courseDescription: string;
  learningOutcomes: string[];
  keyChallenges: string[];
  domains: Domain[];
  materials: CourseMaterial[];

  // Step 2 – Syllabus Setup
  includeSyllabus: boolean;
  syllabusTitle: string;
  structureType: SyllabusStructureType;
  policies: SyllabusPolicy[];
  gradingCategories: WizardGradingCategory[];
  release_mode: ReleaseMode;

  // Step 3 – Outline Builder (sections)
  sections: WizardSectionData[];
}

const DEFAULT_WIZARD_DATA: WizardData = {
  courseTitle: '',
  startDate: '',
  endDate: '',
  courseDescription: '',
  learningOutcomes: ['', '', ''],
  keyChallenges: ['', ''],
  domains: [],
  materials: [],

  includeSyllabus: true,
  syllabusTitle: '',
  structureType: 'weeks',
  policies: [],
  gradingCategories: [],
  release_mode: 'all_at_once',

  sections: [],
};

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

interface CreateClassroomWizardProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess: (classroomId: string) => void;
}

export const CreateClassroomWizard = ({
  open,
  onOpenChange,
  onSuccess,
}: CreateClassroomWizardProps) => {
  const { t } = useTranslation();
  const { isRTL } = useLanguage();
  const { user } = useAuth();
  const queryClient = useQueryClient();
  const provisionBundle = useProvisionSyllabusBundle();

  const wizardImportFileRef = useRef<HTMLInputElement>(null);

  const [currentStep, setCurrentStep] = useState(0);
  const [wizardData, setWizardData] = useState<WizardData>({ ...DEFAULT_WIZARD_DATA });
  const [loading, setLoading] = useState(false);
  const [wizardImportLoading, setWizardImportLoading] = useState(false);

  const wizardBusy = loading || wizardImportLoading;

  const WIZARD_STEPS: WizardStep[] = [
    { id: 'basics', title: t('createClassroom.courseBasics', 'Course Basics') },
    { id: 'syllabus', title: t('syllabus.wizard.syllabusSetup') },
    { id: 'outline', title: t('syllabus.wizard.courseOutline') },
    { id: 'review', title: t('syllabus.wizard.reviewCreate') },
  ];

  const effectiveSteps = WIZARD_STEPS;

  const updateWizardData = useCallback((partial: Partial<WizardData>) => {
    setWizardData((prev) => ({ ...prev, ...partial }));
  }, []);

  const canProceed = (): boolean => {
    if (currentStep === 0) return wizardData.courseTitle.trim().length > 0;
    return true;
  };

  const handleNext = () => {
    if (!canProceed()) return;
    setCurrentStep((s) => Math.min(s + 1, 3));
  };

  const handleBack = () => {
    setCurrentStep((s) => Math.max(s - 1, 0));
  };

  const resetWizard = () => {
    setCurrentStep(0);
    setWizardData({ ...DEFAULT_WIZARD_DATA });
  };

  const handleWizardImportPick = () => {
    wizardImportFileRef.current?.click();
  };

  const handleWizardImportFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    e.target.value = '';
    if (!file || !user?.id) return;

    setWizardImportLoading(true);
    try {
      const text = await file.text();
      let json: unknown;
      try {
        json = JSON.parse(text);
      } catch {
        toast.error(t('coursePackage.importFailed'), {
          description: t('coursePackage.invalidFile'),
        });
        return;
      }
      const parsed = parseCoursePackageJson(json);
      if (parsed.ok === false) {
        toast.error(t('coursePackage.importFailed'), { description: parsed.error });
        return;
      }
      const pkgForCreate = packageForNewClassroomFromAny(parsed.data);
      const { data, error } = await importCoursePackageV1(pkgForCreate, user.id);
      if (error || !data) {
        toast.error(t('coursePackage.importFailed'), { description: error?.message });
        return;
      }
      toast.success(t('coursePackage.importSuccessWizard'));
      await queryClient.invalidateQueries({ queryKey: classroomKeys.lists() });
      onOpenChange(false);
      resetWizard();
      onSuccess(data.classroomId);
    } catch (err) {
      console.error(err);
      toast.error(t('coursePackage.importFailed'));
    } finally {
      setWizardImportLoading(false);
    }
  };

  const handleSubmit = async () => {
    if (!user) return;
    setLoading(true);

    try {
      const filteredDomains = wizardData.domains
        .filter((d) => d.name.trim())
        .map((d) => ({
          name: d.name,
          components: d.components.filter((c) => c.trim()),
        }))
        .filter((d) => d.components.length > 0);

      // 1. Create classroom
      const { data: classroom, error: classroomError } = await supabase
        .from('classrooms')
        .insert({
          teacher_id: user.id,
          name: wizardData.courseTitle || 'New Classroom',
          subject: wizardData.courseTitle || 'General',
          course_title: wizardData.courseTitle,
          start_date: wizardData.startDate || null,
          end_date: wizardData.endDate || null,
          resources: wizardData.courseDescription || '',
          learning_outcomes: wizardData.learningOutcomes.filter((o) => o.trim()) as unknown as Json,
          key_challenges: wizardData.keyChallenges.filter((c) => c.trim()) as unknown as Json,
          domains: filteredDomains as unknown as Json,
          materials: [] as unknown as Json,
        })
        .select()
        .single();

      if (classroomError) throw classroomError;

      // 2. Create syllabus if opted in (single service path — matches Course Outline)
      let syllabusCreated = true;
      if (wizardData.includeSyllabus) {
        const bundleStatus: SyllabusStatus = 'published';
        try {
          const sectionResourceItems: ProvisionBundleResourceItem[][] = wizardData.sections.map(
            () => []
          );

          const provisioned = await provisionBundle.mutateAsync({
            classroom_id: classroom.id,
            title: wizardData.syllabusTitle || wizardData.courseTitle,
            summary: null,
            structure_type: wizardData.structureType,
            policies: wizardData.policies,
            status: bundleStatus,
            release_mode: wizardData.release_mode,
            sections: wizardData.sections.map((s, index) => ({
              tempId: s.tempId,
              title: s.title,
              description: s.description.trim() || null,
              order_index: index,
              start_date: s.startDate || null,
              end_date: s.endDate || null,
              objectives: s.objectives.filter((o) => o.trim()),
              resources: null,
              notes: null,
              content: s.content.trim() ? s.content : null,
              completion_status: s.completion_status,
              prerequisitesTempIds: [],
              is_locked: wizardData.release_mode === 'manual' ? s.is_locked : false,
            })),
            gradingCategories: wizardData.gradingCategories
              .filter((c) => c.name.trim())
              .map((c) => ({ name: c.name, weight: c.weight })),
            sectionResourceItems,
          });

          if (bundleStatus === 'published' && provisioned) {
            await runSyllabusPublishedSideEffects(t, {
              classroomId: classroom.id,
              syllabusId: provisioned.id,
              syllabusTitle: provisioned.title,
              sectionsCount: wizardData.sections.length,
              userId: user.id,
              wasAlreadyPublished: false,
            });
          }
        } catch (syllabusErr) {
          console.error('Syllabus creation failed:', syllabusErr);
          syllabusCreated = false;
        }
      }

      // 5. Log activity
      try {
        await supabase.from('activity_events' as any).insert([
          {
            teacher_id: user.id,
            type: 'create',
            entity_type: 'classroom',
            entity_id: classroom.id,
            title: `Created classroom: ${wizardData.courseTitle || 'New Classroom'}`,
            route: `/teacher/classroom/${classroom.id}`,
          },
        ]);
      } catch {
        // non-critical
      }

      if (syllabusCreated) {
        toast.success(t('createClassroom.success.created', 'Classroom created successfully!'));
      } else {
        toast.warning(t('syllabus.wizard.syllabusWarning'));
      }
      onOpenChange(false);
      onSuccess(classroom.id);
      resetWizard();
    } catch (error: any) {
      toast.error(error.message || 'Failed to create classroom');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog
      open={open}
      onOpenChange={(val) => {
        onOpenChange(val);
        if (!val) resetWizard();
      }}
    >
      <DialogContent
        dir={isRTL ? 'rtl' : 'ltr'}
        className="sm:max-w-6xl w-[95vw] max-h-[92vh] h-[92vh] p-0 overflow-hidden rounded-xl border-none shadow-2xl bg-background flex flex-col"
        showCloseButton
      >
        {/* Header */}
        <div className="px-6 pt-6 pb-4 border-b border-border bg-gradient-to-br from-muted/20 to-transparent flex-shrink-0">
          <h2
            className={`text-2xl font-bold tracking-tight text-foreground mb-4 ${isRTL ? 'text-right' : 'text-left'}`}
          >
            {t('createClassroom.title', 'Create Classroom')}
          </h2>

          <div className={`mb-4 flex flex-col gap-2 ${isRTL ? 'items-end' : 'items-start'}`}>
            <input
              ref={wizardImportFileRef}
              type="file"
              accept="application/json,.json"
              className="hidden"
              tabIndex={-1}
              onChange={handleWizardImportFileChange}
            />
            <Button
              type="button"
              variant="outline"
              size="sm"
              disabled={wizardBusy}
              onClick={handleWizardImportPick}
              className="rounded-full gap-2 shrink-0"
            >
              {wizardImportLoading ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <Upload className="h-4 w-4" />
              )}
              {wizardImportLoading
                ? t('createClassroom.importFromFileBusy')
                : t('createClassroom.importFromFile')}
            </Button>
            <p
              className={`text-xs text-muted-foreground max-w-md ${isRTL ? 'text-right' : 'text-left'}`}
            >
              {t('createClassroom.importWizardHint')}
            </p>
          </div>

          <WizardStepIndicator steps={effectiveSteps} currentStep={currentStep} isRTL={isRTL} />
        </div>

        {/* Body */}
        <ScrollArea className="flex-1 min-h-0">
          <div className="px-6 py-6">
            {currentStep === 0 && (
              <CourseBasicsStep data={wizardData} onChange={updateWizardData} isRTL={isRTL} />
            )}
            {currentStep === 1 && (
              <SyllabusSetupStep data={wizardData} onChange={updateWizardData} isRTL={isRTL} />
            )}
            {currentStep === 2 && (
              <OutlineBuilderStep data={wizardData} onChange={updateWizardData} isRTL={isRTL} />
            )}
            {currentStep === 3 && <ReviewStep data={wizardData} isRTL={isRTL} />}
          </div>
        </ScrollArea>

        {/* Footer */}
        <div className="px-6 py-4 border-t border-border flex-shrink-0">
          <div className={`flex items-center justify-between ${isRTL ? 'flex-row-reverse' : ''}`}>
            <div>
              {currentStep > 0 && (
                <Button
                  type="button"
                  variant="ghost"
                  onClick={handleBack}
                  disabled={wizardBusy}
                  className="rounded-full gap-2"
                >
                  {isRTL ? <ArrowRight className="h-4 w-4" /> : <ArrowLeft className="h-4 w-4" />}
                  {t('syllabus.wizard.back')}
                </Button>
              )}
            </div>

            <div className={`flex items-center gap-3 ${isRTL ? 'flex-row-reverse' : ''}`}>
              <Button
                type="button"
                variant="ghost"
                onClick={() => {
                  onOpenChange(false);
                  resetWizard();
                }}
                disabled={wizardBusy}
                className="rounded-full"
              >
                {t('syllabus.cancel')}
              </Button>

              {currentStep < 3 ? (
                <Button
                  type="button"
                  onClick={handleNext}
                  disabled={!canProceed() || wizardBusy}
                  className="rounded-full px-8 font-bold shadow-lg shadow-primary/20 gap-2"
                >
                  {t('syllabus.wizard.next')}
                  {isRTL ? <ArrowLeft className="h-4 w-4" /> : <ArrowRight className="h-4 w-4" />}
                </Button>
              ) : (
                <Button
                  type="button"
                  onClick={handleSubmit}
                  disabled={wizardBusy || !wizardData.courseTitle.trim()}
                  className="rounded-full px-10 font-bold shadow-lg shadow-primary/20"
                >
                  {loading ? (
                    <>
                      <Loader2 className="h-4 w-4 animate-spin me-2" />
                      {t('syllabus.creating')}
                    </>
                  ) : (
                    t('syllabus.wizard.createClassroom')
                  )}
                </Button>
              )}
            </div>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
};

