  videoTracking?: VideoWatchTrackingBase;
}

function buildVideoTracking(
  base: VideoWatchTrackingBase | undefined,
  resourceId: string,
  lessonBlockId?: string | null
) {
  if (!base) return undefined;
  return {
    resourceId,
    lessonBlockId: lessonBlockId ?? null,
    classroomId: base.classroomId,
    studentUserId: base.studentUserId,
  };
}

const resourceTypeConfig: Record<string, { icon: React.ElementType; color: string }> = {
  file: { icon: File, color: 'text-muted-foreground' },
  video: { icon: Video, color: 'text-blue-500' },
  link: { icon: LinkIcon, color: 'text-green-500' },
  document: { icon: FileText, color: 'text-orange-500' },
  image: { icon: ImageIcon, color: 'text-purple-500' },
  text: { icon: FileText, color: 'text-sky-600' },
  lesson: { icon: FileText, color: 'text-violet-600' },
};

function formatFileSize(bytes: number | null): string {
  if (!bytes) return '';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

/** Matches `ResourcePreview` so mis-typed `resource_type` still shows inline player. */
function resourceHasInlinePreview(resource: SectionResource): boolean {
  if (resource.resource_type === 'link') return false;
  const mime = resource.mime_type || '';
  if (resource.resource_type === 'image' || mime.startsWith('image/')) return true;
  if (resource.resource_type === 'video' || mime.startsWith('video/')) return true;
  if (mime === 'application/pdf') return true;
  return false;
}

function isVideoResource(resource: SectionResource): boolean {
  const mime = resource.mime_type || '';
  return resource.resource_type === 'video' || mime.startsWith('video/');
}

/** Video waits for user Open; images/PDF show immediately. */
function shouldShowInlinePreview(resource: SectionResource, videoRevealed: boolean): boolean {
  if (resource.resource_type === 'link') return false;
  if (isVideoResource(resource)) return videoRevealed;
  return resourceHasInlinePreview(resource);
}

/** Save via blob URL or authenticated fetch — never opens shareable Supabase signed URLs. */
async function triggerBrowserDownload(url: string, filename: string): Promise<boolean> {
  const safeName = filename.replace(/[/\\?%*:|"<>]/g, '_').trim() || 'download';
  try {
    if (url.startsWith('blob:')) {
      const a = document.createElement('a');
      a.href = url;
      a.download = safeName;
      a.rel = 'noopener';
      a.style.display = 'none';
      document.body.appendChild(a);
      a.click();
      a.remove();
      return true;
    }
    if (isSupabaseStorageUrl(SYLLABUS_RESOURCES_BUCKET, url)) {
      return false;
    }
    const res = await fetch(url, { mode: 'cors', credentials: 'omit' });
    if (!res.ok) throw new Error(String(res.status));
    const blob = await res.blob();
    const objectUrl = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = objectUrl;
    a.download = safeName;
    a.rel = 'noopener';
    a.style.display = 'none';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(objectUrl), 60_000);
    return true;
  } catch {
    return false;
  }
}

function canOpenUrlInBrowser(url: string): boolean {
  if (!url) return false;
  if (url.startsWith('blob:')) return true;
  if (isSupabaseStorageUrl(SYLLABUS_RESOURCES_BUCKET, url)) return false;
  return url.startsWith('http://') || url.startsWith('https://');
}

export type LessonResourceBodyVariant = 'embedded' | 'reading';

/** Ordered text + video blocks for `resource_type === 'lesson'` (v1 JSON or legacy body_text + url). */
export const LessonResourceBody = ({
  resource,
  className,
  variant = 'embedded',
  isRTL = false,
  videoTracking,
}: {
  resource: SectionResource;
  className?: string;
  /** `reading`: single shell, plain prose, framed video (activity page). `embedded`: compact cards (syllabus preview). */
  variant?: LessonResourceBodyVariant;
  isRTL?: boolean;
  videoTracking?: VideoWatchTrackingBase;
}) => {
  const { t } = useTranslation();
  const reading = variant === 'reading';
  const textPresentation = reading ? 'reading' : 'embedded';
  const videoPresentation = reading ? 'reading' : 'embedded';

  const v1 = parseLessonContent(resource.lesson_content as unknown);

  if (v1?.blocks?.length) {
    const nodes = v1.blocks.map((block) => {
      if (block.type === 'text') {
        const slideList = block.slides;
        if (Array.isArray(slideList) && slideList.length > 1) {
          const nonEmpty = slideList.filter((s) => s && s.trim());
          if (nonEmpty.length > 1) {
            return (
              <div key={block.id} className="w-full min-w-0">
                <LessonTextSlidesBlock
                  slideBodies={nonEmpty}
                  presentation={textPresentation}
                  isRTL={isRTL}
                />
              </div>
            );
          }
        }
        const source =
          Array.isArray(slideList) && slideList.length === 1 ? slideList[0]! : block.body;
        if (!source || !String(source).trim()) return null;
        return (
          <div key={block.id} className="w-full min-w-0">
            <ContentRichTextBlock
              html={lessonTextBodyToHtml(source)}
              presentation={textPresentation}
            />
          </div>
        );
      }
      if (block.type === 'video') {
        if (!shouldShowLessonVideoBlock(block)) return null;
        const videoUrl = block.url || '';
        const source = inferLessonVideoSource(block);
        return (
          <div key={block.id}>
            <ContentVideoBlock
              videoUrl={videoUrl}
              source={source}
              presentation={videoPresentation}
              tracking={buildVideoTracking(videoTracking, resource.id, block.id)}
            />
          </div>
        );
      }
      return null;
    });
    const hasVisible = nodes.some((n) => n != null);
    if (!hasVisible) {
      return (
        <p className={cn('text-sm text-muted-foreground', className)}>
          {t('activityPage.lessonEmpty')}
        </p>
      );
    }
    return (
      <div className={cn(reading ? 'flex flex-col gap-5 sm:gap-6' : 'space-y-3', className)}>
        {nodes}
      </div>
    );
  }

  const videoUrl = resource.url || '';
  const showLessonVideo =
    videoUrl &&
    (isVideoResource(resource) ||
      resource.mime_type?.startsWith('video/') ||
      /\.(mp4|webm|ogg|mov)(\?|$)/i.test(videoUrl));
  const hasLegacyText = !!resource.body_text?.trim();
  if (!hasLegacyText && !showLessonVideo) {
    return (
      <p className={cn('text-sm text-muted-foreground', className)}>
        {t('activityPage.lessonEmpty')}
      </p>
    );
  }
  const legacyInner = (
    <>
      {hasLegacyText ? (
        <ContentRichTextBlock
          html={lessonTextBodyToHtml(resource.body_text ?? '')}
          presentation={textPresentation}
        />
      ) : null}
      {showLessonVideo ? (
        <ContentVideoBlock
          videoUrl={videoUrl}
          presentation={videoPresentation}
          tracking={buildVideoTracking(videoTracking, resource.id)}
        />
      ) : null}
    </>
  );
  if (reading) {
    return <div className={cn('flex flex-col gap-5 sm:gap-6', className)}>{legacyInner}</div>;
  }
  return <div className={cn('space-y-3', className)}>{legacyInner}</div>;
};

const ResourcePreview = ({
  resource,
  videoTracking,
}: {
  resource: SectionResource;
  videoTracking?: VideoWatchTrackingBase;
}) => {
  const url = resource.url || '';
  const mime = resource.mime_type || '';

  if (resource.resource_type === 'text' && resource.body_text?.trim()) {
    return (
      <ContentPlainTextBlock text={resource.body_text} presentation="compact" className="mb-2" />
    );
  }

  if (resource.resource_type === 'lesson') {
    return <LessonResourceBody resource={resource} videoTracking={videoTracking} />;
  }

  if (resource.resource_type === 'image' || mime.startsWith('image/')) {
    return (
      <ContentImageBlock
        src={url}
        alt={resource.title}
        caption={resource.summary}
        presentation="compact"
        className="mb-2"
      />
    );
  }

  if (resource.resource_type === 'video' || mime.startsWith('video/')) {
    return (
      <div className="mb-2">
        <ContentVideoBlock
          videoUrl={url}
          presentation="compact"
          tracking={buildVideoTracking(videoTracking, resource.id)}
        />
      </div>
    );
  }

  if (mime === 'application/pdf') {
    return (
      <div className="rounded-lg overflow-hidden border border-border mb-2">
        <iframe src={`${url}#toolbar=0`} title={resource.title} className="w-full h-72 bg-white" />
      </div>
    );
  }

  return null;
};

const ResourceCard = ({
  resource,
  isRTL,
  compact,
  compactVariant = 'card',
  videoTracking,
}: {
  resource: SectionResource;
  isRTL: boolean;
  compact: boolean;
  compactVariant?: 'card' | 'list';
  videoTracking?: VideoWatchTrackingBase;
}) => {
  const { t } = useTranslation();
  const [videoRevealed, setVideoRevealed] = useState(false);
  const config = resourceTypeConfig[resource.resource_type] || resourceTypeConfig.file;
  const Icon = config.icon;
  const url = resource.url || '';
  const isLink = resource.resource_type === 'link';
  const isVideo = isVideoResource(resource);
  const hasPreview = resourceHasInlinePreview(resource);
  const showPreview = shouldShowInlinePreview(resource, videoRevealed);
  const useOpenAction = hasPreview || isLink;

  const handleOpen = async () => {
    if (isVideo && !videoRevealed) {
      setVideoRevealed(true);
      return;
    }

    let openUrl = url;
    if (!canOpenUrlInBrowser(openUrl)) {
      const resolved = await resolveSectionResourceFileUrl(resource);
      if (resolved) openUrl = resolved;
    }

    if (!useOpenAction && openUrl) {
      const ok = await triggerBrowserDownload(openUrl, resource.title);
      if (ok) return;
      toast.error(t('syllabus.resources.downloadFailed'));
      return;
    }
    if (canOpenUrlInBrowser(openUrl)) {
      window.open(openUrl, '_blank', 'noopener');
      return;
    }
    toast.error(t('syllabus.resources.downloadFailed'));
  };

  if (compact) {
    const listRow = compactVariant === 'list';
    return (
      <button
        type="button"
        onClick={handleOpen}
        className={cn(
          'flex items-center gap-2.5 w-full group text-left',
          listRow
            ? 'px-3 py-2 rounded-none border-0 bg-transparent hover:bg-muted/40 transition-colors'
            : 'px-3 py-2.5 rounded-lg border border-border bg-card/50 hover:bg-muted/30 hover:border-primary/30 transition-all',
          isRTL && 'flex-row-reverse text-right'
        )}
      >
        <div className={cn('p-1.5 rounded-md bg-muted/50 flex-shrink-0', config.color)}>
          <Icon className="h-4 w-4" />
        </div>
        <div className="flex-1 min-w-0">
          <span className="text-sm font-medium text-foreground truncate block group-hover:text-primary transition-colors">
            {resource.title}
          </span>
          <span className="text-[10px] text-muted-foreground">
            {resource.resource_type === 'link'
              ? t('syllabus.resources.externalLink')
              : formatFileSize(resource.file_size)}
          </span>
        </div>
        {isLink ? (
          <ExternalLink className="h-3.5 w-3.5 text-muted-foreground opacity-0 group-hover:opacity-100 transition-opacity flex-shrink-0" />
        ) : (
          <Download className="h-3.5 w-3.5 text-muted-foreground opacity-0 group-hover:opacity-100 transition-opacity flex-shrink-0" />
        )}
      </button>
    );
  }

  return (
    <div
      className={cn(
        'rounded-xl border border-border bg-card/50 overflow-hidden',
        isVideo && videoRevealed && 'w-max max-w-full mx-auto'
      )}
    >
      {showPreview && (
        <div className={cn(isVideo && 'relative')}>
          {isVideo && videoRevealed && (
            <Button
              type="button"
              variant="secondary"
              size="icon"
              className="absolute top-2 end-2 z-10 h-8 w-8 rounded-full border border-border bg-background/95 shadow-sm hover:bg-muted"
              onClick={() => setVideoRevealed(false)}
              aria-label={t('common.close')}
            >
              <X className="h-4 w-4" />
            </Button>
          )}
          <ResourcePreview resource={resource} videoTracking={videoTracking} />
        </div>
      )}
      <div className={cn('flex items-center gap-3 px-4 py-3', isRTL && 'flex-row-reverse')}>
        <div className={cn('p-2 rounded-lg bg-muted/50', config.color)}>
          {isVideo && !videoRevealed ? <Play className="h-4 w-4" /> : <Icon className="h-4 w-4" />}
        </div>
        <div className={`flex-1 min-w-0 ${isRTL ? 'text-right' : 'text-left'}`}>
          <h4 className="text-sm font-medium text-foreground truncate">{resource.title}</h4>
          <p className="text-[11px] text-muted-foreground truncate">
            {isLink ? url : formatFileSize(resource.file_size)}
          </p>
        </div>
        <Button
          variant="outline"
          size="sm"
          onClick={handleOpen}
          aria-expanded={isVideo ? videoRevealed : undefined}
          className="rounded-full gap-1.5 h-8 text-xs flex-shrink-0"
        >
          {useOpenAction ? (
            <>
              <ExternalLink className="h-3 w-3" />{' '}
              {isVideo && videoRevealed
                ? t('syllabus.resources.openInNewTab')
                : t('syllabus.resources.open')}
            </>
          ) : (
            <>
              <Download className="h-3 w-3" /> {t('syllabus.resources.download')}
            </>
          )}
        </Button>
      </div>
    </div>
  );
};

export const ResourceViewer = ({
  resources,
  isRTL = false,
  compact = false,
  hideListHeader = false,
  compactVariant = 'card',
  videoTracking,
}: ResourceViewerProps) => {
  const { t } = useTranslation();
  const { resources: displayResources } = useResolvedSectionResources(resources);

  if (displayResources.length === 0) return null;

  const listMode = compact && compactVariant === 'list';
  const showInnerHeading = !hideListHeader;

  return (
    <div className={cn(!listMode && 'space-y-2')}>
      {showInnerHeading ? (
        <h4
          className={cn(
            'text-xs font-bold text-muted-foreground uppercase tracking-wider flex items-center gap-1',
            isRTL && 'flex-row-reverse text-right'
          )}
        >
          <FileText className="h-3 w-3" /> {t('syllabus.resources.title')} (
          {displayResources.length})
        </h4>
      ) : null}
      <div
        className={cn(
          listMode &&
            'divide-y divide-border overflow-hidden rounded-md border border-border/60 bg-muted/5',
          !listMode && compact && 'space-y-1',
          !listMode && !compact && 'space-y-3'
        )}
      >
        {displayResources.map((resource) => (
          <ResourceCard
            key={resource.id}
            resource={resource}
            isRTL={isRTL}
            compact={compact}
            compactVariant={compact ? compactVariant : 'card'}
            videoTracking={videoTracking}
          />
        ))}
      </div>
    </div>
  );
};

export const ResolvedLessonResourceBody = ({
  resource,
  className,
  variant = 'embedded',
  isRTL = false,
  videoTracking,
}: {
  resource: SectionResource;
  className?: string;
  variant?: LessonResourceBodyVariant;
  isRTL?: boolean;
  videoTracking?: VideoWatchTrackingBase;
}) => {
  const { resources } = useResolvedSectionResources([resource]);
  const resolved = resources[0] ?? resource;
  return (
    <LessonResourceBody
      resource={resolved}
      className={className}
      variant={variant}
      isRTL={isRTL}
      videoTracking={videoTracking}
    />
  );
};

import {
  ArrowLeft,
  ArrowRight,
  Calendar,
  Target,
  BookOpen,
  FileText,
  Lock,
  ChevronLeft,
  ChevronRight,
  ExternalLink,
} from 'lucide-react';
import { useMemo, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { Link } from 'react-router-dom';
import type {
  SyllabusSection,
  SectionResource,
  StudentProgressStatus,
  ReleaseMode,
  ModuleFlowStep,
} from '@/types/syllabus';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Progress } from '@/components/ui/progress';
import { RichTextViewer } from '@/components/ui/rich-text-editor';
import { useAuth } from '@/contexts/useAuth';
import {
  useUpdateStudentProgress,
  useStudentModuleFlowProgressMap,
  useAssignmentSubmittedOrCompletedMap,
} from '@/hooks/queries';
import { CurriculumAssignmentTypeIcon } from '@/lib/assignmentTypeCurriculumIcon';
import { getOrderedActivityCenterFlowSteps, studentModuleFlowStepOptions } from '@/lib/moduleFlow';
import { computeSectionModuleProgressStats } from '@/lib/sectionModuleProgressStats';
import {
  isSectionUnlocked,
  sectionsInCourseOrder,
  type SectionSequentialUnlockFlow,
} from '@/lib/sectionUnlock';
import { cn } from '@/lib/utils';

interface SectionContentPageProps {
  sectionId: string;
  classroomId: string;
  /** Persisted teacher module flow; when non-empty, outline shows assignments + activity steps in order. */
  moduleFlowSteps: ModuleFlowStep[];
  sections: SyllabusSection[];
  sectionResources: Record<string, SectionResource[]>;
  linkedAssignmentsMap: Record<
    string,
    Array<{ id: string; title: string; type: string; due_at: string | null }>
  >;
  syllabusId: string;
  releaseMode: ReleaseMode;
  studentProgressMap: Record<string, StudentProgressStatus>;
  /** Sequential unlock: treat prior units done when module flow is complete, not only `completed` rows. */
  sequentialUnlockFlow?: SectionSequentialUnlockFlow | null;
  isRTL: boolean;
  onBack: () => void;
  onNavigateSection: (sectionId: string) => void;
}

const EMPTY_LINKED_ASSIGNMENTS: Array<{
  id: string;
  title: string;
  type: string;
  due_at: string | null;
}> = [];

export const SectionContentPage = ({
  sectionId,
  classroomId,
  moduleFlowSteps,
  sections,
  sectionResources,
  linkedAssignmentsMap,
  syllabusId,
  releaseMode,
  studentProgressMap,
  sequentialUnlockFlow = null,
  isRTL,
  onBack,
  onNavigateSection,
}: SectionContentPageProps) => {
  const { t } = useTranslation();
  const { user } = useAuth();
  const updateProgress = useUpdateStudentProgress();

  const sortedSections = useMemo(() => sectionsInCourseOrder(sections), [sections]);
  const currentIndex = sortedSections.findIndex((s) => s.id === sectionId);
  const section = sortedSections[currentIndex];
  const prevSection = currentIndex > 0 ? sortedSections[currentIndex - 1] : null;
  const nextSection =
    currentIndex < sortedSections.length - 1 ? sortedSections[currentIndex + 1] : null;
  const resources = sectionResources[sectionId] || [];
  const assignments = useMemo(
    () => linkedAssignmentsMap[sectionId] ?? EMPTY_LINKED_ASSIGNMENTS,
    [linkedAssignmentsMap, sectionId]
  );
  const studentFlowOpts = useMemo(() => studentModuleFlowStepOptions(assignments), [assignments]);
  const orderedFlow = useMemo(
    () =>
      moduleFlowSteps.length > 0
        ? getOrderedActivityCenterFlowSteps(moduleFlowSteps, resources, studentFlowOpts)
        : [],
    [moduleFlowSteps, resources, studentFlowOpts]
  );
  const useFlowList = orderedFlow.length > 0;
  const assignmentById = useMemo(() => {
    const m: Record<string, (typeof assignments)[number]> = {};
    assignments.forEach((a) => {
      m[a.id] = a;
    });
    return m;
  }, [assignments]);
  const resourceById = useMemo(() => {
    const m: Record<string, SectionResource> = {};
    resources.forEach((r) => {
      m[r.id] = r;
    });
    return m;
  }, [resources]);

  const flowStepIds = useMemo(() => orderedFlow.map((s) => s.id), [orderedFlow]);

  const { data: progressByStep = {} } = useStudentModuleFlowProgressMap(user?.id, flowStepIds);

  const assignmentIdsForSubmissionQuery = useMemo(() => {
    if (useFlowList) {
      const ids: string[] = [];
      for (const step of orderedFlow) {
        if (
          step.step_kind === 'assignment' &&
          step.assignment_id &&
          assignmentById[step.assignment_id]
        ) {
          ids.push(step.assignment_id);
        }
      }
      return ids;
    }
    return assignments.map((a) => a.id);
  }, [useFlowList, orderedFlow, assignmentById, assignments]);

  const { data: assignmentDoneMap = {} } = useAssignmentSubmittedOrCompletedMap(
    assignmentIdsForSubmissionQuery,
    user?.id
  );

  const moduleProgressStats = useMemo(
    () =>
      computeSectionModuleProgressStats({
        persistedSteps: moduleFlowSteps,
        resources,
        linkedAssignments: assignments,
        flowCtx: { progressByStep, assignmentDoneMap },
        flowStepOptions: studentFlowOpts,
      }),
    [moduleFlowSteps, resources, assignments, progressByStep, assignmentDoneMap, studentFlowOpts]
  );

  const studentProgress = studentProgressMap[sectionId];

  useEffect(() => {
    if (
      moduleProgressStats.total > 0 &&
      moduleProgressStats.done >= moduleProgressStats.total &&
      studentProgress !== 'completed' &&
      user?.id &&
      section?.id
    ) {
      updateProgress.mutate({
        sectionId: section.id,
        studentId: user.id,
        status: 'completed',
        syllabusId,
      });
    }
  }, [moduleProgressStats, studentProgress, user?.id, section?.id, syllabusId]); // eslint-disable-line react-hooks/exhaustive-deps

  if (!section) return null;

  const locked = !isSectionUnlocked(
    section,
    sortedSections,
    releaseMode,
    studentProgressMap,
    sequentialUnlockFlow ?? undefined
  );

  const topNavRow = (
    <div className={cn('flex items-center justify-between', isRTL && 'flex-row-reverse')}>
      <Button variant="ghost" onClick={onBack} className="rounded-full gap-1.5">
        {isRTL ? <ArrowRight className="h-4 w-4" /> : <ArrowLeft className="h-4 w-4" />}
        {t('common.back', 'Back')}
      </Button>
      <div className="flex items-center gap-2">
        <Button
          variant="outline"
          size="sm"
          disabled={!prevSection}
          onClick={() => prevSection && onNavigateSection(prevSection.id)}
          className="rounded-full gap-1 h-8"
        >
          {isRTL ? (
            <ChevronRight className="h-3.5 w-3.5" />
          ) : (
            <ChevronLeft className="h-3.5 w-3.5" />
          )}
          {t('syllabus.sections.previous', 'Previous')}
        </Button>
        <span className="text-xs text-muted-foreground">
          {currentIndex + 1} / {sortedSections.length}
        </span>
        <Button
          variant="outline"
          size="sm"
          disabled={!nextSection}
          onClick={() => nextSection && onNavigateSection(nextSection.id)}
          className="rounded-full gap-1 h-8"
        >
          {t('syllabus.sections.next', 'Next')}
          {isRTL ? (
            <ChevronLeft className="h-3.5 w-3.5" />
          ) : (
            <ChevronRight className="h-3.5 w-3.5" />
          )}
        </Button>
      </div>
    </div>
  );

  const bottomNavRow = (
    <div className={cn('flex items-center justify-between pt-4', isRTL && 'flex-row-reverse')}>
      <Button
        variant="outline"
        disabled={!prevSection}
        onClick={() => prevSection && onNavigateSection(prevSection.id)}
        className="rounded-full gap-1.5"
      >
        {isRTL ? <ChevronRight className="h-4 w-4" /> : <ChevronLeft className="h-4 w-4" />}
        {prevSection?.title || t('syllabus.sections.previous', 'Previous')}
      </Button>
      <Button
        variant="outline"
        disabled={!nextSection}
        onClick={() => nextSection && onNavigateSection(nextSection.id)}
        className="rounded-full gap-1.5"
      >
        {nextSection?.title || t('syllabus.sections.next', 'Next')}
        {isRTL ? <ChevronLeft className="h-4 w-4" /> : <ChevronRight className="h-4 w-4" />}
      </Button>
    </div>
  );

  if (locked) {
    return (
      <div className="space-y-6">
        {topNavRow}
        <Card className="rounded-xl border-border shadow-sm">
          <CardContent className="flex flex-col items-center justify-center py-16 text-center">
            <Lock className="h-12 w-12 text-muted-foreground mb-4" />
            <h3 className="text-xl font-bold text-foreground mb-2">
              {t('syllabus.sections.locked', 'Locked')}
            </h3>
            <p className="text-muted-foreground max-w-md mb-4">
              {t(
                'syllabus.sections.unlockRequirements',
                'Complete the required sections to unlock this content.'
              )}
            </p>
          </CardContent>
        </Card>
        {bottomNavRow}
      </div>
    );
  }

  const dateRange = [section.start_date, section.end_date].filter(Boolean).join(' → ');

  return (
    <div className="space-y-6">
      {topNavRow}

      {/* Header */}
      <div>
        <h2 className={cn('text-2xl font-bold text-foreground mb-2', isRTL && 'text-right')}>
          {section.title}
        </h2>
        <div className={cn('flex flex-wrap items-center gap-3', isRTL && 'flex-row-reverse')}>
          {dateRange && (
            <span className="text-sm text-muted-foreground flex items-center gap-1">
              <Calendar className="h-3.5 w-3.5" /> {dateRange}
            </span>
          )}
          {!useFlowList && assignments.length > 0 ? (
            <Badge variant="secondary" className="rounded-full text-xs">
              <BookOpen className="h-3 w-3 me-1" /> {assignments.length}{' '}
              {t('syllabus.sections.linkedAssignments', 'assignments')}
            </Badge>
          ) : null}
        </div>
      </div>

      {/* Description */}
      {section.description && (
        <Card className="rounded-xl border-border shadow-sm">
          <CardContent className="p-5">
            <p
              className={cn(
                'text-sm text-foreground/80 leading-relaxed whitespace-pre-wrap',
                isRTL && 'text-right'
              )}
            >
              {section.description}
            </p>
          </CardContent>
        </Card>
      )}

      {/* Rich content */}
      {section.content && (
        <div>
          <h4 className="text-xs font-bold text-muted-foreground uppercase tracking-wider mb-3">
            {t('syllabus.sections.content', 'Content')}
          </h4>
          <RichTextViewer content={section.content} />
        </div>
      )}

      {/* Objectives */}
      {section.objectives && section.objectives.length > 0 && (
        <div>
          <h4 className="text-xs font-bold text-muted-foreground uppercase tracking-wider mb-3 flex items-center gap-1">
            <Target className="h-3 w-3" /> {t('syllabus.detail.objectives', 'Objectives')}
          </h4>
          <div className="space-y-2">
            {section.objectives.map((obj, i) => (
              <div key={i} className="flex items-start gap-2.5 p-2.5 rounded-lg bg-muted/20">
                <div className="h-5 w-5 rounded-full bg-primary/10 flex items-center justify-center flex-shrink-0 mt-0.5">
                  <span className="text-[10px] font-bold text-primary">{i + 1}</span>
                </div>
                <span className="text-sm text-foreground/80">{obj}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Module flow (assignments + activities) or linked assignments only */}
      {(useFlowList || assignments.length > 0) && (
        <div>
          <h4 className="text-xs font-bold text-muted-foreground uppercase tracking-wider mb-3 flex items-center gap-1">
            <BookOpen className="h-3 w-3" />{' '}
            {useFlowList
              ? t('syllabus.detail.moduleStepsHeading', 'Module steps')
              : t('syllabus.detail.linkedAssignments', 'Assignments')}
          </h4>
          {moduleProgressStats.total > 0 && (
            <div className="mb-3">
              <div className="flex items-center justify-between text-xs text-muted-foreground mb-1">
                <span>{t('syllabus.progress.moduleProgress', 'Module progress')}</span>
                <span>
                  {moduleProgressStats.done} / {moduleProgressStats.total}
                </span>
              </div>
              <Progress value={moduleProgressStats.percent} className="h-2" />
            </div>
          )}
          <div className="space-y-1.5">
            {useFlowList
              ? orderedFlow.map((step) => {
                  if (step.step_kind === 'resource' && step.activity_list_id) {
                    const r = resourceById[step.activity_list_id];
                    const title = r?.title ?? t('studentClassroom.activities.activity', 'Activity');
                    const sub = t('syllabus.detail.activityStepLabel', 'Activity');
                    return (
                      <Link
                        key={step.id}
                        to={`/student/classroom/${classroomId}/activity/${step.activity_list_id}`}
                        state={{ returnClassroomSection: 'curriculum' }}
                        className={cn(
                          'flex items-center gap-3 px-3 py-2.5 rounded-lg border border-border bg-card/50',
                          'hover:bg-muted/60 transition-colors cursor-pointer text-foreground no-underline',
                          isRTL && 'flex-row-reverse'
                        )}
                      >
                        <div className="p-1.5 rounded-md bg-muted/50">
                          <FileText className="h-3.5 w-3.5 text-muted-foreground" />
                        </div>
                        <div className={`flex-1 min-w-0 ${isRTL ? 'text-right' : 'text-left'}`}>
                          <span className="text-sm font-medium text-foreground truncate block">
                            {title}
                          </span>
                          <span className="text-[10px] text-muted-foreground">{sub}</span>
                        </div>
                        <span
                          className={cn(
                            'inline-flex items-center gap-1 rounded-full border border-border bg-background px-2.5 py-1 text-[10px] font-medium flex-shrink-0',
                            isRTL && 'flex-row-reverse'
                          )}
                        >
                          <ExternalLink className="h-3 w-3" />
                          {t('syllabus.resources.open')}
                        </span>
                      </Link>
                    );
                  }
                  if (step.step_kind === 'assignment' && step.assignment_id) {
                    const a = assignmentById[step.assignment_id];
                    if (!a) return null;
                    return (
                      <Link
                        key={step.id}
                        to={`/student/assignment/${a.id}`}
                        state={{ returnClassroomSection: 'curriculum' }}
                        className={cn(
                          'flex items-center gap-3 px-3 py-2.5 rounded-lg border border-border bg-card/50',
                          'hover:bg-muted/60 transition-colors cursor-pointer text-foreground no-underline',
                          isRTL && 'flex-row-reverse'
                        )}
                      >
                        <div className="p-1.5 rounded-md bg-muted/50">
                          <CurriculumAssignmentTypeIcon type={a.type} />
                        </div>
                        <div className={`flex-1 min-w-0 ${isRTL ? 'text-right' : 'text-left'}`}>
                          <span className="text-sm font-medium text-foreground truncate block">
                            {a.title}
                          </span>
                          <span className="text-[10px] text-muted-foreground">{a.type}</span>
                        </div>
                        {a.due_at && (
                          <span className="text-[10px] text-muted-foreground flex items-center gap-1 flex-shrink-0">
                            <Calendar className="h-3 w-3" />
                            {new Date(a.due_at).toLocaleDateString()}
                          </span>
                        )}
                        <span
                          className={cn(
                            'inline-flex items-center gap-1 rounded-full border border-border bg-background px-2.5 py-1 text-[10px] font-medium flex-shrink-0',
                            isRTL && 'flex-row-reverse'
                          )}
                        >
                          <ExternalLink className="h-3 w-3" />
                          {t('syllabus.resources.open')}
                        </span>
                      </Link>
                    );
                  }
                  return null;
                })
              : assignments.map((a) => (
                  <Link
                    key={a.id}
                    to={`/student/assignment/${a.id}`}
                    state={{ returnClassroomSection: 'curriculum' }}
                    className={cn(
                      'flex items-center gap-3 px-3 py-2.5 rounded-lg border border-border bg-card/50',
                      'hover:bg-muted/60 transition-colors cursor-pointer text-foreground no-underline',
                      isRTL && 'flex-row-reverse'
                    )}
                  >
                    <div className="p-1.5 rounded-md bg-muted/50">
                      <CurriculumAssignmentTypeIcon type={a.type} />
                    </div>
                    <div className={`flex-1 min-w-0 ${isRTL ? 'text-right' : 'text-left'}`}>
                      <span className="text-sm font-medium text-foreground truncate block">
                        {a.title}
                      </span>
                      <span className="text-[10px] text-muted-foreground">{a.type}</span>
                    </div>
                    {a.due_at && (
                      <span className="text-[10px] text-muted-foreground flex items-center gap-1 flex-shrink-0">
                        <Calendar className="h-3 w-3" />
                        {new Date(a.due_at).toLocaleDateString()}
                      </span>
                    )}
                    <span
                      className={cn(
