interface SectionDetailModalProps {
  section: SyllabusSection | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  assignmentCount: number;
  resources: SectionResource[];
  sectionStatus: SectionStatus;
  mode: 'teacher' | 'student';
  isRTL?: boolean;
  syllabusId?: string;
  studentProgress?: StudentProgressStatus;
  linkedAssignments?: Array<{ id: string; title: string; type: string; due_at: string | null }>;
}

const statusConfig: Record<
  SectionStatus,
  { labelKey: string; icon: React.ElementType; className: string }
> = {
  upcoming: {
    labelKey: 'syllabus.roadmap.upcoming',
    icon: Clock,
    className: 'bg-muted text-muted-foreground',
  },
  in_progress: {
    labelKey: 'syllabus.roadmap.inProgress',
    icon: CircleDot,
    className: 'bg-primary/15 text-primary border-primary/30',
  },
  completed: {
    labelKey: 'syllabus.roadmap.completed',
    icon: CheckCircle2,
    className: 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400',
  },
  skipped: {
    labelKey: 'syllabus.roadmap.skipped',
    icon: SkipForward,
    className: 'bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400',
  },
};

const progressOptions: {
  value: StudentProgressStatus;
  labelKey: string;
  icon: React.ElementType;
}[] = [
  { value: 'not_started', labelKey: 'syllabus.progress.notStarted', icon: Clock },
  { value: 'in_progress', labelKey: 'syllabus.progress.inProgress', icon: CircleDot },
  { value: 'reviewed', labelKey: 'syllabus.progress.reviewed', icon: Eye },
  { value: 'completed', labelKey: 'syllabus.progress.completed', icon: CheckCircle2 },
];

export const SectionDetailModal = ({
  section,
  open,
  onOpenChange,
  assignmentCount,
  resources,
  sectionStatus,
  mode,
  isRTL = false,
  syllabusId,
  studentProgress,
  linkedAssignments = [],
}: SectionDetailModalProps) => {
  const { t } = useTranslation();
  const { user } = useAuth();
  const updateProgress = useUpdateStudentProgress();

  if (!section) return null;

  const dateRange = [section.start_date, section.end_date].filter(Boolean).join(' → ');
  const statusInfo = statusConfig[sectionStatus];
  const StatusIcon = statusInfo.icon;

  const handleProgressChange = (newStatus: StudentProgressStatus) => {
    if (!user?.id || !syllabusId) return;
    updateProgress.mutate({
      sectionId: section.id,
      studentId: user.id,
      status: newStatus,
      syllabusId,
    });
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        className="max-w-2xl max-h-[85vh] p-0 rounded-2xl overflow-hidden flex flex-col"
        dir={isRTL ? 'rtl' : 'ltr'}
      >
        {/* Header with colored accent */}
        <div
          className={cn(
            'px-6 pt-6 pb-4 border-b border-border flex-shrink-0',
            sectionStatus === 'in_progress' && 'bg-primary/5',
            sectionStatus === 'completed' && 'bg-green-50 dark:bg-green-950/20'
          )}
        >
          <DialogHeader>
            <div className="flex items-start justify-between gap-3">
              <div className="flex-1 min-w-0">
                <DialogTitle
                  className={cn('text-xl font-bold text-foreground mb-2', isRTL && 'text-right')}
                >
                  {section.title}
                </DialogTitle>
                <div
                  className={cn('flex flex-wrap items-center gap-2', isRTL && 'flex-row-reverse')}
                >
                  <Badge
                    variant="outline"
                    className={cn('rounded-full text-xs', statusInfo.className)}
                  >
                    <StatusIcon className="h-3 w-3 me-1" />
                    {t(statusInfo.labelKey)}
                  </Badge>
                  {dateRange && (
                    <span className="text-sm text-muted-foreground flex items-center gap-1">
                      <Calendar className="h-3.5 w-3.5" /> {dateRange}
