              </div>
            </div>
          </DialogHeader>
        </div>

        {/* Scrollable content */}
        <ScrollArea className="flex-1 overflow-y-auto max-h-[calc(85vh-120px)]">
          <div className="px-6 py-5 space-y-6">
            {/* Student progress tracker */}
            {mode === 'student' && syllabusId && (
              <div className="space-y-2">
                <h4
                  className={cn(
