                      <div className="p-1.5 rounded-md bg-muted/50">
                        <BookOpen className="h-3.5 w-3.5 text-muted-foreground" />
                      </div>
                      <div className={`flex-1 min-w-0 ${isRTL ? 'text-right' : 'text-left'}`}>
