          </Button>
          <Button
            size="sm"
            onClick={handleSave}
            disabled={updateMutation.isPending || !hasChanges}
            className="rounded-full gap-1.5"
          >
            {updateMutation.isPending ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
            ) : (
              <Save className="h-3.5 w-3.5" />
            )}
            {t('syllabus.customization.save')}
          </Button>
        </div>
      </div>

      <div className="grid md:grid-cols-2 gap-6">
        {/* Accent Color */}
        <Card className="rounded-xl border-border shadow-sm">
          <CardHeader className="pb-3">
            <CardTitle
              className={cn('text-sm flex items-center gap-2', isRTL && 'flex-row-reverse')}
            >
              <Palette className="h-4 w-4 text-muted-foreground" />
              {t('syllabus.customization.accentColor')}
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            <div className="flex flex-wrap gap-2">
              {PRESET_COLORS.map((color) => (
                <button
                  key={color}
                  type="button"
                  onClick={() => setAccentColor(color)}
                  className={cn(
                    'h-8 w-8 rounded-full border-2 transition-all hover:scale-110',
                    accentColor === color
                      ? 'border-foreground ring-2 ring-primary/30 scale-110'
                      : 'border-transparent'
                  )}
                  style={{ backgroundColor: color }}
                />
              ))}
            </div>
            <div className="flex items-center gap-2">
              <Input
                type="color"
                value={accentColor || '#6366f1'}
                onChange={(e) => setAccentColor(e.target.value)}
                className="h-8 w-12 p-0 border-none cursor-pointer rounded-lg"
              />
              <Input
                value={accentColor}
                onChange={(e) => setAccentColor(e.target.value)}
                placeholder="#6366f1"
                className="rounded-lg h-8 text-xs flex-1 font-mono"
                dir="ltr"
              />
            </div>
            {accentColor && (
              <div className="flex items-center gap-2">
                <div className="h-6 flex-1 rounded-full" style={{ backgroundColor: accentColor }} />
                <span className="text-[10px] text-muted-foreground">
                  {t('syllabus.customization.preview')}
                </span>
              </div>
            )}
          </CardContent>
        </Card>

        {/* Section Label Override */}
        <Card className="rounded-xl border-border shadow-sm">
          <CardHeader className="pb-3">
            <CardTitle
              className={cn('text-sm flex items-center gap-2', isRTL && 'flex-row-reverse')}
