              className="rounded-lg h-9 text-sm"
              dir="ltr"
            />
            {bannerUrl && (
              <div className="rounded-xl overflow-hidden border border-border bg-muted/20">
                <img
                  src={bannerUrl}
                  alt="Banner preview"
                  className="w-full h-32 object-cover"
                  onError={(e) => {
                    (e.target as HTMLImageElement).style.display = 'none';
                  }}
                />
              </div>
            )}
          </CardContent>
        </Card>
      </div>
