const SortableSectionRow = ({
  id,
  children,
}: {
  id: string;
  children: (args: {
    dragAttributes: DraggableAttributes;
    dragListeners: Record<string, unknown> | undefined;
  }) => ReactNode;
}) => {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id,
  });
  const style = {
    transform: CSS.Transform.toString(transform),
    transition: isDragging ? undefined : transition,
    opacity: isDragging ? 0 : undefined,
  };
  return (
    <li ref={setNodeRef} style={style} className={cn('list-none', isDragging && 'z-10')}>
      {children({ dragAttributes: attributes, dragListeners: listeners })}
    </li>
  );
};

interface SyllabusEditorProps {
  syllabusId: string;
  classroomId: string;
  sections: SyllabusSection[];
  structureType: string;
  releaseMode?: ReleaseMode;
  isRTL: boolean;
  sectionResources: Record<string, SectionResource[]>;
  /** Opens teacher assignment edit for a flow step (module flow assignment row). */
  onEditAssignment?: (assignmentId: string) => void;
}

export const SyllabusEditor = ({
  syllabusId,
  classroomId,
  sections,
  structureType,
  releaseMode = 'all_at_once',
  isRTL,
  sectionResources,
  onEditAssignment,
}: SyllabusEditorProps) => {
  const { t, i18n } = useTranslation();
  const [selectedIndex, setSelectedIndex] = useState<number>(0);
  const [editValues, setEditValues] = useState<Partial<SyllabusSection>>({});
  const [saving, setSaving] = useState(false);
  const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false);
  const [sectionToDelete, setSectionToDelete] = useState<SyllabusSection | null>(null);
  const [showBulkSchedule, setShowBulkSchedule] = useState(false);
  const [bulkStartDate, setBulkStartDate] = useState('');
  const [bulkDuration, setBulkDuration] = useState(7);
  const [rewritingField, setRewritingField] = useState<string | null>(null);
  const [lessonSectionId, setLessonSectionId] = useState<string | null>(null);
  const [editingLesson, setEditingLesson] = useState<SectionResource | null>(null);
  const [activeDragId, setActiveDragId] = useState<string | null>(null);
  const flowEditorRef = useRef<ModuleFlowEditorHandle>(null);
  const lessonCreatedFromSectionFlowRef = useRef(false);

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 8 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  );
  const sortableSectionIds = useMemo(() => sections.map((s) => s.id), [sections]);
  const activeDragSection = useMemo(
    () => (activeDragId ? sections.find((s) => s.id === activeDragId) : null),
    [activeDragId, sections]
  );

  const createMutation = useCreateSyllabusSection();
  const updateMutation = useUpdateSyllabusSection();
  const deleteMutation = useDeleteSyllabusSection();
  const reorderMutation = useReorderSyllabusSections();
  const { data: allAssignments = [] } = useClassroomAssignments(classroomId);

  const clampedIndex = Math.min(selectedIndex, Math.max(sections.length - 1, 0));
  const selected = sections[clampedIndex] ?? null;
  const moduleFlowResources = useMemo(
    () => (selected ? sectionResources[selected.id] : undefined) ?? EMPTY_SECTION_RESOURCES,
    [sectionResources, selected?.id]
  );
  const outlineResources = useMemo(
    () => filterOutlineMaterialResources(moduleFlowResources),
    [moduleFlowResources]
  );
  const nextResourceOrderIndex = useMemo(() => {
    if (moduleFlowResources.length === 0) return 0;
    return Math.max(...moduleFlowResources.map((r) => r.order_index ?? 0)) + 1;
  }, [moduleFlowResources]);
  const structureLabel =
    structureType === 'weeks' ? 'Week' : structureType === 'units' ? 'Unit' : 'Module';

  const sectionDisplayName = (
    section: SyllabusSection,
    pending: Partial<SyllabusSection>,
    listIndex: number
  ) => {
    const raw = typeof pending.title === 'string' ? pending.title : section.title;
    const trimmed = (raw ?? '').trim();
    if (trimmed) return trimmed;
    return `${structureLabel} ${listIndex + 1}`;
  };

  const getValue = <K extends keyof SyllabusSection>(key: K): SyllabusSection[K] => {
    if (key in editValues) return editValues[key as string] as SyllabusSection[K];
    return selected ? selected[key] : ('' as any);
  };

  const setField = (key: string, value: unknown) => {
    setEditValues((prev) => ({ ...prev, [key]: value }));
  };

  const handleRewrite = async (fieldKey: 'description', currentValue: string) => {
    if (!currentValue.trim() || !selected) return;
    const fieldId = `${selected.id}-${fieldKey}`;
    setRewritingField(fieldId);
    try {
      const { data: result, error } = await supabase.functions.invoke('rephrase-text', {
        body: { text: currentValue, language: i18n.language === 'he' ? 'he' : 'en' },
      });
      if (error) throw error;
      if (result?.rephrasedText) {
        setField(fieldKey, result.rephrasedText);
        toast.success(t('syllabus.sections.rewriteSuccess', 'Text rewritten'));
      }
    } catch {
      toast.error(t('syllabus.sections.rewriteFailed', 'Failed to rewrite'));
    } finally {
      setRewritingField(null);
    }
  };

  const addSection = () => {
    createMutation.mutate(
      {
        input: {
          syllabus_id: syllabusId,
          title: `${structureLabel} ${sections.length + 1}`,
          description: null,
          content: null,
          order_index: sections.length,
          start_date: null,
          end_date: null,
          objectives: null,
          resources: null,
          notes: null,
          completion_status: 'auto',
          prerequisites: [],
          is_locked: false,
        },
        classroomId,
      },
      {
        onSuccess: () => setSelectedIndex(sections.length),
        onError: () => toast.error(t('syllabus.sections.addFailed')),
      }
    );
  };

  const handleSave = () => {
    if (!selected || Object.keys(editValues).length === 0) return;
    setSaving(true);
    const updates = { ...editValues, notes: null as null, resources: null as null };
    updateMutation.mutate(
      {
        sectionId: selected.id,
        updates,
        classroomId,
      },
      {
        onSuccess: () => {
          setEditValues({});
          toast.success(
            t('syllabus.sections.saved', {
              name: sectionDisplayName(selected, editValues, clampedIndex),
            })
          );
        },
        onError: () => toast.error(t('syllabus.sections.saveFailed')),
        onSettled: () => setSaving(false),
      }
    );
  };

  const handleSectionClick = (index: number) => {
    if (Object.keys(editValues).length > 0 && selected) {
      const updates = { ...editValues, notes: null as null, resources: null as null };
      updateMutation.mutate(
        {
          sectionId: selected.id,
          updates,
          classroomId,
        },
        {
          onSuccess: () =>
            toast.success(
              t('syllabus.sections.saved', {
                name: sectionDisplayName(selected, editValues, selectedIndex),
              })
            ),
          onError: () => toast.error(t('syllabus.sections.saveFailed')),
        }
      );
    }
    setSelectedIndex(index);
    setEditValues({});
  };

  const handleDelete = () => {
    if (!sectionToDelete) return;
    const id = sectionToDelete.id;
    setDeleteConfirmOpen(false);
    setSectionToDelete(null);
    setSelectedIndex(Math.max(0, selectedIndex - 1));
    setEditValues({});

    deleteMutation.mutate(
      { sectionId: id, classroomId },
      {
        onSuccess: () => toast.success(t('syllabus.sections.deleted')),
        onError: () => toast.error(t('syllabus.sections.deleteFailed')),
      }
    );
  };

  const handleSectionDragStart = (event: DragStartEvent) => {
    setActiveDragId(String(event.active.id));
  };

  const handleSectionDragEnd = (event: DragEndEvent) => {
    setActiveDragId(null);
    const { active, over } = event;
    if (!over || active.id === over.id) return;
    const oldIndex = sections.findIndex((s) => s.id === String(active.id));
    const newIndex = sections.findIndex((s) => s.id === String(over.id));
    if (oldIndex < 0 || newIndex < 0) return;
    const ordered = arrayMove(sections, oldIndex, newIndex);
    const orderedIds = ordered.map((s) => s.id);
    const selectedId = selected?.id;
    if (selectedId) {
      const nextIdx = orderedIds.indexOf(selectedId);
      if (nextIdx >= 0) setSelectedIndex(nextIdx);
    }
    reorderMutation.mutate(
      { syllabusId, orderedIds, classroomId },
      { onError: () => toast.error(t('syllabus.sections.reorderFailed')) }
    );
  };

  const handleSectionDragCancel = () => {
    setActiveDragId(null);
  };

  const handleBulkSchedule = async () => {
    if (!bulkStartDate || sections.length === 0) return;
    setSaving(true);
    try {
      const start = new Date(bulkStartDate);
      for (let i = 0; i < sections.length; i++) {
        const sectionStart = new Date(start);
        sectionStart.setDate(sectionStart.getDate() + i * bulkDuration);
        const sectionEnd = new Date(sectionStart);
        sectionEnd.setDate(sectionEnd.getDate() + bulkDuration - 1);

        await updateMutation.mutateAsync({
          sectionId: sections[i].id,
          updates: {
            start_date: sectionStart.toISOString().split('T')[0],
            end_date: sectionEnd.toISOString().split('T')[0],
          },
          classroomId,
        });
      }
      toast.success(t('syllabus.sections.bulkScheduled'));
      setShowBulkSchedule(false);
      setEditValues({});
    } catch {
      toast.error(t('syllabus.sections.bulkScheduleFailed'));
    } finally {
      setSaving(false);
    }
  };

  const objectives = (getValue('objectives') as string[] | null) || [];

  return (
    <div className="flex gap-6 min-h-[400px]">
      {/* Sidebar */}
      <div className={cn('w-64 min-h-0 flex-shrink-0 flex flex-col', isRTL && 'order-2')}>
        <div
          className={`flex items-center justify-between mb-3 ${isRTL ? 'flex-row-reverse' : ''}`}
        >
          <h4 className="font-bold text-sm text-foreground">{t('syllabus.sections.title')}</h4>
          <div className="flex items-center gap-1">
            {sections.length > 0 && (
              <Button
                type="button"
                variant="ghost"
                size="sm"
                onClick={() => setShowBulkSchedule(!showBulkSchedule)}
                className="rounded-full gap-1 h-7 text-xs text-muted-foreground"
              >
                <CalendarRange className="h-3 w-3" />
              </Button>
            )}
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={addSection}
              disabled={createMutation.isPending}
              className="rounded-full gap-1 h-7 text-xs"
            >
              <Plus className="h-3 w-3" /> {t('syllabus.sections.add')}
            </Button>
          </div>
        </div>
        {showBulkSchedule && (
          <div className="mb-3 p-3 rounded-xl border border-border bg-card space-y-2 animate-in fade-in slide-in-from-top-1 duration-150">
            <p className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider">
              {t('syllabus.sections.autoSchedule')}
            </p>
            <div className="space-y-1.5">
              <DatePicker
                value={bulkStartDate}
                onChange={setBulkStartDate}
                placeholder={t('syllabus.sections.startDate')}
                className="rounded-lg h-7 text-xs"
              />
              <div className="flex items-center gap-2">
                <Input
                  type="number"
                  min={1}
                  max={30}
                  value={bulkDuration}
                  onChange={(e) => setBulkDuration(parseInt(e.target.value) || 7)}
                  className="rounded-lg h-7 text-xs w-16"
                />
                <span className="text-[10px] text-muted-foreground">
                  {t('syllabus.sections.daysPerSection')}
                </span>
              </div>
            </div>
            <div className="flex justify-end gap-1">
              <Button
                type="button"
                variant="ghost"
                size="sm"
                onClick={() => setShowBulkSchedule(false)}
                className="h-6 text-xs"
              >
                {t('common.cancel')}
              </Button>
              <Button
                type="button"
                size="sm"
                onClick={handleBulkSchedule}
                disabled={saving || !bulkStartDate}
                className="h-6 text-xs gap-1"
              >
                {saving && <Loader2 className="h-3 w-3 animate-spin" />}
                {t('syllabus.sections.apply')}
              </Button>
            </div>
          </div>
        )}
        <ScrollArea className="w-full min-w-0 self-start max-h-[min(32rem,70dvh)]">
          {sections.length === 0 ? (
            <div className="p-4 border-2 border-dashed border-border rounded-xl bg-muted/10 text-center">
              <p className="text-xs text-muted-foreground">{t('syllabus.sections.noSections')}</p>
            </div>
          ) : (
            <DndContext
              sensors={sensors}
              collisionDetection={closestCenter}
              autoScroll={boundedPointerAutoScroll}
              modifiers={[restrictToVerticalAxis, restrictToFirstScrollableAncestor]}
              onDragStart={handleSectionDragStart}
              onDragEnd={handleSectionDragEnd}
              onDragCancel={handleSectionDragCancel}
            >
              <SortableContext items={sortableSectionIds} strategy={verticalListSortingStrategy}>
                <ul className="min-w-0 space-y-1 [contain:layout]">
                  {sections.map((section, index) => (
                    <SortableSectionRow key={section.id} id={section.id}>
                      {({ dragAttributes, dragListeners }) => (
                        <div
                          role="button"
                          tabIndex={0}
                          onClick={() => handleSectionClick(index)}
                          onKeyDown={(e) => {
                            if (e.key === 'Enter' || e.key === ' ') handleSectionClick(index);
                          }}
                          className={cn(
                            'w-full flex items-center gap-2 px-2.5 py-2 rounded-lg text-left transition-all text-sm cursor-pointer',
                            selectedIndex === index
                              ? 'bg-primary/10 border border-primary/30 text-primary'
                              : 'hover:bg-muted/50 border border-transparent text-foreground',
                            isRTL && 'text-right flex-row-reverse'
                          )}
                        >
                          <button
                            type="button"
                            className="touch-none cursor-grab active:cursor-grabbing text-muted-foreground hover:text-foreground p-1 rounded-md shrink-0"
                            aria-label={t('classroomDetail.activitiesFlow.dragReorder')}
                            onPointerDown={(e) => e.stopPropagation()}
                            onClick={(e) => e.stopPropagation()}
                            {...dragListeners}
                            {...dragAttributes}
                          >
                            <GripVertical className="h-4 w-4" />
                          </button>
                          {releaseMode === 'manual' && section.is_locked && (
                            <Lock className="h-3 w-3 text-destructive flex-shrink-0" />
                          )}
                          <span className="flex-1 min-w-0 truncate font-medium">
                            {section.title}
                          </span>
                        </div>
                      )}
                    </SortableSectionRow>
                  ))}
                </ul>
              </SortableContext>
              <div
                aria-hidden
                className="pointer-events-none mt-2 min-h-[3.5rem] w-full shrink-0"
              />
              <DragOverlay dropAnimation={null}>
                {activeDragSection ? (
                  <div
                    className={cn(
                      'flex w-64 min-w-0 max-w-64 items-center gap-2 rounded-lg border border-border bg-card px-2.5 py-2 text-sm text-foreground shadow-lg',
                      isRTL && 'flex-row-reverse'
                    )}
                  >
                    <GripVertical className="h-4 w-4 shrink-0 text-muted-foreground" />
                    {releaseMode === 'manual' && activeDragSection.is_locked && (
                      <Lock className="h-3 w-3 shrink-0 text-destructive" />
                    )}
                    <span className="min-w-0 flex-1 truncate font-medium">
                      {activeDragSection.title}
                    </span>
                  </div>
                ) : null}
              </DragOverlay>
            </DndContext>
          )}
        </ScrollArea>
      </div>

      {/* Editor Panel */}
      <div className={cn('flex-1 min-w-0', isRTL && 'order-1')}>
        {selected ? (
          <div className="space-y-5">
            <div
              className={`flex items-center justify-between gap-3 flex-wrap ${isRTL ? 'flex-row-reverse' : ''}`}
            >
              <h4 className="font-bold text-foreground min-w-0 flex-1 truncate">
                {selected.title}
              </h4>
              <div
                className={`flex flex-wrap items-center gap-1.5 shrink-0 ${isRTL ? 'flex-row-reverse' : ''}`}
              >
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={handleSave}
                  disabled={saving || Object.keys(editValues).length === 0}
                  className="rounded-full gap-1.5 h-8"
                >
                  {saving ? (
                    <Loader2 className="h-3.5 w-3.5 animate-spin" />
                  ) : (
                    <Save className="h-3.5 w-3.5" />
                  )}
                  {t('syllabus.sections.save')}
                </Button>
                {releaseMode === 'manual' && (
                  <Button
                    type="button"
                    variant={getValue('is_locked') ? 'secondary' : 'outline'}
                    size="sm"
                    className={cn(
                      'rounded-full gap-1.5 h-8',
                      getValue('is_locked') &&
                        'border-destructive/40 text-destructive hover:bg-destructive/10'
                    )}
                    onClick={() => setField('is_locked', !getValue('is_locked'))}
                  >
                    {getValue('is_locked') ? (
                      <>
                        <Unlock className="h-3.5 w-3.5" />
                        {t('syllabus.sections.unlockSection', 'Unlock')}
                      </>
                    ) : (
                      <>
                        <Lock className="h-3.5 w-3.5" />
                        {t('syllabus.sections.lockSection', 'Lock')}
                      </>
                    )}
                  </Button>
                )}
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  onClick={() => {
                    setSectionToDelete(selected);
                    setDeleteConfirmOpen(true);
                  }}
                  disabled={deleteMutation.isPending}
                  className="rounded-full text-muted-foreground hover:text-destructive h-8 gap-1"
                >
                  <Trash2 className="h-3.5 w-3.5" /> {t('syllabus.sections.delete')}
                </Button>
              </div>
            </div>

            <div className="space-y-4 p-4 rounded-xl border border-border bg-card">
              <div className="space-y-1.5">
                <Label className="text-xs font-medium flex items-center gap-1">
                  <BookOpen className="h-3 w-3 text-muted-foreground" />{' '}
                  {t('syllabus.sections.sectionTitle')}
                </Label>
                <Input
                  value={getValue('title') as string}
                  onChange={(e) => setField('title', e.target.value)}
                  className="rounded-lg h-9"
                  autoDirection
                />
              </div>

              <div className="space-y-1.5">
                <Label className="text-xs font-medium flex items-center gap-1">
                  <FileText className="h-3 w-3 text-muted-foreground" />{' '}
                  {t('syllabus.sections.description')}
                </Label>
                <ExpandableTextarea
                  value={(getValue('description') as string) || ''}
                  onChange={(v) => setField('description', v)}
                  rows={3}
                  className="bg-card"
                  autoDirection
                  onRewrite={() =>
                    handleRewrite('description', (getValue('description') as string) || '')
                  }
                  isRewriting={rewritingField === `${selected.id}-description`}
                />
              </div>

              <div className="space-y-1.5">
                <Label className="text-xs font-medium flex items-center gap-1">
                  <Pencil className="h-3 w-3 text-muted-foreground" />{' '}
                  {t('syllabus.sections.content', 'Content')}
                </Label>
                <RichTextEditor
                  content={(getValue('content') as string) || ''}
                  onChange={(html) => setField('content', html)}
                  placeholder={t(
                    'syllabus.sections.contentPlaceholder',
                    'Add lesson content, instructions, materials...'
                  )}
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <Label className="text-xs font-medium flex items-center gap-1">
                    <Calendar className="h-3 w-3 text-muted-foreground" />{' '}
                    {t('syllabus.sections.startDate')}
                  </Label>
                  <DatePicker
                    value={(getValue('start_date') as string) || ''}
                    onChange={(v) => setField('start_date', v || null)}
                    placeholder={t('syllabus.sections.startDate')}
                    className="rounded-lg h-8"
                  />
                </div>
                <div className="space-y-1.5">
                  <Label className="text-xs font-medium flex items-center gap-1">
                    <Calendar className="h-3 w-3 text-muted-foreground" />{' '}
                    {t('syllabus.sections.endDate')}
                  </Label>
                  <DatePicker
                    value={(getValue('end_date') as string) || ''}
                    onChange={(v) => setField('end_date', v || null)}
                    placeholder={t('syllabus.sections.endDate')}
                    className="rounded-lg h-8"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <Label className="text-xs font-medium flex items-center gap-1">
                    <Target className="h-3 w-3 text-muted-foreground" />{' '}
                    {t('syllabus.sections.objectives')}
                  </Label>
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    onClick={() => setField('objectives', [...objectives, ''])}
                    className="h-6 text-xs text-primary"
                  >
                    <Plus className="h-3 w-3 me-0.5" /> {t('syllabus.sections.add')}
                  </Button>
                </div>
                {objectives.map((obj, i) => (
                  <div key={i} className="flex items-center gap-1.5">
                    <div className="h-1 w-1 rounded-full bg-primary/30" />
                    <Input
                      value={obj}
                      onChange={(e) => {
                        const o = [...objectives];
                        o[i] = e.target.value;
                        setField('objectives', o);
                      }}
                      className="flex-1 rounded-lg h-7 text-xs"
                      autoDirection
                    />
                    <button
                      type="button"
                      onClick={() =>
                        setField(
                          'objectives',
                          objectives.filter((_, idx) => idx !== i)
                        )
                      }
                      className="text-muted-foreground hover:text-destructive p-0.5"
                    >
                      <Trash2 className="h-3 w-3" />
                    </button>
                  </div>
                ))}
              </div>
            </div>

            <Separator className="my-2" />
            <div className="space-y-3">
              <ResourceUploader
                key={selected.id}
                sectionId={selected.id}
                classroomId={classroomId}
                resources={outlineResources}
                isRTL={isRTL}
                nextOrderIndex={nextResourceOrderIndex}
              />
            </div>
            <div className="space-y-3">
              <ModuleFlowEditor
                key={selected.id}
                ref={flowEditorRef}
                flowHeading={t('syllabus.sections.moduleFlow')}
                sectionId={selected.id}
                classroomId={classroomId}
                resources={moduleFlowResources}
                assignments={
                  allAssignments as {
                    id: string;
                    title: string;
                    syllabus_section_id?: string | null;
                    due_at?: string | null;
                  }[]
                }
                isRTL={isRTL}
                onRequestNewActivity={() => {
                  if (!selected) return;
                  lessonCreatedFromSectionFlowRef.current = true;
                  setLessonSectionId(selected.id);
                  setEditingLesson(null);
                }}
                onViewAssignment={onEditAssignment}
                onEditAssignment={onEditAssignment}
                onEditResource={(resourceId) => {
                  if (!selected) return;
                  const r = moduleFlowResources.find((x) => x.id === resourceId);
                  if (r) {
                    setLessonSectionId(selected.id);
                    setEditingLesson(r);
                  }
                }}
              />
            </div>
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center h-full text-center py-16">
            <BookOpen className="h-10 w-10 text-muted-foreground mb-3" />
            <p className="text-muted-foreground text-sm">{t('syllabus.sections.selectOrAdd')}</p>
          </div>
        )}
      </div>

      <ModuleLessonActivityDialog
        classroomId={classroomId}
        isRTL={isRTL}
        open={lessonSectionId !== null}
        onOpenChange={(o) => {
          if (!o) {
            setLessonSectionId(null);
            setEditingLesson(null);
          }
        }}
        sectionId={lessonSectionId}
        editingLesson={editingLesson}
        sectionResourcesBySection={sectionResources}
        onLessonCreated={async (resourceId) => {
          if (
            lessonCreatedFromSectionFlowRef.current &&
            selected &&
            lessonSectionId === selected.id
          ) {
            await flowEditorRef.current?.appendStep('resource', resourceId);
            lessonCreatedFromSectionFlowRef.current = false;
          }
        }}
      />

      <AlertDialog
        open={deleteConfirmOpen}
        onOpenChange={(open) => {
          setDeleteConfirmOpen(open);
          if (!open) setSectionToDelete(null);
        }}
      >
        <AlertDialogContent className="rounded-xl">
          <AlertDialogHeader>
            <AlertDialogTitle>{t('syllabus.sections.deleteConfirmTitle')}</AlertDialogTitle>
            <AlertDialogDescription>
              {t('syllabus.sections.deleteConfirmDesc', { name: sectionToDelete?.title })}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>{t('syllabus.cancel')}</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {t('syllabus.sections.delete')}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
};

import { FileDown } from 'lucide-react';
import { useRef, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import type { SyllabusWithSections } from '@/types/syllabus';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';

interface SyllabusPDFExportProps {
  syllabus: SyllabusWithSections;
  isRTL?: boolean;
}

export const SyllabusPDFExport = ({ syllabus, isRTL = false }: SyllabusPDFExportProps) => {
  const { t } = useTranslation();
  const printRef = useRef<HTMLDivElement>(null);

  const handlePrint = useCallback(() => {
    const printContent = printRef.current;
    if (!printContent) return;

    const printWindow = window.open('', '_blank');
    if (!printWindow) return;

    const structureLabel =
      syllabus.section_label_override ||
      (syllabus.structure_type === 'weeks'
        ? 'Week'
        : syllabus.structure_type === 'units'
          ? 'Unit'
          : 'Module');

    const accentColor = syllabus.accent_color || '#6366f1';

    const html = `
      <!DOCTYPE html>
      <html dir="${isRTL ? 'rtl' : 'ltr'}">
      <head>
        <meta charset="utf-8">
        <title>${syllabus.title} - Syllabus</title>
        <style>
          * { margin: 0; padding: 0; box-sizing: border-box; }
          body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
            color: #1a1a1a;
            line-height: 1.6;
            padding: 40px;
            max-width: 800px;
            margin: 0 auto;
          }
          h1 { font-size: 28px; margin-bottom: 8px; color: ${accentColor}; }
          h2 { font-size: 18px; margin: 24px 0 12px; color: ${accentColor}; border-bottom: 2px solid ${accentColor}20; padding-bottom: 6px; }
          h3 { font-size: 15px; margin: 16px 0 8px; color: #333; }
          .summary { color: #666; font-size: 14px; margin-bottom: 24px; }
          .meta { display: flex; gap: 20px; margin-bottom: 20px; font-size: 12px; color: #888; flex-wrap: wrap; }
          .meta span { background: #f5f5f5; padding: 4px 10px; border-radius: 6px; }
          .policy-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-bottom: 16px; }
          .policy-card { background: #fafafa; border: 1px solid #eee; border-radius: 8px; padding: 14px; }
          .policy-card h3 { margin: 0 0 6px; font-size: 13px; color: ${accentColor}; }
          .policy-card p { font-size: 12px; color: #555; white-space: pre-wrap; }
          .grading-bar { display: flex; height: 12px; border-radius: 6px; overflow: hidden; margin: 8px 0; }
          .grading-item { display: flex; align-items: center; gap: 6px; font-size: 12px; margin-bottom: 4px; }
          .grading-dot { width: 10px; height: 10px; border-radius: 3px; }
          .section-card {
            border: 1px solid #e5e5e5; border-radius: 10px; padding: 16px; margin-bottom: 12px;
            border-left: 4px solid ${accentColor};
            page-break-inside: avoid;
          }
          .section-header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 8px; }
          .section-title { font-weight: 700; font-size: 14px; }
          .section-dates { font-size: 11px; color: #888; }
          .section-desc { font-size: 12px; color: #555; margin-bottom: 8px; }
          .objectives { list-style: none; padding: 0; }
          .objectives li { font-size: 12px; color: #555; padding: 3px 0 3px 16px; position: relative; }
          .objectives li::before { content: '•'; color: ${accentColor}; position: absolute; left: 0; font-weight: bold; }
          .footer { margin-top: 30px; padding-top: 16px; border-top: 1px solid #eee; text-align: center; font-size: 11px; color: #aaa; }
          @media print {
            body { padding: 20px; }
            .section-card { page-break-inside: avoid; }
          }
        </style>
      </head>
      <body>
        <h1>${syllabus.title}</h1>
        ${syllabus.summary ? `<p class="summary">${syllabus.summary}</p>` : ''}
        <div class="meta">
          <span>${t('syllabus.structureType')}: ${t(`syllabus.${syllabus.structure_type}`)}</span>
          <span>${t('syllabus.settings.status')}: ${syllabus.status}</span>
          ${syllabus.published_at ? `<span>${t('syllabus.publishedAt')}: ${new Date(syllabus.published_at).toLocaleDateString()}</span>` : ''}
        </div>

        ${
          (syllabus.policies ?? []).filter((p) => p.content?.trim()).length > 0
            ? `
          <h2>${t('syllabus.policies.title')}</h2>
          <div class="policy-grid">
            ${(syllabus.policies ?? [])
              .filter((p) => p.content?.trim())
              .map((p) => `<div class="policy-card"><h3>${p.label}</h3><p>${p.content}</p></div>`)
              .join('')}
          </div>
        `
            : ''
        }

        ${
          syllabus.grading_categories.length > 0
            ? `
          <h2>${t('syllabus.grading.breakdown')}</h2>
          <div>
            ${syllabus.grading_categories
              .map((cat, i) => {
                const colors = [
                  '#6366f1',
                  '#22c55e',
                  '#f97316',
                  '#8b5cf6',
                  '#ec4899',
                  '#06b6d4',
                  '#eab308',
                  '#ef4444',
                ];
                return `<div class="grading-item"><div class="grading-dot" style="background:${colors[i % colors.length]}"></div><span>${cat.name}</span><strong>${cat.weight}%</strong></div>`;
              })
              .join('')}
          </div>
        `
            : ''
        }

        <h2>${t('syllabus.tabs.sections')} (${syllabus.sections.length})</h2>
        ${syllabus.sections
          .map((section, i) => {
            const dateRange = [section.start_date, section.end_date].filter(Boolean).join(' → ');
            return `
            <div class="section-card">
              <div class="section-header">
                <span class="section-title">${structureLabel} ${i + 1}: ${section.title}</span>
                ${dateRange ? `<span class="section-dates">${dateRange}</span>` : ''}
              </div>
              ${section.description ? `<p class="section-desc">${section.description}</p>` : ''}
              ${
                section.objectives?.length
                  ? `
                <h3>${t('syllabus.detail.objectives')}</h3>
                <ul class="objectives">
                  ${section.objectives.map((obj) => `<li>${obj}</li>`).join('')}
                </ul>
              `
                  : ''
              }
            </div>
          `;
          })
          .join('')}

        <div class="footer">
          ${t('syllabus.pdfExport.generatedOn')} ${new Date().toLocaleDateString()} | Perleap
        </div>
      </body>
      </html>
    `;

    printWindow.document.write(html);
    printWindow.document.close();
    printWindow.onload = () => {
      printWindow.print();
    };
  }, [syllabus, isRTL, t]);

  return (
    <div ref={printRef}>
      <Button
        variant="outline"
        size="sm"
        onClick={handlePrint}
        className="rounded-full gap-1.5 text-xs"
      >
        <FileDown className="h-3.5 w-3.5" />
        {t('syllabus.pdfExport.button')}
      </Button>
    </div>
  );
};

import {
  ReactFlow,
  type Node,
  type Edge,
  type ReactFlowInstance,
  Background,
  BackgroundVariant,
  useNodesState,
  useEdgesState,
  Controls,
  MiniMap,
} from '@xyflow/react';
import {
  useMemo,
  useCallback,
  useState,
  useEffect,
  useRef,
  useLayoutEffect,
  type MouseEvent,
} from 'react';
import '@xyflow/react/dist/style.css';

import { useTranslation } from 'react-i18next';
import { useTheme } from 'next-themes';
import { RoadmapNode } from './RoadmapNode';
import { SectionDetailModal } from './SectionDetailModal';
import {
  deriveSectionStatus,
  isTodayInDateRange,
  filterRoadmapSections,
  deriveCurrentSectionDisplayIndex,
  roadmapProgressPercent,
  type RoadmapSectionFilter,
} from './syllabusRoadmapUtils';
import type {
  SyllabusSection,
  RoadmapNodeData,
  SectionResource,
  CompletionStatus,
  StudentProgressStatus,
  ReleaseMode,
  SyllabusStructureType,
} from '@/types/syllabus';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Progress } from '@/components/ui/progress';
import { BookOpen, Plus, List } from 'lucide-react';
import { isSectionUnlocked } from '@/lib/sectionUnlock';
import { cn } from '@/lib/utils';

interface SyllabusRoadmapProps {
  sections: SyllabusSection[];
  assignmentCounts?: Record<string, number>;
  sectionResources?: Record<string, SectionResource[]>;
  classroomId: string;
  mode?: 'teacher' | 'student';
  isRTL?: boolean;
  syllabusId?: string;
  releaseMode?: ReleaseMode;
  /** Shown in roadmap caption (e.g. Weeks · All at once) */
  structureType?: SyllabusStructureType;
  studentProgressMap?: Record<string, StudentProgressStatus>;
  linkedAssignmentsMap?: Record<
    string,
    Array<{ id: string; title: string; type: string; due_at: string | null }>
  >;
  onSectionSelect?: (section: SyllabusSection) => void;
  onSwitchToSections?: () => void;
}

const nodeTypes = { syllabusSection: RoadmapNode };

const NODE_SPACING_Y = 188;
const NODE_APPX_HEIGHT = 168;
const EMPTY_OBJECT: Record<string, unknown> = {};

function useMatchMedia(query: string): boolean {
  const [matches, setMatches] = useState(() =>
    typeof window !== 'undefined' ? window.matchMedia(query).matches : false
  );
  useEffect(() => {
    const mq = window.matchMedia(query);
    const handler = () => setMatches(mq.matches);
    mq.addEventListener('change', handler);
    setMatches(mq.matches);
    return () => mq.removeEventListener('change', handler);
  }, [query]);
  return matches;
}

export const SyllabusRoadmap = ({
  sections,
  assignmentCounts = EMPTY_OBJECT as Record<string, number>,
  sectionResources = EMPTY_OBJECT as Record<string, SectionResource[]>,
  classroomId: _classroomId,
  mode = 'teacher',
  isRTL = false,
  syllabusId,
  releaseMode = 'all_at_once',
  structureType,
  studentProgressMap = EMPTY_OBJECT as Record<string, StudentProgressStatus>,
  linkedAssignmentsMap = EMPTY_OBJECT as Record<
    string,
    Array<{ id: string; title: string; type: string; due_at: string | null }>
  >,
  onSectionSelect,
  onSwitchToSections,
}: SyllabusRoadmapProps) => {
  const { t } = useTranslation();
  const { resolvedTheme } = useTheme();
  const [selectedSection, setSelectedSection] = useState<SyllabusSection | null>(null);
  const [modalOpen, setModalOpen] = useState(false);
  const [filter, setFilter] = useState<RoadmapSectionFilter>('all');
  const [activeJumpId, setActiveJumpId] = useState<string | null>(null);
  const [nodeWidth, setNodeWidth] = useState(400);
  const rfInstance = useRef<ReactFlowInstance | null>(null);
  const flowContainerRef = useRef<HTMLDivElement | null>(null);
  const isMdUp = useMatchMedia('(min-width: 768px)');

  const filteredSections = useMemo(
    () =>
      filterRoadmapSections(
        sections,
        filter,
        mode,
        assignmentCounts,
        sectionResources as Record<string, unknown[]>,
        releaseMode,
        studentProgressMap
      ),
    [sections, filter, mode, assignmentCounts, sectionResources, releaseMode, studentProgressMap]
  );

  const statuses = useMemo(
    () => filteredSections.map((s) => deriveSectionStatus(s)),
    [filteredSections]
  );

  const progressPct = useMemo(() => roadmapProgressPercent(statuses), [statuses]);
  const currentIdx = useMemo(() => deriveCurrentSectionDisplayIndex(statuses), [statuses]);

  useEffect(() => {
    const el = flowContainerRef.current;
    if (!el) return;
    const ro = new ResizeObserver((entries) => {
      const w = entries[0]?.contentRect?.width ?? 400;
      const next = Math.max(280, Math.min(560, Math.round(w * 0.92)));
      setNodeWidth(next);
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  const zigzag = isMdUp;

  const initialNodes: Node<RoadmapNodeData>[] = useMemo(() => {
    const gap = Math.max(260, Math.round(nodeWidth * 0.82));
    return filteredSections.map((section, index) => {
      const locked =
        mode === 'student' &&
        !isSectionUnlocked(section, sections, releaseMode, studentProgressMap);
      const x = !zigzag ? 0 : isRTL ? (index % 2 === 0 ? gap : 0) : index % 2 === 0 ? 0 : gap;
      return {
        id: section.id,
        type: 'syllabusSection',
        position: { x, y: index * NODE_SPACING_Y },
        data: {
          title: section.title,
          description: section.description,
          startDate: section.start_date,
          endDate: section.end_date,
          assignmentCount: assignmentCounts[section.id] || 0,
          resourceCount: (sectionResources[section.id] || []).length,
          orderIndex: section.order_index,
          sectionIndex: index + 1,
          nodeWidth,
          enterDelayMs: index * 45,
          status: deriveSectionStatus(section),
          sectionId: section.id,
          completionStatus: (section.completion_status || 'auto') as CompletionStatus,
          studentProgress: studentProgressMap[section.id],
          locked,
          isTodayInRange: isTodayInDateRange(section.start_date, section.end_date),
        },
        draggable: false,
        connectable: false,
      };
    });
  }, [
    filteredSections,
    sections,
    assignmentCounts,
    sectionResources,
    studentProgressMap,
    mode,
    releaseMode,
    nodeWidth,
    zigzag,
    isRTL,
  ]);

  const thenLabel = t('syllabus.roadmap.then');

  const initialEdges: Edge[] = useMemo(() => {
    return filteredSections.slice(1).map((section, index) => ({
      id: `edge-${filteredSections[index].id}-${section.id}`,
      source: filteredSections[index].id,
      target: section.id,
      type: 'smoothstep',
      style: { stroke: 'hsl(var(--primary))', strokeWidth: 3, strokeDasharray: '0' },
      animated: false,
      label: thenLabel,
      labelStyle: { fill: 'hsl(var(--muted-foreground))', fontSize: 11, fontWeight: 500 },
      labelBgPadding: [4, 2] as [number, number],
      labelBgBorderRadius: 6,
      labelBgStyle: { fill: 'hsl(var(--card))', fillOpacity: 0.95 },
    }));
  }, [filteredSections, thenLabel]);

  const [nodes, setNodes, onNodesChange] = useNodesState<Node<RoadmapNodeData>>(initialNodes);
  const [edges, setEdges, onEdgesChange] = useEdgesState(initialEdges);

  useEffect(() => {
    setNodes(initialNodes);
  }, [initialNodes, setNodes]);
  useEffect(() => {
    setEdges(initialEdges);
  }, [initialEdges, setEdges]);

  const refit = useCallback(() => {
    const inst = rfInstance.current;
    if (!inst || filteredSections.length === 0) return;
    requestAnimationFrame(() => {
      inst.fitView({
        padding: 0.18,
        maxZoom: 1.15,
        minZoom: 0.45,
        duration: 200,
        includeHiddenNodes: false,
      });
    });
  }, [filteredSections.length]);

  useLayoutEffect(() => {
    refit();
  }, [refit, nodeWidth, zigzag, filter, filteredSections.length]);

  const handleNodeClick = useCallback(
    (_event: MouseEvent, node: Node<RoadmapNodeData>) => {
      const section = sections.find((s) => s.id === node.id);
      if (!section) return;
      const locked =
        mode === 'student' &&
        !isSectionUnlocked(section, sections, releaseMode, studentProgressMap);
      if (locked) return;
      setActiveJumpId(node.id);
      setSelectedSection(section);
      setModalOpen(true);
      onSectionSelect?.(section);
    },
    [sections, onSectionSelect, mode, releaseMode, studentProgressMap]
  );

  const focusSection = useCallback(
    (sectionId: string) => {
      const inst = rfInstance.current;
      if (!inst) return;
      const n = inst.getNode(sectionId);
      if (!n) return;
      setActiveJumpId(sectionId);
      const x = n.position.x + nodeWidth / 2;
      const y = n.position.y + NODE_APPX_HEIGHT / 2;
      inst.setCenter(x, y, { zoom: 1, duration: 250 });
    },
    [nodeWidth]
  );

  if (sections.length === 0) {
    return (
      <Card className="rounded-xl border-dashed border-2 border-border bg-muted/10">
        <CardContent className="flex flex-col items-center justify-center py-16 text-center">
          <div className="w-14 h-14 bg-card rounded-full flex items-center justify-center shadow-sm mb-4">
            <BookOpen className="h-7 w-7 text-muted-foreground" />
          </div>
          <h3 className="text-lg font-bold text-foreground mb-2">
            {t('syllabus.roadmap.noSections')}
          </h3>
          <p className="text-muted-foreground text-sm max-w-md mb-5">
            {t('syllabus.roadmap.noSectionsDesc')}
          </p>
          {mode === 'teacher' && onSwitchToSections && (
            <Button onClick={onSwitchToSections} variant="outline" className="rounded-full gap-2">
              <Plus className="h-4 w-4" /> {t('syllabus.roadmap.addSections')}
            </Button>
          )}
        </CardContent>
      </Card>
    );
  }

  const selectedStatus = selectedSection ? deriveSectionStatus(selectedSection) : 'upcoming';

  const caption =
    structureType != null
      ? `${t(`syllabus.${structureType}`)} · ${t(`syllabus.releaseMode.${releaseMode}`, releaseMode)}`
      : t(`syllabus.releaseMode.${releaseMode}`, releaseMode);

  const showTeacherTips = mode === 'teacher' && sections.length >= 1 && sections.length <= 3;

  const filterButtons: { key: RoadmapSectionFilter; show: boolean }[] = [
    { key: 'all', show: true },
    { key: 'assignments', show: true },
    { key: 'resources', show: mode === 'teacher' },
    { key: 'locked', show: mode === 'student' },
  ];

  const legendItems: { key: string; labelKey: string; dotClass: string }[] = [
    { key: 'upcoming', labelKey: 'syllabus.roadmap.upcoming', dotClass: 'bg-muted-foreground/40' },
    { key: 'in_progress', labelKey: 'syllabus.roadmap.inProgress', dotClass: 'bg-primary' },
    { key: 'completed', labelKey: 'syllabus.roadmap.completed', dotClass: 'bg-green-500' },
    { key: 'skipped', labelKey: 'syllabus.roadmap.skipped', dotClass: 'bg-orange-400' },
  ];
  if (mode === 'student') {
    legendItems.push({
      key: 'locked',
      labelKey: 'syllabus.sections.locked',
      dotClass: 'bg-muted-foreground/50',
    });
  }

  return (
    <div className="relative space-y-4">
      {showTeacherTips && (
        <Card className="rounded-xl border-primary/20 bg-primary/[0.04]">
          <CardContent className={`p-4 text-sm ${isRTL ? 'text-right' : 'text-left'}`}>
            <p className="font-semibold text-foreground mb-2">
              {t('syllabus.roadmap.teacherTipsTitle')}
            </p>
            <ul className="list-disc list-inside text-muted-foreground space-y-1 mb-3">
              <li>{t('syllabus.roadmap.teacherTipDates')}</li>
              <li>{t('syllabus.roadmap.teacherTipAssignments')}</li>
              <li>{t('syllabus.roadmap.teacherTipPublish')}</li>
            </ul>
            {onSwitchToSections && (
              <Button
                variant="outline"
                size="sm"
                className="rounded-full"
                onClick={onSwitchToSections}
              >
                {t('syllabus.roadmap.goToSections')}
              </Button>
            )}
          </CardContent>
        </Card>
      )}

      <div className={`space-y-3 ${isRTL ? 'text-right' : 'text-left'}`}>
        <p className="text-sm text-muted-foreground">{caption}</p>
        <div className={`flex flex-wrap items-center gap-2 ${isRTL ? 'justify-end' : ''}`}>
          {legendItems.map((item) => (
            <span
              key={item.key}
              className="inline-flex items-center gap-1.5 text-xs text-muted-foreground"
            >
              <span className={cn('size-2 rounded-full shrink-0', item.dotClass)} />
              {t(item.labelKey)}
            </span>
          ))}
        </div>
        <div className="flex flex-col sm:flex-row sm:items-end gap-3 sm:justify-between">
          <div className="space-y-1 flex-1 min-w-0">
            <p className="text-sm font-medium text-foreground">
              {t('syllabus.roadmap.progressLine', {
                current: currentIdx,
                total: filteredSections.length || sections.length,
              })}
            </p>
            <Progress value={progressPct} className="max-w-md w-full h-2" />
          </div>
          <div className={cn('flex flex-wrap gap-1.5', isRTL && 'sm:flex-row-reverse')}>
            {filterButtons
              .filter((b) => b.show)
              .map(({ key }) => (
                <Button
                  key={key}
                  type="button"
                  size="sm"
                  variant={filter === key ? 'default' : 'outline'}
                  className="rounded-full h-8 text-xs"
                  onClick={() => setFilter(key)}
                >
                  {t(`syllabus.roadmap.filter.${key}`)}
                </Button>
              ))}
          </div>
        </div>
      </div>

      {filteredSections.length === 0 ? (
        <Card className="rounded-xl border-dashed border-border bg-muted/10">
          <CardContent className={`p-6 text-sm ${isRTL ? 'text-right' : 'text-left'}`}>
            <p className="text-muted-foreground mb-3">{t('syllabus.roadmap.filterEmpty')}</p>
            <Button
              type="button"
              size="sm"
              variant="outline"
              className="rounded-full"
              onClick={() => setFilter('all')}
            >
              {t('syllabus.roadmap.filterReset')}
            </Button>
          </CardContent>
        </Card>
      ) : (
        <div className="grid gap-4 md:grid-cols-[minmax(0,220px)_1fr]">
          <div className="hidden md:block rounded-xl border border-border bg-card/50 p-3 max-h-[min(70vh,820px)] overflow-y-auto">
            <div
              className={`flex items-center gap-2 text-xs font-bold text-muted-foreground uppercase tracking-wide mb-2 ${isRTL ? 'flex-row-reverse' : ''}`}
            >
              <List className="h-3.5 w-3.5" />
              {t('syllabus.roadmap.jumpListTitle')}
            </div>
            <ul className="space-y-1">
              {filteredSections.map((s) => (
                <li key={s.id}>
                  <button
                    type="button"
                    onClick={() => focusSection(s.id)}
                    className={cn(
                      'w-full rounded-lg px-2 py-2 text-sm transition-colors hover:bg-muted/80',
                      isRTL ? 'text-end' : 'text-start',
                      activeJumpId === s.id && 'bg-primary/10 text-primary font-medium'
                    )}
                  >
                    <span className="line-clamp-2">
                      {s.title || t('syllabus.sections.sectionTitle')}
                    </span>
                  </button>
                </li>
              ))}
            </ul>
          </div>

          <div
            ref={flowContainerRef}
            className="w-full min-h-[560px] h-[min(70vh,820px)] rounded-xl border border-border bg-muted/10 overflow-hidden"
          >
            <ReactFlow
              colorMode={resolvedTheme === 'dark' ? 'dark' : 'light'}
              nodes={nodes}
              edges={edges}
              onNodesChange={onNodesChange}
              onEdgesChange={onEdgesChange}
              nodeTypes={nodeTypes}
              onNodeClick={handleNodeClick}
              onInit={(instance) => {
                rfInstance.current = instance;
                requestAnimationFrame(() => refit());
              }}
              nodesDraggable={false}
              nodesConnectable={false}
              elementsSelectable
              panOnScroll
              zoomOnScroll={false}
              minZoom={0.45}
              maxZoom={1.35}
              proOptions={{ hideAttribution: true }}
            >
              <Background
                variant={BackgroundVariant.Dots}
                gap={20}
                size={1}
                color="hsl(var(--border))"
              />
              <Controls showInteractive={false} className="!bg-card !border-border !shadow-sm" />
              <MiniMap
                nodeStrokeWidth={2}
                zoomable
                pannable
                className="!bg-card/95 !border-border"
                maskColor="hsl(var(--background) / 0.65)"
                nodeColor={(n) => {
                  const st = (n.data as RoadmapNodeData | undefined)?.status;
                  if (st === 'completed') return 'hsl(142 76% 36%)';
                  if (st === 'in_progress') return 'hsl(var(--primary))';
                  if (st === 'skipped') return 'hsl(27 96% 61%)';
                  return 'hsl(var(--muted-foreground))';
                }}
              />
            </ReactFlow>
          </div>
        </div>
      )}

      <SectionDetailModal
        section={selectedSection}
        open={modalOpen}
        onOpenChange={setModalOpen}
        assignmentCount={selectedSection ? assignmentCounts[selectedSection.id] || 0 : 0}
        resources={selectedSection ? sectionResources[selectedSection.id] || [] : []}
        sectionStatus={selectedStatus}
        mode={mode}
        isRTL={isRTL}
        syllabusId={syllabusId}
        studentProgress={selectedSection ? studentProgressMap[selectedSection.id] : undefined}
        linkedAssignments={selectedSection ? linkedAssignmentsMap[selectedSection.id] || [] : []}
      />
    </div>
  );
};

import { useEffect, useId, useMemo, useRef, type IframeHTMLAttributes } from 'react';
import { ContentBlockShell } from './ContentBlockShell';
import { lessonActivityColumnClass } from './readingLayout';
import type { LessonVideoSource } from '@/types/syllabus';
import type { VideoWatchTrackingContext } from '@/types/videoWatch';
import { AspectRatio } from '@/components/ui/aspect-ratio';
import { useVideoWatchTracking } from '@/hooks/useVideoWatchTracking';
import { cn } from '@/lib/utils';
import { parseYoutubeUrl, youtubeEmbedUrl } from '@/lib/youtube';
import { loadYoutubeIframeApi } from '@/lib/youtubeIframeApi';

export type ContentVideoPresentation = 'reading' | 'embedded' | 'compact';

export const ContentVideoBlock = ({
  videoUrl,
  source,
  presentation,
  className,
  tracking,
}: {
  videoUrl: string;
  source?: LessonVideoSource;
  presentation: ContentVideoPresentation;
  className?: string;
  tracking?: VideoWatchTrackingContext;
}) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const youtubeContainerRef = useRef<HTMLDivElement>(null);
  const reactId = useId();
  const youtubeContainerId = useMemo(
    () =>
      `yt-${tracking?.resourceId ?? 'video'}-${tracking?.lessonBlockId ?? 'main'}-${reactId.replace(/:/g, '')}`,
    [reactId, tracking?.lessonBlockId, tracking?.resourceId]
  );

  const parsedYoutube =
    source === 'youtube' || (source !== 'upload' && parseYoutubeUrl(videoUrl))
      ? parseYoutubeUrl(videoUrl)
      : null;

  const {
    handlePlay,
    handlePause,
    handleTimeUpdate,
    handleSeeked,
    handleEnded,
    handleLoadedMetadata,
    flush,
  } = useVideoWatchTracking(tracking);

  useEffect(() => {
    if (!parsedYoutube || !tracking || !youtubeContainerRef.current) return;

    let player: YT.Player | null = null;
    let pollId: number | null = null;
    let cancelled = false;

    void loadYoutubeIframeApi().then(() => {
      if (cancelled || !youtubeContainerRef.current || !window.YT?.Player) return;

      player = new window.YT.Player(youtubeContainerId, {
        height: '100%',
        width: '100%',
        videoId: parsedYoutube.videoId,
        host: 'https://www.youtube-nocookie.com',
        playerVars: {
          enablejsapi: 1,
          origin: window.location.origin,
        },
        events: {
          onStateChange: (event) => {
            if (event.data === YT.PlayerState.PLAYING) {
              handlePlay();
              const current = player?.getCurrentTime() ?? 0;
              const duration = player?.getDuration() ?? 0;
              handleTimeUpdate(current, duration);
            } else if (event.data === YT.PlayerState.PAUSED) {
              const current = player?.getCurrentTime() ?? 0;
              const duration = player?.getDuration() ?? 0;
              handleTimeUpdate(current, duration);
              handlePause();
            } else if (event.data === YT.PlayerState.ENDED) {
              const duration = player?.getDuration() ?? 0;
              handleTimeUpdate(duration, duration);
              handleEnded();
            }
          },
        },
      });

      pollId = window.setInterval(() => {
        if (!player || player.getPlayerState() !== YT.PlayerState.PLAYING) return;
        const current = player.getCurrentTime();
        const duration = player.getDuration();
        handleTimeUpdate(current, duration);
      }, 1000);
    });

    return () => {
      cancelled = true;
      if (pollId != null) window.clearInterval(pollId);
      player?.destroy();
      void flush();
    };
  }, [
    parsedYoutube?.videoId,
    tracking,
    youtubeContainerId,
    handlePlay,
    handlePause,
    handleTimeUpdate,
    handleEnded,
    flush,
  ]);

  const frame = parsedYoutube ? (
    tracking ? (
      <AspectRatio ratio={16 / 9} className="bg-black/25">
        <div
          ref={youtubeContainerRef}
          id={youtubeContainerId}
          className="absolute inset-0 h-full w-full"
        />
      </AspectRatio>
    ) : (
      <AspectRatio ratio={16 / 9} className="bg-black/25">
        <iframe
          {...({ credentialless: '' } as IframeHTMLAttributes<HTMLIFrameElement>)}
          src={youtubeEmbedUrl(parsedYoutube.videoId)}
          title="YouTube video"
          className="absolute inset-0 h-full w-full"
          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
          allowFullScreen
          referrerPolicy="strict-origin-when-cross-origin"
        />
      </AspectRatio>
    )
  ) : (
    <AspectRatio ratio={16 / 9} className="bg-black/25">
      <video
        ref={videoRef}
        src={videoUrl}
        controls
        className="absolute inset-0 h-full w-full object-contain"
        preload="metadata"
        onPlay={() => handlePlay()}
        onPause={() => {
          const el = videoRef.current;
          if (el) handleTimeUpdate(el.currentTime, el.duration);
          handlePause();
        }}
        onTimeUpdate={() => {
          const el = videoRef.current;
          if (!el) return;
          handleTimeUpdate(el.currentTime, el.duration);
        }}
        onSeeked={() => {
          const el = videoRef.current;
          if (el) handleSeeked(el.currentTime);
        }}
        onEnded={() => handleEnded()}
        onLoadedMetadata={() => {
          const el = videoRef.current;
          if (el) handleLoadedMetadata(el.duration);
        }}
      >
        <track kind="captions" />
      </video>
    </AspectRatio>
  );

  if (presentation === 'compact') {
    return (
      <div
        className={cn('overflow-hidden rounded-lg ring-1 ring-border/45 bg-muted/15', className)}
      >
        {frame}
      </div>
    );
  }

  if (presentation === 'reading') {
    return (
      <div className={cn(lessonActivityColumnClass, className)}>
        <ContentBlockShell variant="reading" className="overflow-hidden p-0">
          {frame}
        </ContentBlockShell>
      </div>
    );
  }

  return (
    <div className={cn('mx-auto w-full max-w-2xl', className)}>
      <ContentBlockShell variant="embedded" className="overflow-hidden p-0">
        {frame}
      </ContentBlockShell>
    </div>
  );
};

