interface OutlineBuilderStepProps {
  data: WizardData;
  onChange: (partial: Partial<WizardData>) => void;
  isRTL: boolean;
}

const createEmptySection = (): WizardSectionData => ({
  tempId: crypto.randomUUID(),
  title: '',
  description: '',
  content: '',
  objectives: [''],
  startDate: '',
  endDate: '',
  completion_status: 'auto',
  is_locked: false,
});

export const OutlineBuilderStep = ({ data, onChange, isRTL }: OutlineBuilderStepProps) => {
  const { t } = useTranslation();
  const { language } = useLanguage();
  const [selectedIndex, setSelectedIndex] = useState<number>(0);
  const [rewritingField, setRewritingField] = useState<string | null>(null);

  const sections = data.sections;
  const selected = sections[selectedIndex] ?? null;

  const structureLabel =
    data.structureType === 'weeks' ? 'Week' : data.structureType === 'units' ? 'Unit' : 'Module';

  const addSection = () => {
    const newSection = createEmptySection();
    newSection.title = `${structureLabel} ${sections.length + 1}`;
    const updated = [...sections, newSection];
    onChange({ sections: updated });
    setSelectedIndex(updated.length - 1);
  };

  const duplicateSection = (index: number) => {
    const src = sections[index];
    const dup: WizardSectionData = {
      ...src,
      tempId: crypto.randomUUID(),
      title: `${src.title} (copy)`,
    };
    const updated = [...sections.slice(0, index + 1), dup, ...sections.slice(index + 1)];
    onChange({ sections: updated });
    setSelectedIndex(index + 1);
  };

  const removeSection = (index: number) => {
    const updated = sections.filter((_, i) => i !== index);
    onChange({ sections: updated });
    setSelectedIndex(Math.min(selectedIndex, Math.max(updated.length - 1, 0)));
  };

  const moveSection = (index: number, direction: -1 | 1) => {
    const target = index + direction;
    if (target < 0 || target >= sections.length) return;
    const updated = [...sections];
    [updated[index], updated[target]] = [updated[target], updated[index]];
    onChange({ sections: updated });
    setSelectedIndex(target);
  };

  const updateSection = (index: number, partial: Partial<WizardSectionData>) => {
    const updated = sections.map((s, i) => (i === index ? { ...s, ...partial } : s));
    onChange({ sections: updated });
  };

  const addObjective = () => {
    if (selected) {
      updateSection(selectedIndex, { objectives: [...selected.objectives, ''] });
    }
  };

  const updateObjective = (objIndex: number, value: string) => {
    if (!selected) return;
    const objs = [...selected.objectives];
    objs[objIndex] = value;
    updateSection(selectedIndex, { objectives: objs });
  };

  const removeObjective = (objIndex: number) => {
    if (!selected) return;
    updateSection(selectedIndex, {
      objectives: selected.objectives.filter((_, i) => i !== objIndex),
    });
  };

  const handleRewrite = useCallback(
    async (fieldKey: 'description', currentValue: string) => {
      if (!currentValue.trim()) return;
      const fieldId = `${selected?.tempId}-${fieldKey}`;
      setRewritingField(fieldId);
      try {
        const { data: result, error } = await supabase.functions.invoke('rephrase-text', {
          body: { text: currentValue, language: language === 'he' ? 'he' : 'en' },
        });
        if (error) throw error;
        if (result?.rephrasedText) {
          updateSection(selectedIndex, { [fieldKey]: result.rephrasedText });
          toast.success(t('syllabus.sections.rewriteSuccess', 'Text rewritten'));
        }
      } catch {
        toast.error(t('syllabus.sections.rewriteFailed', 'Failed to rewrite'));
      } finally {
        setRewritingField(null);
      }
    },
    [selected?.tempId, selectedIndex, language, t]
  );

  return (
    <div className="flex gap-6 min-h-[500px]">
      {/* Left Sidebar — Section List */}
      <div className={cn('w-72 flex-shrink-0 flex flex-col', isRTL && 'order-2')}>
        <div
          className={`flex items-center justify-between mb-4 ${isRTL ? 'flex-row-reverse' : ''}`}
        >
          <h3 className="font-bold text-foreground">{t('syllabus.sections.title')}</h3>
          {sections.length > 0 && (
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={addSection}
              className="rounded-full gap-1"
            >
              <Plus className="h-3.5 w-3.5" /> {t('syllabus.sections.add')}
            </Button>
          )}
        </div>

        <ScrollArea className="flex-1">
          {sections.length === 0 ? (
            <div className="p-6 border-2 border-dashed border-border rounded-xl bg-muted/10 text-center">
              <BookOpen className="h-8 w-8 text-muted-foreground mx-auto mb-2" />
              <p className="text-sm text-muted-foreground">{t('syllabus.sections.noSections')}</p>
            </div>
          ) : (
            <div className="space-y-1.5">
              {sections.map((section, index) => (
                <div
                  key={section.tempId}
                  onClick={() => setSelectedIndex(index)}
                  className={cn(
                    'w-full flex items-center gap-2 px-3 py-2.5 rounded-lg text-left transition-all group cursor-pointer',
                    selectedIndex === index
                      ? 'bg-primary/10 border border-primary/30 text-primary'
                      : 'hover:bg-muted/50 border border-transparent text-foreground',
                    isRTL && 'text-right flex-row-reverse'
                  )}
                >
                  <GripVertical className="h-4 w-4 text-muted-foreground flex-shrink-0 opacity-50" />
                  <div className="flex-1 min-w-0">
                    <span className="text-sm font-medium truncate block">
                      {section.title || `${structureLabel} ${index + 1}`}
                    </span>
                    {section.startDate && (
                      <span className="text-xs text-muted-foreground">{section.startDate}</span>
                    )}
                  </div>
                  <div className="flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        moveSection(index, -1);
                      }}
                      disabled={index === 0}
                      className="p-0.5 hover:text-primary disabled:opacity-30"
                    >
                      <ChevronUp className="h-3.5 w-3.5" />
                    </button>
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        moveSection(index, 1);
                      }}
                      disabled={index === sections.length - 1}
                      className="p-0.5 hover:text-primary disabled:opacity-30"
                    >
                      <ChevronDown className="h-3.5 w-3.5" />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </ScrollArea>
      </div>

      {/* Right Panel — Section Form */}
      <div className={cn('flex-1 min-w-0', isRTL && 'order-1')}>
        {selected ? (
          <div className="space-y-6">
            <div className={`flex items-center justify-between ${isRTL ? 'flex-row-reverse' : ''}`}>
              <h3 className="font-bold text-lg text-foreground">
                {selected.title || `${structureLabel} ${selectedIndex + 1}`}
              </h3>
              <div className={`flex items-center gap-1 ${isRTL ? 'flex-row-reverse' : ''}`}>
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  onClick={() => duplicateSection(selectedIndex)}
                  className="text-muted-foreground hover:text-foreground rounded-full gap-1"
                >
                  <Copy className="h-3.5 w-3.5" /> {t('syllabus.sections.duplicate')}
                </Button>
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  onClick={() => removeSection(selectedIndex)}
                  className="text-muted-foreground hover:text-destructive rounded-full gap-1"
                >
                  <Trash2 className="h-3.5 w-3.5" /> {t('syllabus.sections.delete')}
                </Button>
              </div>
            </div>

            <div className="space-y-5 p-5 rounded-xl border border-border bg-card shadow-sm">
              {/* Title */}
              <div className="space-y-2">
                <Label
                  className={`text-sm font-medium flex items-center gap-1.5 ${isRTL ? 'flex-row-reverse text-right' : ''}`}
                >
                  <BookOpen className="h-3.5 w-3.5 text-muted-foreground" />{' '}
                  {t('syllabus.sections.sectionTitle')}
                </Label>
                <Input
                  value={selected.title}
                  onChange={(e) => updateSection(selectedIndex, { title: e.target.value })}
                  placeholder={`${structureLabel} ${selectedIndex + 1}`}
                  className="rounded-xl h-10"
                  autoDirection
                />
              </div>

              {/* Description */}
              <div className="space-y-2">
                <Label
                  className={`text-sm font-medium flex items-center gap-1.5 ${isRTL ? 'flex-row-reverse text-right' : ''}`}
                >
                  <FileText className="h-3.5 w-3.5 text-muted-foreground" />{' '}
                  {t('syllabus.sections.description')}
                </Label>
                <ExpandableTextarea
                  value={selected.description}
                  onChange={(v) => updateSection(selectedIndex, { description: v })}
                  placeholder={t('syllabus.sections.descriptionPlaceholder')}
                  rows={3}
                  autoDirection
                  onRewrite={() => handleRewrite('description', selected.description)}
                  isRewriting={rewritingField === `${selected.tempId}-description`}
                />
              </div>

              <div className="space-y-2">
                <Label
                  className={`text-sm font-medium flex items-center gap-1.5 ${isRTL ? 'flex-row-reverse text-right' : ''}`}
                >
                  <Pencil className="h-3.5 w-3.5 text-muted-foreground" />{' '}
                  {t('syllabus.sections.content', 'Content')}
                </Label>
                <RichTextEditor
                  content={selected.content || ''}
                  onChange={(html) => updateSection(selectedIndex, { content: html })}
                  placeholder={t(
                    'syllabus.sections.contentPlaceholder',
                    'Add lesson content, instructions, materials...'
                  )}
                />
              </div>

              {/* Dates */}
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label
                    className={`text-sm font-medium flex items-center gap-1.5 ${isRTL ? 'flex-row-reverse text-right' : ''}`}
                  >
                    <Calendar className="h-3.5 w-3.5 text-muted-foreground" />{' '}
                    {t('syllabus.sections.startDate')}
                  </Label>
                  <DatePicker
                    value={selected.startDate}
                    onChange={(v) => updateSection(selectedIndex, { startDate: v })}
                    placeholder={t('syllabus.sections.startDate')}
                    className="rounded-xl h-9"
                  />
                </div>
                <div className="space-y-2">
                  <Label
                    className={`text-sm font-medium flex items-center gap-1.5 ${isRTL ? 'flex-row-reverse text-right' : ''}`}
                  >
                    <Calendar className="h-3.5 w-3.5 text-muted-foreground" />{' '}
                    {t('syllabus.sections.endDate')}
                  </Label>
                  <DatePicker
                    value={selected.endDate}
                    onChange={(v) => updateSection(selectedIndex, { endDate: v })}
                    placeholder={t('syllabus.sections.endDate')}
                    className="rounded-xl h-9"
                  />
                </div>
              </div>

              {/* Objectives */}
              <div className="space-y-3">
                <div
                  className={`flex items-center justify-between ${isRTL ? 'flex-row-reverse' : ''}`}
                >
                  <Label
                    className={`text-sm font-medium flex items-center gap-1.5 ${isRTL ? 'flex-row-reverse text-right' : ''}`}
                  >
                    <Target className="h-3.5 w-3.5 text-muted-foreground" />{' '}
                    {t('syllabus.sections.objectives')}
                  </Label>
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    onClick={addObjective}
                    className="text-primary h-7 text-xs"
                  >
                    <Plus className="h-3 w-3 me-1" /> {t('syllabus.sections.add')}
                  </Button>
                </div>
                <div className="space-y-2">
                  {selected.objectives.map((obj, oi) => (
                    <div key={oi} className="flex items-center gap-2">
                      <div className="h-1.5 w-1.5 rounded-full bg-primary/30 flex-shrink-0" />
                      <Input
                        value={obj}
                        onChange={(e) => updateObjective(oi, e.target.value)}
                        placeholder={`${t('syllabus.sections.objectivePlaceholder')} ${oi + 1}`}
                        className="flex-1 rounded-lg h-8 text-sm"
                        autoDirection
                      />
                      {selected.objectives.length > 1 && (
                        <button
                          type="button"
                          onClick={() => removeObjective(oi)}
                          className="text-muted-foreground hover:text-destructive p-1"
                        >
                          <Trash2 className="h-3 w-3" />
                        </button>
                      )}
                    </div>
                  ))}
                </div>
              </div>

              {data.release_mode === 'manual' && (
                <div
                  className={`flex items-center justify-between gap-3 flex-wrap ${isRTL ? 'flex-row-reverse' : ''}`}
                >
                  <Label className="text-sm font-medium flex items-center gap-1.5">
                    <Lock className="h-3.5 w-3.5 text-muted-foreground" />
                    {t('syllabus.sections.manualLock')}
                  </Label>
                  <Button
                    type="button"
                    variant={selected.is_locked ? 'secondary' : 'outline'}
                    size="sm"
                    className={cn(
                      'rounded-full gap-1.5 h-8',
                      selected.is_locked &&
                        'border-destructive/40 text-destructive hover:bg-destructive/10'
                    )}
                    onClick={() => updateSection(selectedIndex, { is_locked: !selected.is_locked })}
                  >
                    {selected.is_locked ? (
                      <>
                        <Unlock className="h-3.5 w-3.5" />
                        {t('syllabus.sections.unlockSection', 'Unlock')}
                      </>
                    ) : (
                      <>
                        <Lock className="h-3.5 w-3.5" />
                        {t('syllabus.sections.lockSection', 'Lock')}
                      </>
                    )}
                  </Button>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center h-full text-center py-20">
            <div className="w-16 h-16 bg-muted rounded-full flex items-center justify-center mb-4">
              <BookOpen className="h-8 w-8 text-muted-foreground" />
            </div>
            <h3 className="text-lg font-bold text-foreground mb-2">
              {t('syllabus.wizard.buildOutline')}
            </h3>
            <p className="text-muted-foreground text-sm max-w-md mb-6">
              {t('syllabus.wizard.buildOutlineDesc')}
            </p>
            <Button type="button" onClick={addSection} className="rounded-full gap-2">
              <Plus className="h-4 w-4" /> {t('syllabus.wizard.addFirst')} {structureLabel}
            </Button>
          </div>
        )}
      </div>
    </div>
  );
};

import {
  Plus,
  Trash2,
  BookOpen,
  GraduationCap,
  Scale,
  FileWarning,
  MessageCircle,
  Shield,
  Users,
  Award,
  PenLine,
  ChevronDown,
  ChevronUp,
  Check,
} from 'lucide-react';
import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { ReleaseModeSelect } from '../ReleaseModeSelect';
import type { WizardData, WizardGradingCategory } from '../CreateClassroomWizard';
import type { SyllabusPolicyType, SyllabusPolicy } from '@/types/syllabus';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Textarea } from '@/components/ui/textarea';
import { cn } from '@/lib/utils';

interface SyllabusSetupStepProps {
  data: WizardData;
  onChange: (partial: Partial<WizardData>) => void;
  isRTL: boolean;
}

const PRESET_POLICIES: {
  type: SyllabusPolicyType;
  labelKey: string;
  fallbackLabel: string;
  icon: typeof GraduationCap;
  colorClass: string;
}[] = [
  {
    type: 'grading',
    labelKey: 'syllabus.policies.grading',
    fallbackLabel: 'Grading Policy',
    icon: GraduationCap,
    colorClass: 'text-blue-500 bg-blue-100 dark:bg-blue-900/30',
  },
  {
    type: 'attendance',
    labelKey: 'syllabus.policies.attendance',
    fallbackLabel: 'Attendance Policy',
    icon: BookOpen,
    colorClass: 'text-green-500 bg-green-100 dark:bg-green-900/30',
  },
  {
    type: 'late_work',
    labelKey: 'syllabus.policies.lateWork',
    fallbackLabel: 'Late Work Policy',
    icon: FileWarning,
    colorClass: 'text-orange-500 bg-orange-100 dark:bg-orange-900/30',
  },
  {
    type: 'communication',
    labelKey: 'syllabus.policies.communication',
    fallbackLabel: 'Communication Policy',
    icon: MessageCircle,
    colorClass: 'text-purple-500 bg-purple-100 dark:bg-purple-900/30',
  },
  {
    type: 'academic_integrity',
    labelKey: 'syllabus.policies.academicIntegrity',
    fallbackLabel: 'Academic Integrity',
    icon: Shield,
    colorClass: 'text-red-500 bg-red-100 dark:bg-red-900/30',
  },
  {
    type: 'participation',
    labelKey: 'syllabus.policies.participation',
    fallbackLabel: 'Participation',
    icon: Users,
    colorClass: 'text-teal-500 bg-teal-100 dark:bg-teal-900/30',
  },
  {
    type: 'extra_credit',
    labelKey: 'syllabus.policies.extraCredit',
    fallbackLabel: 'Extra Credit',
    icon: Award,
    colorClass: 'text-yellow-500 bg-yellow-100 dark:bg-yellow-900/30',
  },
];

export function getPolicyIcon(type: SyllabusPolicyType) {
  const preset = PRESET_POLICIES.find((p) => p.type === type);
  return preset?.icon ?? PenLine;
}

export function getPolicyColor(type: SyllabusPolicyType) {
  const preset = PRESET_POLICIES.find((p) => p.type === type);
  return preset?.colorClass ?? 'text-gray-500 bg-gray-100 dark:bg-gray-900/30';
}

export const SyllabusSetupStep = ({ data, onChange, isRTL }: SyllabusSetupStepProps) => {
  const { t } = useTranslation();
  const [popoverOpen, setPopoverOpen] = useState(false);
  const [expandedPolicies, setExpandedPolicies] = useState<Set<string>>(new Set());

  const structureOptions: { value: WizardData['structureType']; label: string; desc: string }[] = [
    { value: 'weeks', label: t('syllabus.weeks'), desc: t('syllabus.structureDesc.weeks') },
    { value: 'units', label: t('syllabus.units'), desc: t('syllabus.structureDesc.units') },
    { value: 'modules', label: t('syllabus.modules'), desc: t('syllabus.structureDesc.modules') },
  ];

  const addedTypes = new Set(data.policies.map((p) => p.type));

  const addPolicy = (type: SyllabusPolicyType, label: string) => {
    const newPolicy: SyllabusPolicy = {
      id: crypto.randomUUID(),
      type,
      label,
      content: '',
      order_index: data.policies.length,
    };
    onChange({ policies: [...data.policies, newPolicy] });
    setExpandedPolicies((prev) => new Set([...prev, newPolicy.id]));
    setPopoverOpen(false);
  };

  const addCustomPolicy = () => {
    addPolicy('custom', t('syllabus.policies.customPolicy', 'Custom Policy'));
  };

  const removePolicy = (id: string) => {
    onChange({
      policies: data.policies.filter((p) => p.id !== id).map((p, i) => ({ ...p, order_index: i })),
    });
  };

  const updatePolicy = (id: string, partial: Partial<SyllabusPolicy>) => {
    onChange({
      policies: data.policies.map((p) => (p.id === id ? { ...p, ...partial } : p)),
    });
  };

  const toggleExpanded = (id: string) => {
    setExpandedPolicies((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  // --- Grading categories helpers (nested under grading policy) ---
  const addGradingCategory = () => {
    onChange({
      gradingCategories: [
        ...data.gradingCategories,
        { tempId: crypto.randomUUID(), name: '', weight: 0 },
      ],
    });
  };

  const removeGradingCategory = (tempId: string) => {
    onChange({ gradingCategories: data.gradingCategories.filter((c) => c.tempId !== tempId) });
  };

  const updateGradingCategory = (tempId: string, partial: Partial<WizardGradingCategory>) => {
    onChange({
      gradingCategories: data.gradingCategories.map((c) =>
        c.tempId === tempId ? { ...c, ...partial } : c
      ),
    });
  };

  const totalWeight = data.gradingCategories.reduce((sum, c) => sum + (c.weight || 0), 0);

  const hasGradingPolicy = data.policies.some((p) => p.type === 'grading');

  return (
    <div className="space-y-8">
      {/* Syllabus Info */}
      <div className="space-y-6 p-6 rounded-xl border border-border shadow-sm">
        <div className={`flex items-center gap-2 text-primary ${isRTL ? 'flex-row-reverse' : ''}`}>
          <GraduationCap className="h-5 w-5" />
          <h3 className={`font-bold text-heading ${isRTL ? 'text-right' : 'text-left'}`}>
            {t('syllabus.wizard.syllabusDetails')}
          </h3>
        </div>

        <div className="space-y-2">
          <Label className={`text-body font-medium block ${isRTL ? 'text-right' : 'text-left'}`}>
            {t('syllabus.wizard.syllabusTitle')}
          </Label>
          <Input
            value={data.syllabusTitle}
            onChange={(e) => onChange({ syllabusTitle: e.target.value })}
            placeholder={
              data.courseTitle ? `${data.courseTitle} Syllabus` : 'e.g. Biology 101 - Spring 2026'
            }
            className="rounded-xl h-11"
            autoDirection
          />
        </div>

        {/* Structure Type */}
        <div className="space-y-3">
          <Label className={`text-body font-medium block ${isRTL ? 'text-right' : 'text-left'}`}>
            {t('syllabus.structureType')}
          </Label>
          <div className="grid grid-cols-3 gap-3">
            {structureOptions.map((opt) => (
              <button
                key={opt.value}
                type="button"
                onClick={() => onChange({ structureType: opt.value })}
                className={cn(
                  'p-4 rounded-xl border-2 text-left transition-all',
                  data.structureType === opt.value
                    ? 'border-primary bg-primary/5'
                    : 'border-border hover:border-primary/40 bg-card',
                  isRTL && 'text-right'
                )}
              >
                <span className="font-bold text-foreground">{opt.label}</span>
                <p className="text-xs text-muted-foreground mt-1">{opt.desc}</p>
              </button>
            ))}
          </div>
        </div>

        <ReleaseModeSelect
          label={t('syllabus.releaseMode.label', 'Release mode')}
          value={data.release_mode}
          isRTL={isRTL}
          onChange={(release_mode) => {
            let sections = data.sections;
            if (release_mode !== 'manual') {
              sections = sections.map((s) => ({ ...s, is_locked: false }));
            }
            onChange({ release_mode, sections });
          }}
        />
      </div>

      {/* Policies - Dynamic */}
      <div className="space-y-6 p-6 rounded-xl border border-border shadow-sm">
        <div className={`flex items-center justify-between ${isRTL ? 'flex-row-reverse' : ''}`}>
          <div
            className={`flex items-center gap-2 text-primary ${isRTL ? 'flex-row-reverse' : ''}`}
          >
            <Scale className="h-5 w-5" />
            <h3 className={`font-bold text-heading ${isRTL ? 'text-right' : 'text-left'}`}>
              {t('syllabus.wizard.policies')}
            </h3>
          </div>
          <Popover open={popoverOpen} onOpenChange={setPopoverOpen}>
            <PopoverTrigger className="inline-flex items-center justify-center gap-1.5 rounded-full border border-input bg-background px-3 py-1.5 text-sm font-medium shadow-xs hover:bg-accent hover:text-accent-foreground cursor-pointer">
              <Plus className="h-4 w-4" /> {t('syllabus.policies.addPolicy', 'Add Policy')}
            </PopoverTrigger>
            <PopoverContent align="end" className="w-72 p-2 rounded-xl" sideOffset={8}>
              <div className="space-y-0.5">
                {PRESET_POLICIES.map((preset) => {
                  const Icon = preset.icon;
                  const alreadyAdded = addedTypes.has(preset.type);
                  return (
                    <button
                      key={preset.type}
                      type="button"
                      disabled={alreadyAdded}
                      onClick={() =>
                        addPolicy(preset.type, t(preset.labelKey, preset.fallbackLabel))
                      }
                      className={cn(
                        'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm transition-all',
                        alreadyAdded
                          ? 'opacity-50 cursor-not-allowed'
                          : 'hover:bg-muted/60 cursor-pointer',
                        isRTL && 'flex-row-reverse text-right'
                      )}
                    >
                      <div className={cn('p-1.5 rounded-lg', preset.colorClass)}>
                        <Icon className="h-3.5 w-3.5" />
                      </div>
                      <span className="flex-1 font-medium text-foreground">
                        {t(preset.labelKey, preset.fallbackLabel)}
                      </span>
                      {alreadyAdded && <Check className="h-4 w-4 text-muted-foreground" />}
                    </button>
                  );
                })}
                <div className="border-t border-border my-1" />
                <button
                  type="button"
                  onClick={addCustomPolicy}
                  className={cn(
                    'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm hover:bg-muted/60 transition-all',
                    isRTL && 'flex-row-reverse text-right'
                  )}
                >
                  <div className="p-1.5 rounded-lg text-gray-500 bg-gray-100 dark:bg-gray-900/30">
                    <PenLine className="h-3.5 w-3.5" />
                  </div>
                  <span className="flex-1 font-medium text-foreground">
                    {t('syllabus.policies.customPolicy', 'Custom Policy')}
                  </span>
                </button>
              </div>
            </PopoverContent>
          </Popover>
        </div>

        <p className={`text-sm text-muted-foreground ${isRTL ? 'text-right' : 'text-left'}`}>
          {t(
            'syllabus.policies.addPolicyDesc',
            'Add only the policies relevant to your course. You can always add more later.'
          )}
        </p>

        {data.policies.length === 0 ? (
          <div className="p-8 border-2 border-dashed border-border rounded-xl bg-muted/10 text-center">
            <Scale className="h-8 w-8 text-muted-foreground mx-auto mb-2" />
            <p className="text-subtle text-sm">
              {t(
                'syllabus.policies.noPolicies',
                'No policies added yet. Click "Add Policy" to get started.'
              )}
            </p>
          </div>
        ) : (
          <div className="space-y-3">
            {data.policies.map((policy) => {
              const Icon = getPolicyIcon(policy.type);
              const colorClass = getPolicyColor(policy.type);
              const isExpanded = expandedPolicies.has(policy.id);
              const isGrading = policy.type === 'grading';
              const isCustom = policy.type === 'custom';

              return (
                <div
                  key={policy.id}
                  className="border border-border rounded-xl bg-card overflow-hidden"
                >
                  {/* Policy header */}
                  <button
                    type="button"
                    onClick={() => toggleExpanded(policy.id)}
                    className={cn(
                      'w-full flex items-center gap-3 px-4 py-3 transition-all hover:bg-muted/30',
                      isRTL && 'flex-row-reverse'
                    )}
                  >
                    <div className={cn('p-1.5 rounded-lg', colorClass)}>
                      <Icon className="h-3.5 w-3.5" />
                    </div>
                    <span
                      className={cn(
                        'flex-1 font-medium text-sm text-foreground',
                        isRTL ? 'text-right' : 'text-left'
                      )}
                    >
                      {policy.label}
                    </span>
                    {policy.content && (
                      <span className="text-xs text-muted-foreground px-2 py-0.5 bg-muted/50 rounded-full">
                        {t('syllabus.policies.filled', 'Filled')}
                      </span>
                    )}
                    {isExpanded ? (
                      <ChevronUp className="h-4 w-4 text-muted-foreground" />
                    ) : (
                      <ChevronDown className="h-4 w-4 text-muted-foreground" />
                    )}
                  </button>

                  {/* Expanded content */}
                  {isExpanded && (
                    <div className="px-4 pb-4 space-y-3 border-t border-border pt-3">
                      {isCustom && (
                        <div className="space-y-1.5">
                          <Label className="text-xs font-medium">
                            {t('syllabus.policies.policyName', 'Policy Name')}
                          </Label>
                          <Input
                            value={policy.label}
                            onChange={(e) => updatePolicy(policy.id, { label: e.target.value })}
                            className="rounded-lg h-9"
                            autoDirection
                          />
                        </div>
                      )}
                      <Textarea
                        value={policy.content}
                        onChange={(e) => updatePolicy(policy.id, { content: e.target.value })}
                        placeholder={t(
                          'syllabus.policies.contentPlaceholder',
                          'Describe this policy...'
                        )}
                        rows={3}
                        className="rounded-lg resize-none text-sm"
                        autoDirection
                      />

                      {/* Grading categories nested inside grading policy */}
                      {isGrading && (
                        <div className="mt-3 p-3 rounded-lg border border-border bg-muted/10 space-y-3">
                          <div
                            className={`flex items-center justify-between ${isRTL ? 'flex-row-reverse' : ''}`}
                          >
