import { useEffect, useRef, useState } from 'react';
import { cn } from '@/lib/utils';

interface ScrollHighlightTextProps {
  text: string;
  className?: string;
}

export const ScrollHighlightText = ({ text, className }: ScrollHighlightTextProps) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [scrollProgress, setScrollProgress] = useState(0);

  useEffect(() => {
    const handleScroll = () => {
      if (!containerRef.current) return;

      const element = containerRef.current;
      const { top, height } = element.getBoundingClientRect();
      const windowHeight = window.innerHeight;

      // Calculate progress based on element position in viewport
      // Start highlighting when element enters viewport (top < windowHeight)
      // Finish highlighting when element is near center/top
      const start = windowHeight * 0.8;
      const end = windowHeight * 0.2;

      const progress = Math.min(Math.max((start - top) / (start - end), 0), 1);
      setScrollProgress(progress);
    };

    window.addEventListener('scroll', handleScroll);
    handleScroll(); // Initial check

    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const words = text.split(' ');

  return (
    <div ref={containerRef} className={cn('py-20 px-4', className)}>
      <p className="text-4xl md:text-6xl font-bold leading-tight flex flex-wrap gap-x-3 gap-y-2 justify-center text-center max-w-5xl mx-auto">
        {words.map((word, i) => {
          const wordProgress = i / words.length;
          const isHighlighted = scrollProgress > wordProgress;

          return (
            <span
              key={i}
              className={cn(
                'transition-colors duration-300',
                isHighlighted ? 'text-foreground' : 'text-muted-foreground/20'
              )}
            >
              {word}
            </span>
          );
        })}
      </p>
    </div>
  );
};

/**
 * GSAP-powered Skeleton Loading Component
 * Replaces animate-pulse with GSAP animation for smoother loading states
 */

import gsap from 'gsap';
import { useEffect, useRef } from 'react';
import { cn } from '@/lib/utils';

interface GsapSkeletonProps {
  className?: string;
  variant?: 'default' | 'card' | 'text' | 'avatar' | 'button';
}

/**
 * GSAP-animated skeleton loader
 */
export const GsapSkeleton = ({ className, variant = 'default' }: GsapSkeletonProps) => {
  const skeletonRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (skeletonRef.current) {
      // GSAP pulse animation - smoother than CSS
      gsap.to(skeletonRef.current, {
        opacity: 0.5,
        duration: 1,
        repeat: -1,
        yoyo: true,
        ease: 'power1.inOut',
      });
    }

    return () => {
      if (skeletonRef.current) {
        gsap.killTweensOf(skeletonRef.current);
      }
    };
  }, []);

  const variantClasses = {
    default: '',
    card: 'h-48 rounded-xl',
    text: 'h-4 rounded',
    avatar: 'h-12 w-12 rounded-full',
    button: 'h-10 w-24 rounded-lg',
  };

  return <div ref={skeletonRef} className={cn('bg-muted', variantClasses[variant], className)} />;
};

/**
 * Skeleton card for dashboard loading states
 */
export const SkeletonCard = ({ className }: { className?: string }) => {
  return <GsapSkeleton variant="card" className={className} />;
};

/**
 * Multiple skeleton cards for grid layouts
 */
export const SkeletonCardGrid = ({
  count = 4,
  className,
}: {
  count?: number;
  className?: string;
}) => {
  return (
    <div className={cn('grid sm:grid-cols-2 gap-6', className)}>
      {Array.from({ length: count }).map((_, i) => (
        <SkeletonCard key={i} />
      ))}
    </div>
  );
};

/**
 * Skeleton row for list loading states
 */
export const SkeletonRow = ({ className }: { className?: string }) => {
  return <GsapSkeleton className={cn('h-24 rounded-xl', className)} />;
};

/**
 * Multiple skeleton rows for list layouts
 */
export const SkeletonRowList = ({
  count = 3,
  className,
}: {
  count?: number;
  className?: string;
}) => {
  return (
    <div className={cn('space-y-3', className)}>
      {Array.from({ length: count }).map((_, i) => (
        <SkeletonRow key={i} />
      ))}
    </div>
  );
};

import { mergeProps } from '@base-ui/react/merge-props';
import { useRender } from '@base-ui/react/use-render';
import { cva, type VariantProps } from 'class-variance-authority';
