import { useQuery, useQueryClient } from '@tanstack/react-query';
import { createContext, useContext, useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import type { User, Session } from '@supabase/supabase-js';
import type { ReactNode } from 'react';
import { USER_ROLES } from '@/config/constants';
import { profileKeys } from '@/hooks/queries';
import { clearAllPersistedForms } from '@/hooks/usePersistedState';
import { supabase, PERLEAP_AUTH_STORAGE_KEY } from '@/integrations/supabase/client';
import { getTeacherProfile, getStudentProfile } from '@/services/profileService';
import { ACCOUNT_JUST_DELETED_SESSION_KEY } from '@/utils/accountDeletionRedirect';
import {
  shouldAttemptRecovery,
  attemptRoleRecovery,
  incrementRecoveryAttempt,
} from '@/utils/roleRecovery';
import { isSignupInProgress, clearAllSignupState } from '@/utils/sessionState';
import {
  prefetchAvatarBlob,
  STUDENT_AVATARS_BUCKET,
  TEACHER_AVATARS_BUCKET,
} from '@/utils/storageUrls';

interface UserProfile {
  full_name: string;
  avatar_url: string | null;
}

interface AuthContextType {
  user: User | null;
  session: Session | null;
  profile: UserProfile | null;
  loading: boolean;
  signOut: (
    redirectPath?: string,
    options?: { scope?: 'global' | 'local'; skipSupabaseRemoteSignOut?: boolean }
  ) => Promise<void>;
  refreshProfile: (force?: boolean) => Promise<void>;
  hasProfile: boolean | null;
  isProfileLoading: boolean;
}

export const AuthContext = createContext<AuthContextType | undefined>(undefined);

/** Defined in this file (not a separate module) so Vite HMR cannot desync `AuthContext` from `AuthProvider`. */
export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export const AuthProvider = ({ children }: { children: ReactNode }) => {
  const [user, setUser] = useState<User | null>(null);
  const [session, setSession] = useState<Session | null>(null);
  const queryClient = useQueryClient();

  // Initial loading state for the core auth session
  const [loading, setLoading] = useState(true);

  const navigate = useNavigate();

  // Profile query using TanStack Query
  const {
    data: profileData,
    isLoading: isProfileQueryLoading,
    isFetched: isProfileFetched,
    refetch,
  } = useQuery({
    queryKey:
      user?.user_metadata?.role === USER_ROLES.ADMIN
        ? (['auth', 'admin-profile', user?.id || ''] as const)
        : user?.user_metadata?.role === 'teacher'
          ? profileKeys.teacher(user?.id || '')
          : profileKeys.student(user?.id || ''),
    queryFn: async () => {
      if (!user?.id) return null;
      const role = user.user_metadata?.role;
      if (!role) return null;

      if (role === USER_ROLES.ADMIN) {
        const { data: teacherRow } = await getTeacherProfile(user.id);
        if (teacherRow?.full_name?.trim()) {
          return { full_name: teacherRow.full_name, avatar_url: teacherRow.avatar_url ?? null };
        }
        const metaName =
          typeof user.user_metadata?.full_name === 'string'
            ? user.user_metadata.full_name.trim()
            : '';
        if (metaName) {
          return { full_name: metaName, avatar_url: null as string | null };
        }
        const email = user.email || '';
        const display = email ? email.split('@')[0] : 'Admin';
        return { full_name: display, avatar_url: null as string | null };
      }

      console.log(`🔄 AuthContext: Fetching fresh profile for ${role}...`);
      const { data, error } =
        role === 'teacher' ? await getTeacherProfile(user.id) : await getStudentProfile(user.id);

      if (error) {
        console.error('Error fetching profile:', error);
        throw error;
      }

      console.log('✅ AuthContext: Profile found');
      return data;
    },
    // Only run the query if we have a user ID and a role
    enabled: !!user?.id && !!user?.user_metadata?.role,
    staleTime: 5 * 60 * 1000, // 5 minutes
  });

  // Map query states to context values
  // profile: the actual data
  const profile = profileData || null;

  // isProfileLoading: only true on the initial fetch to avoid full-page unmounts on background refreshes
  const isProfileLoading = user ? isProfileQueryLoading && !isProfileFetched : false;

  // hasProfile: null if not yet determined, true if data exists, false if no profile found
  const isAdmin = user?.user_metadata?.role === USER_ROLES.ADMIN;
  const hasProfile = isProfileFetched ? !!profileData || isAdmin : null;

  useEffect(() => {
    const avatarUrl = profile?.avatar_url;
    if (!avatarUrl) return;

    const role = user?.user_metadata?.role;
    const bucket =
      role === 'teacher' || role === USER_ROLES.ADMIN
        ? TEACHER_AVATARS_BUCKET
        : STUDENT_AVATARS_BUCKET;
    prefetchAvatarBlob(avatarUrl, bucket);
  }, [profile?.avatar_url, user?.user_metadata?.role]);

  // Token refresh failure recovery
  const handleTokenRefreshFailure = async () => {
    console.log('🔄 Attempting session recovery after token refresh failure...');

    try {
      const { data, error } = await supabase.auth.getSession();

      if (data?.session) {
        console.log('✅ Session recovered successfully');
        setSession(data.session);
        setUser(data.session.user);
        return;
      }

      if (error) {
        console.error('❌ Session recovery failed:', error);
      }
    } catch (error) {
      console.error('❌ Session recovery exception:', error);
    }

    // Only logout if recovery fails
    console.log('🚪 Logging out due to unrecoverable session');
    try {
      await supabase.auth.signOut({ scope: 'local' });
    } catch (signOutErr) {
      console.error('Sign out after refresh failure:', signOutErr);
    }
    clearAllPersistedForms();
    sessionStorage.clear();
    navigate('/auth');
  };

  useEffect(() => {
    let mounted = true;

    // Check for existing session first (important for browser back/forward)
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (mounted) {
        console.log('🔐 Initial session check:', {
          hasSession: !!session,
          userId: session?.user?.id,
        });
        setSession(session);
        setUser(session?.user ?? null);
        setLoading(false);
      }
    });

    // Set up auth state listener for real-time changes
    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (!mounted) return;

      // Ignore auth events triggered by visibility changes to prevent unnecessary refetches
      if (document.hidden && (event === 'TOKEN_REFRESHED' || event === 'SIGNED_IN')) {
        console.log(`🔕 Ignoring ${event} event while document is hidden`);
        return;
      }

      console.log(`🔐 Auth Event: ${event}`, {
        hasSession: !!session,
        userId: session?.user?.id,
        expiresAt: session?.expires_at ? new Date(session.expires_at * 1000).toISOString() : null,
      });

      // Handle specific auth events
      switch (event as any) {
        case 'TOKEN_REFRESHED':
          console.log('✅ Token refreshed successfully');
          break;

        case 'SIGNED_OUT':
          console.log('🚪 User signed out');
          sessionStorage.removeItem('redirectAfterLogin');
          clearAllPersistedForms();
          clearAllSignupState();
          // Reset profile data in cache
          const r = user?.user_metadata?.role;
          const signoutKey =
            r === USER_ROLES.ADMIN
              ? (['auth', 'admin-profile', user?.id || ''] as const)
              : r === 'teacher'
                ? profileKeys.teacher(user?.id || '')
                : profileKeys.student(user?.id || '');
          queryClient.setQueryData(signoutKey, null);
          break;

        case 'TOKEN_REFRESH_FAILED':
          console.error('❌ Token refresh failed - attempting recovery');
          await handleTokenRefreshFailure();
          return; // Don't update state, let recovery handle it

        case 'USER_UPDATED':
          console.log('👤 User metadata updated');
          break;

        case 'SIGNED_IN':
          console.log('✅ User signed in');
          if (session?.user) {
            const userRole = session.user.user_metadata?.role;

            // Check if user has role metadata
            if (
              !userRole ||
              (userRole !== 'teacher' && userRole !== 'student' && userRole !== USER_ROLES.ADMIN)
            ) {
              // Check if signup is in progress
              const signupInProgress = isSignupInProgress();

              // Check if this is a VERY new account (created < 5 minutes ago)
              const userCreatedAt = session.user.created_at
                ? new Date(session.user.created_at).getTime()
                : 0;
              const now = Date.now();
              const fiveMinutes = 5 * 60 * 1000;
              const isVeryNewAccount = now - userCreatedAt < fiveMinutes;

              // CRITICAL: Don't interfere if on callback page or signup is in progress OR account is brand new
              const isCallbackPage = window.location.pathname.includes('/auth/callback');
              if (signupInProgress || isVeryNewAccount || isCallbackPage) {
                if (signupInProgress) {
                  console.log('🔄 Signup in progress, skipping role check');
                } else if (isCallbackPage) {
                  console.log('🔄 On callback page, letting AuthCallback handle role assignment');
                } else {
                  console.log('🆕 Very new account detected, skipping role check');
                }
                break;
              }

              console.warn('⚠️ User signed in without valid role metadata');

              if (shouldAttemptRecovery()) {
                console.log('🔄 Attempting automatic role recovery...');
                incrementRecoveryAttempt();

                const { recovered, role } = await attemptRoleRecovery();

                if (recovered && role) {
                  console.log(`✅ Role recovered successfully: ${role}`);
                } else {
                  console.log('❌ Role recovery failed, redirecting to role selection');
                  navigate('/role-selection', { replace: true });
                  return;
                }
              } else {
                console.log('⚠️ Max recovery attempts reached, redirecting to role selection');
                navigate('/role-selection', { replace: true });
                return;
              }
            }
          }
          break;

        case 'INITIAL_SESSION':
          console.log('🔍 Initial session loaded');
          break;
      }

      // Update state only if changed to prevent unnecessary re-renders
      setSession((prev) => {
        if (
          prev?.access_token === session?.access_token &&
          prev?.expires_at === session?.expires_at
        ) {
          return prev;
        }
        return session;
      });

      setUser((prev) => {
        if (
          prev?.id === session?.user?.id &&
          JSON.stringify(prev?.user_metadata) === JSON.stringify(session?.user?.user_metadata)
        ) {
          return prev;
        }
        return session?.user ?? null;
      });

      setLoading(false);
    });

    return () => {
      mounted = false;
      subscription.unsubscribe();
    };
  }, [user?.id, queryClient]);

  // Session health monitoring - check every 5 minutes
  useEffect(() => {
    const checkSessionHealth = async () => {
      try {
        const {
          data: { session },
          error,
        } = await supabase.auth.getSession();

        if (error) {
          console.error('⚠️ Session health check error:', error);
          return;
        }

        if (session?.expires_at) {
          const expiresAt = session.expires_at * 1000;
          const now = Date.now();
          const timeToExpiry = expiresAt - now;
          const minutesToExpiry = Math.floor(timeToExpiry / (1000 * 60));

          console.log('🔍 Session health check:', {
            valid: !!session,
            expiresAt: new Date(expiresAt).toISOString(),
            minutesToExpiry,
            userId: session.user?.id,
          });

          if (minutesToExpiry < 10 && minutesToExpiry > 0) {
            console.warn(`⚠️ Session expiring in ${minutesToExpiry} minutes`);
          }
        } else {
          console.log('🔍 Session health check: No active session');
        }
      } catch (error) {
        console.error('❌ Session health check exception:', error);
      }
    };

    const initialTimeout = setTimeout(checkSessionHealth, 60 * 1000);
    const interval = setInterval(checkSessionHealth, 5 * 60 * 1000);

    return () => {
      clearTimeout(initialTimeout);
      clearInterval(interval);
    };
  }, []);

  const signOut = async (
    redirectPath: string = '/',
    options?: { scope?: 'global' | 'local'; skipSupabaseRemoteSignOut?: boolean }
  ) => {
    const signOutScope = options?.scope ?? 'global';
    const skipRemote = options?.skipSupabaseRemoteSignOut === true;

    try {
      if (skipRemote) {
        // Server already removed the user; GoTrue still POSTs /logout for any scope → browser 403 noise.
        try {
          await supabase.auth.stopAutoRefresh();
        } catch {
          /* ignore */
        }
        try {
          localStorage.removeItem(PERLEAP_AUTH_STORAGE_KEY);
          localStorage.removeItem(`${PERLEAP_AUTH_STORAGE_KEY}-code-verifier`);
          localStorage.removeItem(`${PERLEAP_AUTH_STORAGE_KEY}-user`);
        } catch {
          /* ignore */
        }
        setUser(null);
        setSession(null);
      } else {
        await supabase.auth.signOut(signOutScope === 'local' ? { scope: 'local' } : undefined);
      }
    } catch (error) {
      console.error('Sign out failed, cleaning up locally:', error);
    } finally {
      // Perform heavy cleanup in the next tick to prevent blocking the UI
      setTimeout(() => {
        clearAllPersistedForms();
        clearAllSignupState();
        const sessionKeysToKeep = [ACCOUNT_JUST_DELETED_SESSION_KEY];
        for (let i = sessionStorage.length - 1; i >= 0; i--) {
          const key = sessionStorage.key(i);
          if (key && !sessionKeysToKeep.includes(key)) {
            sessionStorage.removeItem(key);
          }
        }
        queryClient.clear();

        const keysToKeep = ['language_preference'];
        const allKeys = Object.keys(localStorage);
        allKeys.forEach((key) => {
          if (!keysToKeep.includes(key)) {
            localStorage.removeItem(key);
          }
        });
        if (skipRemote && typeof window !== 'undefined') {
          if (redirectPath.startsWith('http://') || redirectPath.startsWith('https://')) {
            window.location.assign(redirectPath);
          } else {
            const path = redirectPath.startsWith('/') ? redirectPath : `/${redirectPath}`;
            window.location.assign(`${window.location.origin}${path}`);
          }
        } else {
          navigate(redirectPath);
        }
      }, 0);
    }
  };

  const refreshProfile = async (force: boolean = false) => {
    const r = user?.user_metadata?.role;
    const key =
      r === USER_ROLES.ADMIN
        ? (['auth', 'admin-profile', user?.id || ''] as const)
        : r === 'teacher'
          ? profileKeys.teacher(user?.id || '')
          : profileKeys.student(user?.id || '');

    if (force) {
      await queryClient.invalidateQueries({ queryKey: key });
    } else {
      await refetch();
    }
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        session,
        profile,
        loading,
        signOut,
        refreshProfile,
        hasProfile,
        isProfileLoading,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { useTranslation } from 'react-i18next';
import { EvaluationRefreshProgressBanner } from '@/components/features/analytics/EvaluationRefreshProgressBanner';
import { supabase } from '@/integrations/supabase/client';
import {
  estimateRefreshDurationSeconds,
  estimateSecondsPerStudent,
  formatEta,
} from '@/lib/evaluationRefreshEstimate';

export type EvaluationRefreshActiveJob = {
  jobId: string;
  classroomId: string;
  percent: number;
  progressLabel: string;
  etaLabel: string;
  totalStudents: number;
  completedStudents: number;
  isCancelling: boolean;
};

export type RefreshResponse = {
  status: 'completed' | 'cancelled' | 'failed' | 'empty';
  batchId?: string | null;
  updated?: number;
  skipped?: number;
  failed?: number;
  manualSkipped?: number;
  canUndo?: boolean;
  error?: string;
};

type EvaluationRefreshProcessingContextValue = {
  activeJob: EvaluationRefreshActiveJob | null;
  isRefreshing: boolean;
  startRefresh: (classroomId: string) => Promise<RefreshResponse | { error: string }>;
  cancelRefresh: () => Promise<void>;
};

const EvaluationRefreshProcessingContext =
  createContext<EvaluationRefreshProcessingContextValue | null>(null);

const POLL_MS = 1000;
const COMPLETE_PAUSE_MS = 400;
const PROGRESS_CAP = 95;

type JobRow = {
  status: string;
  completed_students: number;
  total_students: number;
  total_submissions: number;
  batch_id: string | null;
  error_message: string | null;
};

type StartResponse = {
  jobId?: string;
  totalStudents?: number;
  totalSubmissions?: number;
  manualSkipped?: number;
  skipped?: number;
  updated?: number;
  batchId?: string | null;
  failed?: number;
  error?: string;
};

function jobToRefreshResponse(job: JobRow, manualSkipped = 0, skipped = 0): RefreshResponse {
  if (job.status === 'completed') {
    return {
      status: 'completed',
      batchId: job.batch_id,
      updated: job.total_submissions,
      skipped,
      failed: 0,
      manualSkipped,
      canUndo: !!job.batch_id,
    };
  }
  if (job.status === 'cancelled') {
    return { status: 'cancelled' };
  }
  return {
    status: 'failed',
    error: job.error_message ?? 'Refresh failed',
  };
}

export const EvaluationRefreshProcessingProvider = ({ children }: { children: ReactNode }) => {
  const { t } = useTranslation();
  const [activeJob, setActiveJob] = useState<EvaluationRefreshActiveJob | null>(null);
  const pollRef = useRef<number | null>(null);
  const jobMetaRef = useRef({ manualSkipped: 0, skipped: 0, secondsPerStudent: 28 });
  const isCancellingRef = useRef(false);

  const clearPoll = useCallback(() => {
    if (pollRef.current !== null) {
      window.clearInterval(pollRef.current);
      pollRef.current = null;
    }
  }, []);

  const clearJob = useCallback(() => {
    clearPoll();
    isCancellingRef.current = false;
    setActiveJob(null);
  }, [clearPoll]);

  const updateJobFromRow = useCallback(
    (jobId: string, classroomId: string, row: JobRow) => {
      const { total_students: totalStudents, completed_students: completedStudents } = row;
      const { secondsPerStudent } = jobMetaRef.current;

      const computePercent =
        row.status === 'completed'
          ? 100
          : Math.min(
              PROGRESS_CAP,
              totalStudents > 0 ? (completedStudents / totalStudents) * 100 : 0
            );

      const remainingStudents = Math.max(0, totalStudents - completedStudents);
      const remainingSeconds = remainingStudents * secondsPerStudent;

      setActiveJob({
        jobId,
        classroomId,
        percent: computePercent,
        totalStudents,
        completedStudents,
        isCancelling: isCancellingRef.current,
        progressLabel: t('analytics.refreshProgress.label', {
          current: completedStudents,
          total: totalStudents,
        }),
        etaLabel:
          row.status === 'running' && remainingSeconds > 0
            ? t('analytics.refreshProgress.eta', { time: formatEta(remainingSeconds) })
            : '',
      });
    },
    [t]
  );

  const waitForTerminalJob = useCallback(
    (jobId: string, classroomId: string, manualSkipped: number, skipped: number) =>
      new Promise<RefreshResponse>((resolve, reject) => {
        jobMetaRef.current = { ...jobMetaRef.current, manualSkipped, skipped };

        const poll = async () => {
          try {
            const { data, error } = await supabase
              .from('evaluation_refresh_jobs')
              .select(
                'status, completed_students, total_students, total_submissions, batch_id, error_message'
              )
              .eq('id', jobId)
              .single();

            if (error) throw error;
            if (!data) throw new Error('Job not found');

            const row = data as JobRow;
            updateJobFromRow(jobId, classroomId, row);

            if (row.status === 'running') return;

            clearPoll();
            isCancellingRef.current = false;
            updateJobFromRow(jobId, classroomId, row);

            await new Promise<void>((r) => {
              window.setTimeout(r, COMPLETE_PAUSE_MS);
            });
            clearJob();

            resolve(jobToRefreshResponse(row, manualSkipped, skipped));
          } catch (e) {
            clearPoll();
            clearJob();
            reject(e);
          }
        };

        void poll();
        pollRef.current = window.setInterval(() => {
          void poll();
        }, POLL_MS);
      }),
    [clearJob, clearPoll, updateJobFromRow]
  );

  const startRefresh = useCallback(
    async (classroomId: string): Promise<RefreshResponse | { error: string }> => {
      clearJob();

      try {
        const { data, error } = await supabase.functions.invoke<StartResponse>(
          'refresh-class-evaluations',
          { body: { classroomId } }
        );

        if (error) {
          return { error: error.message || 'invoke_failed' };
        }

        const payload = data ?? {};

        if (payload.error) {
          return { error: payload.error };
        }

        if (!payload.jobId) {
          return {
            status: 'empty',
            batchId: payload.batchId ?? null,
            updated: payload.updated ?? 0,
            skipped: payload.skipped ?? 0,
            failed: payload.failed ?? 0,
            manualSkipped: payload.manualSkipped ?? 0,
          };
        }

        const totalStudents = payload.totalStudents ?? 0;
        const totalSubmissions = payload.totalSubmissions ?? totalStudents;
        const manualSkipped = payload.manualSkipped ?? 0;
        const skipped = payload.skipped ?? 0;

        jobMetaRef.current = {
          manualSkipped,
          skipped,
          secondsPerStudent: estimateSecondsPerStudent(totalStudents, totalSubmissions),
        };

        setActiveJob({
          jobId: payload.jobId,
          classroomId,
          percent: 0,
          totalStudents,
          completedStudents: 0,
          isCancelling: false,
          progressLabel: t('analytics.refreshProgress.label', {
            current: 0,
            total: totalStudents,
          }),
          etaLabel: t('analytics.refreshProgress.eta', {
            time: formatEta(estimateRefreshDurationSeconds(totalStudents, totalSubmissions)),
          }),
        });

        return await waitForTerminalJob(payload.jobId, classroomId, manualSkipped, skipped);
      } catch (e) {
        clearJob();
        return { error: e instanceof Error ? e.message : 'invoke_failed' };
      }
    },
    [clearJob, t, waitForTerminalJob]
  );

  const cancelRefresh = useCallback(async () => {
    if (!activeJob) return;

    isCancellingRef.current = true;
    setActiveJob((job) => (job ? { ...job, isCancelling: true } : job));

    await supabase.functions.invoke('cancel-evaluation-refresh', {
      body: { classroomId: activeJob.classroomId, jobId: activeJob.jobId },
    });
  }, [activeJob]);

  const value = useMemo(
    (): EvaluationRefreshProcessingContextValue => ({
      activeJob,
      isRefreshing: activeJob !== null,
      startRefresh,
      cancelRefresh,
    }),
    [activeJob, startRefresh, cancelRefresh]
  );

  return (
    <EvaluationRefreshProcessingContext.Provider value={value}>
      {children}
      {activeJob ? <EvaluationRefreshProgressBanner job={activeJob} /> : null}
    </EvaluationRefreshProcessingContext.Provider>
  );
};

export function useEvaluationRefreshProcessing(): EvaluationRefreshProcessingContextValue {
  const ctx = useContext(EvaluationRefreshProcessingContext);
  if (!ctx) {
    throw new Error(
      'useEvaluationRefreshProcessing must be used within EvaluationRefreshProcessingProvider'
    );
  }
  return ctx;
}

import React, { createContext, useContext, useState, useEffect } from 'react';
import type { User } from '@supabase/supabase-js';
import type { ReactNode } from 'react';
import i18n from '@/i18n/config';
import { supabase } from '@/integrations/supabase/client';

type Language = 'en' | 'he';

interface LanguageContextType {
  language: Language;
  setLanguage: (lang: Language) => void;
  isRTL: boolean;
}

const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

export const LanguageProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  /** Supabase session only — avoids `useAuth` here so Vite HMR cannot desync AuthContext vs Provider. */
  const [user, setUser] = useState<User | null>(null);

  useEffect(() => {
    void supabase.auth.getSession().then(({ data: { session } }) => {
      setUser(session?.user ?? null);
    });
    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user ?? null);
    });
    return () => subscription.unsubscribe();
  }, []);

  // Initialize from localStorage with more robust checking
  const getStoredLanguage = (): Language => {
    try {
      const stored = localStorage.getItem('language_preference');
      return stored === 'he' || stored === 'en' ? stored : 'en';
    } catch {
      return 'en';
    }
  };

  const [language, setLanguageState] = useState<Language>(getStoredLanguage);

  const isRTL = language === 'he';

  // Load user's preferred language from profile when user logs in (ONLY ONCE)
  const [loadedUserId, setLoadedUserId] = useState<string | null>(null);

  useEffect(() => {
    // Only load once per user ID
    if (user && user.id !== loadedUserId) {
      loadUserLanguagePreference();
      setLoadedUserId(user.id);
    } else if (!user && loadedUserId) {
      // Reset when user logs out
      setLoadedUserId(null);
    }
  }, [user?.id]); // Only depend on user ID, not the entire user object

  const loadUserLanguagePreference = async () => {
    if (!user) return;

    console.log('🌐 LanguageContext: Loading language preference for user:', user.id);

    try {
      let dbLanguage: Language | null = null;
      const userRole = user.user_metadata?.role;

      if (userRole === 'student') {
        const { data: studentProfile } = await supabase
          .from('student_profiles')
          .select('preferred_language')
          .eq('user_id', user.id)
          .maybeSingle();

        if (studentProfile?.preferred_language) {
          dbLanguage = studentProfile.preferred_language as Language;
        }
      } else if (userRole === 'teacher' || userRole === 'admin') {
        const { data: teacherProfile } = await supabase
          .from('teacher_profiles')
          .select('preferred_language')
          .eq('user_id', user.id)
          .maybeSingle();

        if (teacherProfile?.preferred_language) {
          dbLanguage = teacherProfile.preferred_language as Language;
        }
      }
      // No fallback to both tables - trust the metadata role

      if (dbLanguage) {
        // If DB has a preference, use it (overriding local storage)
        if (dbLanguage !== language) {
          console.log('🌐 ✅ Syncing language from database:', dbLanguage);
          setLanguage(dbLanguage);
        } else {
          console.log('🌐 ✅ Database language matches current:', dbLanguage);
        }
      } else {
        // If DB has no preference, use localStorage and keep it synced
        const localPref = getStoredLanguage();
        console.log('🌐 No DB preference, checking localStorage:', localPref);

        // Apply the localStorage language preference immediately
        if (localPref !== language) {
          console.log('🌐 ✅ APPLYING localStorage language:', localPref, '(was:', language, ')');
          setLanguage(localPref);
        } else {
          console.log('🌐 localStorage language already applied:', localPref);
        }

        // Silently try to update database to match localStorage
        if (localPref === 'he') {
          const userRole = user.user_metadata?.role;
          const table =
            userRole === 'teacher' || userRole === 'admin'
              ? 'teacher_profiles'
              : 'student_profiles';

          if (userRole === 'teacher' || userRole === 'student' || userRole === 'admin') {
            console.log(`🌐 Attempting to sync Hebrew to ${table}...`);
            supabase.from(table).update({ preferred_language: localPref }).eq('user_id', user.id);
          }
        }
      }
    } catch (error) {
      console.error('🌐 ❌ Error loading language preference:', error);
    }
  };

  const setLanguage = (lang: Language) => {
    console.log('🌐 setLanguage called with:', lang);

    // Update local state
    setLanguageState(lang);

    // Update i18n
    i18n.changeLanguage(lang);

    // Update localStorage
    localStorage.setItem('language_preference', lang);
    console.log('🌐 localStorage updated to:', lang);

    // Update HTML attributes
    document.documentElement.dir = lang === 'he' ? 'rtl' : 'ltr';
    document.documentElement.lang = lang;

    // Update user profile if logged in (ONLY if different from what's in database)
    if (user) {
      const userRole = user.user_metadata?.role;
      const table =
        userRole === 'teacher' || userRole === 'admin' ? 'teacher_profiles' : 'student_profiles';

      if (userRole === 'teacher' || userRole === 'student' || userRole === 'admin') {
        try {
          supabase
            .from(table)
            .update({ preferred_language: lang })
            .eq('user_id', user.id)
            .then(({ error }) => {
              if (error) {
                console.error(`Failed to update ${table}:`, error);
              }
            });
        } catch (error) {
          console.error('Error updating language preference:', error);
        }
      }
    }
  };

  // Initialize language on mount - ensure i18n is in sync
  useEffect(() => {
    const storedLang = getStoredLanguage();

    // If stored language doesn't match state, update state
    if (storedLang !== language) {
      setLanguageState(storedLang);
    }

    // Make sure i18n language matches
    if (i18n.language !== storedLang) {
      i18n.changeLanguage(storedLang);
    }

    // Update HTML attributes
    document.documentElement.dir = storedLang === 'he' ? 'rtl' : 'ltr';
    document.documentElement.lang = storedLang;
  }, []); // Only run on mount

  // Sync whenever language changes
  useEffect(() => {
    document.documentElement.dir = isRTL ? 'rtl' : 'ltr';
    document.documentElement.lang = language;

    if (i18n.language !== language) {
      i18n.changeLanguage(language);
    }
  }, [language, isRTL]);

  // Removed visibility change listener - it was causing unnecessary re-renders when tabbing back
  // Language is already synced via localStorage and won't change unless user explicitly changes it

  return (
    <LanguageContext.Provider value={{ language, setLanguage, isRTL }}>
      {children}
    </LanguageContext.Provider>
  );
};

export const useLanguage = (): LanguageContextType => {
  const context = useContext(LanguageContext);
  if (!context) {
    throw new Error('useLanguage must be used within a LanguageProvider');
  }
  return context;
};

import { useQueryClient } from '@tanstack/react-query';
import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { useTranslation } from 'react-i18next';
import { useNavigate } from 'react-router-dom';
import { toast } from 'sonner';
import type { LiveSessionType, LiveSessionUploadMode } from '@/types/liveSession';
import { LiveSessionProcessingBanner } from '@/components/features/liveSession/LiveSessionProcessingBanner';
import { buildRoute } from '@/config/routes';
import { assignmentKeys } from '@/hooks/queries/useAssignmentQueries';
import {
  runLiveSessionCreatePipeline,
  type LiveSessionPipelineProgress,
} from '@/services/liveSessionCreatePipeline';

export type LiveSessionActiveJob = {
  classroomId: string;
  assignmentId: string | null;
  title: string;
  percent: number;
  progressLabel: string;
  transcriptionPhase: LiveSessionPipelineProgress['transcriptionPhase'] | null;
  chunkIndex?: number;
  chunkTotal?: number;
  minimized: boolean;
};

type StartJobInput = {
  classroomId: string;
  syllabusSectionId?: string | null;
  title: string;
  sessionType: LiveSessionType;
  file: File;
  uploadMode: LiveSessionUploadMode;
  language: 'en' | 'he';
  knownDurationSeconds?: number;
  onAssignmentCreated?: (assignmentId: string) => void;
};

type LiveSessionProcessingContextValue = {
  activeJob: LiveSessionActiveJob | null;
  isRunning: boolean;
  startJob: (
    input: StartJobInput
  ) => Promise<{ assignmentId: string; minimized: boolean } | { error: string }>;
  minimizeJob: () => void;
};

const LiveSessionProcessingContext = createContext<LiveSessionProcessingContextValue | null>(null);

function labelForProgress(
  progress: LiveSessionPipelineProgress,
  t: (key: string) => string
): string {
  switch (progress.phase) {
    case 'creating':
      return t('liveSession.create.creating');
    case 'converting':
      return t('liveSession.create.converting');
    case 'preparing':
      return t('liveSession.create.preparing');
    case 'uploading':
      return t('liveSession.create.uploading');
    case 'transcribing':
      return t('liveSession.create.transcribing');
    case 'summarizing':
      return t('liveSession.create.summarizing');
    case 'finishing':
      return t('liveSession.create.transcriptReady');
    default:
      return t('liveSession.create.creating');
  }
}

export const LiveSessionProcessingProvider = ({ children }: { children: ReactNode }) => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [activeJob, setActiveJob] = useState<LiveSessionActiveJob | null>(null);
  const minimizedRef = useRef(false);

  const clearJob = useCallback(() => {
    setActiveJob(null);
    minimizedRef.current = false;
  }, []);

  const minimizeJob = useCallback(() => {
    minimizedRef.current = true;
    setActiveJob((job) => (job ? { ...job, minimized: true } : null));
  }, []);

  const startJob = useCallback(
    async (
      input: StartJobInput
    ): Promise<{ assignmentId: string; minimized: boolean } | { error: string }> => {
      minimizedRef.current = false;
      setActiveJob({
        classroomId: input.classroomId,
        assignmentId: null,
        title: input.title.trim(),
        percent: 0,
        progressLabel: t('liveSession.create.creating'),
        transcriptionPhase: null,
        minimized: false,
      });

      const result = await runLiveSessionCreatePipeline({
        classroomId: input.classroomId,
        syllabusSectionId: input.syllabusSectionId,
        title: input.title,
        sessionType: input.sessionType,
        file: input.file,
        uploadMode: input.uploadMode,
        language: input.language,
        knownDurationSeconds: input.knownDurationSeconds,
        onAssignmentCreated: (assignmentId) => {
          setActiveJob((job) => (job ? { ...job, assignmentId } : job));
          input.onAssignmentCreated?.(assignmentId);
        },
        onProgress: (progress) => {
          setActiveJob((job) =>
            job
              ? {
                  ...job,
                  percent: progress.percent,
                  progressLabel: labelForProgress(progress, t),
                  transcriptionPhase: progress.transcriptionPhase ?? null,
                  chunkIndex: progress.chunkIndex,
                  chunkTotal: progress.chunkTotal,
                  minimized: minimizedRef.current,
                }
              : job
          );
        },
      });

      await queryClient.invalidateQueries({
        queryKey: assignmentKeys.classroomAssignmentLists(input.classroomId),
        exact: false,
      });

      if ('error' in result) {
        clearJob();
        const message = result.conversionError
          ? t('liveSession.create.conversionError')
          : t('liveSession.create.error');
        toast.error(message);
        return { error: result.error };
      }

      const assignmentId = result.assignmentId;
      const classroomId = input.classroomId;
      const wasMinimized = minimizedRef.current;

      clearJob();

      if (wasMinimized) {
        toast.success(t('liveSession.processing.completeTitle'), {
          duration: 10000,
          action: {
            label: t('liveSession.processing.view'),
            onClick: () => navigate(buildRoute.teacherLiveSession(classroomId, assignmentId)),
          },
          cancel: {
            label: t('liveSession.processing.later'),
            onClick: () => {},
          },
        });
      }

      return { assignmentId, minimized: wasMinimized };
    },
    [clearJob, navigate, queryClient, t]
  );

  const value = useMemo(
    (): LiveSessionProcessingContextValue => ({
      activeJob,
      isRunning: activeJob !== null,
      startJob,
      minimizeJob,
    }),
    [activeJob, startJob, minimizeJob]
  );

  return (
    <LiveSessionProcessingContext.Provider value={value}>
      {children}
      {activeJob?.minimized ? <LiveSessionProcessingBanner job={activeJob} /> : null}
    </LiveSessionProcessingContext.Provider>
  );
};

export function useLiveSessionProcessing(): LiveSessionProcessingContextValue {
  const ctx = useContext(LiveSessionProcessingContext);
  if (!ctx) {
    throw new Error('useLiveSessionProcessing must be used within LiveSessionProcessingProvider');
  }
  return ctx;
}

/**
 * Vite logs every HMR apply via console.debug (shows as "Verbose" in Chrome).
 * In folders synced by OneDrive / aggressive watchers, that can mean thousands
 * of identical lines. Filter only the noisy [vite] hot-update lines in development.
 */
if (import.meta.env.DEV) {
  const orig = console.debug.bind(console);
  console.debug = (...args: unknown[]) => {
    const first = args[0];
    if (typeof first === 'string') {
      if (first.startsWith('[vite] hot updated:') || first.startsWith('[vite] css hot updated:')) {
        return;
      }
    }
    orig(...args);
  };
}

/**
 * Activity Query Hooks
 * React Query hooks for activity events
 */

import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { resolveUserDisplayProfiles } from '@/lib/resolveUserDisplayProfiles';

export const activityKeys = {
  all: ['activity'] as const,
  recent: (userId: string) => [...activityKeys.all, 'recent', userId] as const,
};

/**
 * Hook to fetch recent activity for a teacher
 */
export const useRecentActivity = (
  userId: string | undefined,
  teacherProfile: any,
  options?: { isAppAdmin?: boolean }
) => {
  const isAppAdmin = options?.isAppAdmin === true;
  return useQuery({
    queryKey: [...activityKeys.recent(userId || ''), isAppAdmin ? 'all' : 'own'] as const,
    queryFn: async () => {
      if (!userId) throw new Error('Missing user ID');

      let evQ = supabase
        .from('activity_events' as any)
        .select('*')
        .order('created_at', { ascending: false })
        .limit(10);
      if (!isAppAdmin) {
        evQ = evQ.eq('teacher_id', userId);
      }
      const { data: events, error } = await evQ;

      if (error) throw error;
      const rawEvents = (events as any[]) || [];

      // Fetch performer info for each event
      const submissionIds = rawEvents
        .filter((e: any) => e.entity_type === 'submission')
        .map((e: any) => e.entity_id);

      let studentProfilesMap: Record<string, { name: string; avatar_url: string }> = {};
      let submissionById: Record<string, { student_id: string; is_teacher_attempt: boolean }> = {};

      if (submissionIds.length > 0) {
        const { data: submissions } = await supabase
          .from('submissions')
          .select('id, student_id, is_teacher_attempt')
          .in('id', submissionIds);

        const profileMap = await resolveUserDisplayProfiles(
          supabase,
          submissions?.map((s) => s.student_id) ?? []
        );

        if (submissions && submissions.length > 0) {
          studentProfilesMap = submissions.reduce((acc, s) => {
            const profile = profileMap.get(s.student_id);
            if (profile) {
              acc[s.id] = {
                name: profile.full_name ?? 'Unknown',
                avatar_url: profile.avatar_url ?? '',
              };
            }
            return acc;
          }, {} as any);
          submissionById = submissions.reduce(
            (acc, s) => {
              acc[s.id] = {
                student_id: s.student_id,
                is_teacher_attempt: Boolean(s.is_teacher_attempt),
              };
              return acc;
            },
            {} as Record<string, { student_id: string; is_teacher_attempt: boolean }>
          );
        }
      }

      return rawEvents.map((event: any) => {
        let performer = {
          name: teacherProfile?.full_name || 'Teacher',
          avatar_url: teacherProfile?.avatar_url,
        };

        if (event.entity_type === 'submission' && studentProfilesMap[event.entity_id]) {
          performer = studentProfilesMap[event.entity_id];
        }

        let title = event.title as string;
        if (
          event.entity_type === 'submission' &&
          typeof title === 'string' &&
          title.startsWith('Student submitted ')
        ) {
          const meta = submissionById[event.entity_id];
          if (meta && (meta.is_teacher_attempt || meta.student_id === event.teacher_id)) {
            const suffix = title.slice('Student submitted '.length);
            const who = (performer?.name ?? 'Teacher').trim() || 'Teacher';
            title = `${who} submitted ${suffix}`;
          }
        }

        let route = event.route;
        if (event.entity_type === 'submission' && event.entity_id) {
          route = `/teacher/submission/${event.entity_id}`;
        }

        return {
          ...event,
          title,
          performer,
          route,
        };
      });
    },
    enabled: !!userId,
    staleTime: 60 * 1000, // 1 minute
  });
};

/**
 * Analytics Query Hooks
 * React Query hooks for classroom and student analytics
 *
 * Phase 2: Time-based “trend” charts are intentionally not implemented; see
 * `src/lib/analyticsExport.ts` (ANALYTICS_TRENDS_NOT_IMPLEMENTED). Splitting this
 * query with `useQueries` remains optional if profiling shows load issues.
 */

import { useQuery } from '@tanstack/react-query';
import type { Json } from '@/integrations/supabase/types';
import type { AnalyticsAssignmentRef, AnalyticsModuleRef } from '@/lib/analyticsScope';
import type { SyllabusStructureType } from '@/types/syllabus';
import { INCLUDE_TEACHER_5D_EVIDENCE } from '@/config/constants';
import { supabase } from '@/integrations/supabase/client';
import { parseScoreExplanations, type Analytics5dNarrativeRow } from '@/lib/analytics5dEvidence';
import {
  selectBestSubmissionIdForAggregate,
  type SubmissionAttemptForBest,
} from '@/lib/bestSubmission';
import { averageQedMeasuresAcrossSnapshots } from '@/lib/qedMeasures';

type SubRow = {
  id: string;
  student_id: string;
  assignment_id: string;
  status: string;
  attempt_number?: number | null;
  submitted_at?: string | null;
};

type SnapshotRow = {
  user_id: string;
  submission_id: string;
  scores: Json;
  score_explanations: Json | null;
  qed_measures: Json | null;
};

function sectionLabelFor(
  syllabusSectionId: string | null,
  sectionRows: { id: string; title: string }[]
): string {
  if (syllabusSectionId == null) return 'Unplaced';
  return sectionRows.find((s) => s.id === syllabusSectionId)?.title ?? '—';
}

function bestSnapshotsForStudentPair(
  studentId: string,
  assignmentId: string,
  allSubmissions: SubRow[],
  snapshots: SnapshotRow[]
): SnapshotRow[] {
  const attempts = allSubmissions.filter(
    (s) => s.student_id === studentId && s.assignment_id === assignmentId
  );
  if (attempts.length === 0) return [];
  const map = new Map<string, { scores: unknown }>();
  for (const sn of snapshots) {
    if (sn.user_id === studentId && attempts.some((a) => a.id === sn.submission_id)) {
      map.set(sn.submission_id, { scores: sn.scores });
    }
  }
  const forBest: SubmissionAttemptForBest[] = attempts.map((a) => ({
    id: a.id,
    attempt_number: a.attempt_number ?? 1,
    status: a.status as 'in_progress' | 'completed',
    submitted_at: a.submitted_at ?? null,
  }));
  const bestId = selectBestSubmissionIdForAggregate(forBest, map);
  if (!bestId) return [];
  const sn = snapshots.find((s) => s.submission_id === bestId && s.user_id === studentId);
  return sn ? [sn] : [];
}

export const analyticsKeys = {
  all: ['analytics'] as const,
  classroom: (classroomId: string) => [...analyticsKeys.all, 'classroom', classroomId] as const,
  student: (studentId: string, classroomId: string) =>
    [...analyticsKeys.all, 'student', studentId, classroomId] as const,
};

/**
 * Hook to fetch classroom analytics data
 */
export const useClassroomAnalytics = (classroomId: string | undefined) => {
  return useQuery({
    queryKey: analyticsKeys.classroom(classroomId || ''),
    queryFn: async () => {
      if (!classroomId) throw new Error('Missing classroom ID');

      // 1. Fetch enrollment count
      const { count: studentCount } = await supabase
        .from('enrollments')
        .select('*', { count: 'exact', head: true })
        .eq('classroom_id', classroomId);

      // 2. Syllabus + sections (for module filter)
      const { data: syllabusRow } = await supabase
        .from('syllabi')
        .select('id, structure_type')
        .eq('classroom_id', classroomId)
        .maybeSingle();

      const structureType =
        (syllabusRow?.structure_type as SyllabusStructureType | undefined) ?? null;

      const { data: sectionRows } = syllabusRow
        ? await supabase
            .from('syllabus_sections')
            .select('id, title, order_index')
            .eq('syllabus_id', syllabusRow.id)
            .order('order_index', { ascending: true })
        : { data: [] as { id: string; title: string; order_index: number }[] };

      const modules: AnalyticsModuleRef[] = (sectionRows || []).map((s) => ({
        id: s.id,
        title: s.title,
        orderIndex: s.order_index,
      }));

      // 3. Fetch assignments (linked to syllabus sections when present)
      const { data: assignments } = await supabase
        .from('assignments')
        .select('id, title, syllabus_section_id, instructions, status, active, deleted_at')
        .eq('classroom_id', classroomId);

      const assignmentRefs: AnalyticsAssignmentRef[] = (assignments || []).map((a) => ({
        id: a.id,
        title: a.title,
        syllabusSectionId: a.syllabus_section_id,
        instructions: a.instructions,
        status: a.status as AnalyticsAssignmentRef['status'],
        active: a.active,
        deletedAt: a.deleted_at,
      }));

      // 4. Fetch enrollments with student profiles in bulk
      const { data: enrollments } = await supabase
        .from('enrollments')
        .select('student_id, student_profiles(user_id, full_name, avatar_url)')
        .eq('classroom_id', classroomId);

      const studentIds = enrollments?.map((e) => e.student_id) || [];
      const profileMap = new Map(
        enrollments?.map((e) => [e.student_id, (e as any).student_profiles]) || []
      );

      // 5. Fetch all submissions for these assignments
      const assignmentIds = assignments?.map((a) => a.id) || [];
      const { data: allSubmissions } = await supabase
        .from('submissions')
        .select('id, student_id, assignment_id, status, attempt_number, submitted_at')
        .in('assignment_id', assignmentIds);

      const submissionIds = allSubmissions?.map((s) => s.id) || [];

      // 6. Fetch 5D snapshots in bulk
      const { data: snapshots } = await supabase
        .from('five_d_snapshots')
        .select('user_id, submission_id, scores, score_explanations, qed_measures')
        .in('submission_id', submissionIds)
        .eq('classroom_id', classroomId)
        .neq('source', 'onboarding');

      // 7. Fetch feedback in bulk (text for 5D narrative evidence). This hook is teacher-only
      // (`ClassroomAnalytics`). `teacher_feedback` is mapped into narrative rows only when
      // INCLUDE_TEACHER_5D_EVIDENCE; build5dNarrativeEvidence caps and labels it separately.
      const { data: feedbackData } = await supabase
        .from('assignment_feedback')
        .select('submission_id, student_id, assignment_id, student_feedback, teacher_feedback')
        .in('submission_id', submissionIds);

      // 8. Fetch hard skill assessments in bulk
      const { data: hardSkills } = await supabase
        .from('hard_skill_assessments')
        .select('*')
        .in('submission_id', submissionIds);

      const subs = (allSubmissions || []) as SubRow[];
      const snapRows = (snapshots || []) as SnapshotRow[];
      const assignById = new Map(
        (assignments || []).map((a) => [a.id, a] as [string, (typeof assignments)[0]])
      );
      const feedbackBySubmission = new Map(
        (feedbackData || []).map((f) => [f.submission_id, f] as [string, (typeof feedbackData)[0]])
      );

      // Process data into the format needed by ClassroomAnalytics
      const processedStudents = studentIds.map((sid) => {
        const profile = profileMap.get(sid);
        const studentSubmissions = subs.filter((s) => s.student_id === sid);
        const studentFeedback = feedbackData?.filter((f) => f.student_id === sid) || [];

        const studentSnapshotsForAggregate: SnapshotRow[] = [];
        for (const aid of assignmentIds) {
          studentSnapshotsForAggregate.push(
            ...bestSnapshotsForStudentPair(sid, aid, subs, snapRows)
          );
        }

        const narrativeRows: Analytics5dNarrativeRow[] = [];
        for (const sn of studentSnapshotsForAggregate) {
          const sub = subs.find((s) => s.id === sn.submission_id);
          if (!sub) continue;
          const a = assignById.get(sub.assignment_id);
          if (!a) continue;
          const fb = feedbackBySubmission.get(sn.submission_id);
          const studentFb = typeof fb?.student_feedback === 'string' ? fb.student_feedback : null;
          const teacherNote =
            INCLUDE_TEACHER_5D_EVIDENCE && typeof fb?.teacher_feedback === 'string'
              ? fb.teacher_feedback
              : null;
          narrativeRows.push({
            studentId: sid,
            studentName: (profile as { full_name?: string } | undefined)?.full_name || 'Unknown',
            assignmentId: a.id,
            assignmentTitle: a.title,
            sectionTitle: sectionLabelFor(a.syllabus_section_id, sectionRows || []),
            syllabusSectionId: a.syllabus_section_id,
            submissionId: sn.submission_id,
            studentFeedback: studentFb,
            teacherNote,
            scoreExplanations: parseScoreExplanations(sn.score_explanations),
          });
        }

        let averageScores = null;
        let latestQedMeasures = null;
        if (studentSnapshotsForAggregate.length > 0) {
          const totals = { vision: 0, values: 0, thinking: 0, connection: 0, action: 0 };
          studentSnapshotsForAggregate.forEach((s) => {
            const scores = s.scores as Record<string, number>;
            Object.keys(totals).forEach((k) => {
              totals[k as keyof typeof totals] += scores[k] || 0;
            });
          });
          averageScores = Object.keys(totals).reduce(
            (acc, k) => ({
              ...acc,
              [k]: totals[k as keyof typeof totals] / studentSnapshotsForAggregate.length,
            }),
            {} as Record<string, number>
          );
          latestQedMeasures = averageQedMeasuresAcrossSnapshots(studentSnapshotsForAggregate);
        }

        const studentHardSkills =
          hardSkills?.filter((h) => {
            if (h.student_id !== sid) return false;
            const bestForAssignment = bestSnapshotsForStudentPair(
              sid,
              h.assignment_id,
              subs,
              snapRows
            );
            return bestForAssignment.some((b) => b.submission_id === h.submission_id);
          }) || [];

        return {
          id: sid,
          fullName: profile?.full_name || 'Unknown',
          latestScores: averageScores,
          latestQedMeasures,
          feedbackCount: studentFeedback.length,
          submissions: studentSubmissions,
          snapshots: studentSnapshotsForAggregate,
          narrativeRows,
          hardSkills: studentHardSkills,
        };
      });

      const aggregatedSnapshotsFlat = processedStudents.flatMap((s) => s.snapshots);

      return {
        studentCount: studentCount || 0,
        assignmentCount: assignments?.length || 0,
        structureType,
        modules,
        assignments: assignmentRefs,
        students: processedStudents,
        allStudents: processedStudents.map((s) => ({ id: s.id, name: s.fullName })),
        rawSubmissions: allSubmissions || [],
        rawSnapshots: aggregatedSnapshotsFlat,
        rawFeedback: feedbackData || [],
        rawHardSkills: hardSkills || [],
      };
    },
    enabled: !!classroomId,
    staleTime: 2 * 60 * 1000, // 2 minutes
  });
};

/**
 * Calendar Query Hooks
 * React Query hooks for calendar data
 */

import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';

export const calendarKeys = {
  all: ['calendar'] as const,
  teacher: (teacherId: string) => [...calendarKeys.all, 'teacher', teacherId] as const,
  student: (studentId: string) => [...calendarKeys.all, 'student', studentId] as const,
};

/**
 * Hook to fetch all data needed for the teacher calendar
 * @param isAdmin - when true, do not filter by teacher_id (RLS limits rows to what the user may see)
 */
export const useTeacherCalendarData = (
  teacherId: string | undefined,
  options?: { isAdmin?: boolean }
) => {
  const isAdmin = options?.isAdmin === true;
  return useQuery({
    queryKey: [...calendarKeys.teacher(teacherId || ''), isAdmin ? 'all' : 'own'] as const,
    queryFn: async () => {
      if (!teacherId) throw new Error('Missing teacher ID');

      // 1. Fetch classrooms
      let classQ = supabase
        .from('classrooms')
        .select('id, name, subject, start_date, end_date')
        .eq('active', true);
      if (!isAdmin) {
        classQ = classQ.eq('teacher_id', teacherId);
      }
      const { data: classrooms, error: classroomError } = await classQ;

      if (classroomError) throw classroomError;
      if (!classrooms || classrooms.length === 0) return { classrooms: [], assignments: [] };

      const classroomIds = classrooms.map((c) => c.id);

      // 2. Fetch assignments
      const { data: assignmentsData, error: assignError } = await supabase
        .from('assignments')
        .select('id, title, due_at, type, classroom_id, classrooms(name, subject)')
        .in('classroom_id', classroomIds)
        .eq('status', 'published')
        .order('due_at', { ascending: true });

      if (assignError) throw assignError;
      if (!assignmentsData || assignmentsData.length === 0) return { classrooms, assignments: [] };

      const assignmentIds = assignmentsData.map((a) => a.id);

      // 3. Fetch enrollments and submissions in bulk
      const [{ data: allEnrollments }, { data: allSubmissions }] = await Promise.all([
        supabase
          .from('enrollments')
          .select('student_id, classroom_id, student_profiles(user_id, full_name, avatar_url)')
          .in('classroom_id', classroomIds),
        supabase
          .from('submissions')
          .select('student_id, assignment_id')
          .in('assignment_id', assignmentIds),
      ]);

      // 4. Process student profiles into a map
      const studentProfilesMap = new Map();
      allEnrollments?.forEach((e) => {
        if ((e as any).student_profiles) {
          studentProfilesMap.set(e.student_id, (e as any).student_profiles);
        }
      });

      // 5. Process data
      const enrollmentsByClassroom = new Map();
      allEnrollments?.forEach((e) => {
        if (!enrollmentsByClassroom.has(e.classroom_id))
          enrollmentsByClassroom.set(e.classroom_id, []);
        enrollmentsByClassroom.get(e.classroom_id).push(e.student_id);
      });

      const submissionsByAssignment = new Map();
      allSubmissions?.forEach((s) => {
        if (!submissionsByAssignment.has(s.assignment_id))
          submissionsByAssignment.set(s.assignment_id, []);
        submissionsByAssignment.get(s.assignment_id).push(s.student_id);
      });

      const assignmentsWithIncomplete = assignmentsData.map((assignment) => {
        const enrolledStudentIds = enrollmentsByClassroom.get(assignment.classroom_id) || [];
        const completedStudentIds = submissionsByAssignment.get(assignment.id) || [];
        const incompleteStudentIds = enrolledStudentIds.filter(
          (id) => !completedStudentIds.includes(id)
        );

        const incompleteStudents = incompleteStudentIds
          .map((id) => studentProfilesMap.get(id))
          .filter(Boolean);

        return {
          ...assignment,
          incompleteStudents,
          totalStudents: enrolledStudentIds.length,
        };
      });

      return {
        classrooms,
        assignments: assignmentsWithIncomplete,
      };
    },
    enabled: !!teacherId,
    staleTime: 5 * 60 * 1000,
  });
};

/**
 * Hook to fetch all data needed for the student calendar
 */
export const useStudentCalendarData = (studentId: string | undefined) => {
  return useQuery({
    queryKey: calendarKeys.student(studentId || ''),
    queryFn: async () => {
      if (!studentId) throw new Error('Missing student ID');

      const { data: enrollments, error: enrollError } = await supabase
        .from('enrollments')
        .select('classroom_id, classrooms(id, name, subject, start_date, end_date)')
        .eq('student_id', studentId);

      if (enrollError) throw enrollError;

      if (!enrollments?.length) {
        return { classrooms: [], assignments: [] };
      }

      const classroomIds = enrollments.map((e) => e.classroom_id);
      const classroomsData = enrollments.map((e) => e.classrooms).filter(Boolean) as any[];

      const { data: assignmentsData, error: assignError } = await supabase
        .from('assignments')
        .select('id, title, due_at, type, classrooms(name, subject)')
        .in('classroom_id', classroomIds)
        .eq('status', 'published')
        .order('due_at', { ascending: true });

      if (assignError) throw assignError;

      return {
        classrooms: classroomsData,
        assignments: (assignmentsData as any[]) || [],
      };
    },
    enabled: !!studentId,
    staleTime: 5 * 60 * 1000,
  });
};

