import { useState, useEffect } from 'react';
import type { ToastActionElement, ToastProps } from '@/components/ui/toast';
import type { ReactNode } from 'react';

const TOAST_LIMIT = 1;
const TOAST_REMOVE_DELAY = 1000000;

type ToasterToast = ToastProps & {
  id: string;
  title?: ReactNode;
  description?: ReactNode;
  action?: ToastActionElement;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
};

const actionTypes = {
  ADD_TOAST: 'ADD_TOAST',
  UPDATE_TOAST: 'UPDATE_TOAST',
  DISMISS_TOAST: 'DISMISS_TOAST',
  REMOVE_TOAST: 'REMOVE_TOAST',
} as const;

let count = 0;

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER;
  return count.toString();
}

type ActionType = typeof actionTypes;

type Action =
  | {
      type: ActionType['ADD_TOAST'];
      toast: ToasterToast;
    }
  | {
      type: ActionType['UPDATE_TOAST'];
      toast: Partial<ToasterToast>;
    }
  | {
      type: ActionType['DISMISS_TOAST'];
      toastId?: ToasterToast['id'];
    }
  | {
      type: ActionType['REMOVE_TOAST'];
      toastId?: ToasterToast['id'];
    };

interface State {
  toasts: ToasterToast[];
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>();

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return;
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId);
    dispatch({
      type: 'REMOVE_TOAST',
      toastId: toastId,
    });
  }, TOAST_REMOVE_DELAY);

  toastTimeouts.set(toastId, timeout);
};

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case 'ADD_TOAST':
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      };

    case 'UPDATE_TOAST':
      return {
        ...state,
        toasts: state.toasts.map((t) => (t.id === action.toast.id ? { ...t, ...action.toast } : t)),
      };

    case 'DISMISS_TOAST': {
      const { toastId } = action;

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId);
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id);
        });
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t
        ),
      };
    }
    case 'REMOVE_TOAST':
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        };
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      };
  }
};

const listeners: Array<(state: State) => void> = [];

let memoryState: State = { toasts: [] };

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action);
  listeners.forEach((listener) => {
    listener(memoryState);
  });
}

type Toast = Omit<ToasterToast, 'id'>;

function toast({ ...props }: Toast) {
  const id = genId();

  const update = (props: ToasterToast) =>
    dispatch({
      type: 'UPDATE_TOAST',
      toast: { ...props, id },
    });
  const dismiss = () => dispatch({ type: 'DISMISS_TOAST', toastId: id });

  dispatch({
    type: 'ADD_TOAST',
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss();
      },
    },
  });

  return {
    id: id,
    dismiss,
    update,
  };
}

function useToast() {
  const [state, setState] = useState<State>(memoryState);

  useEffect(() => {
    listeners.push(setState);
    return () => {
      const index = listeners.indexOf(setState);
      if (index > -1) {
        listeners.splice(index, 1);
      }
    };
  }, [state]);

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: 'DISMISS_TOAST', toastId }),
  };
}

export { useToast, toast };

import { useEffect, useRef, useCallback } from 'react';
import {
  resolveClipboardCopyFromSelection,
  type ResolvedClipboardCopy,
} from '@/lib/clipboardSourceResolution';
import {
  queueClipboardEvent,
  flushClipboardEvents,
  flushClipboardEventsBeacon,
  linkChatPasteToMessage,
  type ClipboardSourceKind,
} from '@/services/clipboardEventService';

export interface TrackCopyParams {
  copiedText: string;
  sourceKind: ClipboardSourceKind;
  messageIndex?: number;
  sentenceIndex?: number;
  sentenceText?: string;
  contextKey?: string;
}

export interface TrackPasteParams {
  pastedText: string;
  sourceKind: ClipboardSourceKind;
  contextKey?: string;
}

export interface AssignmentClipboardTrackingCallbacks {
  trackCopy: (params: TrackCopyParams) => void;
  trackPaste: (params: TrackPasteParams) => void;
  linkRecentChatPastes: (messageIndex: number) => void;
  handleWorkspaceCopy: (root: HTMLElement | null) => void;
}

interface UseAssignmentClipboardTrackingParams {
  studentId: string | undefined;
  assignmentId: string | undefined;
  submissionId: string | undefined;
  enabled?: boolean;
}

const COPY_DEDUPE_MS = 2000;

export function useAssignmentClipboardTracking({
  studentId,
  assignmentId,
  submissionId,
  enabled = true,
}: UseAssignmentClipboardTrackingParams): AssignmentClipboardTrackingCallbacks {
  const canTrack = enabled && !!studentId && !!assignmentId && !!submissionId;
  const lastCopyRef = useRef<{ text: string; at: number } | null>(null);

  useEffect(() => {
    if (!canTrack) return;

    const handleBeforeUnload = () => {
      flushClipboardEventsBeacon();
    };
    window.addEventListener('beforeunload', handleBeforeUnload);

    return () => {
      window.removeEventListener('beforeunload', handleBeforeUnload);
      void flushClipboardEvents();
    };
  }, [canTrack]);

  const emitCopy = useCallback(
    (params: TrackCopyParams) => {
      if (!canTrack) return;
      const text = params.copiedText.trim();
      if (!text) return;

      const now = Date.now();
      const last = lastCopyRef.current;
      if (last && last.text === text && now - last.at < COPY_DEDUPE_MS) return;
      lastCopyRef.current = { text, at: now };

      queueClipboardEvent({
        submission_id: submissionId!,
        assignment_id: assignmentId!,
        event_type: 'copy',
        source_kind: params.sourceKind,
        copied_text: text,
        message_index: params.messageIndex,
        sentence_index: params.sentenceIndex,
        sentence_text: params.sentenceText,
        context_key: params.contextKey,
      });
    },
    [canTrack, submissionId, assignmentId]
  );

  const trackCopy = useCallback(
    (params: TrackCopyParams) => {
      emitCopy(params);
    },
    [emitCopy]
  );

  const trackPaste = useCallback(
    (params: TrackPasteParams) => {
      if (!canTrack) return;
      const text = params.pastedText.trim();
      if (!text) return;

      queueClipboardEvent({
        submission_id: submissionId!,
        assignment_id: assignmentId!,
        event_type: 'paste',
        source_kind: params.sourceKind,
        pasted_text: text,
        context_key: params.contextKey,
      });
    },
    [canTrack, submissionId, assignmentId]
  );

  const linkRecentChatPastes = useCallback(
    (messageIndex: number) => {
      if (!canTrack || !submissionId) return;
      void linkChatPasteToMessage(submissionId, messageIndex);
    },
    [canTrack, submissionId]
  );

  const handleWorkspaceCopy = useCallback(
    (root: HTMLElement | null) => {
      const resolved: ResolvedClipboardCopy | null = resolveClipboardCopyFromSelection(root);
      if (!resolved) return;
      emitCopy(resolved);
    },
    [emitCopy]
  );

  return {
    trackCopy,
    trackPaste,
    linkRecentChatPastes,
    handleWorkspaceCopy,
  };
}

/**
 * Assignments Hook
 * Custom hook for fetching and managing assignments
 */

import { useState, useEffect, useCallback } from 'react';
import type { Assignment, AssignmentWithClassroom, ApiError } from '@/types';
import { useAuth } from '@/contexts/useAuth';
import { getClassroomAssignments, getStudentAssignments } from '@/services';

interface UseAssignmentsResult {
  assignments: Assignment[] | AssignmentWithClassroom[];
  loading: boolean;
  error: ApiError | null;
  refetch: () => Promise<void>;
}

/**
 * Hook to fetch classroom assignments (teacher view)
 */
export const useClassroomAssignments = (classroomId: string): UseAssignmentsResult => {
  const [assignments, setAssignments] = useState<Assignment[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<ApiError | null>(null);

  const fetchAssignments = useCallback(async () => {
    if (!classroomId) {
      setLoading(false);
      return;
    }

    setLoading(true);
    setError(null);

    const { data, error: fetchError } = await getClassroomAssignments(classroomId);

    if (fetchError) {
      setError(fetchError);
    } else {
      setAssignments(data || []);
    }

    setLoading(false);
  }, [classroomId]);

  useEffect(() => {
    fetchAssignments();
  }, [fetchAssignments]);

  return {
    assignments,
    loading,
    error,
    refetch: fetchAssignments,
  };
};

/**
 * Hook to fetch student assignments
 */
export const useStudentAssignments = (): UseAssignmentsResult => {
  const { user } = useAuth();
  const [assignments, setAssignments] = useState<AssignmentWithClassroom[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<ApiError | null>(null);

