    const { data, error: fetchError } = await getStudentAssignments(user.id);

    if (fetchError) {
      setError(fetchError);
    } else {
      setAssignments(data || []);
    }

    setLoading(false);
  }, [user?.id]);

  useEffect(() => {
    fetchAssignments();
  }, [fetchAssignments]);

  return {
    assignments,
    loading,
    error,
    refetch: fetchAssignments,
  };
};

