    setLoading(true);
    setError(null);

    const { data, error: fetchError } =
      role === USER_ROLES.TEACHER
        ? await getTeacherClassrooms(user.id, {
            allClassroomsForAdmin: user.user_metadata?.role === USER_ROLES.ADMIN,
          })
        : await getStudentClassrooms(user.id);

    if (fetchError) {
      setError(fetchError);
    } else {
      setClassrooms(data || []);
    }

    setLoading(false);
  }, [user?.id, role]);

  useEffect(() => {
    fetchClassrooms();
  }, [fetchClassrooms]);

  return {
    classrooms,
    loading,
    error,
    refetch: fetchClassrooms,
  };
};

/**
 * Conversation Hook
 * Custom hook for managing assignment conversations
 */

import { useState, useEffect, useRef, useCallback } from 'react';
import { toast } from 'sonner';
import type {
  Message,
  ApiError,
  ChatRequest,
  ChatDebugPayload,
  InitialGreetingMode,
} from '@/types';
import { supabase } from '@/api/client';
import { useLanguage } from '@/contexts/LanguageContext';
import { areAllParsedTasksComplete, resolveAssignmentTutorText } from '@/lib/assignmentTasks';
import { hasConversationCompleteMarker } from '@/lib/chatDisplay';
import { rehydrateMessages } from '@/lib/conversationMessages';
import { streamChatMessage } from '@/services';
import { getAssignmentLanguage } from '@/utils/languageDetection';

interface UseConversationResult {
  messages: Message[];
  loading: boolean;
  sending: boolean;
  error: ApiError | null;
  conversationEnded: boolean;
  language: string;
  lastAssistantDebug: ChatDebugPayload | null;
  sendMessage: (
    content: string,
    fileContext?: { name: string; content: string; url?: string; type?: string }
  ) => Promise<void>;
  initializeConversation: (mode?: InitialGreetingMode) => Promise<void>;
}

interface UseConversationParams {
  submissionId: string;
  /** Used only for local language detection (`getAssignmentLanguage`); never sent on the chat API. */
  assignmentInstructions: string;
  /** Prefer over instructions when inferring task progress on reload. */
  studentFacingTask?: string | null;
  assignmentId: string;
  priorSubmissionIds?: string[];
  /** When true, AI "conversation complete" does not lock the chat or drive assignment submission. */
  companionMode?: boolean;
  /** App admins only; server verifies `is_app_admin` before returning debug payloads. */
  debugChat?: boolean;
  /** When false, empty conversations are not auto-started until `autoInitialize` becomes true. */
  autoInitialize?: boolean;
  /** First greeting mode when auto-initializing (e.g. after task-understanding confirmation). */
  initialGreetingMode?: InitialGreetingMode;
  /** Lighter tutoring on follow-up turns after task-explanation overview. */
  postExplainTutoring?: boolean;
}

/**
 * Hook to manage assignment conversation state
 */
export const useConversation = ({
  submissionId,
  assignmentInstructions,
  studentFacingTask,
  assignmentId,
  priorSubmissionIds,
  companionMode = false,
  debugChat = false,
  autoInitialize = true,
  initialGreetingMode = 'default',
  postExplainTutoring = false,
}: UseConversationParams): UseConversationResult => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [conversationEnded, setConversationEnded] = useState(false);
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  const [error, setError] = useState<ApiError | null>(null);
  const [lastAssistantDebug, setLastAssistantDebug] = useState<ChatDebugPayload | null>(null);
  const hasLoadedSubmission = useRef(false);
  const loadCompletedRef = useRef(false);
  const initInFlightRef = useRef(false);
  const initScheduledRef = useRef(false);
  /** Bumped on submission change / unmount so stale stream callbacks are ignored. */
  const streamGenerationRef = useRef(0);
  const autoInitializeRef = useRef(autoInitialize);
  const initialGreetingModeRef = useRef(initialGreetingMode);
  const postExplainTutoringRef = useRef(postExplainTutoring);
  autoInitializeRef.current = autoInitialize;
  initialGreetingModeRef.current = initialGreetingMode;
  postExplainTutoringRef.current = postExplainTutoring;
  const priorSubmissionIdsRef = useRef<string[] | undefined>(priorSubmissionIds);
  priorSubmissionIdsRef.current = priorSubmissionIds;
  const { language: uiLanguage } = useLanguage();

  const language = getAssignmentLanguage(assignmentInstructions, uiLanguage);

  const appendAssistantStreamToken = useCallback((streamGen: number, token: string) => {
    if (streamGen !== streamGenerationRef.current) return;
    setMessages((prev) => {
      const last = prev[prev.length - 1];
      if (last && last.role === 'assistant') {
        const nextContent = last.content + token;
        return [...prev.slice(0, -1), { ...last, content: nextContent }];
      }
      return prev;
    });
  }, []);

  /** Replace the last assistant message body atomically (used for post-stream polish frame). */
  const replaceLastAssistantContent = useCallback((streamGen: number, polished: string) => {
    if (streamGen !== streamGenerationRef.current) return;
    setMessages((prev) => {
      const last = prev[prev.length - 1];
      if (last && last.role === 'assistant') {
        return [...prev.slice(0, -1), { ...last, content: polished }];
      }
      return prev;
    });
  }, []);

  const initializeConversation = useCallback(
    async (mode: InitialGreetingMode = 'default') => {
      if (initInFlightRef.current) {
        return;
      }
      initInFlightRef.current = true;
      const streamGen = streamGenerationRef.current;
      setSending(true);
      try {
        const request: ChatRequest = {
          message: '',
          submissionId,
          assignmentId,
          isInitialGreeting: true,
          initialGreetingMode: mode,
          language,
          ...(priorSubmissionIdsRef.current?.length
            ? { priorSubmissionIds: priorSubmissionIdsRef.current }
            : {}),
          ...(debugChat ? { debugChat: true } : {}),
          ...(postExplainTutoringRef.current ? { postExplainTutoring: true } : {}),
          ...(companionMode ? { companionMode: true } : {}),
        };

        const aiMessage: Message = { role: 'assistant', content: '' };
        setMessages([aiMessage]);
        setLastAssistantDebug(null);

        const { data: endData, error: chatError } = await streamChatMessage(request, (token) => {
          appendAssistantStreamToken(streamGen, token);
        });

        if (streamGen !== streamGenerationRef.current) {
          return;
        }

        if (chatError) {
          setError(chatError);
          toast.error('Error starting conversation');
          setMessages([]);
          return;
        }
        if (endData?.debug) {
          setLastAssistantDebug(endData.debug);
        }
        if (endData?.shouldEnd && !companionMode) {
          setConversationEnded(true);
        }
      } catch {
        if (streamGen === streamGenerationRef.current) {
          toast.error('Error starting conversation');
        }
      } finally {
        if (streamGen === streamGenerationRef.current) {
          initInFlightRef.current = false;
          setSending(false);
          setLoading(false);
        }
      }
    },
    [submissionId, assignmentId, language, debugChat, companionMode, appendAssistantStreamToken]
  );

  const loadConversation = useCallback(async () => {
    loadCompletedRef.current = false;
    try {
      const { data, error: fetchError } = await supabase
        .from('assignment_conversations')
        .select('messages, completed_task_indexes')
        .eq('submission_id', submissionId)
        .maybeSingle();

      if (fetchError && fetchError.code !== 'PGRST116') {
        throw fetchError;
      }

      if (data?.messages && Array.isArray(data.messages) && data.messages.length > 0) {
        const rawMessages = data.messages as unknown as Message[];
        const lastAssistantRaw = [...rawMessages].reverse().find((m) => m.role === 'assistant');
        let markerDetected = false;
        let semanticDetected = false;
        let tasksComplete = false;
        if (lastAssistantRaw && !companionMode) {
          const upperContent = String(lastAssistantRaw.content).toUpperCase();
          const semanticPhrases = [
            'WE ARE DONE',
            'COMPLETED ALL THE TASKS',
            'FINISHED ALL THE TASKS',
            'COMPLETED THE ASSIGNMENT',
            'FINISHED THE ASSIGNMENT',
            'YOU HAVE COMPLETED ALL',
            'YOU COMPLETED ALL',
            "YOU'VE COMPLETED ALL",
            'SUCCESSFULLY ANSWERED ALL',
            'ACTIVITY IS COMPLETE',
            'YES, WE ARE DONE',
            "WE'VE ACTUALLY COMPLETED ALL",
            'JOB ON COMPLETING THE TASKS',
            'COMPLETING THE TASKS',
            'DONE WITH THE TASKS',
            'FINISHED THE TASKS',
            'FINISHED THE ACTIVITY',
            'COMPLETED THE ACTIVITY',
            'YOU HAVE FINISHED',
            "YOU'VE FINISHED",
            'ALL TASKS ARE COMPLETE',
            'סיימנו את המשימה',
            'השלמת את כל המשימות',
            'כל הכבוד על סיום המטלה',
            'סיימת את המטלה',
            'סיימת את הפעילות',
          ];
          markerDetected = hasConversationCompleteMarker(String(lastAssistantRaw.content));
          semanticDetected = semanticPhrases.some((phrase) => upperContent.includes(phrase));
          const tutorText = resolveAssignmentTutorText(assignmentInstructions, studentFacingTask);
          tasksComplete = areAllParsedTasksComplete(tutorText, data.completed_task_indexes);
          if (markerDetected || semanticDetected || tasksComplete) {
            setConversationEnded(true);
          }
        }
        const loadedMessages = rehydrateMessages(rawMessages);
        setMessages(loadedMessages);
      }
      // Empty conversation: greeting is started only by the autoInitialize effect (single init path).
    } catch {
      toast.error('Error loading conversation');
    } finally {
      setLoading(false);
      loadCompletedRef.current = true;
    }
  }, [submissionId, companionMode, assignmentInstructions, studentFacingTask]);

  const loadConversationRef = useRef(loadConversation);
  loadConversationRef.current = loadConversation;

  const sendMessage = async (
    content: string,
    fileContext?: { name: string; content: string; url?: string; type?: string }
  ) => {
    if (!content.trim() && !fileContext) return;

    const userMessage: Message = { role: 'user', content, fileContext };
    const streamGen = streamGenerationRef.current;
    setMessages((prev) => [...prev, userMessage, { role: 'assistant', content: '' }]);
    setSending(true);
    setLastAssistantDebug(null);

    try {
      const request: ChatRequest = {
        message: content,
        submissionId,
        assignmentId,
        language,
        ...(fileContext ? { fileContext } : {}),
        ...(priorSubmissionIdsRef.current?.length
          ? { priorSubmissionIds: priorSubmissionIdsRef.current }
          : {}),
        ...(debugChat ? { debugChat: true } : {}),
        ...(postExplainTutoringRef.current ? { postExplainTutoring: true } : {}),
        ...(companionMode ? { companionMode: true } : {}),
      };

      const { data, error: chatError } = await streamChatMessage(request, (token) => {
        appendAssistantStreamToken(streamGen, token);
      });

      if (streamGen !== streamGenerationRef.current) {
        return;
      }

      if (chatError) {
        setError(chatError);
        toast.error('Error communicating with Perleap agent');
        setMessages((prev) => prev.slice(0, -1));
        return;
      }

      if (data?.debug) {
        setLastAssistantDebug(data.debug);
      }

      if (data?.shouldEnd && !companionMode) {
        setConversationEnded(true);
      }
    } catch {
      toast.error('Error sending message');
    } finally {
      setSending(false);
    }
  };

  useEffect(() => {
    if (!hasLoadedSubmission.current) {
      hasLoadedSubmission.current = true;
      void loadConversationRef.current();
    }

    return () => {
      streamGenerationRef.current += 1;
      initInFlightRef.current = false;
      initScheduledRef.current = false;
      hasLoadedSubmission.current = false;
      loadCompletedRef.current = false;
    };
  }, [submissionId]);

  /** Start greeting when task-understanding gate opens (autoInitialize false → true). */
  useEffect(() => {
    if (
      !autoInitialize ||
      !loadCompletedRef.current ||
      loading ||
      sending ||
      initInFlightRef.current
    ) {
      return;
    }
    if (messages.length > 0) return;
    if (initScheduledRef.current) return;
    initScheduledRef.current = true;
    void initializeConversation(initialGreetingModeRef.current).finally(() => {
      initScheduledRef.current = false;
    });
  }, [autoInitialize, loading, sending, messages.length, initializeConversation]);

  const initializeConversationExposed = useCallback(
    async (mode: InitialGreetingMode = 'default') => {
      await initializeConversation(mode);
    },
    [initializeConversation]
  );

  return {
    messages,
    loading,
    sending,
    error,
    conversationEnded,
    language,
    lastAssistantDebug,
    sendMessage,
    initializeConversation: initializeConversationExposed,
  };
};

import { useGSAP } from '@gsap/react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { useEffect, useRef, useCallback } from 'react';
import {
  fadeInUp,
  staggerFadeInUp,
  scrollFadeIn,
  scrollStaggerIn,
  pageEnter,
  cardHoverEnter,
  cardHoverLeave,
} from '@/lib/animations';

// Register plugins
gsap.registerPlugin(ScrollTrigger, useGSAP);

/**
 * Hook for page transition animation
 * Automatically animates the container on mount
 */
export function usePageTransition(dependencies: React.DependencyList = []) {
  const containerRef = useRef<HTMLDivElement>(null);

  useGSAP(
    () => {
      if (containerRef.current) {
        pageEnter(containerRef.current);
      }
    },
    { scope: containerRef, dependencies: [...dependencies] }
  );

  return containerRef;
}

/**
 * Hook for fade in animation on mount
 */
export function useFadeIn(delay = 0, dependencies: React.DependencyList = []) {
  const elementRef = useRef<HTMLDivElement>(null);

  useGSAP(
    () => {
      if (elementRef.current) {
        fadeInUp(elementRef.current, delay);
      }
    },
    { scope: elementRef, dependencies: [...dependencies] }
  );

  return elementRef;
}

/**
 * Hook for stagger animation on children
 * Optimized to prevent forced reflows by using requestAnimationFrame
 * and only animating when dependencies actually change
 */
export function useStaggerAnimation(
  childSelector = ':scope > *',
  stagger = 0.1,
  dependencies: React.DependencyList = []
) {
  const containerRef = useRef<HTMLDivElement>(null);
  const animationFrameRef = useRef<number | null>(null);
  const lastDepsRef = useRef<string>(JSON.stringify(dependencies));

  useGSAP(
    () => {
      const currentDeps = JSON.stringify(dependencies);

      // Only animate if dependencies actually changed
      if (containerRef.current && currentDeps !== lastDepsRef.current) {
        // Cancel any pending animation
        if (animationFrameRef.current) {
          cancelAnimationFrame(animationFrameRef.current);
        }

        // Use requestAnimationFrame to batch DOM operations and avoid forced reflow
        animationFrameRef.current = requestAnimationFrame(() => {
          if (containerRef.current) {
            const children = containerRef.current.querySelectorAll(childSelector);
            if (children.length > 0) {
              // Reduced duration and simplified animation for better performance
              staggerFadeInUp(children, stagger, 0.3);
            }
          }
          lastDepsRef.current = currentDeps;
        });
      }
    },
    { scope: containerRef, dependencies: [...dependencies] }
  );

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
    };
  }, []);

  return containerRef;
}

/**
 * Hook for scroll-triggered animation
 */
export function useScrollAnimation(options: ScrollTrigger.Vars = {}) {
  const elementRef = useRef<HTMLDivElement>(null);

  useGSAP(
    () => {
      if (elementRef.current) {
        scrollFadeIn(elementRef.current, options);
      }
    },
    { scope: elementRef }
  );

  return elementRef;
}

/**
 * Hook for scroll-triggered stagger animation on children
 */
export function useScrollStagger(childSelector = ':scope > *', options: ScrollTrigger.Vars = {}) {
  const containerRef = useRef<HTMLDivElement>(null);

  useGSAP(
    () => {
      if (containerRef.current) {
        scrollStaggerIn(containerRef.current, childSelector, options);
      }
    },
    { scope: containerRef }
  );

  return containerRef;
}

/**
 * Hook for card hover animations
 */
export function useCardHover() {
  const cardRef = useRef<HTMLDivElement>(null);

  const handleMouseEnter = useCallback(() => {
    if (cardRef.current) {
      cardHoverEnter(cardRef.current);
    }
  }, []);

  const handleMouseLeave = useCallback(() => {
    if (cardRef.current) {
      cardHoverLeave(cardRef.current);
    }
  }, []);

  return {
    ref: cardRef,
    onMouseEnter: handleMouseEnter,
    onMouseLeave: handleMouseLeave,
  };
}

/**
 * Hook for animating a list of items when they change
 */
export function useAnimatedList<T>(items: T[], childSelector = ':scope > *', stagger = 0.05) {
  const containerRef = useRef<HTMLDivElement>(null);
  const prevLengthRef = useRef(items.length);

  useEffect(() => {
    if (containerRef.current && items.length > prevLengthRef.current) {
      // New items added, animate them
      const children = containerRef.current.querySelectorAll(childSelector);
      const newItems = Array.from(children).slice(prevLengthRef.current);

      if (newItems.length > 0) {
        gsap.fromTo(
          newItems,
          { opacity: 0, y: 20 },
          { opacity: 1, y: 0, duration: 0.4, stagger, ease: 'power2.out' }
        );
      }
    }
    prevLengthRef.current = items.length;
  }, [items.length, childSelector, stagger]);

  return containerRef;
}

/**
 * Hook for button press animation
 */
export function useButtonPress() {
  const buttonRef = useRef<HTMLButtonElement>(null);

  const handleClick = useCallback((e: React.MouseEvent) => {
    if (buttonRef.current) {
      gsap.to(buttonRef.current, {
        scale: 0.95,
        duration: 0.1,
        yoyo: true,
        repeat: 1,
        ease: 'power2.inOut',
      });
    }
  }, []);

  return {
    ref: buttonRef,
    onClick: handleClick,
  };
}

/**
 * Hook for pulse animation (notifications, badges)
 */
export function usePulse(active = true) {
  const elementRef = useRef<HTMLDivElement>(null);
  const tweenRef = useRef<gsap.core.Tween | null>(null);

  useEffect(() => {
    if (elementRef.current && active) {
      tweenRef.current = gsap.to(elementRef.current, {
        scale: 1.05,
        duration: 0.6,
        yoyo: true,
        repeat: -1,
        ease: 'power1.inOut',
      });
    }

    return () => {
      if (tweenRef.current) {
        tweenRef.current.kill();
      }
    };
  }, [active]);

  return elementRef;
}

/**
 * Hook for slide in from a direction
 */
export function useSlideIn(
  direction: 'up' | 'down' | 'left' | 'right' = 'up',
  delay = 0,
  dependencies: React.DependencyList = []
) {
  const elementRef = useRef<HTMLDivElement>(null);

  useGSAP(
    () => {
      if (elementRef.current) {
        const fromVars: gsap.TweenVars = { opacity: 0 };
        const toVars: gsap.TweenVars = {
          opacity: 1,
          duration: 0.5,
          delay,
          ease: 'power2.out',
        };

        switch (direction) {
          case 'up':
            fromVars.y = 30;
            toVars.y = 0;
            break;
          case 'down':
            fromVars.y = -30;
            toVars.y = 0;
            break;
          case 'left':
            fromVars.x = 30;
            toVars.x = 0;
            break;
          case 'right':
            fromVars.x = -30;
            toVars.x = 0;
            break;
        }

        gsap.fromTo(elementRef.current, fromVars, toVars);
      }
    },
    { scope: elementRef, dependencies: [...dependencies] }
  );

  return elementRef;
}

export { gsap, ScrollTrigger };

import { useState, useEffect, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { toast } from 'sonner';
import type { Notification, NotificationWithProfile } from '@/types/notifications';
import { getUnreadNotifications, markAsRead, markAllAsRead } from '@/lib/notificationService';

/**
 * Custom hook for managing user notifications
 * Provides notification state and actions for notification management
 *
 * @param userId - The ID of the user to fetch notifications for
 * @returns Notification state and management functions
 */
export const useNotifications = (userId: string | undefined) => {
  const { t } = useTranslation();
  const [notifications, setNotifications] = useState<NotificationWithProfile[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [loading, setLoading] = useState(true);

  const fetchNotifications = useCallback(async () => {
    if (!userId) return;

    setLoading(true);
    try {
      const notifs = await getUnreadNotifications(userId);
      setNotifications(notifs);
      setUnreadCount(notifs.length);
    } catch (error) {
      console.error('Error fetching notifications:', error);
    } finally {
      setLoading(false);
    }
  }, [userId]);

  useEffect(() => {
    fetchNotifications();
  }, [fetchNotifications]);

  const handleMarkAsRead = useCallback(
    async (notificationId: string) => {
      try {
        await markAsRead(notificationId);
        setNotifications((prev) => prev.filter((n) => n.id !== notificationId));
        setUnreadCount((prev) => Math.max(0, prev - 1));
      } catch (error) {
        console.error('Error marking notification as read:', error);
        toast.error(t('notifications.errors.markingRead'));
      }
    },
    [t]
  );

  const handleMarkAllAsRead = useCallback(async () => {
    if (!userId) return;

    try {
      await markAllAsRead(userId);
      setNotifications([]);
      setUnreadCount(0);
      toast.success(t('notifications.success.markedAllRead'));
    } catch (error) {
      console.error('Error marking all as read:', error);
      toast.error(t('notifications.errors.markingRead'));
    }
  }, [userId, t]);

  return {
    notifications,
    unreadCount,
    loading,
    fetchNotifications,
    handleMarkAsRead,
    handleMarkAllAsRead,
  };
};

import { useEffect, useRef, useCallback } from 'react';
import type { UnderstandingCueResult } from '@/lib/understandingCueDetection';
import {
  trackNuanceEvent,
  flushNuanceEvents,
  flushNuanceEventsBeacon,
  type NuanceEventType,
} from '@/services/nuanceEventService';

/** No mouse/keyboard activity for this long while tab is visible counts as in-tab idle. */
export const IN_TAB_IDLE_THRESHOLD_MS = 30_000;

export interface NuanceTrackingCallbacks {
  trackResponseSubmitted: (responseTimeMs: number, messageIndex: number) => void;
  trackResponseStarted: (messageIndex: number) => void;
  recordAiMessageArrival: () => void;
  getTimeSinceLastAiMessage: () => number | null;
  trackUnderstandingCue: (
    result: UnderstandingCueResult,
    messageLength: number,
    messageIndex: number
  ) => void;
}

interface UseNuanceTrackingParams {
  studentId: string | undefined;
  assignmentId: string | undefined;
  submissionId: string | undefined;
  enabled?: boolean;
}

export function useNuanceTracking({
  studentId,
  assignmentId,
  submissionId,
  enabled = true,
}: UseNuanceTrackingParams): NuanceTrackingCallbacks {
  const lastAiMessageTimestamp = useRef<number | null>(null);
  const sessionActive = useRef(false);
  const hasTrackedOpen = useRef(false);
  const inTabIdleActive = useRef(false);
  const idleTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const canTrack = enabled && !!studentId && !!assignmentId;

  const emit = useCallback(
    (eventType: NuanceEventType, metadata?: Record<string, unknown>) => {
      if (!canTrack) return;
      trackNuanceEvent({
        student_id: studentId!,
        assignment_id: assignmentId!,
        submission_id: submissionId,
        event_type: eventType,
        metadata,
      });
    },
    [canTrack, studentId, assignmentId, submissionId]
  );

  const clearIdleTimer = useCallback(() => {
    if (idleTimerRef.current !== null) {
      clearTimeout(idleTimerRef.current);
      idleTimerRef.current = null;
    }
  }, []);

  const endInTabIdle = useCallback(() => {
    if (inTabIdleActive.current) {
      emit('in_tab_idle_end');
      inTabIdleActive.current = false;
    }
  }, [emit]);

  const scheduleIdleTimer = useCallback(() => {
    clearIdleTimer();
    if (document.visibilityState !== 'visible') return;

    idleTimerRef.current = setTimeout(() => {
      idleTimerRef.current = null;
      if (document.visibilityState !== 'visible' || inTabIdleActive.current) return;
      inTabIdleActive.current = true;
      emit('in_tab_idle_start');
    }, IN_TAB_IDLE_THRESHOLD_MS);
  }, [clearIdleTimer, emit]);

  const noteUserActivity = useCallback(() => {
    if (document.visibilityState !== 'visible') return;
    endInTabIdle();
    scheduleIdleTimer();
  }, [endInTabIdle, scheduleIdleTimer]);

  // -- Activity opened + session started on mount --
  useEffect(() => {
    if (!canTrack) return;

    if (!hasTrackedOpen.current) {
      emit('activity_opened');
      hasTrackedOpen.current = true;
    }

    emit('session_started');
    sessionActive.current = true;
    scheduleIdleTimer();

    const activityEvents = ['keydown', 'pointerdown', 'scroll', 'touchstart'] as const;
    const handleActivity = () => noteUserActivity();

    // -- Visibility change (blur / focus) --
    const handleVisibility = () => {
      if (document.visibilityState === 'hidden') {
        clearIdleTimer();
        endInTabIdle();
        emit('page_blur');
      } else {
        emit('page_focus');
        scheduleIdleTimer();
      }
    };
    document.addEventListener('visibilitychange', handleVisibility);
    for (const eventName of activityEvents) {
      document.addEventListener(eventName, handleActivity, { passive: true });
    }

    // -- Page unload (best-effort beacon flush) --
    const handleBeforeUnload = () => {
      if (sessionActive.current) {
        clearIdleTimer();
        endInTabIdle();
        emit('session_ended');
        flushNuanceEventsBeacon();
      }
    };
    window.addEventListener('beforeunload', handleBeforeUnload);

    return () => {
      document.removeEventListener('visibilitychange', handleVisibility);
      for (const eventName of activityEvents) {
        document.removeEventListener(eventName, handleActivity);
      }
      window.removeEventListener('beforeunload', handleBeforeUnload);
      clearIdleTimer();
      endInTabIdle();

      if (sessionActive.current) {
        emit('session_ended');
        sessionActive.current = false;
        flushNuanceEvents();
      }
    };
  }, [canTrack, emit, clearIdleTimer, endInTabIdle, noteUserActivity, scheduleIdleTimer]);

  const trackResponseSubmitted = useCallback(
    (responseTimeMs: number, messageIndex: number) => {
      noteUserActivity();
      emit('response_submitted', {
        response_time_ms: responseTimeMs,
        message_index: messageIndex,
      });
    },
    [emit, noteUserActivity]
  );

  const trackResponseStarted = useCallback(
    (messageIndex: number) => {
      noteUserActivity();
      emit('response_started', { message_index: messageIndex });
    },
    [emit, noteUserActivity]
  );

  const recordAiMessageArrival = useCallback(() => {
    lastAiMessageTimestamp.current = Date.now();
  }, []);

  const getTimeSinceLastAiMessage = useCallback((): number | null => {
    if (lastAiMessageTimestamp.current === null) return null;
    return Date.now() - lastAiMessageTimestamp.current;
  }, []);

  const trackUnderstandingCue = useCallback(
    (result: UnderstandingCueResult, messageLength: number, messageIndex: number) => {
      if (import.meta.env.DEV) {
        // eslint-disable-next-line no-console -- dev-only visibility for understanding cue path
        console.debug('[Nuance] understanding cue (on send)', {
          hit: result.hit,
          reasonCodes: result.reasonCodes,
          localeHint: result.localeHint,
          messageIndex,
          messageLength,
          willQueueToSupabase: result.hit && canTrack,
        });
      }
      if (!result.hit) return;
      if (!canTrack) {
        if (import.meta.env.DEV) {
          // eslint-disable-next-line no-console
          console.debug(
            '[Nuance] understanding_cue not emitted — tracking off (check: submission+no feedback, studentId, assignmentId, useNuanceTracking enabled)',
            { enabled, hasStudentId: !!studentId, hasAssignmentId: !!assignmentId }
          );
        }
        return;
      }
      emit('understanding_cue', {
        reason_codes: result.reasonCodes,
        locale_hint: result.localeHint,
        length_bucket: messageLength < 50 ? 'short' : messageLength < 200 ? 'medium' : 'long',
        message_index: messageIndex,
      });
    },
    [canTrack, emit, enabled, studentId, assignmentId]
  );

  return {
    trackResponseSubmitted,
    trackResponseStarted,
    recordAiMessageArrival,
    getTimeSinceLastAiMessage,
    trackUnderstandingCue,
  };
}

import { useState, useEffect, useCallback } from 'react';
import type { Dispatch, SetStateAction } from 'react';

/**
 * A hook that persists state to localStorage/sessionStorage
 * This helps preserve user data when navigating back/forward in the browser
 *
 * @param key - Unique key for storing the state
 * @param initialValue - Initial value if no stored value exists
 * @param storage - 'local' for localStorage (persists across sessions) or 'session' for sessionStorage (cleared on tab close)
 */
export function usePersistedState<T>(
  key: string,
  initialValue: T,
  storage: 'local' | 'session' = 'session'
): [T, Dispatch<SetStateAction<T>>, () => void] {
  const storageObject = storage === 'local' ? localStorage : sessionStorage;

  // Get stored value or use initial value
  const [state, setState] = useState<T>(() => {
    try {
      const item = storageObject.getItem(key);
      return item ? JSON.parse(item) : initialValue;
    } catch {
      return initialValue;
    }
  });

  // Update storage when state changes
  useEffect(() => {
    try {
      storageObject.setItem(key, JSON.stringify(state));
    } catch {
      // Silently fail if storage is full or unavailable
    }
  }, [key, state, storageObject]);

  // Function to clear the persisted state
  const clearPersistedState = useCallback(() => {
    try {
      storageObject.removeItem(key);
      setState(initialValue);
    } catch {
      // Silently fail if storage is unavailable
    }
  }, [key, initialValue, storageObject]);

  return [state, setState, clearPersistedState];
}

/**
 * Save form data to prevent loss on navigation
 * Useful for forms, text inputs, etc.
 *
 * Example usage:
 * ```tsx
 * const [formData, setFormData, clearFormData] = usePersistedState('my-form', {
 *   name: '',
 *   email: ''
 * });
 *
 * // On successful form submission:
 * clearFormData(); // Clear the saved data
 * ```
 */
export const usePersistedFormState = <T extends Record<string, any>>(
  formKey: string,
  initialValues: T
) => {
  return usePersistedState<T>(`form-${formKey}`, initialValues, 'session');
};

/**
 * Clear all persisted form data for a specific user
 * Useful when logging out or switching accounts
 */
export const clearAllPersistedForms = () => {
  const keys = Object.keys(sessionStorage);
  keys.forEach((key) => {
    if (key.startsWith('form-')) {
      sessionStorage.removeItem(key);
    }
  });
};

/**
 * Single-section module flow data for student sequential access (route guards + shared with list logic).
 */

import { useMemo } from 'react';
import type { StudentFlowProgressContext } from '@/lib/moduleFlowStudent';
import type { ModuleFlowStep } from '@/types/syllabus';
import { useSyllabus, useClassroomAssignments } from '@/hooks/queries';
import {
  useAssignmentFlowProgressMaps,
  useModuleFlowSteps,
  useStudentModuleFlowProgressMap,
} from '@/hooks/queries/useModuleFlowQueries';
import {
  computeDefaultModuleFlow,
  getOrderedActivityCenterFlowSteps,
  studentModuleFlowStepOptions,
  type ComputedFlowItem,
} from '@/lib/moduleFlow';

export function useStudentSectionModuleFlow(
  classroomId: string | undefined,
  sectionId: string | undefined,
  studentId: string | undefined
) {
  const { data: syllabus, isLoading: syllabusLoading } = useSyllabus(classroomId);
  const { data: assignments = [] } = useClassroomAssignments(classroomId);
  const { data: flowSteps = [], isLoading: flowLoading } = useModuleFlowSteps(sectionId);

  const sectionResources = useMemo(
    () => (sectionId ? (syllabus?.section_resources?.[sectionId] ?? []) : []),
    [syllabus?.section_resources, sectionId]
  );

  const studentFlowOpts = useMemo(
    () => studentModuleFlowStepOptions(assignments as Array<{ id: string; type?: string | null }>),
    [assignments]
  );

  const orderedPersisted = useMemo(
    () => getOrderedActivityCenterFlowSteps(flowSteps, sectionResources, studentFlowOpts),
    [flowSteps, sectionResources, studentFlowOpts]
  );

  const computed = useMemo(
    () =>
      sectionId
        ? computeDefaultModuleFlow(
            sectionId,
            sectionResources,
            assignments as {
              id: string;
              syllabus_section_id?: string | null;
              due_at?: string | null;
              type?: string | null;
            }[],
            studentFlowOpts
          )
        : [],
    [sectionId, sectionResources, assignments]
  );

  const usePersistedFlow = orderedPersisted.length > 0;

  const flowStepIds = useMemo(() => orderedPersisted.map((s) => s.id), [orderedPersisted]);

  const { data: progressByStep = {} } = useStudentModuleFlowProgressMap(studentId, flowStepIds);

  const assignmentIdsInSection = useMemo(() => {
    const set = new Set<string>();
    orderedPersisted.forEach((s) => {
      if (s.step_kind === 'assignment' && s.assignment_id) set.add(s.assignment_id);
    });
    computed.forEach((c) => {
      if (c.kind === 'assignment') set.add(c.assignment_id);
    });
    return [...set];
  }, [orderedPersisted, computed]);

  const { data: flowMaps, isLoading: assignmentDoneLoading } = useAssignmentFlowProgressMaps(
    assignmentIdsInSection,
    studentId,
    !!studentId && !!sectionId
  );
  const assignmentDoneMap = flowMaps?.completedMap ?? {};
  const assignmentHasSubmissionRowMap = flowMaps?.hasAnyRowMap ?? {};

  const ctx: StudentFlowProgressContext = useMemo(
    () => ({ progressByStep, assignmentDoneMap, assignmentHasSubmissionRowMap }),
    [progressByStep, assignmentDoneMap, assignmentHasSubmissionRowMap]
  );

  const loading =
    !!classroomId && !!sectionId && (syllabusLoading || flowLoading || assignmentDoneLoading);

  return {
    loading,
    syllabus,
    sectionResources,
    orderedPersisted,
    computed,
    usePersistedFlow,
    ctx,
    assignments,
  };
}

export type StudentSectionModuleFlowResult = {
  loading: boolean;
  orderedPersisted: ModuleFlowStep[];
  computed: ComputedFlowItem[];
  usePersistedFlow: boolean;
  ctx: StudentFlowProgressContext;
};

import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';

// Import translation files directly
import enTranslations from '../locales/en/translation.json';
import heTranslations from '../locales/he/translation.json';

// Get initial language from localStorage before init - with validation
const getInitialLanguage = (): string => {
  try {
    const stored = localStorage.getItem('language_preference');
    // Only accept valid languages, ignore browser language
    if (stored === 'he' || stored === 'en') {
      return stored;
    }
  } catch (e) {
    console.error('Error reading language preference:', e);
  }
  return 'en';
};

const storedLanguage = getInitialLanguage();

i18n.use(initReactI18next).init({
  resources: {
    en: {
      translation: enTranslations,
    },
    he: {
      translation: heTranslations,
    },
  },
  fallbackLng: 'en',
  lng: storedLanguage,

  // Disable language detection to prevent automatic language changes
  detection: {
    order: [],
    caches: [],
  },

  interpolation: {
    escapeValue: false, // React already escapes values
  },

  react: {
    useSuspense: false,
  },
});

// Listen for language changes and persist to localStorage
i18n.on('languageChanged', (lng) => {
  // Only save valid languages
  if (lng === 'he' || lng === 'en') {
    try {
      localStorage.setItem('language_preference', lng);
    } catch (e) {
      console.error('Error saving language preference:', e);
    }
  }

  // Update HTML dir attribute for RTL
  document.documentElement.dir = lng === 'he' ? 'rtl' : 'ltr';
  document.documentElement.lang = lng;
});

// Set initial direction BEFORE React renders
const initialLang = getInitialLanguage();
document.documentElement.dir = initialLang === 'he' ? 'rtl' : 'ltr';
document.documentElement.lang = initialLang;

export default i18n;

