/**
 * Build v1 course package JSON from live DB-shaped data (no I/O).
 */

import type { Json } from '@/integrations/supabase/types';
import type {
  CoursePackageActivityV1,
  CoursePackageAssignmentActivityLinkV1,
  CoursePackageAssignmentV1,
  CoursePackageClassroomV1,
  CoursePackageCourseV1,
  CoursePackageGradingCategoryV1,
  CoursePackageModuleFlowStepV1,
  CoursePackagePolicyV1,
  CoursePackageSectionV1,
  CoursePackageSyllabusV1,
  PerleapCoursePackageV1,
  CoursePackageActivityV2,
  CoursePackageAssignmentActivityLinkV2,
  CoursePackageAssignmentV2,
  CoursePackageCourseV2,
  CoursePackageGradingCategoryV2,
  CoursePackageModuleFlowStepV2,
  CoursePackageSectionV2,
  CoursePackageSyllabusV2,
  PerleapCoursePackageV2,
} from '@/types/coursePackage';
import type { Assignment } from '@/types/models';
import type {
  GradingCategory,
  ModuleFlowStep,
  SectionResource,
  SyllabusSection,
  SyllabusWithSections,
  AssignmentModuleActivity,
} from '@/types/syllabus';
import {
  COURSE_PACKAGE_FORMAT,
  COURSE_PACKAGE_VERSION,
  COURSE_PACKAGE_VERSION_V2,
} from '@/types/coursePackage';

export type BuildCoursePackageInput = {
  classroom: Record<string, unknown>;
  syllabus: SyllabusWithSections | null;
  assignments: Array<Record<string, unknown>>;
  moduleFlowSteps: ModuleFlowStep[];
  assignmentModuleActivitiesByAssignmentId: Record<string, AssignmentModuleActivity[]>;
  sourceClassroomName?: string | null;
};

function sectionLocalId(index: number): string {
  return `sec_${index}`;
}

function gradingLocalId(index: number): string {
  return `gc_${index}`;
}

function activityLocalId(sectionIndex: number, activityIndex: number): string {
  return `act_${sectionIndex}_${activityIndex}`;
}

function assignmentLocalId(index: number): string {
  return `asg_${index}`;
}

function toJsonArrayField(v: unknown): Json | null {
  if (v === null || v === undefined) return null;
  if (Array.isArray(v)) return v as unknown as Json;
  return v as Json;
}

export function buildCoursePackageV1(input: BuildCoursePackageInput): PerleapCoursePackageV1 {
  const c = input.classroom;
  const learningOutcomes = c.learning_outcomes;
  const keyChallenges = c.key_challenges;

  const classroomPayload: CoursePackageClassroomV1 = {
    name: String(c.name ?? 'Course'),
    subject: c.subject != null ? String(c.subject) : null,
    goals: c.goals != null ? String(c.goals) : null,
    course_title: c.course_title != null ? String(c.course_title) : null,
    course_duration: c.course_duration != null ? String(c.course_duration) : null,
    start_date: c.start_date != null ? String(c.start_date) : null,
    end_date: c.end_date != null ? String(c.end_date) : null,
    course_outline: c.course_outline != null ? String(c.course_outline) : null,
    resources: c.resources != null ? String(c.resources) : null,
    learning_outcomes: toJsonArrayField(learningOutcomes),
    key_challenges: toJsonArrayField(keyChallenges),
    domains: (c.domains as Json | null) ?? null,
    materials: (c.materials as Json | null) ?? null,
  };

  const syllabusData = input.syllabus;
  let syllabusPayload: CoursePackageSyllabusV1 | null = null;

  const sectionUuidToLocal = new Map<string, string>();
  const activityUuidToLocal = new Map<string, string>();
  const gcUuidToLocal = new Map<string, string>();

  if (syllabusData) {
    const policies: CoursePackagePolicyV1[] = (syllabusData.policies ?? []).map((p, i) => ({
      type: p.type,
      label: p.label,
      content: p.content,
      order_index: p.order_index ?? i,
    }));

    const gradingSorted = [...(syllabusData.grading_categories ?? [])].sort(
      (a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime()
    );
    const grading_categories: CoursePackageGradingCategoryV1[] = gradingSorted.map(
      (g: GradingCategory, i) => {
        const lid = gradingLocalId(i);
        gcUuidToLocal.set(g.id, lid);
        return { local_id: lid, name: g.name, weight: g.weight };
      }
    );

    const sectionsSorted = [...syllabusData.sections].sort(
      (a, b) => (a.order_index ?? 0) - (b.order_index ?? 0)
    );

    sectionsSorted.forEach((s: SyllabusSection, si: number) => {
      sectionUuidToLocal.set(s.id, sectionLocalId(si));
    });

    const resourceMap = syllabusData.section_resources ?? {};
    const sections: CoursePackageSectionV1[] = sectionsSorted.map(
      (s: SyllabusSection, si: number) => {
        const prereqLocal = (s.prerequisites ?? [])
          .map((pid) => sectionUuidToLocal.get(pid))
          .filter((x): x is string => Boolean(x));

        const rawActs = (resourceMap[String(s.id)] ?? []) as SectionResource[];
        const actsSorted = [...rawActs].sort((a, b) => (a.order_index ?? 0) - (b.order_index ?? 0));
        const activities: CoursePackageActivityV1[] = actsSorted.map((r, ai) => {
          const lid = activityLocalId(si, ai);
          activityUuidToLocal.set(r.id, lid);
          const a: CoursePackageActivityV1 = {
            local_id: lid,
            resource_type: r.resource_type,
            title: r.title,
            order_index: r.order_index,
            status: (r.status as string) || 'published',
            lesson_content: (r.lesson_content as unknown as Json | null) ?? null,
            summary: r.summary ?? null,
            body_text: r.body_text ?? null,
            file_path: r.file_path ?? null,
            url: r.url ?? null,
            mime_type: r.mime_type ?? null,
            file_size: r.file_size ?? null,
            estimated_duration_minutes: r.estimated_duration_minutes ?? null,
          };
          return a;
        });

        const sec: CoursePackageSectionV1 = {
          local_id: sectionLocalId(si),
          title: s.title,
          description: s.description,
          content: s.content,
          order_index: s.order_index,
          start_date: s.start_date,
          end_date: s.end_date,
          objectives: s.objectives,
          resources: s.resources,
          notes: s.notes,
          completion_status: s.completion_status,
          prerequisites_local_ids: prereqLocal,
          is_locked: s.is_locked,
          activities,
        };
        return sec;
      }
    );

    syllabusPayload = {
      title: syllabusData.title,
      summary: syllabusData.summary,
      structure_type: syllabusData.structure_type,
      policies,
      status: syllabusData.status,
      release_mode: syllabusData.release_mode,
      published_at: syllabusData.published_at,
      accent_color: syllabusData.accent_color,
      banner_url: syllabusData.banner_url,
      section_label_override: syllabusData.section_label_override,
      custom_settings:
        syllabusData.custom_settings && typeof syllabusData.custom_settings === 'object'
          ? syllabusData.custom_settings
          : {},
      grading_categories,
      sections,
    };
  }

  const roster = input.assignments
    .map((row) => {
      const { student_profiles: _sp, submissions: _sub, ...rest } = row as Record<string, unknown>;
      return rest;
    })
    .sort(
      (a, b) =>
        new Date(String(a.created_at ?? 0)).getTime() -
        new Date(String(b.created_at ?? 0)).getTime()
    );

  const assignmentUuidToLocal = new Map<string, string>();
  const exportAssignments: CoursePackageAssignmentV1[] = roster.map((row, i) => {
    const lid = assignmentLocalId(i);
    const id = String((row as { id: string }).id);
    assignmentUuidToLocal.set(id, lid);

    const a = row as unknown as Assignment & {
      syllabus_section_id?: string | null;
      grading_category_id?: string | null;
      target_dimensions?: unknown;
      materials?: unknown;
    };

    const sectionRef = a.syllabus_section_id
      ? (sectionUuidToLocal.get(a.syllabus_section_id) ?? null)
      : null;
    const gcRef = a.grading_category_id ? (gcUuidToLocal.get(a.grading_category_id) ?? null) : null;

    return {
      local_id: lid,
      syllabus_section_ref: sectionRef,
      grading_category_ref: gcRef,
      title: a.title,
      instructions: a.instructions,
      student_facing_task: a.student_facing_task ?? null,
      type: a.type,
      status: a.status,
      due_at: a.due_at,
      target_dimensions: (a.target_dimensions as unknown as Json) ?? ({} as Json),
      personalization_flag: Boolean(a.personalization_flag),
      enable_ai_feedback: a.enable_ai_feedback !== false,
      auto_publish_ai_feedback: a.auto_publish_ai_feedback !== false,
      attempt_mode: a.attempt_mode ?? null,
      materials: (a.materials as unknown as Json | null) ?? null,
      hard_skills:
        typeof a.hard_skills === 'string'
          ? a.hard_skills
          : a.hard_skills != null
            ? JSON.stringify(a.hard_skills)
            : null,
      hard_skill_domain: a.hard_skill_domain ?? null,
      assigned_student_id: null,
    };
  });

  const assignment_activity_links: CoursePackageAssignmentActivityLinkV1[][] =
    exportAssignments.map((_, i) => {
      const aid = String((roster[i] as { id: string }).id);
      const links = input.assignmentModuleActivitiesByAssignmentId[aid] ?? [];
      const sorted = [...links].sort((x, y) => x.order_index - y.order_index);
      return sorted.map((l) => {
        const actRef = activityUuidToLocal.get(l.activity_list_id);
        return {
          activity_ref: actRef ?? `missing_${l.activity_list_id}`,
          order_index: l.order_index,
          include_in_ai_context: l.include_in_ai_context,
        };
      });
    });

  let module_flow_by_section: CoursePackageModuleFlowStepV1[][] | null = null;
  if (syllabusData && sectionUuidToLocal.size > 0) {
    const stepsBySection = new Map<string, ModuleFlowStep[]>();
    for (const st of input.moduleFlowSteps) {
      const list = stepsBySection.get(st.section_id) ?? [];
      list.push(st);
      stepsBySection.set(st.section_id, list);
    }
    const sectionsOrder = [...syllabusData.sections].sort(
      (a, b) => (a.order_index ?? 0) - (b.order_index ?? 0)
    );
    module_flow_by_section = sectionsOrder.map((sec) => {
      const steps = (stepsBySection.get(sec.id) ?? []).sort(
        (a, b) => a.order_index - b.order_index
      );
      return steps.map((st, idx) => {
        const step: CoursePackageModuleFlowStepV1 = {
          order_index: idx,
          step_kind: st.step_kind,
          activity_ref:
            st.step_kind === 'resource' && st.activity_list_id
              ? (activityUuidToLocal.get(st.activity_list_id) ?? null)
              : null,
          assignment_ref:
            st.step_kind === 'assignment' && st.assignment_id
              ? (assignmentUuidToLocal.get(st.assignment_id) ?? null)
              : null,
        };
        return step;
      });
    });
  }

  const course: CoursePackageCourseV1 = {
    classroom: classroomPayload,
    syllabus: syllabusPayload,
    assignments: exportAssignments,
    assignment_activity_links,
    module_flow_by_section,
  };

  const pkg: PerleapCoursePackageV1 = {
    format: COURSE_PACKAGE_FORMAT,
    version: COURSE_PACKAGE_VERSION,
    exported_at: new Date().toISOString(),
    source_classroom_name: input.sourceClassroomName ?? (String(c.name ?? null) || null),
    course,
  };
  return pkg;
}

/**
 * Build v2 merge-safe package: real UUIDs for entities and cross-refs so import can PATCH in place.
 */
export function buildCoursePackageV2(input: BuildCoursePackageInput): PerleapCoursePackageV2 {
  const c = input.classroom;
  const classroomIdStr =
    typeof c.id === 'string' ? c.id : String((c.id as unknown as string | undefined) ?? '');
  const learningOutcomes = c.learning_outcomes;
  const keyChallenges = c.key_challenges;

  const classroomPayload: CoursePackageCourseV2['classroom'] = {
    id: classroomIdStr || undefined,
    name: String(c.name ?? 'Course'),
    subject: c.subject != null ? String(c.subject) : null,
    goals: c.goals != null ? String(c.goals) : null,
    course_title: c.course_title != null ? String(c.course_title) : null,
    course_duration: c.course_duration != null ? String(c.course_duration) : null,
    start_date: c.start_date != null ? String(c.start_date) : null,
    end_date: c.end_date != null ? String(c.end_date) : null,
    course_outline: c.course_outline != null ? String(c.course_outline) : null,
    resources: c.resources != null ? String(c.resources) : null,
    learning_outcomes: toJsonArrayField(learningOutcomes),
    key_challenges: toJsonArrayField(keyChallenges),
    domains: (c.domains as Json | null) ?? null,
    materials: (c.materials as Json | null) ?? null,
  };

  const syllabusData = input.syllabus;
  let syllabusPayload: CoursePackageSyllabusV2 | null = null;

  const sectionUuidSet = new Set<string>();

  if (syllabusData) {
    const policies: CoursePackagePolicyV1[] = (syllabusData.policies ?? []).map((p, i) => ({
      type: p.type,
      label: p.label,
      content: p.content,
      order_index: p.order_index ?? i,
    }));

    const gradingSorted = [...(syllabusData.grading_categories ?? [])].sort(
      (a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime()
    );

    const grading_categories: CoursePackageGradingCategoryV2[] = gradingSorted.map(
      (g: GradingCategory) => ({
        id: g.id,
        name: g.name,
        weight: g.weight,
      })
    );

    const sectionsSorted = [...syllabusData.sections].sort(
      (a, b) => (a.order_index ?? 0) - (b.order_index ?? 0)
    );
    sectionsSorted.forEach((s) => sectionUuidSet.add(s.id));

    const resourceMap = syllabusData.section_resources ?? {};
    const sections: CoursePackageSectionV2[] = sectionsSorted.map(
      (s: SyllabusSection, si: number) => {
        const prereqUuids = (s.prerequisites ?? []).filter((pid) => sectionUuidSet.has(pid));

        const rawActs = (resourceMap[String(s.id)] ?? []) as SectionResource[];
        const actsSorted = [...rawActs].sort((a, b) => (a.order_index ?? 0) - (b.order_index ?? 0));

        const activities: CoursePackageActivityV2[] = actsSorted.map((r, ai) => {
          const lid = activityLocalId(si, ai);
          const act: CoursePackageActivityV2 = {
            local_id: lid,
            id: r.id,
            resource_type: r.resource_type,
            title: r.title,
            order_index: r.order_index,
            status: (r.status as string) || 'published',
            lesson_content: (r.lesson_content as unknown as Json | null) ?? null,
            summary: r.summary ?? null,
            body_text: r.body_text ?? null,
            file_path: r.file_path ?? null,
            url: r.url ?? null,
            mime_type: r.mime_type ?? null,
            file_size: r.file_size ?? null,
            estimated_duration_minutes: r.estimated_duration_minutes ?? null,
          };
          return act;
        });

        const sec: CoursePackageSectionV2 = {
          local_id: sectionLocalId(si),
          id: s.id,
          title: s.title,
          description: s.description,
          content: s.content,
          order_index: s.order_index,
          start_date: s.start_date,
          end_date: s.end_date,
          objectives: s.objectives,
          resources: s.resources,
          notes: s.notes,
          completion_status: s.completion_status,
          prerequisites_section_ids: prereqUuids,
          is_locked: s.is_locked,
          activities,
        };
        return sec;
      }
    );

    syllabusPayload = {
      id: syllabusData.id,
      title: syllabusData.title,
      summary: syllabusData.summary,
      structure_type: syllabusData.structure_type,
      policies,
      status: syllabusData.status,
      release_mode: syllabusData.release_mode,
      published_at: syllabusData.published_at,
      accent_color: syllabusData.accent_color,
      banner_url: syllabusData.banner_url,
      section_label_override: syllabusData.section_label_override,
      custom_settings:
        syllabusData.custom_settings && typeof syllabusData.custom_settings === 'object'
          ? syllabusData.custom_settings
          : {},
      grading_categories,
      sections,
    };
  }

  const roster = input.assignments
    .map((row) => {
      const { student_profiles: _sp, submissions: _sub, ...rest } = row as Record<string, unknown>;
      return rest;
    })
    .sort(
      (a, b) =>
        new Date(String(a.created_at ?? 0)).getTime() -
        new Date(String(b.created_at ?? 0)).getTime()
    );

  const exportAssignments: CoursePackageAssignmentV2[] = roster.map((row, i) => {
    const lid = assignmentLocalId(i);
    const idStr = String((row as { id: string }).id);

    const a = row as unknown as Assignment & {
      syllabus_section_id?: string | null;
      grading_category_id?: string | null;
      target_dimensions?: unknown;
      materials?: unknown;
    };

    const sectionUuid = a.syllabus_section_id ?? null;
    const gcUuid = a.grading_category_id ?? null;

    const base: CoursePackageAssignmentV2 = {
      id: idStr,
      local_id: lid,
      syllabus_section_ref: sectionUuid,
      grading_category_ref: gcUuid,
      title: a.title,
      instructions: a.instructions,
      student_facing_task: a.student_facing_task ?? null,
      type: a.type,
      status: a.status,
      due_at: a.due_at,
      target_dimensions: (a.target_dimensions as unknown as Json) ?? ({} as Json),
      personalization_flag: Boolean(a.personalization_flag),
      enable_ai_feedback: a.enable_ai_feedback !== false,
      auto_publish_ai_feedback: a.auto_publish_ai_feedback !== false,
      attempt_mode: a.attempt_mode ?? null,
      materials: (a.materials as unknown as Json | null) ?? null,
      hard_skills:
        typeof a.hard_skills === 'string'
          ? a.hard_skills
          : a.hard_skills != null
            ? JSON.stringify(a.hard_skills)
            : null,
      hard_skill_domain: a.hard_skill_domain ?? null,
      assigned_student_id: null,
    };
    return base;
  });

  const assignment_activity_links: CoursePackageAssignmentActivityLinkV2[][] =
    exportAssignments.map((_, i) => {
      const aid = String((roster[i] as { id: string }).id);
      const links = input.assignmentModuleActivitiesByAssignmentId[aid] ?? [];
      const sorted = [...links].sort((x, y) => x.order_index - y.order_index);
      return sorted.map((l) => ({
        activity_ref: l.activity_list_id,
        order_index: l.order_index,
        include_in_ai_context: l.include_in_ai_context,
      }));
    });

  let module_flow_by_section: CoursePackageModuleFlowStepV2[][] | null = null;
  if (syllabusPayload && sectionUuidSet.size > 0) {
    const stepsBySection = new Map<string, ModuleFlowStep[]>();
    for (const st of input.moduleFlowSteps) {
      const list = stepsBySection.get(st.section_id) ?? [];
      list.push(st);
      stepsBySection.set(st.section_id, list);
    }
    const sectionsOrder = [...syllabusPayload.sections].sort(
      (a, b) => (a.order_index ?? 0) - (b.order_index ?? 0)
    );
    module_flow_by_section = sectionsOrder.map((sec) => {
      const steps = (stepsBySection.get(sec.id) ?? []).sort(
        (a, b) => a.order_index - b.order_index
      );
      return steps.map((st, idx) => {
        const step: CoursePackageModuleFlowStepV2 = {
          order_index: idx,
          step_kind: st.step_kind,
          activity_ref:
            st.step_kind === 'resource' && st.activity_list_id ? st.activity_list_id : null,
          assignment_ref:
            st.step_kind === 'assignment' && st.assignment_id ? st.assignment_id : null,
        };
        return step;
      });
    });
  }

  const course: CoursePackageCourseV2 = {
    classroom: classroomPayload,
    syllabus: syllabusPayload,
    assignments: exportAssignments,
    assignment_activity_links,
    module_flow_by_section,
  };

  const pkg: PerleapCoursePackageV2 = {
    format: COURSE_PACKAGE_FORMAT,
    version: COURSE_PACKAGE_VERSION_V2,
    exported_at: new Date().toISOString(),
    source_classroom_name: input.sourceClassroomName ?? (String(c.name ?? null) || null),
    exported_from_classroom_id: classroomIdStr,
    course,
  };
  return pkg;
}

/**
 * Converts a merge-safe v2 package into portable v1 for create-classroom / full apply flows.
 */

import type {
  PerleapCoursePackageV1,
  PerleapCoursePackageV2,
  CoursePackageAssignmentActivityLinkV1,
  CoursePackageAssignmentV1,
  CoursePackageCourseV1,
  CoursePackageModuleFlowStepV1,
  CoursePackageSectionV1,
  CoursePackageSyllabusV1,
} from '@/types/coursePackage';
import { COURSE_PACKAGE_FORMAT, COURSE_PACKAGE_VERSION } from '@/types/coursePackage';

function sectionLocalId(index: number): string {
  return `sec_${index}`;
}
function gradingLocalId(index: number): string {
  return `gc_${index}`;
}
function activityLocalId(sectionIndex: number, activityIndex: number): string {
  return `act_${sectionIndex}_${activityIndex}`;
}
function assignmentLocalId(index: number): string {
  return `asg_${index}`;
}

export function coursePackageV2ToV1Portable(pkg: PerleapCoursePackageV2): PerleapCoursePackageV1 {
  const cc = pkg.course.classroom;
  const { id: _classroomUuid, ...classroomSansId } = cc;

  let syllabusPayload: CoursePackageSyllabusV1 | null = null;
  const sectionUuidToLocal = new Map<string, string>();
  const fileLocalToV1SectionLocal = new Map<string, string>();
  const activityUuidToLocal = new Map<string, string>();
  const gcUuidToLocal = new Map<string, string>();

  const syl = pkg.course.syllabus;
  if (syl) {
    const grading_sorted = [...syl.grading_categories];
    grading_sorted.forEach((g, i) => {
      const lid = gradingLocalId(i);
      gcUuidToLocal.set(g.id, lid);
    });

    const sectionsSorted = [...syl.sections].sort(
      (a, b) => a.order_index - b.order_index || a.title.localeCompare(b.title)
    );
    sectionsSorted.forEach((sec, si) => {
      const v1Local = sectionLocalId(si);
      const fileLid = typeof sec.local_id === 'string' ? sec.local_id.trim() : '';
      if (fileLid) fileLocalToV1SectionLocal.set(fileLid, v1Local);
      const sid = typeof sec.id === 'string' ? sec.id.trim() : '';
      if (sid) sectionUuidToLocal.set(sid, v1Local);
    });

    const grading_categories = grading_sorted.map((g, i) => ({
      local_id: gradingLocalId(i),
      name: g.name,
      weight: g.weight,
    }));

    const sections: CoursePackageSectionV1[] = sectionsSorted.map((s, si) => {
      const fromUuids = (s.prerequisites_section_ids ?? [])
        .map((pid) => sectionUuidToLocal.get(pid))
        .filter((x): x is string => Boolean(x));
      const fromKeys = (s.prerequisites_merge_keys ?? [])
        .map((k) => fileLocalToV1SectionLocal.get(String(k).trim()))
        .filter((x): x is string => Boolean(x));
      const prereqLocal = [...new Set([...fromUuids, ...fromKeys])];

      const activities_sorted = [...s.activities].sort(
        (a, b) => a.order_index - b.order_index || a.title.localeCompare(b.title)
      );
      const activities = activities_sorted.map((r, ai) => {
        const lid = activityLocalId(si, ai);
        const aid = typeof r.id === 'string' ? r.id.trim() : '';
        if (aid) activityUuidToLocal.set(aid, lid);
        return {
          local_id: lid,
          resource_type: r.resource_type,
          title: r.title,
          order_index: r.order_index,
          status: r.status,
          lesson_content: r.lesson_content,
          summary: r.summary,
          body_text: r.body_text,
          file_path: r.file_path,
          url: r.url,
          mime_type: r.mime_type,
          file_size: r.file_size,
          estimated_duration_minutes: r.estimated_duration_minutes,
        };
      });

      const sec: CoursePackageSectionV1 = {
        local_id: sectionLocalId(si),
        title: s.title,
        description: s.description,
        content: s.content,
        order_index: s.order_index,
        start_date: s.start_date,
        end_date: s.end_date,
        objectives: s.objectives,
        resources: s.resources,
        notes: s.notes,
        completion_status: s.completion_status,
        prerequisites_local_ids: prereqLocal,
        is_locked: s.is_locked,
        activities,
      };
      return sec;
    });

    syllabusPayload = {
      title: syl.title,
      summary: syl.summary,
      structure_type: syl.structure_type,
      policies: syl.policies,
      status: syl.status,
      release_mode: syl.release_mode,
      published_at: syl.published_at,
      accent_color: syl.accent_color,
      banner_url: syl.banner_url,
      section_label_override: syl.section_label_override,
      custom_settings: syl.custom_settings,
      grading_categories,
      sections,
    };
  }

  const assignmentUuidToLocal = new Map<string, string>();
  const roster = pkg.course.assignments;

  const exportAssignments: CoursePackageAssignmentV1[] = roster.map((a, i) => {
    const lid =
      typeof a.local_id === 'string' && a.local_id.trim() ? a.local_id : assignmentLocalId(i);
    if (a.id !== undefined && a.id !== null && String(a.id).trim())
      assignmentUuidToLocal.set(String(a.id), lid);

    const sectionRef =
      a.syllabus_section_ref != null
        ? (sectionUuidToLocal.get(a.syllabus_section_ref) ?? null)
        : null;
    const gcRef =
      a.grading_category_ref != null ? (gcUuidToLocal.get(a.grading_category_ref) ?? null) : null;

    return {
      local_id: lid,
      syllabus_section_ref: sectionRef,
      grading_category_ref: gcRef,
      title: a.title,
      instructions: a.instructions,
      student_facing_task: a.student_facing_task,
      type: a.type,
      status: a.status,
      due_at: a.due_at,
      target_dimensions: a.target_dimensions,
      personalization_flag: a.personalization_flag,
      enable_ai_feedback: a.enable_ai_feedback !== false,
      auto_publish_ai_feedback: a.auto_publish_ai_feedback,
      attempt_mode: a.attempt_mode,
      materials: a.materials,
      hard_skills: a.hard_skills,
      hard_skill_domain: a.hard_skill_domain,
      assigned_student_id: a.assigned_student_id,
    };
  });

  const assignment_activity_links: CoursePackageAssignmentActivityLinkV1[][] =
    exportAssignments.map((_, i) => {
      const origLinks = pkg.course.assignment_activity_links[i] ?? [];
      return origLinks.map((l) => ({
        activity_ref: activityUuidToLocal.get(String(l.activity_ref)) ?? String(l.activity_ref),
        order_index: l.order_index,
        include_in_ai_context: l.include_in_ai_context,
      }));
    });

  let module_flow_by_section: CoursePackageModuleFlowStepV1[][] | null = null;
  const flows = pkg.course.module_flow_by_section;
  if (syl && flows && flows.length === syl.sections.length) {
    const sectionsSorted = [...syl.sections].sort(
      (a, b) => a.order_index - b.order_index || a.title.localeCompare(b.title)
    );
    module_flow_by_section = sectionsSorted.map((_sec, si) => {
      const rawSteps = flows[si] ?? [];
      return rawSteps.map((st, ord) => {
        const step: CoursePackageModuleFlowStepV1 = {
          order_index: ord,
          step_kind: st.step_kind,
          activity_ref:
            st.activity_ref != null ? (activityUuidToLocal.get(st.activity_ref) ?? null) : null,
          assignment_ref:
            st.assignment_ref != null
              ? (assignmentUuidToLocal.get(st.assignment_ref) ?? null)
              : null,
        };
        return step;
      });
    });
  }

  const course: CoursePackageCourseV1 = {
    classroom: classroomSansId,
    syllabus: syllabusPayload,
    assignments: exportAssignments,
    assignment_activity_links,
    module_flow_by_section,
  };

  return {
    format: COURSE_PACKAGE_FORMAT,
    version: COURSE_PACKAGE_VERSION,
    exported_at: pkg.exported_at,
    source_classroom_name: pkg.source_classroom_name ?? null,
    course,
  };
}

/**
 * Parse and validate perleap.course v1 / v2 JSON from unknown input.
 */

import type {
  PerleapCoursePackageAny,
  PerleapCoursePackageV1,
  PerleapCoursePackageV2,
} from '@/types/coursePackage';
import {
  COURSE_PACKAGE_FORMAT,
  COURSE_PACKAGE_VERSION,
  COURSE_PACKAGE_VERSION_V2,
} from '@/types/coursePackage';

export type ParseCoursePackageResult =
  | { ok: true; data: PerleapCoursePackageAny }
  | { ok: false; error: string };

function isUuid(s: unknown): s is string {
  if (typeof s !== 'string') return false;
  const t = s.trim();
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(t);
}

function validateCourseCommon(course: Record<string, unknown>): string | null {
  if (course.classroom === null || typeof course.classroom !== 'object') {
    return 'Missing course.classroom';
  }
  const cls = course.classroom as Record<string, unknown>;
  if (typeof cls.name !== 'string' || !cls.name.trim()) {
    return 'course.classroom.name is required';
  }
  if (!Array.isArray(course.assignments)) {
    return 'course.assignments must be an array';
  }
  if (!Array.isArray(course.assignment_activity_links)) {
    return 'course.assignment_activity_links must be an array';
  }
  if (course.assignment_activity_links.length !== course.assignments.length) {
    return 'course.assignment_activity_links length must match course.assignments';
  }
  if (
    course.syllabus !== null &&
    course.syllabus !== undefined &&
    typeof course.syllabus !== 'object'
  ) {
    return 'course.syllabus must be object or null';
  }
  if (course.module_flow_by_section !== null && course.module_flow_by_section !== undefined) {
    if (!Array.isArray(course.module_flow_by_section)) {
      return 'course.module_flow_by_section must be array or null';
    }
  }
  return null;
}

function validateCourseV2Shape(course: Record<string, unknown>): string | null {
  const common = validateCourseCommon(course);
  if (common) return common;

  let syllabusHasPartialIdentity = false;
  const sylRaw = course.syllabus as Record<string, unknown> | null | undefined;
  if (sylRaw !== null && sylRaw !== undefined && typeof sylRaw === 'object') {
    if (!isUuid(sylRaw.id)) return 'course.syllabus.id must be a UUID';
    const gcs = sylRaw.grading_categories as unknown[];
    if (!Array.isArray(gcs)) return 'course.syllabus.grading_categories invalid';
    for (let i = 0; i < gcs.length; i++) {
      const g = gcs[i];
      if (g === null || typeof g !== 'object')
        return 'course.syllabus.grading_categories entries must be objects';
      const gr = g as Record<string, unknown>;
      if (!isUuid(gr.id)) return `grading category at index ${i} must have UUID id`;
    }
    const secs = sylRaw.sections as unknown[];
    if (!Array.isArray(secs)) return 'course.syllabus.sections invalid';
    const uuidSectionIds = new Set<string>();
    const localIdsNeedingInsert = new Set<string>();

    for (let si = 0; si < secs.length; si++) {
      const s = secs[si];
      if (s === null || typeof s !== 'object') return 'Invalid syllabus section row';
      const sec = s as Record<string, unknown>;
      const lid = typeof sec.local_id === 'string' ? sec.local_id.trim() : '';
      const rawId = sec.id;
      const hasUuidId = rawId != null && String(rawId).trim() !== '' && isUuid(rawId);

      if (hasUuidId) {
        const sid = String(rawId).trim();
        uuidSectionIds.add(sid);
        const mk = sec.prerequisites_merge_keys;
        if (Array.isArray(mk) && mk.length > 0) {
          return `section at index ${si}: prerequisites_merge_keys only allowed when section omits id`;
        }
      } else {
        if (!lid) return `section at index ${si} must have UUID id or non-empty local_id`;
        localIdsNeedingInsert.add(lid);
        syllabusHasPartialIdentity = true;
      }

      const prereqs = sec.prerequisites_section_ids;
      if (!Array.isArray(prereqs)) return 'prerequisites_section_ids must be array';
      for (const p of prereqs) {
        if (p !== null && !isUuid(p)) return 'prerequisite_section id must be UUID';
      }

      const mkArr = sec.prerequisites_merge_keys;
      if (mkArr != null && !Array.isArray(mkArr))
        return 'prerequisites_merge_keys must be array when present';
      if (Array.isArray(mkArr)) {
        for (const k of mkArr) {
          if (typeof k !== 'string' || !k.trim())
            return 'prerequisites_merge_keys must be non-empty strings';
        }
      }

      const acts = sec.activities;
      if (!Array.isArray(acts)) return 'section.activities invalid';
      for (let ai = 0; ai < acts.length; ai++) {
        const ar = acts[ai];
        if (ar === null || typeof ar !== 'object') return 'Invalid activity row';
        const row = ar as Record<string, unknown>;
        const actId = row.id;
        const hasActUuid = actId != null && String(actId).trim() !== '' && isUuid(actId);
        const actLid = typeof row.local_id === 'string' ? row.local_id.trim() : '';
        if (hasActUuid) {
          /* ok */
        } else {
          if (!actLid) return `activity at sec ${si}/${ai} must have UUID id or non-empty local_id`;
          syllabusHasPartialIdentity = true;
        }
      }
    }

    for (let si = 0; si < secs.length; si++) {
      const sec = secs[si] as Record<string, unknown>;
      const prereqs = sec.prerequisites_section_ids as unknown[];
      for (const p of prereqs) {
        if (isUuid(p) && !uuidSectionIds.has(String(p).trim()))
          return 'prerequisite references unknown section id';
      }
      const mkArr = (sec.prerequisites_merge_keys ?? []) as unknown[];
      for (const k of mkArr) {
        const ks = String(k).trim();
        if (!localIdsNeedingInsert.has(ks))
          return 'prerequisite_merge_key references unknown new section local_id';
      }
    }
  }

  const assigns = course.assignments as unknown[];
  for (let i = 0; i < assigns.length; i++) {
    const a = assigns[i];
    if (a === null || typeof a !== 'object') return 'invalid assignment row';
    const row = a as Record<string, unknown>;
    if (!isUuid(row.id)) return `assignment at index ${i} must include UUID id`;
    if (row.syllabus_section_ref != null && !isUuid(row.syllabus_section_ref)) {
      return 'assignment syllabus_section_ref must be UUID or null';
    }
    if (row.grading_category_ref != null && !isUuid(row.grading_category_ref)) {
      return 'assignment grading_category_ref must be UUID or null';
    }
  }

  const linksArr = course.assignment_activity_links as unknown[];
  for (let i = 0; i < linksArr.length; i++) {
    const entry = linksArr[i];
    if (!Array.isArray(entry)) return 'assignment_activity_links must be array-of-arrays';
    for (const l of entry) {
      if (l === null || typeof l !== 'object') continue;
      const row = l as Record<string, unknown>;
      if (row.activity_ref != null && !isUuid(row.activity_ref)) return 'invalid activity_ref';
    }
  }

  const mf = course.module_flow_by_section as unknown[] | null | undefined;
  if (
    syllabusHasPartialIdentity &&
    mf !== null &&
    mf !== undefined &&
    Array.isArray(mf) &&
    mf.length > 0
  ) {
    return 'module_flow_by_section must be empty when any syllabus section or activity omits a UUID id';
  }
  if (mf !== null && mf !== undefined && Array.isArray(mf)) {
    for (let si = 0; si < mf.length; si++) {
      const row = mf[si];
      if (!Array.isArray(row)) return 'module_flow_by_section rows must be arrays';
      for (const st of row) {
        if (st === null || typeof st !== 'object') return 'invalid flow step';
        const os = st as Record<string, unknown>;
        const sk = os.step_kind;
        if (sk !== 'resource' && sk !== 'assignment') return 'invalid step_kind';
        if (sk === 'resource' && os.activity_ref != null && !isUuid(os.activity_ref)) {
          return 'flow activity_ref must be UUID or null';
        }
        if (sk === 'assignment' && os.assignment_ref != null && !isUuid(os.assignment_ref)) {
          return 'flow assignment_ref must be UUID or null';
        }
      }
    }
    if (
      typeof sylRaw === 'object' &&
      sylRaw !== null &&
      Array.isArray(sylRaw.sections) &&
      mf.length !== sylRaw.sections.length
    ) {
      return 'module_flow_by_section length must match syllabus sections when present';
    }
  }

  return null;
}

export function parseCoursePackageJson(raw: unknown): ParseCoursePackageResult {
  if (raw === null || typeof raw !== 'object') {
    return { ok: false, error: 'Invalid JSON: expected an object' };
  }
  const o = raw as Record<string, unknown>;
  if (o.format !== COURSE_PACKAGE_FORMAT) {
    return { ok: false, error: `Unknown format: expected "${COURSE_PACKAGE_FORMAT}"` };
  }
  if (typeof o.exported_at !== 'string') {
    return { ok: false, error: 'Missing exported_at' };
  }
  if (o.course === null || typeof o.course !== 'object') {
    return { ok: false, error: 'Missing course object' };
  }

  const course = o.course as Record<string, unknown>;
  const ver = o.version;

  if (ver === COURSE_PACKAGE_VERSION) {
    const err = validateCourseCommon(course);
    if (err) return { ok: false, error: err };
    return { ok: true, data: raw as PerleapCoursePackageV1 };
  }

  if (ver === COURSE_PACKAGE_VERSION_V2) {
    if (!isUuid(o.exported_from_classroom_id)) {
      return { ok: false, error: 'exported_from_classroom_id must be a UUID (merge-safe package)' };
    }
    const errV2 = validateCourseV2Shape(course);
    if (errV2) return { ok: false, error: errV2 };
    return { ok: true, data: raw as PerleapCoursePackageV2 };
  }

  return { ok: false, error: `Unsupported version: ${String(ver)}` };
}

/**
 * Normalize hard_skills JSON: legacy string[] or structured { domain, skill }[]
 */

export type HardSkillPair = { domain: string; skill: string };

function isPair(x: unknown): x is HardSkillPair {
  if (!x || typeof x !== 'object') return false;
  const o = x as Record<string, unknown>;
  const d = typeof o.domain === 'string' ? o.domain.trim() : '';
  if (!d) return false;
  const sk =
    typeof o.skill === 'string'
      ? o.skill
      : typeof o.skill_component === 'string'
        ? o.skill_component
        : '';
  return sk.trim().length > 0;
}

/** Parse raw DB or form value into normalized pairs */
export function parseHardSkillsFromDb(
  raw: unknown,
  fallbackDomain: string | null | undefined
): HardSkillPair[] {
  let arr: unknown[] = [];
  if (raw == null) return [];
  if (typeof raw === 'string') {
    try {
      const parsed = JSON.parse(raw);
      arr = Array.isArray(parsed) ? parsed : [];
    } catch {
      arr = raw
        .split(',')
        .map((s) => s.trim())
        .filter(Boolean);
    }
  } else if (Array.isArray(raw)) {
    arr = raw;
  } else {
    return [];
  }

  const fallback = (fallbackDomain ?? '').trim();
  const out: HardSkillPair[] = [];
  for (const item of arr) {
    if (typeof item === 'string') {
      const s = item.trim();
      if (s) out.push({ domain: fallback, skill: s });
    } else if (isPair(item)) {
      const o = item as Record<string, string>;
      const skill = (o.skill ?? o.skill_component ?? '').trim();
      if (skill) out.push({ domain: o.domain.trim(), skill });
    }
  }
  return out;
}

/** Serialize pairs for assignments.hard_skills column */
export function stringifyHardSkillsForDb(pairs: HardSkillPair[]): string {
  return JSON.stringify(pairs);
}

/** Distinct non-empty domains */
export function distinctDomains(pairs: HardSkillPair[]): string[] {
  const s = new Set<string>();
  for (const p of pairs) {
    if (p.domain.trim()) s.add(p.domain.trim());
  }
  return [...s];
}

/** For hard_skill_domain column: single domain or null if none / multiple */
export function deriveSingleDomainField(pairs: HardSkillPair[]): string | null {
  const d = distinctDomains(pairs);
  if (d.length === 1) return d[0]!;
  return null;
}

/** Persisted DB value for assignments.hard_skill_domain */
export function resolveHardSkillDomainForDb(
  pairs: HardSkillPair[],
  manualDomain: string
): string | null {
  const single = deriveSingleDomainField(pairs);
  if (single) return single;
  if (pairs.length === 0) return manualDomain.trim() || null;
  return null;
}

export function pairKey(p: HardSkillPair): string {
  return `${p.domain.trim()}\0${p.skill.trim()}`;
}

export function pairsEqual(a: HardSkillPair, b: HardSkillPair): boolean {
  return pairKey(a) === pairKey(b);
}

import type { FlowStepInput } from '@/services/moduleFlowService';
import type {
  ModuleFlowStep,
  ResourceType,
  SectionResource,
  SyllabusSection,
  ModuleFlowStepKind,
} from '@/types/syllabus';

/**
 * Activities center + module flow only include these: combined lessons and legacy text/video activities.
 * Generic outline materials (file, link, document, image) stay in Course Outline only.
 */
export function isActivityCenterResourceType(resourceType: ResourceType): boolean {
  return resourceType === 'lesson' || resourceType === 'text' || resourceType === 'video';
}

export function isActivityCenterResource(resource: SectionResource): boolean {
  return isActivityCenterResourceType(resource.resource_type);
}

/** Outline-only materials (files, links, etc.) — not module-flow steps; shown at unit level. */
export function isOutlineMaterialResourceType(resourceType: ResourceType): boolean {
  return (
    resourceType === 'file' ||
    resourceType === 'link' ||
    resourceType === 'document' ||
    resourceType === 'image'
  );
}

export function isOutlineMaterialResource(resource: SectionResource): boolean {
  return isOutlineMaterialResourceType(resource.resource_type);
}

export type OutlineMaterialFilterOptions = {
  /** Omit `activity_list` rows with status draft (student-facing surfaces). */
  excludeDrafts?: boolean;
  /** Drop this id after filtering (e.g. current activity row). */
  excludeResourceId?: string | null;
};

export function filterOutlineMaterialResources(
  resources: SectionResource[] | undefined | null,
  options?: OutlineMaterialFilterOptions
): SectionResource[] {
  let out = (resources ?? []).filter((r) => isOutlineMaterialResource(r));
  if (options?.excludeDrafts) {
    out = out.filter((r) => r.status !== 'draft');
  }
  const ex = options?.excludeResourceId;
  if (ex) {
    out = out.filter((r) => r.id !== ex);
  }
  return [...out].sort((a, b) => a.order_index - b.order_index);
}

/** Published assignments only — mirrors student RLS on teacher read-only curriculum views. */
export function filterStudentVisibleAssignments<T extends { status?: string | null }>(
  assignments: T[]
): T[] {
  return assignments.filter((a) => a.status === 'published');
}

/** Published activity_list rows only — mirrors student RLS on teacher read-only curriculum views. */
export function filterStudentVisibleSectionResources(
  sectionResources: Record<string, SectionResource[]>
): Record<string, SectionResource[]> {
  const out: Record<string, SectionResource[]> = {};
  for (const [sectionId, resources] of Object.entries(sectionResources)) {
    out[sectionId] = resources.filter((r) => r.status !== 'draft');
  }
  return out;
}

/** Assignment steps plus resource steps whose linked material is lesson/text/video (not outline-only files/links). */
export function filterActivityCenterModuleFlowSteps(
  steps: ModuleFlowStep[],
  sectionResources: SectionResource[]
): ModuleFlowStep[] {
  return steps.filter((step) => {
    if (step.step_kind === 'assignment') return true;
    if (step.step_kind === 'resource' && step.activity_list_id) {
      const r = sectionResources.find((x) => x.id === step.activity_list_id);
      return r ? isActivityCenterResource(r) : false;
    }
    return false;
  });
}

export function isLiveSessionAssignmentType(type: string | null | undefined): boolean {
  return type === 'live_session';
}

export type OrderedActivityCenterFlowStepsOptions = {
  /** Omit live_session assignment steps (student course outline). */
  hideLiveSessions?: boolean;
  assignmentsById?: Record<string, { type?: string | null }>;
};

export function studentModuleFlowStepOptions(
  assignments: Array<{ id: string; type?: string | null }>
): OrderedActivityCenterFlowStepsOptions {
  const assignmentsById: Record<string, { type?: string | null }> = {};
  for (const a of assignments) {
    assignmentsById[a.id] = { type: a.type };
  }
  return { hideLiveSessions: true, assignmentsById };
}

/** Filter + sort by `order_index` for activity-center steps in a module. */
export function getOrderedActivityCenterFlowSteps(
  steps: ModuleFlowStep[],
  sectionResources: SectionResource[],
  options?: OrderedActivityCenterFlowStepsOptions
): ModuleFlowStep[] {
  let filtered = filterActivityCenterModuleFlowSteps(steps, sectionResources);
  if (options?.assignmentsById) {
    filtered = filtered.filter((step) => {
      if (step.step_kind !== 'assignment' || !step.assignment_id) return true;
      return step.assignment_id in options.assignmentsById!;
    });
  }
  if (options?.hideLiveSessions && options.assignmentsById) {
    filtered = filtered.filter((step) => {
      if (step.step_kind !== 'assignment' || !step.assignment_id) return true;
      const type = options.assignmentsById![step.assignment_id]?.type;
      return !isLiveSessionAssignmentType(type);
    });
  }
  return [...filtered].sort((a, b) => a.order_index - b.order_index);
}

/** Next step in teacher-defined order, or undefined if last or not found. */
export function getNextActivityCenterStep(
  orderedSteps: ModuleFlowStep[],
  currentStepId: string
): ModuleFlowStep | undefined {
  const i = orderedSteps.findIndex((s) => s.id === currentStepId);
  if (i < 0 || i >= orderedSteps.length - 1) return undefined;
  return orderedSteps[i + 1];
}

export type ComputedFlowItem =
  | { kind: 'resource'; activity_list_id: string; order_index: number }
  | { kind: 'assignment'; assignment_id: string; order_index: number };

/** Assignment fields used for module flow ordering and merge. */
export type AssignmentRow = {
  id: string;
  syllabus_section_id?: string | null;
  due_at?: string | null;
  attempt_mode?: string | null;
  type?: string | null;
};

/** Same ordering as the assignment tail of `computeDefaultModuleFlow` (due_at, then id). */
export function sortAssignmentsForSection(sectionAssignments: AssignmentRow[]): AssignmentRow[] {
  return sectionAssignments.slice().sort((a, b) => {
    const da = a.due_at ? new Date(a.due_at).getTime() : 0;
    const db = b.due_at ? new Date(b.due_at).getTime() : 0;
    if (da !== db) return da - db;
    return a.id.localeCompare(b.id);
  });
}

export type ModuleFlowLocalStep =
  | { kind: 'resource'; resourceId: string }
  | { kind: 'assignment'; assignmentId: string };

/** Append section-linked assignments missing from `base` (sorted like default flow). */
export function appendMissingSectionLinkedAssignments(
  base: ModuleFlowLocalStep[],
  sectionAssignments: AssignmentRow[]
): ModuleFlowLocalStep[] {
  const present = new Set(
    base
      .filter((s): s is { kind: 'assignment'; assignmentId: string } => s.kind === 'assignment')
      .map((s) => s.assignmentId)
  );
  const missing = sortAssignmentsForSection(sectionAssignments).filter((a) => !present.has(a.id));
  if (missing.length === 0) return base;
  return [...base, ...missing.map((a) => ({ kind: 'assignment' as const, assignmentId: a.id }))];
}

/** Append activity-center resources (lesson/text/video) for the section that are missing from `base`, by outline order. */
export function appendMissingActivityCenterResources(
  base: ModuleFlowLocalStep[],
  sectionId: string,
  resources: SectionResource[]
): ModuleFlowLocalStep[] {
  const present = new Set(
    base
      .filter((s): s is { kind: 'resource'; resourceId: string } => s.kind === 'resource')
      .map((s) => s.resourceId)
  );
  const missing = resources
    .filter((r) => r.section_id === sectionId && isActivityCenterResource(r) && !present.has(r.id))
    .slice()
    .sort((a, b) => a.order_index - b.order_index);
  if (missing.length === 0) return base;
  return [...base, ...missing.map((r) => ({ kind: 'resource' as const, resourceId: r.id }))];
}

/** Map computed default flow to local step shape (no assignment append). */
export function computedFlowItemsToLocalSteps(items: ComputedFlowItem[]): ModuleFlowLocalStep[] {
  return items.map((c) =>
    c.kind === 'resource'
      ? { kind: 'resource', resourceId: c.activity_list_id }
      : { kind: 'assignment', assignmentId: c.assignment_id }
  );
}

/**
 * Activity-center flow steps before appending missing section-linked assignments.
 * Used when comparing whether auto-persist should run in ModuleFlowEditor.
 */
export function resolveDisplayedModuleFlowBase(
  sectionId: string,
  resources: SectionResource[],
  assignments: AssignmentRow[],
  persistedSteps: ModuleFlowStep[],
  options?: OrderedActivityCenterFlowStepsOptions
): ModuleFlowLocalStep[] {
  const computedDefault = computeDefaultModuleFlow(sectionId, resources, assignments, options);

  let base: ModuleFlowLocalStep[];
  if (persistedSteps.length > 0) {
    const ordered = getOrderedActivityCenterFlowSteps(persistedSteps, resources, options);
    if (ordered.length > 0) {
      base = ordered.map((s) =>
        s.step_kind === 'resource' && s.activity_list_id
          ? { kind: 'resource', resourceId: s.activity_list_id }
          : { kind: 'assignment', assignmentId: s.assignment_id! }
      );
    } else {
      base = computedFlowItemsToLocalSteps(computedDefault);
    }
  } else {
    base = computedFlowItemsToLocalSteps(computedDefault);
  }

  return base;
}

/**
 * Steady-state module flow for display (Activities page) and as the server baseline in ModuleFlowEditor.
 * Matches persisted activity-center steps when present (ordered by order_index), else default computation,
 * then appends missing activity-center resources and section-linked assignments (same idea as outline sync).
 */
/** Drop flow steps whose resource or assignment no longer exists (deleted rows, stale persisted steps). */
export function filterOrphanModuleFlowLocalSteps(
  steps: ModuleFlowLocalStep[],
  resources: SectionResource[],
  allAssignments: AssignmentRow[]
): ModuleFlowLocalStep[] {
  const assignmentIds = new Set(allAssignments.map((a) => a.id));
  return steps.filter((s) => {
    if (s.kind === 'resource') {
      const r = resources.find((x) => x.id === s.resourceId);
      return r ? isActivityCenterResource(r) : false;
    }
    return assignmentIds.has(s.assignmentId);
  });
}

/** Teacher curriculum list: persisted/default base without full student merge, but hide orphan steps. */
export function resolveTeacherCurriculumModuleFlow(
  sectionId: string,
  resources: SectionResource[],
  assignments: AssignmentRow[],
  persistedSteps: ModuleFlowStep[]
): ModuleFlowLocalStep[] {
  const base = resolveDisplayedModuleFlowBase(sectionId, resources, assignments, persistedSteps);
  return filterOrphanModuleFlowLocalSteps(base, resources, assignments);
}

export function resolveDisplayedModuleFlow(
  sectionId: string,
  resources: SectionResource[],
  assignments: AssignmentRow[],
  persistedSteps: ModuleFlowStep[],
  options?: OrderedActivityCenterFlowStepsOptions
): ModuleFlowLocalStep[] {
  const base = resolveDisplayedModuleFlowBase(
    sectionId,
    resources,
    assignments,
    persistedSteps,
    options
  );
  let sectionAssignments = assignments.filter((a) => a.syllabus_section_id === sectionId);
  if (options?.hideLiveSessions) {
    sectionAssignments = sectionAssignments.filter((a) => !isLiveSessionAssignmentType(a.type));
  }
  let merged = appendMissingActivityCenterResources(base, sectionId, resources);
  /** When the teacher has a saved flow, do not append every section-linked assignment — that undoes removals from the flow. */
  const hasSavedActivityCenterFlow =
    persistedSteps.length > 0 &&
    getOrderedActivityCenterFlowSteps(persistedSteps, resources, options).length > 0;
  if (!hasSavedActivityCenterFlow) {
    merged = appendMissingSectionLinkedAssignments(merged, sectionAssignments);
  }
  return filterOrphanModuleFlowLocalSteps(merged, resources, assignments);
}

export function moduleFlowLocalStepsEqual(
  a: ModuleFlowLocalStep[],
  b: ModuleFlowLocalStep[]
): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    const x = a[i];
    const y = b[i];
    if (x.kind !== y.kind) return false;
    if (x.kind === 'resource' && y.kind === 'resource') {
      if (x.resourceId !== y.resourceId) return false;
    } else if (x.kind === 'assignment' && y.kind === 'assignment') {
      if (x.assignmentId !== y.assignmentId) return false;
    }
  }
  return true;
}

/**
 * When no persisted module_flow_steps exist, derive a default ordering:
 * section resources by order_index, then assignments for that section (by due_at then id).
 */
export function computeDefaultModuleFlow(
  sectionId: string,
  resources: SectionResource[],
  assignments: AssignmentRow[],
  options?: OrderedActivityCenterFlowStepsOptions
): ComputedFlowItem[] {
  const res = resources
    .filter((r) => r.section_id === sectionId && isActivityCenterResource(r))
    .slice()
    .sort((a, b) => a.order_index - b.order_index);
  let sectionAssignments = assignments.filter((a) => a.syllabus_section_id === sectionId);
  if (options?.hideLiveSessions) {
    sectionAssignments = sectionAssignments.filter((a) => !isLiveSessionAssignmentType(a.type));
  }
  const assigns = sortAssignmentsForSection(sectionAssignments);

  let i = 0;
  const out: ComputedFlowItem[] = [];
  for (const r of res) {
    out.push({ kind: 'resource', activity_list_id: r.id, order_index: i++ });
  }
  for (const a of assigns) {
    out.push({ kind: 'assignment', assignment_id: a.id, order_index: i++ });
  }
  return out;
}

/**
 * Match a computed item to a persisted flow step (same kind + target id).
 */
export function flowItemMatchesStep(
  item: ComputedFlowItem,
  step: {
    step_kind: ModuleFlowStepKind;
    activity_list_id: string | null;
    assignment_id: string | null;
  }
): boolean {
  if (item.kind === 'resource' && step.step_kind === 'resource') {
    return step.activity_list_id === item.activity_list_id;
  }
  if (item.kind === 'assignment' && step.step_kind === 'assignment') {
    return step.assignment_id === item.assignment_id;
  }
  return false;
}

/** Ordered sections for unlock checks (same as Course Outline). */
export function orderedSections(sections: SyllabusSection[]): SyllabusSection[] {
  return [...sections].sort((a, b) => a.order_index - b.order_index);
}

/** Persist local module-flow steps to the API shape (order_index + step_kind + ids). */
export function moduleFlowLocalStepsToFlowInput(
  localSteps: ModuleFlowLocalStep[]
): FlowStepInput[] {
  return localSteps.map((s, order_index) =>
    s.kind === 'resource'
      ? {
          order_index,
          step_kind: 'resource',
          activity_list_id: s.resourceId,
          assignment_id: null,
        }
      : {
          order_index,
          step_kind: 'assignment',
          activity_list_id: null,
          assignment_id: s.assignmentId,
        }
  );
}

/**
 * Student outline / linked-assignments lists: when the teacher saved `module_flow_steps`, only assignments
 * that appear as assignment steps should show — not every row with `syllabus_section_id`.
 * If there is no saved flow (`persistedFlowSteps` empty), keep legacy behavior (all section-linked assignments).
 * Order matches module flow `order_index`.
 */
export function linkedAssignmentsVisibleInModuleFlow<T extends { id: string; type?: string }>(
  sectionLinked: T[],
  persistedFlowSteps: ModuleFlowStep[] | undefined | null,
  options?: Pick<OrderedActivityCenterFlowStepsOptions, 'hideLiveSessions'>
): T[] {
  const withoutLiveSessions = (list: T[]) =>
    options?.hideLiveSessions ? list.filter((a) => !isLiveSessionAssignmentType(a.type)) : list;

  if (!persistedFlowSteps || persistedFlowSteps.length === 0) {
    return withoutLiveSessions(sectionLinked);
  }
  const orderedIds: string[] = [];
  const seen = new Set<string>();
  [...persistedFlowSteps]
    .sort((a, b) => a.order_index - b.order_index)
    .forEach((s) => {
      if (s.step_kind === 'assignment' && s.assignment_id && !seen.has(s.assignment_id)) {
        seen.add(s.assignment_id);
        orderedIds.push(s.assignment_id);
      }
    });
  if (orderedIds.length === 0) return [];
  const byId = new Map(sectionLinked.map((a) => [a.id, a]));
  return withoutLiveSessions(
    orderedIds.map((id) => byId.get(id)).filter((a): a is T => a !== undefined)
  );
}

/** Same ordering the curriculum tab and flow editor use, ready for `replaceModuleFlowSteps`. */
export function buildResolvedModuleFlowStepInputs(
  sectionId: string,
  resources: SectionResource[],
  assignments: AssignmentRow[],
  persistedSteps: ModuleFlowStep[]
): FlowStepInput[] {
  return moduleFlowLocalStepsToFlowInput(
    resolveDisplayedModuleFlow(sectionId, resources, assignments, persistedSteps)
  );
}

import type { Database, Json } from '@/integrations/supabase/types';
import type {
  Notification,
  NotificationType,
  NotificationMetadata,
  CreateNotificationInput,
  NotificationWithProfile,
} from '@/types/notifications';
import { supabase } from '@/integrations/supabase/client';

type NotificationDbInsert = Database['public']['Tables']['notifications']['Insert'];

function actorIdFromMetadata(metadata: NotificationMetadata | undefined): string | null {
  if (!metadata) return null;
  if (typeof metadata.student_id === 'string') return metadata.student_id;
  if (typeof metadata.teacher_id === 'string') return metadata.teacher_id;
  return null;
}

function toNotificationInsert(
  userId: string,
  type: NotificationType,
  title: string,
  message: string,
  link: string | undefined,
  metadata: NotificationMetadata | undefined,
  actorId?: string
): NotificationDbInsert {
  return {
    user_id: userId,
    type,
    title,
    message,
    link: link ?? null,
    metadata: (metadata ?? {}) as unknown as Json,
    is_read: false,
    actor_id: actorId ?? actorIdFromMetadata(metadata) ?? null,
  };
}

/**
 * Create a new notification for a user
 * Designed to work with both direct calls and future real-time triggers
 */
export async function createNotification(
  userId: string,
  type: NotificationType,
  title: string,
  message: string,
  link?: string,
  metadata?: NotificationMetadata,
  actorId?: string
): Promise<Notification> {
  const insertData = toNotificationInsert(userId, type, title, message, link, metadata, actorId);

  if (!insertData.actor_id) {
    const {
      data: { session },
    } = await supabase.auth.getSession();
    if (session?.user?.id) {
      insertData.actor_id = session.user.id;
    }
  }

  const { data, error } = await supabase
    .from('notifications')
    .insert(insertData)
    .select()
    .single();

  if (error) throw error;

  return data as Notification;
}

/**
 * Create multiple notifications at once (batch operation)
 * Useful for notifying all students in a classroom
 */
export async function createBulkNotifications(
  notifications: (CreateNotificationInput & { actorId?: string })[]
): Promise<Notification[]> {
  const {
    data: { session },
  } = await supabase.auth.getSession();
  const currentUserId = session?.user?.id;

  const insertData: NotificationDbInsert[] = notifications.map((n) => {
    const row = toNotificationInsert(
      n.userId,
      n.type,
      n.title,
      n.message,
      n.link,
      n.metadata,
      n.actorId
    );
    if (!row.actor_id && currentUserId) {
      row.actor_id = currentUserId;
    }
    return row;
  });

  const { data, error } = await supabase.from('notifications').insert(insertData).select();

  if (error) throw error;

  return data as Notification[];
}

/**
 * Get unread notifications for a user with actor profiles
 */
export async function getUnreadNotifications(userId: string): Promise<NotificationWithProfile[]> {
  try {
    const { data: notifications, error } = await supabase
      .from('notifications')
      .select('*')
      .eq('user_id', userId)
      .eq('is_read', false)
      .order('created_at', { ascending: false });

    if (error) throw error;
    if (!notifications || notifications.length === 0) return [];

    return await enrichNotificationsWithProfiles(notifications as unknown as Notification[]);
  } catch {
    return [];
  }
}

/**
 * Get all notifications for a user with actor profiles
 */
export async function getAllNotifications(
  userId: string,
  limit: number = 50
): Promise<NotificationWithProfile[]> {
  try {
    const { data: notifications, error } = await supabase
      .from('notifications')
      .select('*')
      .eq('user_id', userId)
      .order('created_at', { ascending: false })
      .limit(limit);

    if (error) throw error;
    if (!notifications || notifications.length === 0) return [];

    return await enrichNotificationsWithProfiles(notifications as unknown as Notification[]);
  } catch {
    return [];
  }
}

/**
 * Internal helper to enrich notifications with user profiles (student or teacher)
 */
async function enrichNotificationsWithProfiles(
  notifications: Notification[]
): Promise<NotificationWithProfile[]> {
  const actorIds = [
    ...new Set(
      notifications
        .map((n) => n.actor_id ?? actorIdFromMetadata(n.metadata ?? undefined))
        .filter(Boolean)
    ),
  ] as string[];

  if (actorIds.length === 0) {
    return notifications as NotificationWithProfile[];
  }

  const [studentProfiles, teacherProfiles] = await Promise.all([
    supabase
      .from('student_profiles')
      .select('user_id, full_name, avatar_url')
      .in('user_id', actorIds),
    supabase
      .from('teacher_profiles')
      .select('user_id, full_name, avatar_url')
      .in('user_id', actorIds),
  ]);

  const profileMap = new Map<string, { full_name: string; avatar_url: string | null }>();

  studentProfiles.data?.forEach((p) => profileMap.set(p.user_id, p));
  teacherProfiles.data?.forEach((p) => profileMap.set(p.user_id, p));

  return notifications.map((n) => {
    const actorId = n.actor_id ?? actorIdFromMetadata(n.metadata ?? undefined);
    const profile = actorId ? profileMap.get(actorId) : null;

    return {
      ...n,
      actor_profile: profile || null,
    };
  });
}

/**
 * Get count of unread notifications for a user
 */
export async function getUnreadCount(userId: string): Promise<number> {
  try {
    const { count, error } = await supabase
      .from('notifications')
      .select('*', { count: 'exact', head: true })
      .eq('user_id', userId)
      .eq('is_read', false);

    if (error) return 0;

    return count || 0;
  } catch {
    return 0;
  }
}

/**
 * Mark a single notification as read
 */
export async function markAsRead(notificationId: string): Promise<boolean> {
  try {
    const { error } = await supabase
      .from('notifications')
      .update({ is_read: true })
      .eq('id', notificationId);

    if (error) throw error;

    return true;
  } catch {
    return false;
  }
}

/**
 * Mark all notifications as read for a user
 */
export async function markAllAsRead(userId: string): Promise<boolean> {
  try {
    const { error } = await supabase
      .from('notifications')
      .update({ is_read: true })
      .eq('user_id', userId)
      .eq('is_read', false);

    if (error) throw error;

    return true;
  } catch {
    return false;
  }
}

/**
 * Delete old read notifications (cleanup utility)
 * Can be called periodically to keep the table manageable
 */
export async function deleteOldNotifications(
  userId: string,
  daysOld: number = 30
): Promise<boolean> {
  try {
    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - daysOld);

    const { error } = await supabase
      .from('notifications')
      .delete()
      .eq('user_id', userId)
      .eq('is_read', true)
      .lt('created_at', cutoffDate.toISOString());

    if (error) throw error;

    return true;
  } catch {
    return false;
  }
}

