import type { FlowStepTarget } from '@/lib/moduleFlowNavigation';
import type { StudentFlowProgressContext } from '@/lib/moduleFlowStudent';
import type {
  ReleaseMode,
  StudentProgressStatus,
  SyllabusSection,
  ModuleFlowStep,
  SectionResource,
} from '@/types/syllabus';
import {
  getOrderedActivityCenterFlowSteps,
  resolveDisplayedModuleFlow,
  studentModuleFlowStepOptions,
  type AssignmentRow,
  type ModuleFlowLocalStep,
} from '@/lib/moduleFlow';
import {
  isAssignmentMissedDeadline,
  localResourceInferredDoneFromLaterAssignments,
} from '@/lib/moduleFlowStudent';
import { isSectionUnlocked } from '@/lib/sectionUnlock';

export type StudentResumeTargetHit = { target: FlowStepTarget; sectionId: string };

/** Mirrors persisted resource completion (step row or any later assignment in this list done). */
function localResourceStepDone(
  local: ModuleFlowLocalStep[],
  index: number,
  ctx: StudentFlowProgressContext,
  orderedPersisted: ModuleFlowStep[]
): boolean {
  const step = local[index];
  if (step.kind !== 'resource') return false;
  const persistedRow = orderedPersisted.find(
    (p) => p.step_kind === 'resource' && p.activity_list_id === step.resourceId
  );
  if (persistedRow && ctx.progressByStep[persistedRow.id]) return true;
  return localResourceInferredDoneFromLaterAssignments(local, index, ctx);
}

function localStepDone(
  local: ModuleFlowLocalStep[],
  index: number,
  ctx: StudentFlowProgressContext,
  persisted: ModuleFlowStep[],
  sectionResources: SectionResource[],
  assignments: AssignmentRow[]
): boolean {
  const step = local[index];
  if (step.kind === 'assignment') {
    return ctx.assignmentDoneMap[step.assignmentId] ?? false;
  }
  const studentFlowOpts = studentModuleFlowStepOptions(assignments);
  const orderedPersisted = getOrderedActivityCenterFlowSteps(
    persisted,
    sectionResources,
    studentFlowOpts
  );
  return localResourceStepDone(local, index, ctx, orderedPersisted);
}

function localPreviousStepsComplete(
  local: ModuleFlowLocalStep[],
  index: number,
  ctx: StudentFlowProgressContext,
  persisted: ModuleFlowStep[],
  sectionResources: SectionResource[],
  assignments: AssignmentRow[],
  now: Date
): boolean {
  if (index === 0) return true;
  for (let i = 0; i < index; i++) {
    if (localStepDone(local, i, ctx, persisted, sectionResources, assignments)) continue;
    const step = local[i];
    if (
      step.kind === 'assignment' &&
      isAssignmentMissedDeadline(step.assignmentId, assignments, ctx, now)
    ) {
      continue;
    }
    return false;
  }
  return true;
}

/**
 * Same ordering as Curriculum / outline (resolveDisplayedModuleFlow), including assignments
 * appended when the teacher flow omits them.
 */
function firstIncompleteInDisplayedFlow(
  sectionId: string,
  sectionResources: SectionResource[],
  assignments: AssignmentRow[],
  persisted: ModuleFlowStep[],
  ctx: StudentFlowProgressContext,
  now: Date
): FlowStepTarget | null {
  const studentFlowOpts = studentModuleFlowStepOptions(assignments);
  const local = resolveDisplayedModuleFlow(
    sectionId,
    sectionResources,
    assignments,
    persisted,
    studentFlowOpts
  );
  for (let i = 0; i < local.length; i++) {
    if (!localPreviousStepsComplete(local, i, ctx, persisted, sectionResources, assignments, now))
      continue;
    if (!localStepDone(local, i, ctx, persisted, sectionResources, assignments)) {
      const s = local[i];
      if (
        s.kind === 'assignment' &&
        isAssignmentMissedDeadline(s.assignmentId, assignments, ctx, now)
      ) {
        continue;
      }
      if (s.kind === 'resource') return { kind: 'resource', id: s.resourceId };
      return { kind: 'assignment', id: s.assignmentId };
    }
  }
  return null;
}

/**
 * Scans every section in course order for the first incomplete displayed-flow step,
 * ignoring release-mode / manual locks. Used to tell “all reachable work done, more may be gated”
 * from “no incomplete work anywhere.”
 */
export function findFirstIncompleteDisplayedFlowAcrossCourse(params: {
  sections: SyllabusSection[];
  flowBulk: Record<string, ModuleFlowStep[]>;
  resourceMap: Record<string, SectionResource[]>;
  assignments: AssignmentRow[];
  flowCtx: StudentFlowProgressContext;
  now?: Date;
}): FlowStepTarget | null {
  const { sections, flowBulk, resourceMap, assignments, flowCtx } = params;
  const now = params.now ?? new Date();
  const sorted = [...sections].sort((a, b) => a.order_index - b.order_index);

  for (const section of sorted) {
    const persisted = flowBulk[section.id] ?? [];
    const sectionResources = resourceMap[section.id] ?? [];
    const fromDisplayed = firstIncompleteInDisplayedFlow(
      section.id,
      sectionResources,
      assignments,
      persisted,
      flowCtx,
      now
    );
    if (fromDisplayed) return fromDisplayed;
  }
  return null;
}

export function resolveStudentResumeTargetWithSection(params: {
  sections: SyllabusSection[];
  releaseMode: ReleaseMode;
  studentProgressMap: Record<string, StudentProgressStatus>;
  flowBulk: Record<string, ModuleFlowStep[]>;
  resourceMap: Record<string, SectionResource[]>;
  assignments: AssignmentRow[];
  flowCtx: StudentFlowProgressContext;
  /** Clock for due-date checks (tests should pass a fixed instant). */
  now?: Date;
}): StudentResumeTargetHit | null {
  const { releaseMode, studentProgressMap, flowBulk, resourceMap, assignments, flowCtx } = params;
  const now = params.now ?? new Date();
  const sorted = [...params.sections].sort((a, b) => a.order_index - b.order_index);
  const sequentialFlow = {
    flowBulk,
    resourceMap,
    assignments,
    flowCtx,
    now,
  };

  for (const section of sorted) {
    if (!isSectionUnlocked(section, sorted, releaseMode, studentProgressMap, sequentialFlow)) {
      continue;
    }
    const persisted = flowBulk[section.id] ?? [];
    const sectionResources = resourceMap[section.id] ?? [];

    const fromDisplayed = firstIncompleteInDisplayedFlow(
      section.id,
      sectionResources,
      assignments,
      persisted,
      flowCtx,
      now
    );
    if (fromDisplayed) {
      return { target: fromDisplayed, sectionId: section.id };
    }
  }

  return null;
}

export function resolveStudentResumeTarget(params: {
  sections: SyllabusSection[];
  releaseMode: ReleaseMode;
  studentProgressMap: Record<string, StudentProgressStatus>;
  flowBulk: Record<string, ModuleFlowStep[]>;
  resourceMap: Record<string, SectionResource[]>;
  assignments: AssignmentRow[];
  flowCtx: StudentFlowProgressContext;
  now?: Date;
}): FlowStepTarget | null {
  return resolveStudentResumeTargetWithSection(params)?.target ?? null;
}

import * as tus from 'tus-js-client';
import { supabase } from '@/api/client';
import { isStoragePayloadTooLarge } from '@/lib/storageUploadErrors';

export type UploadProgressCallback = (loaded: number, total: number) => void;

export type ResumableUploadOptions = {
  onProgress?: UploadProgressCallback;
  signal?: AbortSignal;
};

const TUS_CHUNK_SIZE = 6 * 1024 * 1024;

function getResumableEndpoint(): string {
  const base = import.meta.env.VITE_SUPABASE_URL as string;
  const match = base.match(/https:\/\/([^.]+)\.supabase\.co/);
  if (!match?.[1]) {
    throw new Error('Invalid VITE_SUPABASE_URL for resumable uploads');
  }
  return `https://${match[1]}.storage.supabase.co/storage/v1/upload/resumable`;
}

export async function uploadFileResumable(
  bucketName: string,
  objectName: string,
  file: File,
  options?: ResumableUploadOptions
): Promise<void> {
  const onProgress = options?.onProgress;
  const signal = options?.signal;

  if (signal?.aborted) {
    throw new DOMException('Upload aborted', 'AbortError');
  }

  let {
    data: { session },
  } = await supabase.auth.getSession();

  if (!session?.access_token) {
    const { data } = await supabase.auth.refreshSession();
    session = data.session ?? null;
  }

  if (!session?.access_token) {
    throw new Error('Not authenticated');
  }

  const anonKey = import.meta.env.VITE_SUPABASE_ANON_KEY as string | undefined;

  await new Promise<void>((resolve, reject) => {
    const upload = new tus.Upload(file, {
      endpoint: getResumableEndpoint(),
      retryDelays: [0, 3000, 5000, 10000, 20000],
      headers: {
        authorization: `Bearer ${session!.access_token}`,
        ...(anonKey ? { apikey: anonKey } : {}),
        'x-upsert': 'false',
      },
      uploadDataDuringCreation: true,
      removeFingerprintOnSuccess: true,
      metadata: {
        bucketName,
        objectName,
        contentType: file.type || 'application/octet-stream',
        cacheControl: '3600',
      },
      chunkSize: TUS_CHUNK_SIZE,
      onError: (error) => {
        if (signal?.aborted) {
          reject(new DOMException('Upload aborted', 'AbortError'));
          return;
        }
        if (isStoragePayloadTooLarge(error)) {
          reject(new Error('STORAGE_GLOBAL_LIMIT_EXCEEDED'));
          return;
        }
        reject(error);
      },
      onProgress: (bytesUploaded, bytesTotal) => {
        onProgress?.(bytesUploaded, bytesTotal);
      },
      onSuccess: () => resolve(),
    });

    const onAbort = () => {
      upload.abort(true);
      reject(new DOMException('Upload aborted', 'AbortError'));
    };

    if (signal) {
      signal.addEventListener('abort', onAbort, { once: true });
    }

    void upload.findPreviousUploads().then((previousUploads) => {
      if (signal?.aborted) {
        onAbort();
        return;
      }
      if (previousUploads.length > 0) {
        upload.resumeFromPreviousUpload(previousUploads[0]!);
      }
      upload.start();
    });
  });
}

export const TUS_UPLOAD_THRESHOLD_BYTES = TUS_CHUNK_SIZE;

import type { AssignmentRow } from '@/lib/moduleFlow';
import type { StudentFlowProgressContext } from '@/lib/moduleFlowStudent';
import type {
  ModuleFlowStep,
  SectionResource,
  SyllabusSection,
  ReleaseMode,
  StudentProgressStatus,
} from '@/types/syllabus';
import { isSectionActivityFlowFullyComplete } from '@/lib/moduleFlowStudent';

/** Course order: `order_index` then stable `id` so ties are not non-deterministic across renders. */
export function sectionsInCourseOrder(sections: SyllabusSection[]): SyllabusSection[] {
  return [...sections].sort((a, b) => a.order_index - b.order_index || a.id.localeCompare(b.id));
}

/**
 * When provided, sequential unlock treats a prior section as satisfied if its syllabus row is
 * `completed` **or** its module-activity flow has no remaining actionable steps (same rule as Curriculum).
 */
export type SectionSequentialUnlockFlow = {
  flowBulk: Record<string, ModuleFlowStep[]>;
  resourceMap: Record<string, SectionResource[]>;
  assignments: AssignmentRow[];
  flowCtx: StudentFlowProgressContext;
  now: Date;
};

function priorSectionSatisfiedForSequential(
  prior: SyllabusSection,
  studentProgressMap: Record<string, StudentProgressStatus>,
  flow: SectionSequentialUnlockFlow | null | undefined
): boolean {
  if (studentProgressMap[prior.id] === 'completed') return true;
  if (!flow) return false;
  return isSectionActivityFlowFullyComplete(
    prior.id,
    flow.flowBulk[prior.id] ?? [],
    flow.resourceMap[prior.id] ?? [],
    flow.assignments,
    flow.flowCtx,
    flow.now
  );
}

export function isSectionUnlocked(
  section: SyllabusSection,
  allSections: SyllabusSection[],
  releaseMode: ReleaseMode,
  studentProgressMap: Record<string, StudentProgressStatus>,
  sequentialFlow?: SectionSequentialUnlockFlow | null
): boolean {
  switch (releaseMode) {
    case 'all_at_once':
      return true;

    case 'sequential': {
      const ordered = sectionsInCourseOrder(allSections);
      const idx = ordered.findIndex((s) => s.id === section.id);
      if (idx < 0) return false;
      if (idx === 0) return true;
      for (let j = 0; j < idx; j++) {
        if (!priorSectionSatisfiedForSequential(ordered[j], studentProgressMap, sequentialFlow)) {
          return false;
        }
      }
      return true;
    }

    case 'date_based': {
      if (!section.start_date) return true;
      return new Date(section.start_date) <= new Date();
    }

    case 'manual':
      return !section.is_locked;

    default:
      return true;
  }
}

/**
 * Concatenate streaming text chunks for chat display.
 * Do not insert spaces between bare letter runs — stream boundaries are arbitrary.
 * Keep in sync with supabase/functions/perleap-chat/typography.ts mergeStreamingTextChunk.
 */
export function mergeStreamingTextChunk(prev: string, chunk: string): string {
  if (!prev || !chunk) return prev + chunk;
  if (/[<>\[\]]/.test(chunk)) return prev + chunk;
  const window = prev.slice(-24) + chunk.slice(0, 24);
  if (/<<<|PROGRESS/i.test(window)) return prev + chunk;
  return prev + chunk;
}

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Detects the text direction based on the first meaningful character.
 * Hebrew characters (Unicode range \u0590-\u05FF) return 'rtl', otherwise 'ltr'.
 */
export function detectTextDirection(text: string): 'rtl' | 'ltr' {
  // Find the first letter character (skip spaces, numbers, symbols)
  const letterMatch = text.match(/[\p{L}]/u);
  if (!letterMatch) return 'ltr';

  const firstLetter = letterMatch[0];
  const hebrewRegex = /[\u0590-\u05FF]/;
  return hebrewRegex.test(firstLetter) ? 'rtl' : 'ltr';
}

/**
 * Copies text to clipboard and returns a promise
 * @param text - The text to copy to clipboard
 * @returns Promise that resolves when copy is successful
 */
export async function copyToClipboard(text: string): Promise<void> {
  if (navigator.clipboard && window.isSecureContext) {
    await navigator.clipboard.writeText(text);
  } else {
    // Fallback for older browsers
    const textArea = document.createElement('textarea');
    textArea.value = text;
    textArea.style.position = 'fixed';
    textArea.style.left = '-999999px';
    textArea.style.top = '-999999px';
    document.body.appendChild(textArea);
    textArea.focus();
    textArea.select();
    try {
      document.execCommand('copy');
      textArea.remove();
    } catch (error) {
      textArea.remove();
      throw new Error('Failed to copy');
    }
  }
}

/** True when `value` looks like a Postgres UUID (excludes optimistic `temp-*` client ids). */
export function isUuidLike(value: unknown): value is string {
  if (value == null || typeof value !== 'string') return false;
  const trimmed = value.trim();
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(trimmed);
}

