    if (materials !== undefined) payload.materials = materials as unknown as Json | null;

    const { data, error } = await supabase
      .from('classrooms')
      .update(payload)
      .eq('id', classroomId)
      .select()
      .single();

    if (error) {
      return { data: null, error: handleSupabaseError(error) };
