    const { data, error } = await supabase
      .from('enrollments')
      .select('id')
      .eq('classroom_id', classroomId)
      .eq('student_id', studentId)
      .maybeSingle();

    if (error) {
      return { enrolled: false, error: handleSupabaseError(error) };
    }

    return { enrolled: !!data, error: null };
  } catch (error) {
    return { enrolled: false, error: handleSupabaseError(error) };
  }
};

