async function insertSubmissionRow(
  assignmentId: string,
  studentId: string,
  attemptNumber: number,
  opts?: { isTeacherAttempt?: boolean }
): Promise<{ data: Submission | null; error: ApiError | null }> {
  const { data: newSubmission, error: createError } = await supabase
    .from('submissions')
    .insert([
      {
        assignment_id: assignmentId,
        student_id: studentId,
        attempt_number: attemptNumber,
        status: SUBMISSION_STATUS.IN_PROGRESS as SubmissionStatus,
        started_at: new Date().toISOString(),
        ...(opts?.isTeacherAttempt ? { is_teacher_attempt: true } : {}),
      },
    ])
    .select()
    .single();

  if (createError) {
    return { data: null, error: handleSupabaseError(createError) };
  }

  return { data: newSubmission as unknown as Submission, error: null };
}

/**
 * Resolves which submission row the student should see and whether they may start a retry after completing.
 * Creates the first in-progress row when none exist (if policy allows).
 */
export const getStudentSubmissionContext = async (
  assignmentId: string,
  studentId: string,
  opts?: { isTeacherTry?: boolean; preferredSubmissionId?: string },
  prefetchedAssignment?: SubmissionContextAssignment | null
): Promise<{ data: StudentSubmissionContext; error: ApiError | null }> => {
  try {
    let assignment: SubmissionContextAssignment | null = prefetchedAssignment ?? null;

    if (!assignment) {
      const { data: fetched, error: assignErr } = await supabase
        .from('assignments')
        .select('id, attempt_mode, due_at, status')
        .eq('id', assignmentId)
        .maybeSingle();

      if (assignErr) {
        return {
          data: { submission: null, allAttempts: [], canRetry: false },
          error: handleSupabaseError(assignErr),
        };
      }
      assignment = fetched;
    }

    if (!assignment) {
      return { data: { submission: null, allAttempts: [], canRetry: false }, error: null };
    }

    const { data: rows, error: rowsErr } = await supabase
      .from('submissions')
      .select('*')
      .eq('assignment_id', assignmentId)
      .eq('student_id', studentId)
      .order('attempt_number', { ascending: true });

    if (rowsErr) {
      return {
        data: { submission: null, allAttempts: [], canRetry: false },
        error: handleSupabaseError(rowsErr),
      };
    }

    const list = (rows ?? []) as unknown as Submission[];
    const now = new Date();

    if (opts?.isTeacherTry !== true && opts?.preferredSubmissionId) {
      const preferred = list.find((s) => s.id === opts.preferredSubmissionId);
      if (preferred) {
        const retry = canRetryAfterCompleting(assignment, now);
        return {
          data: {
            submission: preferred,
            allAttempts: list,
            canRetry: retry,
          },
          error: null,
        };
      }
    }

    if (opts?.isTeacherTry === true) {
      const teacherAttempts = list.filter(
        (s) => (s as { is_teacher_attempt?: boolean }).is_teacher_attempt
      );

      let inProgress = teacherAttempts.find((s) => s.status === SUBMISSION_STATUS.IN_PROGRESS);
      if (!inProgress) {
        const legacyInProgress = list.find((s) => s.status === SUBMISSION_STATUS.IN_PROGRESS);
        if (legacyInProgress) {
          const { error: patchErr } = await supabase
            .from('submissions')
            .update({ is_teacher_attempt: true })
            .eq('id', legacyInProgress.id);
          if (!patchErr) {
            (legacyInProgress as { is_teacher_attempt?: boolean }).is_teacher_attempt = true;
            inProgress = legacyInProgress;
          }
        }
      }

      if (inProgress) {
        const allAttempts = teacherAttempts.some((s) => s.id === inProgress!.id)
          ? teacherAttempts
          : [...teacherAttempts, inProgress];
        return {
          data: {
            submission: inProgress,
            allAttempts,
            canRetry: false,
          },
          error: null,
        };
      }

      const nextNum =
        teacherAttempts.length > 0
          ? Math.max(...teacherAttempts.map((s) => s.attempt_number ?? 1)) + 1
          : 1;
      const { data: created, error: insErr } = await insertSubmissionRow(
        assignmentId,
        studentId,
        nextNum,
        { isTeacherAttempt: true }
      );
      if (insErr || !created) {
        return {
          data: { submission: null, allAttempts: teacherAttempts, canRetry: false },
          error: insErr,
        };
      }
      return {
        data: {
          submission: created,
          allAttempts: [...teacherAttempts, created],
          canRetry: false,
        },
        error: null,
      };
    }

    const inProgress = list.find((s) => s.status === SUBMISSION_STATUS.IN_PROGRESS);
    if (inProgress) {
      return {
        data: {
          submission: inProgress,
          allAttempts: list,
          canRetry: false,
        },
        error: null,
      };
    }

    if (list.length === 0) {
      const allowFirst = canStartFirstAttempt(assignment, now);
      if (!allowFirst) {
        return {
          data: { submission: null, allAttempts: [], canRetry: false },
          error: null,
        };
      }
      const { data: created, error: insErr } = await insertSubmissionRow(
        assignmentId,
        studentId,
        1
      );
      if (insErr || !created) {
        return { data: { submission: null, allAttempts: [], canRetry: false }, error: insErr };
      }
      return {
        data: { submission: created, allAttempts: [created], canRetry: false },
        error: null,
      };
    }

    const completed = list.filter((s) => s.status === SUBMISSION_STATUS.COMPLETED);
    let latestCompleted = [...completed].sort((a, b) => {
      const ta = a.submitted_at ? new Date(a.submitted_at).getTime() : 0;
      const tb = b.submitted_at ? new Date(b.submitted_at).getTime() : 0;
      return tb - ta;
    })[0];

    /** If rows exist but none matched `completed` (e.g. legacy status), still surface the latest attempt. */
    if (!latestCompleted && list.length > 0) {
      latestCompleted = [...list].sort(
        (a, b) => (b.attempt_number ?? 0) - (a.attempt_number ?? 0)
      )[0];
    }

    const retry = canRetryAfterCompleting(assignment, now);
    return {
      data: {
        submission: latestCompleted ?? null,
        allAttempts: list,
        canRetry: retry,
      },
      error: null,
    };
  } catch (error) {
    return {
      data: { submission: null, allAttempts: [], canRetry: false },
      error: handleSupabaseError(error),
    };
  }
};

export const startNewSubmissionAttempt = async (
  assignmentId: string,
  studentId: string,
  opts?: { isTeacherAttempt?: boolean }
): Promise<{ data: Submission | null; error: ApiError | null }> => {
  try {
    const { data: assignment, error: assignErr } = await supabase
      .from('assignments')
      .select('id, attempt_mode, due_at')
      .eq('id', assignmentId)
      .maybeSingle();

    if (assignErr) return { data: null, error: handleSupabaseError(assignErr) };
    if (!assignment) {
      return { data: null, error: { message: 'Assignment not found', code: 'NOT_FOUND' } };
    }

    const now = new Date();
    if (!canRetryAfterCompleting(assignment, now)) {
      return {
        data: null,
        error: {
          message: 'Another attempt is not allowed for this assignment.',
          code: 'ATTEMPT_NOT_ALLOWED',
        },
      };
    }

    const { data: rows, error: rowsErr } = await supabase
      .from('submissions')
      .select('*')
      .eq('assignment_id', assignmentId)
      .eq('student_id', studentId)
      .order('attempt_number', { ascending: true });

    if (rowsErr) return { data: null, error: handleSupabaseError(rowsErr) };
    const list = (rows ?? []) as unknown as Submission[];
    if (list.some((s) => s.status === SUBMISSION_STATUS.IN_PROGRESS)) {
      return {
        data: null,
        error: { message: 'You already have a draft in progress.', code: 'DUPLICATE_DRAFT' },
      };
    }
    if (!list.some((s) => s.status === SUBMISSION_STATUS.COMPLETED)) {
      return {
        data: null,
        error: { message: 'Complete your current attempt first.', code: 'INVALID_STATE' },
      };
    }

    const nextNum = Math.max(...list.map((s) => s.attempt_number ?? 1)) + 1;
    return insertSubmissionRow(assignmentId, studentId, nextNum, {
      isTeacherAttempt: opts?.isTeacherAttempt,
    });
  } catch (error) {
    return { data: null, error: handleSupabaseError(error) };
  }
};

/**
 * Lightweight poll for evaluation pipeline status (one row, two columns).
 */
export const getSubmissionEvaluationStatus = async (
  submissionId: string
): Promise<{ data: EvaluationStatus | null; error: ApiError | null }> => {
  try {
    const { data, error } = await supabase
      .from('submissions')
      .select('evaluation_status')
      .eq('id', submissionId)
      .maybeSingle();

    if (error) {
      return { data: null, error: handleSupabaseError(error) };
    }

    const status = data?.evaluation_status as EvaluationStatus | null | undefined;
    return { data: status ?? null, error: null };
  } catch (error) {
    return { data: null, error: handleSupabaseError(error) };
  }
};

