/**
 * Get full submission details including assignment, student profile, feedback, and alerts
 */
export const getFullSubmissionDetails = async (
  submissionId: string
): Promise<{ data: FullSubmissionDetails | null; error: ApiError | null }> => {
  try {
    const { data: submission, error: subError } = await supabase
      .from('submissions')
      .select(
        `
        *,
        assignments(id, title, instructions, classroom_id, due_at, type, enable_ai_feedback, auto_publish_ai_feedback, student_facing_task, opik_trace_ids, classrooms(name, teacher_id))
      `
      )
      .eq('id', submissionId)
      .single();

    if (subError) throw subError;
    if (!submission) return { data: null, error: null };

    const [{ data: feedback }, { data: alerts }, profileMap] = await Promise.all([
      supabase
        .from('assignment_feedback')
        .select('*')
        .eq('submission_id', submissionId)
        .order('created_at', { ascending: false })
        .limit(1)
        .maybeSingle(),
      supabase
        .from('student_alerts')
        .select('*')
        .eq('submission_id', submissionId)
        .order('created_at', { ascending: false }),
      resolveUserDisplayProfiles(supabase, [(submission as { student_id: string }).student_id]),
    ]);

    const prof = profileMap.get((submission as { student_id: string }).student_id);

    return {
