const BULK_QUERY_CHUNK_SIZE = 200;

function chunkIds<T>(ids: T[], size = BULK_QUERY_CHUNK_SIZE): T[][] {
  if (ids.length === 0) return [];
  const chunks: T[][] = [];
  for (let i = 0; i < ids.length; i += size) {
    chunks.push(ids.slice(i, i + size));
  }
  return chunks;
}

