/**
 * Report teacher AI content flag in DB, then sync to Opik (fire-and-forget on Opik).
 */
export const reportTeacherAiContentFlag = async (params: {
  assignmentId?: string;
  submissionId?: string;
  contentType: TeacherAiContentType;
  contentExcerpt: string;
  opikTraceId?: string;
}): Promise<{ ok: boolean; duplicate?: boolean; error?: string }> => {
  try {
    const hasPersistTarget = Boolean(params.assignmentId || params.submissionId);
    if (hasPersistTarget) {
      const { data, error } = await supabase.rpc('report_teacher_ai_content_flag', {
        args: {
          p_assignment_id: params.assignmentId ?? null,
          p_submission_id: params.submissionId ?? null,
          p_content_type: params.contentType,
          p_content_excerpt: params.contentExcerpt,
          p_opik_trace_id: params.opikTraceId ?? null,
        },
      });
      if (error) {
        return { ok: false, error: error.message };
      }
      const r = data as { ok?: boolean; duplicate?: boolean; error?: string };
      if (r?.duplicate) {
        return { ok: false, duplicate: true };
      }
      if (!r?.ok) {
        return { ok: false, error: r?.error ?? 'flag_rejected' };
      }
    }

    void supabase.functions
      .invoke('opik-ai-flag-feedback', {
        body: {
          type: 'teacher_content',
          assignmentId: params.assignmentId,
          submissionId: params.submissionId,
          contentType: params.contentType,
          contentExcerpt: params.contentExcerpt,
          opikTraceId: params.opikTraceId,
        },
      })
      .catch(() => undefined);

    return { ok: true };
  } catch (error) {
    return { ok: false, error: handleSupabaseError(error).message };
  }
};

/**
 * Get all submissions for a classroom with full enrichment (profiles + feedback)
 */
export const getEnrichedClassroomSubmissions = async (
  classroomId: string
): Promise<{ data: EnrichedClassroomSubmission[] | null; error: ApiError | null }> => {
  try {
    // 1. Get all assignments in this classroom with their assigned student profile if any
    const { data: assignments, error: assignError } = await supabase
      .from('assignments')
      .select(
        'id, title, type, created_at, assigned_student_id, status, syllabus_section_id, student_profiles(user_id, full_name, avatar_url)'
      )
      .eq('classroom_id', classroomId);

    if (assignError) throw assignError;
    if (!assignments || assignments.length === 0) return { data: [], error: null };

    const assignmentIds = assignments.map((a) => a.id);

    // 2. Get all submissions with student profiles
    const { data: submissions, error: subError } = await supabase
      .from('submissions')
      .select(
        `
        id, 
        submitted_at, 
        student_id, 
        assignment_id, 
        status,
        attempt_number,
        conversation_complete_at_submit,
        is_teacher_attempt
      `
      )
      .in('assignment_id', assignmentIds)
      .order('submitted_at', { ascending: false });

    if (subError) throw subError;

    const profileByUserId = await resolveUserDisplayProfiles(
      supabase,
      (submissions || []).map((s) => s.student_id)
    );

    const submissionIds = (submissions || []).map((s) => s.id);

    // 3. Bulk fetch feedback (list view only — skip conversation_context; loaded on submission detail)
    const { data: feedback } = await supabase
      .from('assignment_feedback')
      .select('submission_id, teacher_feedback')
      .in('submission_id', submissionIds);

    const flagCountBySubmissionId = new Map<string, number>();
    const clipboardActivityBySubmissionId = new Map<
      string,
      { hasCopy: boolean; hasPaste: boolean }
    >();
    if (submissionIds.length > 0) {
      const { data: flagRows } = await supabase
        .from('assignment_chat_sentence_flags')
        .select('submission_id')
        .in('submission_id', submissionIds);
      for (const row of flagRows ?? []) {
        const sid = row.submission_id;
        flagCountBySubmissionId.set(sid, (flagCountBySubmissionId.get(sid) ?? 0) + 1);
      }

      const { data: clipboardRows } = await supabase
        .from('assignment_clipboard_events')
        .select('submission_id, event_type')
        .in('submission_id', submissionIds);
      for (const row of clipboardRows ?? []) {
        const sid = row.submission_id;
        const current = clipboardActivityBySubmissionId.get(sid) ?? {
          hasCopy: false,
          hasPaste: false,
        };
        if (row.event_type === 'copy') current.hasCopy = true;
        if (row.event_type === 'paste') current.hasPaste = true;
        clipboardActivityBySubmissionId.set(sid, current);
      }
    }

    // 4. Combine data
    const feedbackMap = new Map(feedback?.map((f) => [f.submission_id, f]) || []);
    const submissionMap = new Set(
      submissions?.map((s) => `${s.assignment_id}-${s.student_id}`) || []
    );

    const enriched = (submissions || []).map((sub) => {
      const fb = feedbackMap.get(sub.id);
      const studentProfile = profileByUserId.get(sub.student_id);
      const assignment = assignments.find((a) => a.id === sub.assignment_id);
      const assignmentType = (assignment as { type?: string } | undefined)?.type;

      return {
        ...sub,
        student_name: studentProfile?.full_name || 'Unknown',
        student_avatar_url: studentProfile?.avatar_url,
        assignment_title: assignment?.title || 'Unknown Assignment',
        assignment_type: assignmentType ?? null,
        syllabus_section_id: assignment?.syllabus_section_id ?? null,
        has_feedback: !!fb,
        teacher_feedback: fb?.teacher_feedback,
        conversation_context: [],
        chat_sentence_flag_count: flagCountBySubmissionId.get(sub.id) ?? 0,
        clipboard_has_copy: clipboardActivityBySubmissionId.get(sub.id)?.hasCopy ?? false,
        clipboard_has_paste: clipboardActivityBySubmissionId.get(sub.id)?.hasPaste ?? false,
      };
    });

    // 5. Add pending assignments (assigned to specific students but not yet started)
    assignments.forEach((assign) => {
      if (
        assign.status === 'published' &&
        assign.assigned_student_id &&
        !submissionMap.has(`${assign.id}-${assign.assigned_student_id}`)
      ) {
        const profile = assign.student_profiles;
        const studentProfile = Array.isArray(profile) ? profile[0] : profile;

        if (studentProfile) {
          const pendingSub: EnrichedClassroomSubmission = {
            id: `pending-${assign.id}-${assign.assigned_student_id}`,
            submitted_at: assign.created_at,
            student_id: assign.assigned_student_id,
            assignment_id: assign.id,
            status: 'in_progress',
            attempt_number: 1,
            conversation_complete_at_submit: null,
            student_name: studentProfile.full_name || 'Unknown',
            student_avatar_url: studentProfile.avatar_url,
            assignment_title: assign.title,
            assignment_type: assign.type ?? null,
            syllabus_section_id: assign.syllabus_section_id ?? null,
            has_feedback: false,
            teacher_feedback: null,
            conversation_context: [],
            is_teacher_attempt: false,
            chat_sentence_flag_count: 0,
            clipboard_has_copy: false,
            clipboard_has_paste: false,
          };
          enriched.push(pendingSub);
        }
      }
    });

    // Sort by date (submitted_at or created_at for pending)
    enriched.sort(
      (a, b) => new Date(b.submitted_at).getTime() - new Date(a.submitted_at).getTime()
    );

    return { data: enriched, error: null };
  } catch (error) {
    return { data: null, error: handleSupabaseError(error) };
  }
};

