/**
 * Complete a submission and queue background AI evaluation (non-blocking for the student).
 */
export const submitWithBackgroundAiFeedback = async (params: {
  submissionId: string;
  studentId: string;
  assignmentId: string;
  language: string;
  completeOptions?: {
    awaitingTeacherFeedbackRelease?: boolean;
    conversationCompleteAtSubmit?: boolean | null;
  };
}): Promise<{ success: boolean; error: ApiError | null; evaluationInvokeFailed?: boolean }> => {
  const { submissionId, studentId, assignmentId, language, completeOptions } = params;

  const { success, error } = await completeSubmission(submissionId, {
    ...completeOptions,
    aiEvaluationPending: true,
  });
  if (!success || error) {
    return { success: false, error };
  }

  void requestBackgroundFeedback({
    submissionId,
    studentId,
    assignmentId,
    language,
  }).then(({ error: invokeError }) => {
    if (invokeError) {
      void markEvaluationStatus(submissionId, EVALUATION_STATUS.FAILED);
    }
  });

  return { success: true, error: null };
};

/**
 * Mark submission as completed
 */
export const completeSubmission = async (
  submissionId: string,
  options?: {
    awaitingTeacherFeedbackRelease?: boolean;
    /** Chat-primary: true if conversation had ended (green banner) at submit; false if early. Omit to leave column unchanged. */
    conversationCompleteAtSubmit?: boolean | null;
    /** Set evaluation_status=pending when AI feedback will run asynchronously after submit. */
    aiEvaluationPending?: boolean;
  }
): Promise<{ success: boolean; error: ApiError | null }> => {
  try {
    const submittedAt = new Date().toISOString();

    const { data: existing, error: fetchError } = await supabase
      .from('submissions')
      .select('started_at')
      .eq('id', submissionId)
      .maybeSingle();

    if (fetchError) {
      return { success: false, error: handleSupabaseError(fetchError) };
    }

    const update: Database['public']['Tables']['submissions']['Update'] = {
      status: SUBMISSION_STATUS.COMPLETED,
      submitted_at: submittedAt,
    };

    if (existing?.started_at) {
      const startedMs = new Date(existing.started_at).getTime();
      const submittedMs = new Date(submittedAt).getTime();
      update.duration_seconds = Math.max(0, Math.round((submittedMs - startedMs) / 1000));
    }

    if (options?.awaitingTeacherFeedbackRelease) {
      update.awaiting_teacher_feedback_release = true;
    }
    if (options && 'conversationCompleteAtSubmit' in options) {
      update.conversation_complete_at_submit = options.conversationCompleteAtSubmit ?? null;
    }
    if (options?.aiEvaluationPending) {
      update.evaluation_status = EVALUATION_STATUS.PENDING;
    }

    const { error } = await supabase.from('submissions').update(update).eq('id', submissionId);

    if (error) {
      return { success: false, error: handleSupabaseError(error) };
    }

    // Fire-and-forget: distill unit memory from this completed submission (idempotent).
    void supabase.functions
      .invoke('extract-unit-memory', { body: { submissionId } })
      .catch(() => undefined);

    return { success: true, error: null };
  } catch (error) {
    return { success: false, error: handleSupabaseError(error) };
  }
};

function normalizeFeedbackString(s: string | null | undefined): string {
  return (s ?? '').trim();
}

/**
 * Teacher edits stored feedback text before publishing to the student.
 */
export const updateAssignmentFeedbackText = async (params: {
  submissionId: string;
  teacher_feedback?: string | null;
  student_feedback?: string | null;
  /** When feedback was already published to the student and text changes, insert a student notification. */
  editNotification?: {
    studentId: string;
    assignmentId: string;
    assignmentTitle: string;
    teacherId: string | null;
    title: string;
    message: string;
    previousTeacher: string | null;
    previousStudent: string | null;
    shouldNotify: boolean;
  };
}): Promise<{ success: boolean; error: ApiError | null }> => {
  try {
    const { submissionId, teacher_feedback, student_feedback, editNotification } = params;
    const payload: Pick<
      Database['public']['Tables']['assignment_feedback']['Update'],
      'teacher_feedback' | 'student_feedback'
    > = {};
    if (teacher_feedback !== undefined) payload.teacher_feedback = teacher_feedback;
    if (student_feedback !== undefined) payload.student_feedback = student_feedback;
    if (Object.keys(payload).length === 0) {
      return { success: true, error: null };
    }

    const { error } = await supabase
      .from('assignment_feedback')
      .update(payload)
      .eq('submission_id', submissionId);

    if (error) {
      return { success: false, error: handleSupabaseError(error) };
    }

    if (editNotification?.shouldNotify) {
      const n = editNotification;
      const tf = teacher_feedback;
      const sf = student_feedback;
      let textChanged = false;
      if (
        tf !== undefined &&
        normalizeFeedbackString(tf) !== normalizeFeedbackString(n.previousTeacher)
      ) {
        textChanged = true;
      }
      if (
        sf !== undefined &&
        normalizeFeedbackString(sf) !== normalizeFeedbackString(n.previousStudent)
      ) {
        textChanged = true;
      }
      if (textChanged) {
        try {
          await createNotification(
            n.studentId,
            'feedback_updated',
            n.title,
            n.message,
            studentAssignmentDetailLink(n.assignmentId, submissionId),
            {
              assignment_id: n.assignmentId,
              assignment_title: n.assignmentTitle,
              submission_id: submissionId,
              feedback_updated: true,
            },
            n.teacherId ?? undefined
          );
        } catch (notifErr) {
          return { success: false, error: handleSupabaseError(notifErr) };
        }
      }
    }

    return { success: true, error: null };
  } catch (error) {
    return { success: false, error: handleSupabaseError(error) };
  }
};

/**
 * Teacher releases AI feedback to the student (when assignment uses teacher approval gate).
 */
export const releaseAiFeedbackToStudent = async (params: {
  submissionId: string;
  studentId: string;
  assignmentId: string;
  assignmentTitle: string;
  teacherId: string | null;
  notification?: {
    title: string;
    message: string;
  };
}): Promise<{ success: boolean; error: ApiError | null }> => {
  try {
    const { submissionId, studentId, assignmentId, assignmentTitle, teacherId, notification } =
      params;

    const { error: fbErr } = await supabase
      .from('assignment_feedback')
      .update({ visible_to_student: true })
      .eq('submission_id', submissionId);

    if (fbErr) {
      return { success: false, error: handleSupabaseError(fbErr) };
    }

    const { error: subErr } = await supabase
      .from('submissions')
      .update({ awaiting_teacher_feedback_release: false })
      .eq('id', submissionId);

    if (subErr) {
      return { success: false, error: handleSupabaseError(subErr) };
    }

    if (notification) {
      try {
        await createNotification(
          studentId,
          'feedback_received',
          notification.title,
          notification.message,
          studentAssignmentDetailLink(assignmentId, submissionId),
          {
            assignment_id: assignmentId,
            assignment_title: assignmentTitle,
            submission_id: submissionId,
          },
          teacherId ?? undefined
        );
      } catch (notifErr) {
        return { success: false, error: handleSupabaseError(notifErr) };
      }
    }

    return { success: true, error: null };
  } catch (error) {
    return { success: false, error: handleSupabaseError(error) };
  }
};

