const STORAGE_BUCKET = 'syllabus-resources';

/** Outline links / uploads use `lesson_content` when `url` / `file_path` columns are missing (slim `activity_list`). */
const OUTLINE_LINK_V1 = '__outline_link_v1';
const OUTLINE_FILE_V1 = '__outline_file_v1';

function normalizeUrlForLinkStorage(raw: string): string {
  const t = raw.trim();
  if (!t) return t;
  if (/^https?:\/\//i.test(t)) return t;
  if (/^[a-z][a-z0-9+.-]*:\/\//i.test(t)) return t;
  return `https://${t}`;
}

function outlineLinkLessonJson(url: string): Json {
  return { [OUTLINE_LINK_V1]: { url } } as unknown as Json;
}

function extractOutlineLinkUrl(lessonContent: unknown): string | null {
  if (!lessonContent || typeof lessonContent !== 'object' || Array.isArray(lessonContent))
    return null;
  const inner = (lessonContent as Record<string, unknown>)[OUTLINE_LINK_V1];
  if (!inner || typeof inner !== 'object' || Array.isArray(inner)) return null;
  const u = (inner as Record<string, unknown>).url;
  return typeof u === 'string' && u.trim() ? u.trim() : null;
}

function outlineFileLessonJson(meta: {
  file_path: string;
  url?: string | null;
  mime_type: string;
  file_size: number;
}): Json {
  return {
    [OUTLINE_FILE_V1]: {
      file_path: meta.file_path,
      url: meta.url ?? null,
      mime_type: meta.mime_type,
      file_size: meta.file_size,
    },
  } as unknown as Json;
}

function extractOutlineFileMeta(lessonContent: unknown): {
  file_path: string;
  url: string;
  mime_type: string | null;
  file_size: number | null;
} | null {
  if (!lessonContent || typeof lessonContent !== 'object' || Array.isArray(lessonContent))
    return null;
  const inner = (lessonContent as Record<string, unknown>)[OUTLINE_FILE_V1];
  if (!inner || typeof inner !== 'object' || Array.isArray(inner)) return null;
  const o = inner as Record<string, unknown>;
  const file_path = o.file_path;
  const url = o.url;
  if (typeof file_path !== 'string' || !file_path.trim()) return null;
  const urlVal = typeof url === 'string' && url.trim() ? url.trim() : null;
  const mime_type = typeof o.mime_type === 'string' ? o.mime_type : null;
  const rawSize = o.file_size;
  let file_size: number | null = null;
  if (typeof rawSize === 'number' && Number.isFinite(rawSize)) file_size = rawSize;
  else if (
    typeof rawSize === 'string' &&
    rawSize.trim() !== '' &&
    Number.isFinite(Number(rawSize))
  ) {
    file_size = Number(rawSize);
  }
  return { file_path: file_path.trim(), url: urlVal, mime_type, file_size };
}

export type BlobRevokeRegistry = {
  register: (revoke: () => void) => void;
};

function syllabusResourceStoragePath(resource: SectionResource): string | null {
  return (
    resource.file_path?.trim() ||
    (resource.url?.trim()
      ? extractStorageObjectPath(SYLLABUS_RESOURCES_BUCKET, resource.url.trim())
      : null)
  );
}

/** Download file bytes using the logged-in user's session (RLS enforced). */
export async function downloadSectionResourceFile(resource: SectionResource): Promise<Blob | null> {
  if (resource.resource_type === 'link') return null;
  const path = syllabusResourceStoragePath(resource);
  if (!path) return null;
  return downloadStorageBlob(STORAGE_BUCKET, path);
}

/** Resolve file-backed syllabus resource to an in-app blob URL (or external link as-is). */
export async function resolveSectionResourceFileUrl(
  resource: SectionResource,
  registry?: BlobRevokeRegistry
): Promise<string | null> {
  if (resource.resource_type === 'link') {
    return resource.url?.trim() || null;
  }
  const resolved = await resolveSyllabusResourceStoredValue(resource.file_path, resource.url);
  if (!resolved) return null;
  registry?.register(resolved.revoke);
  return resolved.url;
}

/** Resolve storage-backed URLs inside lesson blocks and top-level file fields for display. */
export async function resolveSectionResourceForDisplay(
  resource: SectionResource,
  registry?: BlobRevokeRegistry
): Promise<SectionResource> {
  if (resource.resource_type === 'link') {
    return resource;
  }

  let next: SectionResource = { ...resource };

  if (FILE_BACKED_RESOURCE_TYPES.has(resource.resource_type)) {
    const resolved = await resolveSyllabusResourceStoredValue(resource.file_path, resource.url);
    if (resolved) {
      registry?.register(resolved.revoke);
      next = { ...next, url: resolved.url };
    }
  }

  if (resource.resource_type === 'lesson') {
    const v1 = parseLessonContent(resource.lesson_content as unknown);
    if (v1?.blocks?.length) {
      const blocks = await Promise.all(
        v1.blocks.map(async (block) => {
          if (block.type !== 'video') return block;
          if (block.source === 'youtube' || isYoutubeUrl(block.url ?? '')) return block;
          const resolved = await resolveSyllabusResourceStoredValue(block.file_path, block.url);
          if (!resolved) return block;
          registry?.register(resolved.revoke);
          return { ...block, url: resolved.url };
        })
      );
      next = {
        ...next,
        lesson_content: { ...v1, blocks },
      };
    } else if (resource.file_path || resource.url) {
      const resolved = await resolveSyllabusResourceStoredValue(resource.file_path, resource.url);
      if (resolved) {
        registry?.register(resolved.revoke);
        next = { ...next, url: resolved.url };
      }
    }
  }

  return next;
}

const FILE_BACKED_RESOURCE_TYPES = new Set<SectionResource['resource_type']>([
  'file',
  'document',
  'image',
  'video',
]);

export function mapActivityListRowToSectionResource(
  row: SectionResource | null | undefined
): SectionResource | null {
  if (!row) return null;

  if (row.resource_type === 'link') {
    const u = row.url?.trim();
    if (u) return row;
    const fromLc = extractOutlineLinkUrl(row.lesson_content);
    if (!fromLc) return row;
    return { ...row, url: fromLc };
  }

  if (FILE_BACKED_RESOURCE_TYPES.has(row.resource_type)) {
    const hasPath = row.file_path?.trim();
    const hasUrl = row.url?.trim();
    if (hasPath || hasUrl) return row;
    const meta = extractOutlineFileMeta(row.lesson_content);
    if (!meta) return row;
    return {
      ...row,
      file_path: hasPath ?? meta.file_path,
      url: hasUrl ?? meta.url ?? null,
      mime_type: row.mime_type ?? meta.mime_type,
      file_size: row.file_size ?? meta.file_size,
    };
  }

  return row;
}

/**
 * Keys allowed on activity_list insert/update. PostgREST returns 400 if the JSON includes a
 * column name that does not exist (e.g. after manually dropping columns).
 * Slim schema (typical): section_id, title, resource_type, order_index, status, lesson_content,
 * active, deleted_at. Re-add any of summary, body_text, estimated_duration_minutes, file_path,
 * url, mime_type, file_size when those columns exist in your DB.
 */
const ACTIVITY_LIST_WRITE_KEYS = new Set([
  'section_id',
  'title',
  'resource_type',
  'order_index',
  'status',
  'lesson_content',
  'summary',
  'body_text',
  'file_path',
  'url',
  'mime_type',
  'file_size',
  'estimated_duration_minutes',
  'active',
  'deleted_at',
]);

/** Omit from PATCH like nulls — trims noise and avoids slim DB rejecting unknown cols on empty payloads. */
const ACTIVITY_PATCH_OMIT_WHEN_ABSENTLIKE = ACTIVITY_LIST_OPTIONAL_COLUMNS;

function activityPatchIncludesField(key: string, v: unknown): boolean {
  if (v === undefined || v === null) return false;
  if (ACTIVITY_PATCH_OMIT_WHEN_ABSENTLIKE.has(key) && typeof v === 'string' && !v.trim()) {
    return false;
  }
  return true;
}

function pickActivityListWritePayload(row: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const key of Object.keys(row)) {
    if (!ACTIVITY_LIST_WRITE_KEYS.has(key)) continue;
    const v = row[key];
    if (v === undefined) continue;
    out[key] = v;
  }
  return out;
}

