export interface ClassroomAnalytics {
  studentCount: number;
  assignmentCount: number;
  totalSubmissions: number;
  completionRate: number;
  classAverage: FiveDScores | null;
  students: StudentAnalytics[];
}

// Error Types
export interface ApiError {
  message: string;
  code?: string;
  details?: unknown;
}

/** Structured context when course package merge fails (see ApiError.details.merge). */
export type MergeFailurePhase =
  | 'exported_from_guard'
  | 'classroom_patch'
  | 'syllabus_fetch'
  | 'syllabus_mismatch'
  | 'syllabus_patch'
  | 'grading_categories'
  | 'sections'
  | 'activities'
  | 'section_prerequisites'
  | 'assignments'
  | 'assignment_links'
  | 'module_flow';

export type MergeFailureEntity =
  | 'grading_category'
  | 'section'
  | 'activity'
  | 'assignment'
  | 'flow_step';

export interface MergeFailureContext {
  phase: MergeFailurePhase;
  /** 0-based index into package array for the active loop, when applicable. */
  indexInPkg?: number;
  entity?: MergeFailureEntity;
  /** Id from the merge file (UUID), when present. */
  entityId?: string;
  /** Short human label (e.g. section title). */
  humanLabel?: string;
  /** True when merge ran via atomic Postgres RPC (full rollback on error). */
  atomic?: boolean;
}

export function isMergeFailureContext(v: unknown): v is MergeFailureContext {
  if (v === null || typeof v !== 'object') return false;
  const o = v as Record<string, unknown>;
  return typeof o.phase === 'string';
}

export function getMergeFailureFromApiError(
  err: ApiError | null | undefined
): MergeFailureContext | null {
  if (!err?.details || typeof err.details !== 'object') return null;
  const d = err.details as Record<string, unknown>;
  const m = d.merge;
  return isMergeFailureContext(m) ? m : null;
}

declare module '*.json' {
  const value: any;
  export default value;
}

/**
 * Language Detection Utilities
 * Detect language from text content
 */

/**
 * Detect if text contains Hebrew characters
 */
export function containsHebrew(text: string): boolean {
  // Hebrew Unicode range: \u0590-\u05FF
  const hebrewRegex = /[\u0590-\u05FF]/;
  return hebrewRegex.test(text);
}

/**
 * Detect language from text content
 * Returns 'he' if Hebrew characters detected, otherwise 'en'
 */
export function detectLanguage(text: string): 'he' | 'en' {
  if (!text) return 'en';

  // Check if text contains Hebrew characters
  if (containsHebrew(text)) {
    return 'he';
  }

  return 'en';
}

/**
 * Get language for assignment based on instructions
 * Prioritizes instruction language over UI language
 */
export function getAssignmentLanguage(instructions: string, uiLanguage: 'he' | 'en'): 'he' | 'en' {
  // If instructions contain Hebrew, use Hebrew regardless of UI language
  if (containsHebrew(instructions)) {
    return 'he';
  }

  // Otherwise, instructions are in English/Latin script
  // Always use English for non-Hebrew instructions regardless of UI language
  return 'en';
}

/**
 * Role Recovery Utilities
 *
 * Handles recovery of user role metadata when it's missing or incomplete.
 * This can happen due to network failures, browser closures during signup,
 * or API errors.
 */

import { USER_ROLES } from '@/config/constants';
import { supabase } from '@/integrations/supabase/client';

const PENDING_ROLE_KEY = 'pending_role';
const ROLE_RECOVERY_ATTEMPT_KEY = 'role_recovery_attempt';

/**
 * Save role to localStorage as a backup during signup
 */
export const savePendingRole = (role: 'teacher' | 'student'): void => {
  try {
    localStorage.setItem(PENDING_ROLE_KEY, role);
    console.log('💾 Role saved to localStorage as backup:', role);
  } catch (error) {
    console.error('Failed to save pending role:', error);
  }
};

/**
 * Get pending role from localStorage
 */
export const getPendingRole = (): string | null => {
  try {
    return localStorage.getItem(PENDING_ROLE_KEY);
  } catch (error) {
    console.error('Failed to get pending role:', error);
    return null;
  }
};

/**
 * Clear pending role from localStorage
 */
export const clearPendingRole = (): void => {
  try {
    localStorage.removeItem(PENDING_ROLE_KEY);
    console.log('🗑️ Cleared pending role from localStorage');
  } catch (error) {
    console.error('Failed to clear pending role:', error);
  }
};

/**
 * Update user's role metadata in Supabase Auth.
 * 'admin' is only applied if a row exists in public.app_admins for the current user.
 */
export const updateUserRole = async (role: 'teacher' | 'student' | 'admin'): Promise<boolean> => {
  try {
    if (role === USER_ROLES.ADMIN) {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) return false;
      const { data: row } = await supabase
        .from('app_admins')
        .select('user_id')
        .eq('user_id', user.id)
        .maybeSingle();
      if (!row) {
        console.error('❌ Refusing to set admin metadata without app_admins row');
        return false;
      }
    }

    console.log('🔄 Attempting to update user role to:', role);

    const { data, error } = await supabase.auth.updateUser({
      data: { role },
    });

    if (error) {
      console.error('❌ Failed to update user role:', error);
      return false;
    }

    if (data?.user?.user_metadata?.role === role) {
      console.log('✅ User role updated successfully:', role);
      return true;
    }

    console.warn('⚠️ User role update returned success but role not confirmed');
    return false;
  } catch (error) {
    console.error('❌ Exception updating user role:', error);
    return false;
  }
};

/**
 * Verify that user's role metadata is set correctly
 */
export const verifyUserRole = async (): Promise<{
  hasRole: boolean;
  role: string | null;
}> => {
  try {
    const {
      data: { user },
    } = await supabase.auth.getUser();

    if (!user) {
      return { hasRole: false, role: null };
    }

    const role = user.user_metadata?.role;
    const hasRole = role === 'teacher' || role === 'student' || role === USER_ROLES.ADMIN;

    console.log('🔍 Role verification:', { hasRole, role, userId: user.id });

    return { hasRole, role };
  } catch (error) {
    console.error('❌ Error verifying user role:', error);
    return { hasRole: false, role: null };
  }
};

/**
 * Check if user has both auth account and valid role
 */
export const isRegistrationComplete = async (): Promise<boolean> => {
  const { hasRole } = await verifyUserRole();
  return hasRole;
};

/**
 * Attempt to recover role from various sources
 */
export const attemptRoleRecovery = async (): Promise<{
  recovered: boolean;
  role: string | null;
  source: 'metadata' | 'localStorage' | 'database' | 'none';
}> => {
  // 1. First check if role is already in metadata
  const { hasRole, role: metadataRole } = await verifyUserRole();

  if (hasRole && metadataRole) {
    return { recovered: true, role: metadataRole, source: 'metadata' };
  }

  // 2. Try to recover from database (most reliable source of truth)
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (user) {
    const { data: adminRow } = await supabase
      .from('app_admins')
      .select('user_id')
      .eq('user_id', user.id)
      .maybeSingle();
    if (adminRow) {
      const ok = await updateUserRole(USER_ROLES.ADMIN);
      if (ok) {
        return { recovered: true, role: USER_ROLES.ADMIN, source: 'database' };
      }
    }

    console.log('🔍 Checking database for existing profile to recover role...');
    const { data: tp } = await supabase
      .from('teacher_profiles')
      .select('id')
      .eq('user_id', user.id)
      .maybeSingle();
    if (tp) {
      console.log('✅ Found teacher profile, updating role metadata');
      await updateUserRole('teacher');
      return { recovered: true, role: 'teacher', source: 'database' };
    }

    const { data: sp } = await supabase
      .from('student_profiles')
      .select('id')
      .eq('user_id', user.id)
      .maybeSingle();
    if (sp) {
      console.log('✅ Found student profile, updating role metadata');
      await updateUserRole('student');
      return { recovered: true, role: 'student', source: 'database' };
    }
  }

  // 3. Try to recover from localStorage
  const pendingRole = getPendingRole();

  if (pendingRole && (pendingRole === 'teacher' || pendingRole === 'student')) {
    console.log('🔄 Attempting to recover role from localStorage:', pendingRole);

    const updated = await updateUserRole(pendingRole as 'teacher' | 'student');

    if (updated) {
      clearPendingRole();
      return { recovered: true, role: pendingRole, source: 'localStorage' };
    }
  }

  return { recovered: false, role: null, source: 'none' };
};

/**
 * Track recovery attempts to prevent infinite loops
 */
export const incrementRecoveryAttempt = (): number => {
  try {
    const current = parseInt(localStorage.getItem(ROLE_RECOVERY_ATTEMPT_KEY) || '0');
    const next = current + 1;
    localStorage.setItem(ROLE_RECOVERY_ATTEMPT_KEY, next.toString());
    return next;
  } catch (error) {
    return 1;
  }
};

/**
 * Reset recovery attempt counter
 */
export const resetRecoveryAttempts = (): void => {
  try {
    localStorage.removeItem(ROLE_RECOVERY_ATTEMPT_KEY);
  } catch (error) {
    console.error('Failed to reset recovery attempts:', error);
  }
};

/**
 * Check if we should attempt recovery (max 3 attempts)
 */
export const shouldAttemptRecovery = (): boolean => {
  try {
    const attempts = parseInt(localStorage.getItem(ROLE_RECOVERY_ATTEMPT_KEY) || '0');
    return attempts < 3;
  } catch (error) {
    return true;
  }
};

/**
 * Session State Management
 *
 * Tracks signup progress to prevent confusion between:
 * - Active signup flow (user just registered, going through onboarding)
 * - Truly stuck users (old session, missing role metadata)
 */

const SIGNUP_IN_PROGRESS_KEY = 'signup_in_progress';
const SIGNUP_TIMESTAMP_KEY = 'signup_timestamp';

/**
 * Mark that signup is in progress
 * Called when user begins signup process
 */
export const markSignupInProgress = (): void => {
  try {
    sessionStorage.setItem(SIGNUP_IN_PROGRESS_KEY, 'true');
    sessionStorage.setItem(SIGNUP_TIMESTAMP_KEY, Date.now().toString());
    console.log('✅ Signup marked as in progress');
  } catch (error) {
    console.error('Failed to mark signup in progress:', error);
  }
};

/**
 * Mark that signup is complete
 * Called after onboarding is successfully completed
 */
export const markSignupComplete = (): void => {
  try {
    sessionStorage.removeItem(SIGNUP_IN_PROGRESS_KEY);
    sessionStorage.removeItem(SIGNUP_TIMESTAMP_KEY);
    console.log('✅ Signup marked as complete');
  } catch (error) {
    console.error('Failed to mark signup complete:', error);
  }
};

/**
 * Check if signup is currently in progress
 * Returns false if:
 * - Flag is not set
 * - Signup started more than 30 minutes ago (timed out)
 */
export const isSignupInProgress = (): boolean => {
  try {
    const inProgress = sessionStorage.getItem(SIGNUP_IN_PROGRESS_KEY) === 'true';

    if (!inProgress) {
      return false;
    }

    // Check if signup has timed out (30 minutes)
    const timestamp = sessionStorage.getItem(SIGNUP_TIMESTAMP_KEY);
    if (timestamp) {
      const signupTime = parseInt(timestamp);
      const now = Date.now();
      const thirtyMinutes = 30 * 60 * 1000;

      if (now - signupTime > thirtyMinutes) {
        console.warn('⚠️ Signup timed out (30+ minutes), clearing flags');
        markSignupComplete();
        return false;
      }
    }

    return true;
  } catch (error) {
    console.error('Failed to check signup status:', error);
    return false;
  }
};

/**
 * Clear all signup-related state
 * Used on sign out or when cleaning up
 */
export const clearAllSignupState = (): void => {
  try {
    sessionStorage.removeItem(SIGNUP_IN_PROGRESS_KEY);
    sessionStorage.removeItem(SIGNUP_TIMESTAMP_KEY);
    console.log('🗑️ Cleared all signup state');
  } catch (error) {
    console.error('Failed to clear signup state:', error);
  }
};

/**
 * Check how long signup has been in progress
 * Returns milliseconds, or null if not in progress
 */
export const getSignupDuration = (): number | null => {
  try {
    if (!isSignupInProgress()) {
      return null;
    }

    const timestamp = sessionStorage.getItem(SIGNUP_TIMESTAMP_KEY);
    if (!timestamp) {
      return null;
    }

    return Date.now() - parseInt(timestamp);
  } catch (error) {
    return null;
  }
};

